pub const SpecifierOverride = struct {
    vfs_path: []const u8,
    wire_specifier: []const u8,
};

pub const SourceFileView = struct {
    vfs_path: []const u8,
    contents: []const u8,
};

/// Lowering configuration for `lowerGraph`.
pub const LowerOptions = struct {
    /// Optional VFS base directory stripped from file-module paths when deriving relative module names.
    base_dir: ?[]const u8 = null,
    /// Optional explicit primary VFS entry paths (`-t / --types`). When non-empty and `modules` is
    /// empty, only primary modules are re-exported by `root.zig`, and unreferenced non-primary
    /// modules are pruned via reachability closure.
    primary_vfs_paths: []const []const u8 = &.{},
    /// Optional public package `"exports"` wire specifier overrides (`vfs_path -> "pkg/subpath"`).
    vfs_specifier_overrides: []const SpecifierOverride = &.{},
    /// Optional VFS directory prefixes of packages that declare `package.json` `"exports"`
    /// (scoping `"exports"` module encapsulation so sibling non-`"exports"` `-t` inputs remain public).
    exports_pkg_vfs_prefixes: []const []const u8 = &.{},
    /// Optional VFS directory prefixes belonging to pure declaration-only helper packages
    /// (such as `undici-types`) that have no runtime JavaScript module.
    types_only_vfs_prefixes: []const []const u8 = &.{},
    /// Optional VFS declaration source files used to detect unresolved local `import` bindings.
    source_files: []const SourceFileView = &.{},
    /// Optional `-m / --module` filters. Empty means emit primary modules and their dependencies.
    modules: []const []const u8 = &.{},
    /// Optional `-s / --substitute <from=to>` rules.
    substitutions: []const cli.Substitution = &.{},
};

