pub const LowerError = error{
    OutOfMemory,
    NoMatchingModules,
};

/// Applies `-s / --substitute <from=to>` rules sequentially to a module/namespace specifier.
pub fn applySubstitutions(
    allocator: std.mem.Allocator,
    raw_specifier: []const u8,
    substitutions: []const cli.Substitution,
) ![]u8 {
    var current = try allocator.dupe(u8, raw_specifier);
    errdefer allocator.free(current);

    for (substitutions) |rule| {
        if (std.mem.eql(u8, current, rule.from)) {
            if (rule.to.len > 0) {
                const next = try allocator.dupe(u8, rule.to);
                allocator.free(current);
                current = next;
            }
            continue;
        }
        if (std.mem.startsWith(u8, current, rule.from) and current.len > rule.from.len) {
            const boundary = current[rule.from.len];
            const from_ends_sep = rule.from[rule.from.len - 1] == ':' or
                rule.from[rule.from.len - 1] == '/' or
                rule.from[rule.from.len - 1] == '.';
            if (from_ends_sep or boundary == '/' or boundary == '.' or boundary == ':') {
                const next = try std.fmt.allocPrint(allocator, "{s}{s}", .{
                    rule.to,
                    current[rule.from.len..],
                });
                allocator.free(current);
                current = next;
            }
        }
    }

    return current;
}

fn stripNodePrefix(s: []const u8) []const u8 {
    if (std.mem.startsWith(u8, s, "node:")) return s["node:".len..];
    return s;
}

/// Checks whether a candidate module matches a single `-m / --module` filter pattern.
pub fn moduleMatchesPattern(
    wire_spec: []const u8,
    substituted_spec: []const u8,
    pattern: []const u8,
) bool {
    const pat = std.mem.trim(u8, pattern, " \t\r\n");
    if (pat.len == 0) return false;

    const candidates = [_][]const u8{ wire_spec, substituted_spec };
    const pat_no_node = stripNodePrefix(naming.stripModuleExtension(pat));

    for (candidates) |cand_raw| {
        const cand = naming.stripModuleExtension(cand_raw);
        if (std.mem.eql(u8, cand_raw, pat) or std.mem.eql(u8, cand, pat)) return true;
        const cand_no_node = stripNodePrefix(cand);
        if (std.mem.eql(u8, cand_no_node, pat_no_node)) return true;

        // Also match normalized '.' <-> '/' namespace vs path spelling (e.g. monaco.editor <-> monaco/editor).
        if (cand_no_node.len == pat_no_node.len) {
            var eq_norm = true;
            for (cand_no_node, pat_no_node) |ca, cb| {
                const na: u8 = if (ca == '.') '/' else ca;
                const nb: u8 = if (cb == '.') '/' else cb;
                if (na != nb) {
                    eq_norm = false;
                    break;
                }
            }
            if (eq_norm) return true;
        }
    }
    return false;
}

/// Lowers any `DeclarationGraph` value generated from `zigar:typescript@7.1.0` (`types.DeclarationGraph`
/// across native/wasm32/wasm64 bindgen instantiations) into a normalized, cycle-safe `PackageIr`.
pub fn lowerGraph(
    backing_allocator: std.mem.Allocator,
    graph: anytype,
    options: LowerOptions,
) LowerError!PackageIr {
    var arena = std.heap.ArenaAllocator.init(backing_allocator);
    errdefer arena.deinit();
    const alloc = arena.allocator();

    var scratch_arena = std.heap.ArenaAllocator.init(backing_allocator);
    defer scratch_arena.deinit();

    var ctx = LowerCtx(@TypeOf(graph)){
        .alloc = alloc,
        .scratch = scratch_arena.allocator(),
        .graph = graph,
        .options = options,
    };
    defer ctx.deinitScratch();

    const modules = try ctx.build();
    return .{
        .arena = arena,
        .modules = modules,
        .fallbacks = try ctx.fallbacks.toOwnedSlice(alloc),
    };
}

fn LowerCtx(comptime GraphType: type) type {
    return struct {
        const Self = @This();

        const ForeignExportEntry = struct {
            decl_id: u32,
            wire_name_override: ?[]const u8 = null,
            is_default_export: bool = false,
        };

        const CandidateModule = struct {
            wire_specifier: []const u8,
            substituted_specifier: []const u8,
            rel_zig_path: []const u8,
            source_mod_ids: std.ArrayList(u32) = .empty,
            decl_ids: std.ArrayList(u32) = .empty,
            exported_decl_ids: std.ArrayList(u32) = .empty,
            foreign_exports: std.ArrayList(ForeignExportEntry) = .empty,
            same_mod_export_equals_children: std.ArrayList(u32) = .empty,
            star_re_export_source_mods: std.ArrayList(u32) = .empty,
            star_re_export_specs: std.ArrayList([]const u8) = .empty,
            default_export_decl_id: ?u32 = null,
            export_equals_decl_id: ?u32 = null,
            export_equals_subns_decl_id: ?u32 = null,
            is_primary: bool = false,
            is_public_export_mod: bool = true,
            included: bool = false,
        };

        const DeclLocation = struct {
            module_index: u32,
            zig_path: []const []const u8,
            type_param_names: []const []const u8 = &.{},
            type_param_defaults: []const ?u32,
            target_decl_id: u32 = std.math.maxInt(u32),
        };

        const ActiveTypeParam = struct {
            ts_name: []const u8,
            zig_ident: []const u8 = "",
            subst_ty: ?*TypeIr = null,
        };

        const DeclNodeType = std.meta.Elem(@FieldType(GraphType, "decls"));
        const DeclKindType = @FieldType(DeclNodeType, "kind");
        const IfaceDataType = @FieldType(DeclKindType, "interface_decl");
        const MethodNodeType = std.meta.Elem(@FieldType(IfaceDataType, "methods"));
        const IndexSigNodeType = std.meta.Elem(@FieldType(IfaceDataType, "index_signatures"));

        const HeritageBinding = struct {
            ts_name: []const u8,
            arg_ty_id: ?u32,
            arg_in_self_env: bool = false,
        };

        const HeritageEnv = struct {
            bindings: []const HeritageBinding,
            parent: ?*const HeritageEnv = null,
        };

        const SourcedProp = struct {
            pid: u32,
            env: ?*const HeritageEnv = null,
            from_class_base: bool = false,
        };

        const SourcedMethod = struct {
            method: MethodNodeType,
            env: ?*const HeritageEnv = null,
        };

        const SourcedSig = struct {
            sid: u32,
            env: ?*const HeritageEnv = null,
        };

        const SourcedIndexSig = struct {
            sig: IndexSigNodeType,
            env: ?*const HeritageEnv = null,
        };

        const SourcedBaseClause = struct {
            target_decl: ?u32 = null,
            target_type: u32,
            type_args: []const u32 = &.{},
            env: ?*const HeritageEnv = null,
        };

        const StarExportItem = struct {
            decl_id: u32,
            wire_name_override: ?[]const u8 = null,
        };

        const PlannedReExport = struct {
            source_decl_id: u32,
            zig_ident: []const u8,
            logical_name: []const u8,
            wire_name: []const u8,
            is_default_export: bool,
            target_module_index: u32,
            target_zig_path: []const []const u8,
        };

        const LoweredTypeParams = struct {
            ir: []TypeParamIr,
            active: []ActiveTypeParam,
        };

        alloc: std.mem.Allocator,
        scratch: std.mem.Allocator,
        graph: GraphType,
        options: LowerOptions,

        candidates: std.ArrayList(CandidateModule) = .empty,
        source_mod_to_cand: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        has_globals_hub: bool = false,
        decl_locations: std.AutoHashMapUnmanaged(u32, DeclLocation) = .empty,
        merged_ns_consumed: std.AutoHashMapUnmanaged(u32, void) = .empty,
        merged_iface_consumed: std.AutoHashMapUnmanaged(u32, void) = .empty,
        merged_ctor_var_consumed: std.AutoHashMapUnmanaged(u32, void) = .empty,
        merged_generic_ctor_var_peer: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        merged_fn_consumed: std.AutoHashMapUnmanaged(u32, void) = .empty,
        decl_classifications: std.AutoHashMapUnmanaged(u32, classify_decls.DeclClassification) = .empty,
        merged_generic_ns_peer: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        merged_generic_ns_set: std.AutoHashMapUnmanaged(u32, void) = .empty,
        pure_export_equals_ns: std.AutoHashMapUnmanaged(u32, void) = .empty,
        ns_child_ids: std.AutoHashMapUnmanaged(u32, void) = .empty,
        child_to_parent_ns: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        js_exported_decls: std.AutoHashMapUnmanaged(u32, void) = .empty,
        global_aug_decls: std.AutoHashMapUnmanaged(u32, void) = .empty,
        decl_to_cand: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        deduped_decl_ids: std.AutoHashMapUnmanaged(u32, void) = .empty,
        cand_to_final_map: ?[]?u32 = null,
        type_ref_counts: []u32 = &.{},
        type_closed_cache: []u8 = &.{},
        cur_mod_idx: u32 = 0,
        cur_mod_hoisted_locs: std.AutoHashMapUnmanaged(u32, DeclLocation) = .empty,
        cur_mod_closed_types: std.AutoHashMapUnmanaged(u32, *TypeIr) = .empty,
        cur_mod_enum_member_types: std.AutoHashMapUnmanaged(u64, DeclLocation) = .empty,
        cur_mod_unit_literal_types: std.StringHashMapUnmanaged(DeclLocation) = .empty,
        cur_mod_property_key_loc: ?DeclLocation = null,
        cur_mod_array_buffer_view_loc: ?DeclLocation = null,
        star_summary_cands: std.AutoHashMapUnmanaged(u32, ModuleStarSummary) = .empty,
        star_summary_smods: std.AutoHashMapUnmanaged(u32, ModuleStarSummary) = .empty,
        vfs_sources: std.StringHashMapUnmanaged([]const u8) = .empty,
        cur_mod_decls_out: ?*std.ArrayList(DeclIr) = null,
        cur_mod_root_scope: ?*naming.ScopeNamer = null,
        cur_mod_anon_counter: u32 = 0,
        inline_anon_depth: u32 = 0,
        in_synthesized_resolved_depth: u32 = 0,
        in_handle_struct: bool = false,
        cur_cand_idx: ?u32 = null,
        cur_mod_specifier: []const u8 = "",
        cur_decl_logical_name: []const u8 = "<module>",
        cur_decl_fallback_notes: ?*std.ArrayList([]const u8) = null,
        fallbacks: std.ArrayList(FallbackEntry) = .empty,
        fallbacks_seen: std.StringHashMapUnmanaged(void) = .empty,

        fn deinitScratch(self: *Self) void {
            self.fallbacks_seen.deinit(self.scratch);
            for (self.candidates.items) |*c| {
                c.source_mod_ids.deinit(self.scratch);
                c.decl_ids.deinit(self.scratch);
                c.exported_decl_ids.deinit(self.scratch);
                c.foreign_exports.deinit(self.scratch);
                c.same_mod_export_equals_children.deinit(self.scratch);
                c.star_re_export_source_mods.deinit(self.scratch);
                c.star_re_export_specs.deinit(self.scratch);
            }
            self.candidates.deinit(self.scratch);
            self.source_mod_to_cand.deinit(self.scratch);
            self.decl_locations.deinit(self.scratch);
            self.merged_ns_consumed.deinit(self.scratch);
            self.merged_iface_consumed.deinit(self.scratch);
            self.merged_ctor_var_consumed.deinit(self.scratch);
            self.merged_generic_ctor_var_peer.deinit(self.scratch);
            self.merged_fn_consumed.deinit(self.scratch);
            self.decl_classifications.deinit(self.scratch);
            self.merged_generic_ns_peer.deinit(self.scratch);
            self.merged_generic_ns_set.deinit(self.scratch);
            self.pure_export_equals_ns.deinit(self.scratch);
            self.ns_child_ids.deinit(self.scratch);
            self.child_to_parent_ns.deinit(self.scratch);
            self.js_exported_decls.deinit(self.scratch);
            self.global_aug_decls.deinit(self.scratch);
            self.decl_to_cand.deinit(self.scratch);
            self.deduped_decl_ids.deinit(self.scratch);
            self.cur_mod_hoisted_locs.deinit(self.scratch);
            self.cur_mod_closed_types.deinit(self.scratch);
            self.cur_mod_enum_member_types.deinit(self.scratch);
            self.cur_mod_unit_literal_types.deinit(self.scratch);
            self.star_summary_cands.deinit(self.scratch);
            self.star_summary_smods.deinit(self.scratch);
            self.vfs_sources.deinit(self.scratch);
        }

        fn str(self: *const Self, id: u32) []const u8 {
            if (id < self.graph.strings.len) return self.graph.strings[id];
            return "";
        }

        fn sanitizeSingleLineNote(alloc: std.mem.Allocator, raw: []const u8) error{OutOfMemory}![]const u8 {
            var needs_clean = false;
            for (raw) |c| {
                if (c == '\n' or c == '\r') {
                    needs_clean = true;
                    break;
                }
            }
            if (!needs_clean) return try alloc.dupe(u8, raw);
            const buf = try alloc.dupe(u8, raw);
            for (buf) |*c| {
                if (c.* == '\n' or c.* == '\r') c.* = ' ';
            }
            return buf;
        }

        fn recordFallbackAt(
            self: *Self,
            mod_spec: []const u8,
            decl_name: []const u8,
            notes_out: ?*std.ArrayList([]const u8),
            kind: FallbackKind,
            detail_raw: []const u8,
        ) error{OutOfMemory}!void {
            const clean_detail = try sanitizeSingleLineNote(self.alloc, detail_raw);
            const note = try std.fmt.allocPrint(self.alloc, "{s}: {s}", .{ kind.tagName(), clean_detail });
            const dedup_key = try std.fmt.allocPrint(self.scratch, "{s}\x00{s}\x00{s}", .{ mod_spec, decl_name, note });
            const gop = try self.fallbacks_seen.getOrPut(self.scratch, dedup_key);
            if (gop.found_existing) {
                self.scratch.free(dedup_key);
                return;
            }
            try self.fallbacks.append(self.alloc, .{
                .module_specifier = try self.alloc.dupe(u8, mod_spec),
                .decl_name = try self.alloc.dupe(u8, decl_name),
                .kind = kind,
                .detail = clean_detail,
            });
            if (notes_out) |lst| {
                try lst.append(self.scratch, note);
            }
        }

        fn recordFallback(self: *Self, kind: FallbackKind, detail_raw: []const u8) error{OutOfMemory}!void {
            try self.recordFallbackAt(
                self.cur_mod_specifier,
                self.cur_decl_logical_name,
                self.cur_decl_fallback_notes,
                kind,
                detail_raw,
            );
        }

        fn classifyDecl(self: *Self, decl_id: u32) error{OutOfMemory}!classify_decls.DeclClassification {
            if (self.decl_classifications.get(decl_id)) |cached| return cached;
            var cls = classify_decls.Classifier(GraphType).init(self.scratch, &self.graph);
            defer cls.state.deinit(self.scratch);
            cls.memo = self.decl_classifications;
            defer self.decl_classifications = cls.memo;
            return try cls.classifyDecl(decl_id);
        }

        fn classifyObjectLiteral(self: *const Self, obj: anytype) classify_decls.DeclClassification {
            var cls = classify_decls.Classifier(GraphType).init(self.scratch, &self.graph);
            return cls.classifyObjectLiteralData(obj);
        }

        fn classifyObjectType(self: *Self, ty_id: u32) error{OutOfMemory}!classify_decls.DeclClassification {
            var cls = classify_decls.Classifier(GraphType).init(self.scratch, &self.graph);
            defer cls.state.deinit(self.scratch);
            cls.memo = self.decl_classifications;
            defer self.decl_classifications = cls.memo;
            return try cls.classifyObjectType(ty_id, 0);
        }

        fn isPrimaryVfsPath(self: *const Self, fp: []const u8) bool {
            if (fp.len == 0) return false;
            for (self.options.primary_vfs_paths) |p| {
                if (std.mem.eql(u8, p, fp)) return true;
            }
            return false;
        }

        fn normalizeExternalNodeModulesSubpath(self: *Self, nm_rel: []const u8) ![]const u8 {
            const pkg_rel = if (std.mem.startsWith(u8, nm_rel, "@types/"))
                nm_rel["@types/".len..]
            else
                nm_rel;
            const stripped = naming.stripModuleExtension(pkg_rel);
            const final_rel = if (std.mem.endsWith(u8, stripped, "/index") and stripped.len > "/index".len)
                stripped[0 .. stripped.len - "/index".len]
            else if (stripped.len == 0)
                "index"
            else
                stripped;
            return try self.alloc.dupe(u8, final_rel);
        }

        fn deriveFileLogicalSpecifier(self: *Self, mod: anytype) ![]const u8 {
            const raw_spec = self.str(mod.specifier);
            const file_path = self.str(mod.file_path);

            // Non-path package/ambient specifier takes precedence.
            if (raw_spec.len > 0 and !std.mem.startsWith(u8, raw_spec, "/") and !std.mem.startsWith(u8, raw_spec, ".")) {
                return try self.alloc.dupe(u8, naming.stripModuleExtension(raw_spec));
            }

            const chosen = if (file_path.len > 0) file_path else raw_spec;
            var rel = chosen;
            if (self.options.base_dir) |base| {
                const trimmed_base = std.mem.trimEnd(u8, base, "/");
                if (trimmed_base.len > 0 and std.mem.startsWith(u8, chosen, trimmed_base)) {
                    const after = chosen[trimmed_base.len..];
                    if (after.len == 0) {
                        rel = "index";
                    } else if (after[0] == '/') {
                        const sub = after[1..];
                        if (std.mem.startsWith(u8, sub, "node_modules/")) {
                            return self.normalizeExternalNodeModulesSubpath(sub["node_modules/".len..]);
                        }
                        if (std.mem.lastIndexOf(u8, sub, "/node_modules/")) |nm_idx| {
                            return self.normalizeExternalNodeModulesSubpath(sub[nm_idx + "/node_modules/".len ..]);
                        }
                        rel = sub;
                    }
                } else if (std.mem.lastIndexOf(u8, chosen, "/node_modules/")) |nm_idx| {
                    return self.normalizeExternalNodeModulesSubpath(chosen[nm_idx + "/node_modules/".len ..]);
                } else if (std.mem.lastIndexOfScalar(u8, chosen, '/')) |slash| {
                    rel = chosen[slash + 1 ..];
                }
            } else if (std.mem.lastIndexOf(u8, chosen, "/node_modules/")) |nm_idx| {
                return self.normalizeExternalNodeModulesSubpath(chosen[nm_idx + "/node_modules/".len ..]);
            } else if (std.mem.startsWith(u8, chosen, "/")) {
                rel = chosen[1..];
            }

            const stripped = naming.stripModuleExtension(rel);
            if (stripped.len == 0) return try self.alloc.dupe(u8, "index");
            return try self.alloc.dupe(u8, stripped);
        }

        fn getOrCreateCandidate(
            self: *Self,
            wire_spec: []const u8,
            source_mod_id: ?u32,
        ) !u32 {
            const sub_spec = try applySubstitutions(self.alloc, wire_spec, self.options.substitutions);
            // Normalize '.' in dotted namespace specifiers (e.g. monaco.editor -> monaco/editor) before path sanitization.
            const slash_spec = try self.alloc.dupe(u8, sub_spec);
            for (slash_spec) |*ch| {
                if (ch.* == '.') ch.* = '/';
            }
            const rel_zig_path = try naming.sanitizeModuleRelPath(self.alloc, slash_spec);

            for (self.candidates.items, 0..) |*existing, idx| {
                if (std.mem.eql(u8, existing.rel_zig_path, rel_zig_path)) {
                    // Canonicalize unprefixed Node built-in specifiers (`"fs"` + `"node:fs"`,
                    // `"fs/promises"` + `"node:fs/promises"`, etc.) to `"node:*"` whenever
                    // the canonical `"node:*"` ambient module shares the same `rel_zig_path`.
                    if (std.mem.startsWith(u8, wire_spec, "node:") and
                        std.mem.eql(u8, existing.wire_specifier, wire_spec["node:".len..]))
                    {
                        existing.wire_specifier = try self.alloc.dupe(u8, wire_spec);
                        existing.substituted_specifier = sub_spec;
                    }
                    if (source_mod_id) |smid| {
                        try appendUniqueU32(&existing.source_mod_ids, self.scratch, smid);
                        try self.source_mod_to_cand.put(self.scratch, smid, @intCast(idx));
                    }
                    return @intCast(idx);
                }
            }

            const new_idx: u32 = @intCast(self.candidates.items.len);
            var cand = CandidateModule{
                .wire_specifier = try self.alloc.dupe(u8, wire_spec),
                .substituted_specifier = sub_spec,
                .rel_zig_path = rel_zig_path,
            };
            if (source_mod_id) |smid| {
                try cand.source_mod_ids.append(self.scratch, smid);
                try self.source_mod_to_cand.put(self.scratch, smid, new_idx);
            }
            try self.candidates.append(self.scratch, cand);
            return new_idx;
        }

        fn appendDeclRecursiveToCand(self: *Self, decl_id: u32, cand_idx: u32) error{OutOfMemory}!void {
            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);
            try self.appendDeclRecursiveToCandInner(decl_id, cand_idx, &visited);
        }

        fn appendDeclRecursiveToCandInner(
            self: *Self,
            decl_id: u32,
            cand_idx: u32,
            visited: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            if (decl_id >= self.graph.decls.len) return;
            if (visited.contains(decl_id)) return;
            try visited.put(self.scratch, decl_id, {});
            if (!self.decl_to_cand.contains(decl_id)) {
                try self.decl_to_cand.put(self.scratch, decl_id, cand_idx);
            }
            const d = self.graph.decls[decl_id];
            switch (d.kind) {
                .namespace_decl => |children| {
                    for (children) |cid| {
                        try self.appendDeclRecursiveToCandInner(cid, cand_idx, visited);
                    }
                },
                else => {},
            }
        }

        fn findDottedNamespaceDecls(self: *const Self, dotted: []const u8) ?[]const u32 {
            if (std.mem.indexOfScalar(u8, dotted, '.') == null) return null;
            var seg_it = std.mem.splitScalar(u8, dotted, '.');
            const first_seg = seg_it.next() orelse return null;

            for (self.graph.modules) |mod| {
                const top_lists = [_][]const u32{ mod.exports, mod.global_augmentations };
                for (top_lists) |list| {
                    for (list) |did| {
                        if (did >= self.graph.decls.len) continue;
                        const d = self.graph.decls[did];
                        if (!std.mem.eql(u8, self.str(d.name), first_seg)) continue;
                        if (d.kind != .namespace_decl) continue;

                        var cur_children = d.kind.namespace_decl;
                        var rem_it = seg_it;
                        var matched_all = true;
                        while (rem_it.next()) |seg| {
                            var found_next: ?[]const u32 = null;
                            for (cur_children) |cid| {
                                if (cid >= self.graph.decls.len) continue;
                                const cd = self.graph.decls[cid];
                                if (cd.kind == .namespace_decl and std.mem.eql(u8, self.str(cd.name), seg)) {
                                    found_next = cd.kind.namespace_decl;
                                    break;
                                }
                            }
                            if (found_next) |nxt| {
                                cur_children = nxt;
                            } else {
                                matched_all = false;
                                break;
                            }
                        }
                        if (matched_all) return cur_children;
                    }
                }
            }
            return null;
        }

        fn isBundledLibModule(self: *const Self, mod: anytype) bool {
            const fp = self.str(mod.file_path);
            if (std.mem.startsWith(u8, fp, "/lib.") and std.mem.endsWith(u8, fp, ".d.ts")) return true;
            if (std.mem.indexOf(u8, fp, "/typescript/lib/lib.") != null) return true;
            return false;
        }

        fn markGlobalScopeDeclRecursive(self: *Self, did: u32) error{OutOfMemory}!void {
            if (did >= self.graph.decls.len) return;
            if (self.global_aug_decls.contains(did)) return;
            try self.global_aug_decls.put(self.scratch, did, {});
            const d = self.graph.decls[did];
            if (d.kind == .namespace_decl) {
                for (d.kind.namespace_decl) |cid| {
                    try self.markGlobalScopeDeclRecursive(cid);
                }
            }
            for (d.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].kind == .namespace_decl) {
                    try self.markGlobalScopeDeclRecursive(mid);
                }
            }
        }

        fn isBuiltinMappedReference(
            self: *const Self,
            ref_name: []const u8,
            type_args_len: usize,
            target_decl: ?u32,
        ) bool {
            const is_bvk = lower_types.BinaryViewKind.fromTypeName(ref_name) != null;
            const is_boxed = (type_args_len == 0 and lower_types.BoxedIntrinsicKind.fromTypeName(ref_name) != null);
            if (!is_bvk and !is_boxed) return false;

            const td = target_decl orelse return true;
            if (td >= self.graph.decls.len) return true;
            if (self.global_aug_decls.contains(td)) return true;

            if (self.decl_to_cand.get(td)) |c_idx| {
                if (c_idx < self.candidates.items.len and self.candidates.items[c_idx].source_mod_ids.items.len == 0) {
                    const cand_spec = self.candidates.items[c_idx].wire_specifier;
                    if (lower_types.isBuiltinBufferOrGlobalsModule(cand_spec, "")) {
                        return true;
                    }
                }
            }

            var cur_ns_opt = self.child_to_parent_ns.get(td);
            var ns_depth: usize = 0;
            while (cur_ns_opt) |ns_id| : (ns_depth += 1) {
                if (ns_depth >= 32 or ns_id >= self.graph.decls.len) break;
                const ns_name = self.str(self.graph.decls[ns_id].name);
                if (lower_types.isBuiltinBufferOrGlobalsModule(ns_name, "")) {
                    return true;
                }
                cur_ns_opt = self.child_to_parent_ns.get(ns_id);
            }

            const owner_mid = self.findGraphModuleIndexById(self.graph.decls[td].module) orelse return true;
            const owner_mod = self.graph.modules[owner_mid];
            if (self.isBundledLibModule(owner_mod)) return true;
            if (lower_types.isBuiltinBufferOrGlobalsModule(self.str(owner_mod.specifier), self.str(owner_mod.file_path))) {
                return true;
            }
            return false;
        }

        fn isBuiltinProtocolTarget(self: *const Self, target_decl: ?u32) bool {
            const td = target_decl orelse return true;
            if (td >= self.graph.decls.len) return true;
            if (self.global_aug_decls.contains(td)) return true;

            if (self.decl_to_cand.get(td)) |c_idx| {
                if (c_idx < self.candidates.items.len and self.candidates.items[c_idx].source_mod_ids.items.len == 0) {
                    const cand_spec = self.candidates.items[c_idx].wire_specifier;
                    if (lower_types.isBuiltinBufferOrGlobalsModule(cand_spec, "")) return true;
                }
            }

            var cur_ns_opt = self.child_to_parent_ns.get(td);
            var ns_depth: usize = 0;
            while (cur_ns_opt) |ns_id| : (ns_depth += 1) {
                if (ns_depth >= 32 or ns_id >= self.graph.decls.len) break;
                const ns_name = self.str(self.graph.decls[ns_id].name);
                if (lower_types.isBuiltinBufferOrGlobalsModule(ns_name, "")) return true;
                cur_ns_opt = self.child_to_parent_ns.get(ns_id);
            }

            const owner_mid = self.findGraphModuleIndexById(self.graph.decls[td].module) orelse return true;
            const owner_mod = self.graph.modules[owner_mid];
            if (self.isBundledLibModule(owner_mod)) return true;
            const fpath = self.str(owner_mod.file_path);
            if (lower_types.isBuiltinBufferOrGlobalsModule(self.str(owner_mod.specifier), fpath)) return true;
            if (std.mem.endsWith(u8, fpath, "/disposable.d.ts") or std.mem.endsWith(u8, fpath, "/iterators.d.ts")) return true;
            return false;
        }

        fn classifyBuiltinProtocolReference(
            self: *const Self,
            ref_name: []const u8,
            target_decl: ?u32,
        ) ?lower_protocols.BuiltinProtocolKind {
            const kind = lower_protocols.classifyBuiltinProtocolRef(ref_name) orelse return null;
            if (!self.isBuiltinProtocolTarget(target_decl)) return null;
            return kind;
        }

        fn typeShouldUnwrapAliasInReturnPos(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth >= 8 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .reference => |ref| blk: {
                    if (self.classifyBuiltinProtocolReference(self.str(ref.target_name), ref.target_decl)) |pk| {
                        if (pk == .iterable) break :blk true;
                    }
                    const stripped = lower_types.stripGlobalQualifier(self.str(ref.target_name));
                    if (std.mem.eql(u8, stripped, "Promise") or std.mem.eql(u8, stripped, "PromiseLike")) {
                        if (ref.target_decl == null or self.isBundledLibDecl(ref.target_decl.?)) {
                            break :blk true;
                        }
                    }
                    if (std.mem.eql(u8, stripped, "NoInfer") and ref.type_args.len > 0) {
                        break :blk self.typeShouldUnwrapAliasInReturnPos(ref.type_args[0], depth + 1);
                    }
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                            const alias_rhs = self.graph.decls[td].kind.type_alias_decl;
                            if (alias_rhs != ty_id and self.typeShouldUnwrapAliasInReturnPos(alias_rhs, depth + 1)) break :blk true;
                        }
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn typeHasTopLevelPositionalIterable(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth >= 8 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .reference => |ref| blk: {
                    if (self.classifyBuiltinProtocolReference(self.str(ref.target_name), ref.target_decl)) |pk| {
                        if (pk == .iterable) break :blk true;
                        if (std.mem.eql(u8, lower_types.stripGlobalQualifier(self.str(ref.target_name)), "Promise") or
                            std.mem.eql(u8, lower_types.stripGlobalQualifier(self.str(ref.target_name)), "PromiseLike"))
                        {
                            if (ref.type_args.len > 0 and self.typeHasTopLevelPositionalIterable(ref.type_args[0], depth + 1)) break :blk true;
                        }
                    } else {
                        const stripped = lower_types.stripGlobalQualifier(self.str(ref.target_name));
                        if (std.mem.eql(u8, stripped, "Promise") or std.mem.eql(u8, stripped, "PromiseLike") or std.mem.eql(u8, stripped, "NoInfer")) {
                            if (ref.type_args.len > 0 and self.typeHasTopLevelPositionalIterable(ref.type_args[0], depth + 1)) break :blk true;
                        } else if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                                const alias_rhs = self.graph.decls[td].kind.type_alias_decl;
                                if (alias_rhs != ty_id and self.typeHasTopLevelPositionalIterable(alias_rhs, depth + 1)) break :blk true;
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id and self.typeHasTopLevelPositionalIterable(rt, depth + 1)) break :blk true;
                                }
                            }
                        }
                    }
                    break :blk false;
                },
                .union_type => |arms| blk: {
                    for (arms) |aid| {
                        if (self.typeHasTopLevelPositionalIterable(aid, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn hasProtocolInGraphTypes(self: *const Self, ty_ids: []const u32, depth: usize) bool {
            if (depth > 12) return false;
            for (ty_ids) |tid| {
                if (tid >= self.graph.types.len) continue;
                const tn = self.graph.types[tid];
                switch (tn.kind) {
                    .reference => |ref| {
                        if (self.classifyBuiltinProtocolReference(self.str(ref.target_name), ref.target_decl) != null) {
                            return true;
                        }
                        if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len) {
                                const bd = self.graph.decls[td];
                                switch (bd.kind) {
                                    .type_alias_decl => |ta_ty| {
                                        if (ta_ty != tid and self.hasProtocolInGraphTypes(&.{ta_ty}, depth + 1)) return true;
                                    },
                                    .interface_decl => |iface| {
                                        for (iface.methods) |m| {
                                            if (m.computed_symbol) |cs| {
                                                if (lower_protocols.classifyProtocolSymbolKey(cs, if (cs == .custom) self.str(cs.custom) else "") != null) return true;
                                            }
                                        }
                                        for (iface.properties) |pid| {
                                            if (pid < self.graph.properties.len) {
                                                if (self.graph.properties[pid].computed_symbol) |cs| {
                                                    if (lower_protocols.classifyProtocolSymbolKey(cs, if (cs == .custom) self.str(cs.custom) else "") != null) return true;
                                                }
                                            }
                                        }
                                    },
                                    .class_decl => |cls| {
                                        for (cls.methods) |m| {
                                            if (m.computed_symbol) |cs| {
                                                if (lower_protocols.classifyProtocolSymbolKey(cs, if (cs == .custom) self.str(cs.custom) else "") != null) return true;
                                            }
                                        }
                                        for (cls.properties) |pid| {
                                            if (pid < self.graph.properties.len) {
                                                if (self.graph.properties[pid].computed_symbol) |cs| {
                                                    if (lower_protocols.classifyProtocolSymbolKey(cs, if (cs == .custom) self.str(cs.custom) else "") != null) return true;
                                                }
                                            }
                                        }
                                    },
                                    else => {},
                                }
                            }
                        }
                    },
                    .object_literal => |obj| {
                        for (obj.properties) |pid| {
                            if (pid < self.graph.properties.len) {
                                if (self.graph.properties[pid].computed_symbol) |cs| {
                                    if (lower_protocols.classifyProtocolSymbolKey(cs, if (cs == .custom) self.str(cs.custom) else "") != null) return true;
                                }
                            }
                        }
                    },
                    .intersection => |parts| {
                        if (self.hasProtocolInGraphTypes(parts, depth + 1)) return true;
                    },
                    else => {},
                }
            }
            return false;
        }

        const ExtractedStructProtocols = struct {
            iterator_elem_ty: ?*const TypeIr = null,
            async_iterator_elem_ty: ?*const TypeIr = null,
            has_sync_dispose: bool = false,
            has_async_dispose: bool = false,

            fn hasAny(self: ExtractedStructProtocols) bool {
                return self.iterator_elem_ty != null or
                    self.async_iterator_elem_ty != null or
                    self.has_sync_dispose or
                    self.has_async_dispose;
            }
        };

        fn tryExtractIteratorResultPayload(
            self: *Self,
            res_tid: u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            depth: usize,
        ) error{OutOfMemory}!?*const TypeIr {
            if (depth > 8 or res_tid >= self.graph.types.len) return null;
            const tn = self.graph.types[res_tid];
            switch (tn.kind) {
                .reference => |ref| {
                    const rname = self.str(ref.target_name);
                    if (lower_protocols.isIteratorResultWrapperName(rname) and ref.type_args.len > 0) {
                        var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                        defer visited.deinit(self.scratch);
                        return try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                    }
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                            if (tn.resolved_type) |rt| {
                                if (rt != res_tid) {
                                    return self.tryExtractIteratorResultPayload(rt, active_tps, self_ident_opt, imports_used, needs_runtime, depth + 1);
                                }
                            }
                        }
                    }
                },
                .union_type => |arms| {
                    for (arms) |aid| {
                        if (aid >= self.graph.types.len) continue;
                        const atn = self.graph.types[aid];
                        if (atn.kind == .reference) {
                            const arname = lower_types.stripGlobalQualifier(self.str(atn.kind.reference.target_name));
                            if (std.mem.eql(u8, arname, "IteratorReturnResult") or std.mem.eql(u8, arname, "BuiltinIteratorReturn")) continue;
                        }
                        if (atn.kind == .object_literal) {
                            var is_done_true = false;
                            for (atn.kind.object_literal.properties) |pid| {
                                if (pid >= self.graph.properties.len) continue;
                                const p = self.graph.properties[pid];
                                if (std.mem.eql(u8, self.str(p.name), "done") and p.ty < self.graph.types.len) {
                                    const dtk = self.graph.types[p.ty].kind;
                                    if (dtk == .literal and dtk.literal == .boolean and dtk.literal.boolean) {
                                        is_done_true = true;
                                        break;
                                    }
                                }
                            }
                            if (is_done_true) continue;
                        }
                        if (try self.tryExtractIteratorResultPayload(aid, active_tps, self_ident_opt, imports_used, needs_runtime, depth + 1)) |found| {
                            return found;
                        }
                    }
                },
                .object_literal => |obj| {
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.computed_symbol == null and std.mem.eql(u8, self.str(p.name), "value")) {
                            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                            defer visited.deinit(self.scratch);
                            return try self.lowerType(p.ty, false, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                        }
                    }
                },
                else => {},
            }
            return null;
        }

        fn extractIteratorElemFromReturnType(
            self: *Self,
            ret_tid: u32,
            is_async: bool,
            env: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            depth: usize,
        ) error{OutOfMemory}!*const TypeIr {
            needs_runtime.* = true;
            if (depth > 8 or ret_tid >= self.graph.types.len) {
                return self.makeType(.js_value);
            }
            const active_tps = try self.resolveHeritageActiveTps(
                env,
                owner_active_tps,
                self_ident_opt,
                imports_used,
                needs_runtime,
                env_cache,
                0,
            );

            {
                var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer visited.deinit(self.scratch);
                const lowered = try self.lowerType(ret_tid, true, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                if (!is_async and lowered.* == .js_iterator) return lowered.js_iterator;
                if (is_async and lowered.* == .js_async_iterator) return lowered.js_async_iterator;
            }

            const tn = self.graph.types[ret_tid];
            switch (tn.kind) {
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const bd = self.graph.decls[td];
                            const child_env = try self.buildHeritageEnv(env, bd.type_params, ref.type_args);
                            const child_tps = try self.resolveHeritageActiveTps(
                                child_env,
                                owner_active_tps,
                                self_ident_opt,
                                imports_used,
                                needs_runtime,
                                env_cache,
                                0,
                            );
                            switch (bd.kind) {
                                .type_alias_decl => |ta_ty| {
                                    if (ta_ty != ret_tid) {
                                        return self.extractIteratorElemFromReturnType(ta_ty, is_async, child_env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, depth + 1);
                                    }
                                },
                                .interface_decl => |iface| {
                                    for (iface.methods) |m| {
                                        if (m.computed_symbol == null and std.mem.eql(u8, self.str(m.name), "next") and m.signatures.len > 0) {
                                            const sid = m.signatures[0];
                                            if (sid < self.graph.signatures.len) {
                                                var nret = self.graph.signatures[sid].return_type;
                                                if (is_async and nret < self.graph.types.len and self.graph.types[nret].kind == .reference) {
                                                    const pr = self.graph.types[nret].kind.reference;
                                                    const prn = lower_types.stripGlobalQualifier(self.str(pr.target_name));
                                                    if ((std.mem.eql(u8, prn, "Promise") or std.mem.eql(u8, prn, "PromiseLike")) and pr.type_args.len > 0) {
                                                        nret = pr.type_args[0];
                                                    }
                                                }
                                                if (try self.tryExtractIteratorResultPayload(nret, child_tps, self_ident_opt, imports_used, needs_runtime, 0)) |el| {
                                                    return el;
                                                }
                                            }
                                        }
                                    }
                                },
                                .class_decl => |cls| {
                                    for (cls.methods) |m| {
                                        if (m.computed_symbol == null and std.mem.eql(u8, self.str(m.name), "next") and m.signatures.len > 0) {
                                            const sid = m.signatures[0];
                                            if (sid < self.graph.signatures.len) {
                                                var nret = self.graph.signatures[sid].return_type;
                                                if (is_async and nret < self.graph.types.len and self.graph.types[nret].kind == .reference) {
                                                    const pr = self.graph.types[nret].kind.reference;
                                                    const prn = lower_types.stripGlobalQualifier(self.str(pr.target_name));
                                                    if ((std.mem.eql(u8, prn, "Promise") or std.mem.eql(u8, prn, "PromiseLike")) and pr.type_args.len > 0) {
                                                        nret = pr.type_args[0];
                                                    }
                                                }
                                                if (try self.tryExtractIteratorResultPayload(nret, child_tps, self_ident_opt, imports_used, needs_runtime, 0)) |el| {
                                                    return el;
                                                }
                                            }
                                        }
                                    }
                                },
                                else => {},
                            }
                            if (bd.kind == .interface_decl or bd.kind == .class_decl) {
                                switch (bd.kind) {
                                    .interface_decl => |cif| {
                                        for (cif.extends_clauses) |hc| {
                                            const base_el = try self.extractIteratorElemFromReturnType(
                                                hc.target_type,
                                                is_async,
                                                child_env,
                                                owner_active_tps,
                                                self_ident_opt,
                                                imports_used,
                                                needs_runtime,
                                                env_cache,
                                                depth + 1,
                                            );
                                            if (base_el.* != .js_value) return base_el;
                                        }
                                    },
                                    .class_decl => |ccls| {
                                        if (ccls.extends_clause) |hc| {
                                            const base_el = try self.extractIteratorElemFromReturnType(
                                                hc.target_type,
                                                is_async,
                                                child_env,
                                                owner_active_tps,
                                                self_ident_opt,
                                                imports_used,
                                                needs_runtime,
                                                env_cache,
                                                depth + 1,
                                            );
                                            if (base_el.* != .js_value) return base_el;
                                        }
                                        for (ccls.implements_clauses) |hc| {
                                            const base_el = try self.extractIteratorElemFromReturnType(
                                                hc.target_type,
                                                is_async,
                                                child_env,
                                                owner_active_tps,
                                                self_ident_opt,
                                                imports_used,
                                                needs_runtime,
                                                env_cache,
                                                depth + 1,
                                            );
                                            if (base_el.* != .js_value) return base_el;
                                        }
                                    },
                                    else => {},
                                }
                            }
                        }
                    }
                },
                .object_literal => |obj| {
                    const split = try self.splitObjectLiteralPropsAndMethodsWithEnv(obj.properties, env);
                    for (split.methods) |sm| {
                        if (sm.method.computed_symbol == null and std.mem.eql(u8, self.str(sm.method.name), "next") and sm.method.signatures.len > 0) {
                            const sid = sm.method.signatures[0];
                            if (sid < self.graph.signatures.len) {
                                var nret = self.graph.signatures[sid].return_type;
                                if (is_async and nret < self.graph.types.len and self.graph.types[nret].kind == .reference) {
                                    const pr = self.graph.types[nret].kind.reference;
                                    const prn = lower_types.stripGlobalQualifier(self.str(pr.target_name));
                                    if ((std.mem.eql(u8, prn, "Promise") or std.mem.eql(u8, prn, "PromiseLike")) and pr.type_args.len > 0) {
                                        nret = pr.type_args[0];
                                    }
                                }
                                if (try self.tryExtractIteratorResultPayload(nret, active_tps, self_ident_opt, imports_used, needs_runtime, 0)) |el| {
                                    return el;
                                }
                            }
                        }
                    }
                },
                else => {},
            }
            return self.makeType(.js_value);
        }

        fn applyProtocolSymbolMethod(
            self: *Self,
            cs: @TypeOf(self.graph.properties[0].computed_symbol.?),
            sig_ids: []const u32,
            env: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            out: *ExtractedStructProtocols,
        ) error{OutOfMemory}!void {
            const custom_txt = if (cs == .custom) self.str(cs.custom) else "";
            const psk = lower_protocols.classifyProtocolSymbolKey(cs, custom_txt) orelse return;
            needs_runtime.* = true;
            switch (psk) {
                .dispose => out.has_sync_dispose = true,
                .async_dispose => out.has_async_dispose = true,
                .iterator => {
                    if (out.iterator_elem_ty == null) {
                        if (sig_ids.len > 0 and sig_ids[0] < self.graph.signatures.len) {
                            out.iterator_elem_ty = try self.extractIteratorElemFromReturnType(
                                self.graph.signatures[sig_ids[0]].return_type,
                                false,
                                env,
                                owner_active_tps,
                                self_ident_opt,
                                imports_used,
                                needs_runtime,
                                env_cache,
                                0,
                            );
                        } else {
                            out.iterator_elem_ty = try self.makeType(.js_value);
                        }
                    }
                },
                .async_iterator => {
                    if (out.async_iterator_elem_ty == null) {
                        if (sig_ids.len > 0 and sig_ids[0] < self.graph.signatures.len) {
                            out.async_iterator_elem_ty = try self.extractIteratorElemFromReturnType(
                                self.graph.signatures[sig_ids[0]].return_type,
                                true,
                                env,
                                owner_active_tps,
                                self_ident_opt,
                                imports_used,
                                needs_runtime,
                                env_cache,
                                0,
                            );
                        } else {
                            out.async_iterator_elem_ty = try self.makeType(.js_value);
                        }
                    }
                },
            }
        }

        fn applyProtocolSymbolProp(
            self: *Self,
            pid: u32,
            env: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            out: *ExtractedStructProtocols,
        ) error{OutOfMemory}!void {
            if (pid >= self.graph.properties.len) return;
            const p = self.graph.properties[pid];
            if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.modifiers.optional_mod) return;
            const cs = p.computed_symbol orelse return;
            var sigs: std.ArrayList(u32) = .empty;
            defer sigs.deinit(self.scratch);
            try self.collectMethodSigsFromType(p.ty, &sigs, 0);
            try self.applyProtocolSymbolMethod(cs, sigs.items, env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, out);
        }

        fn collectProtocolsFromGraphType(
            self: *Self,
            ty_id: u32,
            env: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            visited_decls: *std.AutoHashMapUnmanaged(u32, void),
            out: *ExtractedStructProtocols,
            depth: usize,
        ) error{OutOfMemory}!void {
            if (depth > 12 or ty_id >= self.graph.types.len) return;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .array, .readonly_array => |elem_id| {
                    needs_runtime.* = true;
                    if (out.iterator_elem_ty == null) {
                        const active_tps = try self.resolveHeritageActiveTps(env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, 0);
                        var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                        defer visited.deinit(self.scratch);
                        out.iterator_elem_ty = try self.lowerType(elem_id, false, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                    }
                },
                .intersection => |parts| {
                    if (self.detectOpenPrimitiveIntersection(parts) != null or
                        self.detectBrandedPrimitiveIntersection(parts, 0) != null) return;
                    for (parts) |part_id| {
                        try self.collectProtocolsFromGraphType(part_id, env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, visited_decls, out, depth + 1);
                    }
                },
                .object_literal => |obj| {
                    const split = try self.splitObjectLiteralPropsAndMethodsWithEnv(obj.properties, env);
                    for (split.methods) |sm| {
                        if (sm.method.modifiers.static_mod or sm.method.modifiers.private_mod or sm.method.modifiers.protected_mod or sm.method.modifiers.optional_mod) continue;
                        if (sm.method.computed_symbol) |cs| {
                            try self.applyProtocolSymbolMethod(cs, sm.method.signatures, sm.env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, out);
                        }
                    }
                    for (split.props) |sp| {
                        try self.applyProtocolSymbolProp(sp.pid, sp.env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, out);
                    }
                },
                .reference => |ref| {
                    const rname = self.str(ref.target_name);
                    const stripped_rname = lower_types.stripGlobalQualifier(rname);
                    const array_or_set_iterable = self.isBuiltinProtocolTarget(ref.target_decl) and
                        (std.mem.eql(u8, stripped_rname, "Array") or
                            std.mem.eql(u8, stripped_rname, "ReadonlyArray") or
                            std.mem.eql(u8, stripped_rname, "Set") or
                            std.mem.eql(u8, stripped_rname, "ReadonlySet"));
                    if (self.classifyBuiltinProtocolReference(rname, ref.target_decl) orelse
                        (if (array_or_set_iterable) @as(?lower_protocols.BuiltinProtocolKind, .iterable) else null)) |pk|
                    {
                        needs_runtime.* = true;
                        const active_tps = try self.resolveHeritageActiveTps(env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, 0);
                        switch (pk) {
                            .disposable => out.has_sync_dispose = true,
                            .async_disposable => out.has_async_dispose = true,
                            .iterable, .iterator => {
                                if (out.iterator_elem_ty == null) {
                                    if (ref.type_args.len > 0) {
                                        var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                                        defer visited.deinit(self.scratch);
                                        out.iterator_elem_ty = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                                    } else {
                                        out.iterator_elem_ty = try self.makeType(.js_value);
                                    }
                                }
                            },
                            .async_iterable, .async_iterator => {
                                if (out.async_iterator_elem_ty == null) {
                                    if (ref.type_args.len > 0) {
                                        var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                                        defer visited.deinit(self.scratch);
                                        out.async_iterator_elem_ty = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, &visited, imports_used, needs_runtime);
                                    } else {
                                        out.async_iterator_elem_ty = try self.makeType(.js_value);
                                    }
                                }
                            },
                        }
                        return;
                    }

                    const td = ref.target_decl orelse return;
                    if (td >= self.graph.decls.len) return;
                    const bd = self.graph.decls[td];
                    const child_env = try self.buildHeritageEnv(env, bd.type_params, ref.type_args);

                    switch (bd.kind) {
                        .type_alias_decl => |ta_ty| {
                            if (ta_ty != ty_id) {
                                try self.collectProtocolsFromGraphType(ta_ty, child_env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, visited_decls, out, depth + 1);
                            }
                        },
                        .interface_decl, .class_decl => {
                            const was_visited = visited_decls.contains(td);
                            if (!was_visited) {
                                try visited_decls.put(self.scratch, td, {});
                            }
                            defer if (!was_visited) {
                                _ = visited_decls.remove(td);
                            };
                            if (was_visited and bd.type_params.len == 0) return;

                            const bd_wire = if (bd.export_name) |esid| self.str(esid) else self.str(bd.name);
                            const inspectDecl = struct {
                                fn run(
                                    s: *Self,
                                    did: u32,
                                    c_env: ?*const HeritageEnv,
                                    o_tps: []const ActiveTypeParam,
                                    sid_opt: ?[]const u8,
                                    imp: *std.AutoHashMapUnmanaged(u32, void),
                                    nr: *bool,
                                    ec: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
                                    vd: *std.AutoHashMapUnmanaged(u32, void),
                                    res_out: *ExtractedStructProtocols,
                                    d_lvl: usize,
                                ) error{OutOfMemory}!void {
                                    const cd = s.graph.decls[did];
                                    switch (cd.kind) {
                                        .interface_decl => |cif| {
                                            for (cif.methods) |m| {
                                                if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.modifiers.optional_mod) continue;
                                                if (m.computed_symbol) |cs| {
                                                    try s.applyProtocolSymbolMethod(cs, m.signatures, c_env, o_tps, sid_opt, imp, nr, ec, res_out);
                                                }
                                            }
                                            for (cif.properties) |pid| {
                                                try s.applyProtocolSymbolProp(pid, c_env, o_tps, sid_opt, imp, nr, ec, res_out);
                                            }
                                            for (cif.extends_clauses) |hc| {
                                                try s.collectProtocolsFromGraphType(hc.target_type, c_env, o_tps, sid_opt, imp, nr, ec, vd, res_out, d_lvl + 1);
                                            }
                                        },
                                        .class_decl => |ccls| {
                                            for (ccls.methods) |m| {
                                                if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.modifiers.optional_mod) continue;
                                                if (m.computed_symbol) |cs| {
                                                    try s.applyProtocolSymbolMethod(cs, m.signatures, c_env, o_tps, sid_opt, imp, nr, ec, res_out);
                                                }
                                            }
                                            for (ccls.properties) |pid| {
                                                try s.applyProtocolSymbolProp(pid, c_env, o_tps, sid_opt, imp, nr, ec, res_out);
                                            }
                                            if (ccls.extends_clause) |hc| {
                                                try s.collectProtocolsFromGraphType(hc.target_type, c_env, o_tps, sid_opt, imp, nr, ec, vd, res_out, d_lvl + 1);
                                            }
                                            for (ccls.implements_clauses) |hc| {
                                                try s.collectProtocolsFromGraphType(hc.target_type, c_env, o_tps, sid_opt, imp, nr, ec, vd, res_out, d_lvl + 1);
                                            }
                                        },
                                        else => {},
                                    }
                                }
                            }.run;

                            try inspectDecl(self, td, child_env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, visited_decls, out, depth);
                            for (bd.merged_with) |mid| {
                                if (mid == td or mid >= self.graph.decls.len) continue;
                                const md = self.graph.decls[mid];
                                if (md.kind != .interface_decl and md.kind != .class_decl) continue;
                                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                                if (!merge_decls.sameWireName(bd_wire, m_wire)) continue;
                                const peer_env = try self.buildHeritageEnv(env, md.type_params, ref.type_args);
                                try inspectDecl(self, mid, peer_env, owner_active_tps, self_ident_opt, imports_used, needs_runtime, env_cache, visited_decls, out, depth);
                            }
                        },
                        else => {},
                    }
                },
                else => {},
            }
        }

        fn extractStructProtocols(
            self: *Self,
            raw_props: []const SourcedProp,
            raw_methods: []const SourcedMethod,
            sourced_bases: []const SourcedBaseClause,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
        ) error{OutOfMemory}!ExtractedStructProtocols {
            var out: ExtractedStructProtocols = .{};
            for (raw_methods) |sm| {
                if (sm.method.modifiers.static_mod or sm.method.modifiers.private_mod or
                    sm.method.modifiers.protected_mod or sm.method.modifiers.optional_mod) continue;
                if (sm.method.computed_symbol) |cs| {
                    try self.applyProtocolSymbolMethod(
                        cs,
                        sm.method.signatures,
                        sm.env,
                        owner_active_tps,
                        self_ident_opt,
                        imports_used,
                        needs_runtime,
                        env_cache,
                        &out,
                    );
                }
            }
            for (raw_props) |sp| {
                try self.applyProtocolSymbolProp(
                    sp.pid,
                    sp.env,
                    owner_active_tps,
                    self_ident_opt,
                    imports_used,
                    needs_runtime,
                    env_cache,
                    &out,
                );
            }
            var visited_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_decls.deinit(self.scratch);
            for (sourced_bases) |sb| {
                try self.collectProtocolsFromGraphType(
                    sb.target_type,
                    sb.env,
                    owner_active_tps,
                    self_ident_opt,
                    imports_used,
                    needs_runtime,
                    env_cache,
                    &visited_decls,
                    &out,
                    0,
                );
            }
            return out;
        }

        fn findGraphModuleIndexById(self: *const Self, mod_id: u32) ?usize {
            if (mod_id < self.graph.modules.len and self.graph.modules[mod_id].id == mod_id) {
                return mod_id;
            }
            for (self.graph.modules, 0..) |m, midx| {
                if (m.id == mod_id) return midx;
            }
            return null;
        }

        fn appendUniqueForeignExport(
            list: *std.ArrayList(ForeignExportEntry),
            allocator: std.mem.Allocator,
            entry: ForeignExportEntry,
        ) !void {
            for (list.items) |existing| {
                if (existing.decl_id == entry.decl_id and existing.is_default_export == entry.is_default_export) {
                    const same_override = if (existing.wire_name_override) |a|
                        (if (entry.wire_name_override) |b| std.mem.eql(u8, a, b) else false)
                    else
                        entry.wire_name_override == null;
                    if (same_override) return;
                }
            }
            try list.append(allocator, entry);
        }

        fn registerCanonicalDeclInCandidate(self: *Self, owner_cand: u32, did: u32) !void {
            if (did >= self.graph.decls.len) return;
            if (!self.ns_child_ids.contains(did)) {
                try appendUniqueU32(&self.candidates.items[owner_cand].decl_ids, self.scratch, did);
            }
            try self.appendDeclRecursiveToCand(did, owner_cand);
            const d = self.graph.decls[did];
            for (d.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].module == d.module) {
                    if (!self.ns_child_ids.contains(mid)) {
                        try appendUniqueU32(&self.candidates.items[owner_cand].decl_ids, self.scratch, mid);
                    }
                    try self.appendDeclRecursiveToCand(mid, owner_cand);
                }
            }
        }

        fn markJsExportedDecl(self: *Self, did: u32) !void {
            if (did >= self.graph.decls.len) return;
            const d = self.graph.decls[did];
            if (d.kind == .import_equals_decl and !d.modifiers.export_decl) return;
            try self.js_exported_decls.put(self.scratch, did, {});
            for (d.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].module == d.module) {
                    try self.js_exported_decls.put(self.scratch, mid, {});
                }
            }
        }

        fn isAmbientOnlyFileMod(owner_mod: anytype) bool {
            return owner_mod.ambient_modules.len > 0 and
                owner_mod.exports.len == 0 and
                owner_mod.star_re_exports.len == 0 and
                owner_mod.default_export == null and
                owner_mod.export_equals == null and
                owner_mod.global_augmentations.len == 0;
        }

        fn resolveOrCreateOwnerCandForFileMod(self: *Self, owner_mod: anytype) !u32 {
            if (self.source_mod_to_cand.get(owner_mod.id)) |existing| return existing;
            // If `owner_mod` is a single-block ambient-only `.d.ts` file, route same-file unowned
            // helpers to that sole ambient module. When `ambient_modules.len > 1`, Step 2a has
            // already routed helpers reachable from each ambient block; any truly unreferenced
            // orphan must NOT pollute `ambient_modules[0]` or create a primary file stub.
            if (isAmbientOnlyFileMod(owner_mod)) {
                if (owner_mod.ambient_modules.len == 1) {
                    if (try self.findAmbientCandidateIdx(self.str(owner_mod.ambient_modules[0].module_name))) |amb_c| {
                        return amb_c;
                    }
                }
                const ws = try self.deriveFileLogicalSpecifier(owner_mod);
                return try self.getOrCreateCandidate(ws, null);
            }
            const ws = try self.deriveFileLogicalSpecifier(owner_mod);
            return try self.getOrCreateCandidate(ws, owner_mod.id);
        }

        fn registerCandidateDeclOrForeignExport(
            self: *Self,
            c_idx: u32,
            current_mod_id: ?u32,
            did: u32,
            wire_override: ?[]const u8,
            is_default_export: bool,
        ) !void {
            if (did >= self.graph.decls.len) return;
            const d = self.graph.decls[did];

            if (d.kind == .re_export_decl) {
                const eff_name = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                if (d.kind.re_export_decl.is_namespace and std.mem.eql(u8, eff_name, "*")) {
                    if (!self.decl_to_cand.contains(did)) {
                        try self.decl_to_cand.put(self.scratch, did, c_idx);
                    }
                    if (!d.kind.re_export_decl.is_type_only) {
                        if (d.kind.re_export_decl.target_module) |tmid| {
                            try appendUniqueU32(
                                &self.candidates.items[c_idx].star_re_export_source_mods,
                                self.scratch,
                                tmid,
                            );
                        } else {
                            const mspec = self.str(d.kind.re_export_decl.module_specifier);
                            const cand_wire = self.candidates.items[c_idx].wire_specifier;
                            const is_self_star = std.mem.eql(u8, mspec, cand_wire) or
                                (std.mem.startsWith(u8, cand_wire, "node:") and std.mem.eql(u8, stripNodePrefix(mspec), stripNodePrefix(cand_wire)));
                            if (mspec.len > 0 and !is_self_star) {
                                var seen_spec = false;
                                for (self.candidates.items[c_idx].star_re_export_specs.items) |s| {
                                    if (std.mem.eql(u8, s, mspec)) {
                                        seen_spec = true;
                                        break;
                                    }
                                }
                                if (!seen_spec) {
                                    try self.candidates.items[c_idx].star_re_export_specs.append(self.scratch, mspec);
                                }
                            }
                        }
                    }
                    return;
                }
                if (self.ns_child_ids.contains(did)) {
                    if (self.decl_to_cand.get(did)) |existing_cand| {
                        if (existing_cand != c_idx) {
                            try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                                .decl_id = did,
                                .wire_name_override = wire_override,
                                .is_default_export = is_default_export,
                            });
                            return;
                        }
                    } else {
                        try self.decl_to_cand.put(self.scratch, did, c_idx);
                    }
                    try self.appendDeclRecursiveToCand(did, c_idx);
                    return;
                }
                if (!is_default_export and !d.modifiers.default_export and !d.kind.re_export_decl.is_namespace) {
                    const re = d.kind.re_export_decl;
                    const re_wire = wire_override orelse eff_name;
                    if (self.resolveTransitiveReExportTarget(did)) |root_td| {
                        const root_d = self.graph.decls[root_td];
                        const root_wire = if (root_d.export_name) |esid| self.str(esid) else self.str(root_d.name);

                        // Forward unmerged runtime value peers of merged symbols (`export { Buffer }`
                        // in `declare module "node:buffer"` where generic `interface Buffer<T>` and
                        // `var Buffer: BufferConstructor` live in `globals` as separate declarations!).
                        if (!re.is_type_only and (root_d.kind == .interface_decl or root_d.kind == .type_alias_decl)) {
                            const root_has_tps = self.hasMergedTypeParams(root_td);
                            for (root_d.merged_with) |mid| {
                                if (mid == root_td or mid >= self.graph.decls.len) continue;
                                const md = self.graph.decls[mid];
                                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                                if (!merge_decls.sameWireName(root_wire, m_wire)) continue;
                                const unmerged_value_peer = switch (md.kind) {
                                    .variable_decl, .namespace_decl => root_has_tps,
                                    .function_decl => root_has_tps or !(try merge_decls.fnAndNamespaceIdentCollide(self.scratch, root_wire)),
                                    else => false,
                                };
                                if (unmerged_value_peer) {
                                    if (self.decl_to_cand.get(mid)) |m_cand| {
                                        if (m_cand != c_idx) {
                                            try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                                                .decl_id = mid,
                                                .wire_name_override = wire_override,
                                                .is_default_export = false,
                                            });
                                        }
                                    }
                                }
                            }
                        }

                        // Skip self-noop re-exports (`declare module "buffer" { export * from "node:buffer"; }`
                        // merged into the same `buffer.zig` candidate) BEFORE prebinding names so we never
                        // emit `isUtf8_2`, `isAscii_2`, `atob_2`, etc.!
                        if (!self.ns_child_ids.contains(root_td) and
                            self.decl_to_cand.get(root_td) == c_idx and
                            std.mem.eql(u8, re_wire, root_wire))
                        {
                            if (!re.is_type_only) try self.markJsExportedDecl(root_td);
                            try appendUniqueU32(&self.candidates.items[c_idx].exported_decl_ids, self.scratch, root_td);
                            try self.deduped_decl_ids.put(self.scratch, did, {});
                            return;
                        }

                        // Also deduplicate multiple `re_export_decl`s (or `export import x = ...` +
                        // `re_export_decl`) in the same candidate targeting the exact same `root_td`
                        // under the exact same `re_wire` (e.g. `export import atob = globalThis.atob`
                        // in `"node:buffer"` + `export * from "node:buffer"` in `"buffer"`).
                        for (self.candidates.items[c_idx].exported_decl_ids.items) |ex_did| {
                            if (ex_did >= self.graph.decls.len) continue;
                            const ex_d = self.graph.decls[ex_did];
                            const ex_wire = if (ex_d.export_name) |esid| self.str(esid) else self.str(ex_d.name);
                            if (!std.mem.eql(u8, ex_wire, re_wire)) continue;
                            if (self.resolveTransitiveReExportTarget(ex_did)) |ex_root| {
                                if (StarCanonLoc.areMergedPeers(self.graph.decls, ex_root, root_td)) {
                                    try self.deduped_decl_ids.put(self.scratch, did, {});
                                    return;
                                }
                            }
                        }
                        for (self.candidates.items[c_idx].foreign_exports.items) |fe| {
                            if (fe.is_default_export or fe.decl_id >= self.graph.decls.len) continue;
                            const fe_d = self.graph.decls[fe.decl_id];
                            const fe_wire = fe.wire_name_override orelse
                                (if (fe_d.export_name) |esid| self.str(esid) else self.str(fe_d.name));
                            if (!std.mem.eql(u8, fe_wire, re_wire)) continue;
                            if (self.resolveTransitiveReExportTarget(fe.decl_id)) |fe_root| {
                                if (StarCanonLoc.areMergedPeers(self.graph.decls, fe_root, root_td)) {
                                    try self.deduped_decl_ids.put(self.scratch, did, {});
                                    return;
                                }
                            }
                        }
                    }
                }
                if (self.decl_to_cand.get(did)) |existing_cand| {
                    if (existing_cand != c_idx) {
                        try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                            .decl_id = did,
                            .wire_name_override = wire_override,
                            .is_default_export = is_default_export,
                        });
                        return;
                    }
                } else {
                    try self.decl_to_cand.put(self.scratch, did, c_idx);
                }
                try appendUniqueU32(&self.candidates.items[c_idx].decl_ids, self.scratch, did);
                try self.markJsExportedDecl(did);
                if (!is_default_export and !d.modifiers.default_export) {
                    try appendUniqueU32(&self.candidates.items[c_idx].exported_decl_ids, self.scratch, did);
                }
                try self.appendDeclRecursiveToCand(did, c_idx);
                return;
            }
            if (d.kind == .import_equals_decl) {
                if (self.ns_child_ids.contains(did)) {
                    if (self.decl_to_cand.get(did)) |existing_cand| {
                        if (existing_cand != c_idx) {
                            try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                                .decl_id = did,
                                .wire_name_override = wire_override,
                                .is_default_export = is_default_export,
                            });
                            return;
                        }
                    } else {
                        try self.decl_to_cand.put(self.scratch, did, c_idx);
                    }
                    try self.appendDeclRecursiveToCand(did, c_idx);
                    return;
                }
                if (d.modifiers.export_decl and !is_default_export and !d.modifiers.default_export) {
                    const ie_wire = wire_override orelse (if (d.export_name) |esid| self.str(esid) else self.str(d.name));
                    if (self.resolveTransitiveReExportTarget(did)) |root_td| {
                        if (root_td != did) {
                            for (self.candidates.items[c_idx].exported_decl_ids.items, 0..) |ex_did, ex_pos| {
                                if (ex_did == did or ex_did >= self.graph.decls.len) continue;
                                const ex_d = self.graph.decls[ex_did];
                                const ex_wire = if (ex_d.export_name) |esid| self.str(esid) else self.str(ex_d.name);
                                if (!std.mem.eql(u8, ex_wire, ie_wire)) continue;
                                if (self.resolveTransitiveReExportTarget(ex_did)) |ex_root| {
                                    if (StarCanonLoc.areMergedPeers(self.graph.decls, ex_root, root_td)) {
                                        if (ex_d.kind == .re_export_decl and ex_d.kind.re_export_decl.is_type_only and !d.kind.import_equals_decl.is_type_only) {
                                            // Upgrade synthetic type-only re-export (`buffer.buffer.d.ts`) to
                                            // runtime `export import atob = globalThis.atob` (`buffer.d.ts`) in-place!
                                            self.candidates.items[c_idx].exported_decl_ids.items[ex_pos] = did;
                                            for (self.candidates.items[c_idx].decl_ids.items) |*slot| {
                                                if (slot.* == ex_did) slot.* = did;
                                            }
                                            _ = self.decl_to_cand.remove(ex_did);
                                            try self.deduped_decl_ids.put(self.scratch, ex_did, {});
                                            try self.decl_to_cand.put(self.scratch, did, c_idx);
                                            try self.markJsExportedDecl(did);
                                            try self.appendDeclRecursiveToCand(did, c_idx);
                                        } else {
                                            try self.deduped_decl_ids.put(self.scratch, did, {});
                                        }
                                        return;
                                    }
                                }
                            }
                        }
                    }
                }
                if (self.decl_to_cand.get(did)) |existing_cand| {
                    if (existing_cand != c_idx) {
                        if (d.modifiers.export_decl or is_default_export) {
                            try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                                .decl_id = did,
                                .wire_name_override = wire_override,
                                .is_default_export = is_default_export,
                            });
                        }
                        return;
                    }
                } else {
                    try self.decl_to_cand.put(self.scratch, did, c_idx);
                }
                try appendUniqueU32(&self.candidates.items[c_idx].decl_ids, self.scratch, did);
                if (d.modifiers.export_decl) {
                    try self.markJsExportedDecl(did);
                }
                if (d.modifiers.export_decl and !is_default_export and !d.modifiers.default_export) {
                    try appendUniqueU32(&self.candidates.items[c_idx].exported_decl_ids, self.scratch, did);
                }
                try self.appendDeclRecursiveToCand(did, c_idx);
                return;
            }

            var owner_cand: u32 = c_idx;
            if (current_mod_id != null and d.module != current_mod_id.?) {
                if (self.decl_to_cand.get(did)) |existing_cand| {
                    owner_cand = existing_cand;
                } else if (self.findGraphModuleIndexById(d.module)) |om_idx| {
                    const owner_mod = self.graph.modules[om_idx];
                    if (!self.isBundledLibModule(owner_mod)) {
                        owner_cand = try self.resolveOrCreateOwnerCandForFileMod(owner_mod);
                        try self.registerCanonicalDeclInCandidate(owner_cand, did);
                        if (d.modifiers.export_decl or d.modifiers.default_export) {
                            try self.markJsExportedDecl(did);
                        }
                        if (!d.modifiers.default_export and !self.ns_child_ids.contains(did)) {
                            try appendUniqueU32(&self.candidates.items[owner_cand].exported_decl_ids, self.scratch, did);
                        }
                    } else {
                        owner_cand = c_idx;
                    }
                }
            } else if (self.decl_to_cand.get(did)) |existing_cand| {
                owner_cand = existing_cand;
            }

            if (owner_cand == c_idx) {
                try self.registerCanonicalDeclInCandidate(c_idx, did);
                if (!self.pure_export_equals_ns.contains(did)) {
                    try self.markJsExportedDecl(did);
                }
                if (!is_default_export and
                    !d.modifiers.default_export and
                    !self.ns_child_ids.contains(did) and
                    !self.pure_export_equals_ns.contains(did))
                {
                    try appendUniqueU32(&self.candidates.items[c_idx].exported_decl_ids, self.scratch, did);
                }
            } else {
                try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                    .decl_id = did,
                    .wire_name_override = wire_override,
                    .is_default_export = is_default_export,
                });
                // When a foreign export points at a generic interface/type-alias half of a
                // merged value+type symbol (e.g. `export { Buffer }` in `node:buffer` where
                // `interface Buffer<TArrayBuffer>` cannot merge `var Buffer: BufferConstructor`),
                // also forward its unmerged runtime value peers from the same owner candidate.
                if (!is_default_export and
                    (d.kind == .interface_decl or d.kind == .type_alias_decl) and
                    self.hasMergedTypeParams(did))
                {
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .variable_decl and md.kind != .function_decl and md.kind != .namespace_decl) continue;
                        if (self.decl_to_cand.get(mid) != owner_cand) continue;
                        try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                            .decl_id = mid,
                            .wire_name_override = wire_override,
                            .is_default_export = false,
                        });
                    }
                }
            }
        }

        fn wouldCreateNamespaceParentCycle(self: *const Self, child_id: u32, parent_id: u32) bool {
            if (child_id == parent_id) return true;
            var cur = parent_id;
            var hops: usize = 0;
            while (hops <= self.graph.decls.len) : (hops += 1) {
                const next = self.child_to_parent_ns.get(cur) orelse return false;
                if (next == child_id or next == cur) return true;
                cur = next;
            }
            return true;
        }

        fn registerExportEqualsForCandidate(
            self: *Self,
            c_idx: u32,
            current_mod_id: ?u32,
            raw_eq_id: u32,
        ) !void {
            if (raw_eq_id >= self.graph.decls.len) return;

            var target_id = raw_eq_id;
            var hops: usize = 0;
            while (hops < 32 and target_id < self.graph.decls.len) : (hops += 1) {
                const td = self.graph.decls[target_id];
                switch (td.kind) {
                    .import_equals_decl => |ie| {
                        if (ie.target_decl) |next_id| {
                            if (next_id == target_id) break;
                            target_id = next_id;
                            continue;
                        }
                        if (ie.module_specifier) |msid| {
                            const mspec = self.str(msid);
                            if (mspec.len > 0) {
                                var seen_spec = false;
                                for (self.candidates.items[c_idx].star_re_export_specs.items) |s| {
                                    if (std.mem.eql(u8, s, mspec)) {
                                        seen_spec = true;
                                        break;
                                    }
                                }
                                if (!seen_spec) {
                                    try self.candidates.items[c_idx].star_re_export_specs.append(self.scratch, mspec);
                                }
                            }
                        }
                        try self.registerCandidateDeclOrForeignExport(c_idx, current_mod_id, raw_eq_id, null, false);
                        return;
                    },
                    .re_export_decl => |re| {
                        if (self.isAliasedNamespaceChildReExport(target_id) != null) {
                            if (self.candidates.items[c_idx].export_equals_subns_decl_id == null) {
                                self.candidates.items[c_idx].export_equals_subns_decl_id = target_id;
                            }
                        }
                        if (re.target_decl) |next_id| {
                            if (next_id == target_id) break;
                            target_id = next_id;
                            continue;
                        }
                        break;
                    },
                    else => break,
                }
            }

            if (target_id >= self.graph.decls.len) return;
            const eq_decl = self.graph.decls[target_id];

            var peer_ids: std.ArrayList(u32) = .empty;
            defer peer_ids.deinit(self.scratch);
            try appendUniqueU32(&peer_ids, self.scratch, target_id);
            for (eq_decl.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].module == eq_decl.module) {
                    try appendUniqueU32(&peer_ids, self.scratch, mid);
                }
            }

            // Choose primary declaration (prefer class/function/variable/interface/enum/type_alias over namespace)
            var primary_id = target_id;
            var has_non_ns_peer = false;
            for (peer_ids.items) |pid| {
                const pd = self.graph.decls[pid];
                if (pd.kind != .namespace_decl) {
                    if (!has_non_ns_peer or pd.kind == .class_decl or pd.kind == .function_decl) {
                        primary_id = pid;
                    }
                    has_non_ns_peer = true;
                }
            }

            self.candidates.items[c_idx].export_equals_decl_id = primary_id;

            if (!has_non_ns_peer and eq_decl.kind == .namespace_decl) {
                try self.pure_export_equals_ns.put(self.scratch, target_id, {});
            }

            // Register primary + merged peers into candidate (same-module or foreign)
            for (peer_ids.items) |pid| {
                try self.registerCandidateDeclOrForeignExport(c_idx, current_mod_id, pid, null, false);
            }

            // Expose exported members of any `export =` namespace peer at module top-level
            // (e.g. `join`, `resolve`, `posix` from `export = path`, or `once`, `on`, `Abortable`
            // from `export = EventEmitter`).
            const primary_owner = self.decl_to_cand.get(primary_id);
            if (primary_owner != null and primary_owner.? != c_idx and self.candidates.items[c_idx].export_equals_subns_decl_id == null) {
                const owner_spec = stripNodePrefix(self.candidates.items[primary_owner.?].wire_specifier);
                const cur_spec = stripNodePrefix(self.candidates.items[c_idx].wire_specifier);
                if (cur_spec.len > owner_spec.len + 1 and
                    std.mem.startsWith(u8, cur_spec, owner_spec) and
                    cur_spec[owner_spec.len] == '/')
                {
                    const sub_wire = cur_spec[owner_spec.len + 1 ..];
                    outer_sub: for (peer_ids.items) |pid| {
                        const pd = self.graph.decls[pid];
                        if (pd.kind != .namespace_decl) continue;
                        for (pd.kind.namespace_decl) |cid| {
                            if (self.isAliasedNamespaceChildReExport(cid) == null) continue;
                            const cd = self.graph.decls[cid];
                            const c_wire = if (cd.export_name) |esid| self.str(esid) else self.str(cd.name);
                            if (std.mem.eql(u8, c_wire, sub_wire)) {
                                self.candidates.items[c_idx].export_equals_subns_decl_id = cid;
                                break :outer_sub;
                            }
                        }
                    }
                }
            }
            for (peer_ids.items) |pid| {
                const pd = self.graph.decls[pid];
                if (pd.kind != .namespace_decl) continue;
                for (pd.kind.namespace_decl) |cid| {
                    if (cid >= self.graph.decls.len) continue;
                    if (cid == pid or cid == primary_id) continue;
                    var is_peer = false;
                    for (peer_ids.items) |check_pid| {
                        if (cid == check_pid) {
                            is_peer = true;
                            break;
                        }
                    }
                    if (is_peer) continue;
                    const cd = self.graph.decls[cid];
                    if (!cd.modifiers.export_decl and !cd.modifiers.default_export) continue;
                    // Skip self-re-export aliases (`export { EventEmitter }`) whose wire name matches `eq_decl`.
                    const child_wire = if (cd.export_name) |esid| self.str(esid) else self.str(cd.name);
                    if (has_non_ns_peer and std.mem.eql(u8, child_wire, self.str(eq_decl.name))) continue;

                    if (primary_owner != null and primary_owner.? == c_idx) {
                        try appendUniqueU32(&self.candidates.items[c_idx].same_mod_export_equals_children, self.scratch, cid);
                        try appendUniqueU32(&self.candidates.items[c_idx].exported_decl_ids, self.scratch, cid);
                    } else {
                        try appendUniqueForeignExport(&self.candidates.items[c_idx].foreign_exports, self.scratch, .{
                            .decl_id = cid,
                            .wire_name_override = null,
                            .is_default_export = false,
                        });
                    }
                }
            }
        }

        fn discoverCandidates(self: *Self) !void {
            // Record all global augmentation / script-global declarations across all modules
            // (both user ambient globals and `@types/node` / lib global augmentations).
            for (self.graph.modules) |mod| {
                for (mod.global_augmentations) |did| {
                    try self.markGlobalScopeDeclRecursive(did);
                }
            }

            // Precompute all declarations owned as children of a `namespace_decl` so nested
            // namespace members are never hoisted to top-level `cand.decl_ids`.
            // Guard against cyclic or self-merged namespace children (`H1`/`H2`).
            for (self.graph.decls) |d| {
                if (d.kind == .namespace_decl) {
                    for (d.kind.namespace_decl) |cid| {
                        if (cid >= self.graph.decls.len) continue;
                        if (cid == d.id) continue;
                        var is_merged_peer = false;
                        for (d.merged_with) |mid| {
                            if (cid == mid) {
                                is_merged_peer = true;
                                break;
                            }
                        }
                        if (is_merged_peer) continue;
                        if (self.wouldCreateNamespaceParentCycle(cid, d.id)) continue;
                        try self.ns_child_ids.put(self.scratch, cid, {});
                        if (!self.child_to_parent_ns.contains(cid)) {
                            try self.child_to_parent_ns.put(self.scratch, cid, d.id);
                        }
                    }
                }
            }

            // Pre-mark pure `export = <namespace>` targets before Step 1a/2 so Step 1a doesn't
            // falsely mark the namespace wrapper itself as a named `.js_name` export.
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                for (mod.ambient_modules) |amb| {
                    if (amb.export_equals) |eq_id| {
                        if (eq_id < self.graph.decls.len) {
                            const ed = self.graph.decls[eq_id];
                            if (ed.kind == .namespace_decl) {
                                var has_non_ns = false;
                                for (ed.merged_with) |mid| {
                                    if (mid < self.graph.decls.len and self.graph.decls[mid].kind != .namespace_decl) {
                                        has_non_ns = true;
                                        break;
                                    }
                                }
                                if (!has_non_ns) try self.pure_export_equals_ns.put(self.scratch, eq_id, {});
                            }
                        }
                    }
                }
                if (mod.export_equals) |eq_id| {
                    if (eq_id < self.graph.decls.len) {
                        const ed = self.graph.decls[eq_id];
                        if (ed.kind == .namespace_decl) {
                            var has_non_ns = false;
                            for (ed.merged_with) |mid| {
                                if (mid < self.graph.decls.len and self.graph.decls[mid].kind != .namespace_decl) {
                                    has_non_ns = true;
                                    break;
                                }
                            }
                            if (!has_non_ns) try self.pure_export_equals_ns.put(self.scratch, eq_id, {});
                        }
                    }
                }
            }

            // 0g. Consolidate `mod.global_augmentations` into `"globals"` (`globals.zig`) BEFORE Step 1a
            // when a dedicated `"globals"` / `"globals.*"` / `"web-globals/*"` declaration file with
            // global augmentations exists in the graph (such as `@types/node`), or when nested inside an
            // ambient module file (`declare module "node:buffer" { global { ... } }`). Claiming global
            // declarations in `"globals"` first ensures `globals.zig` owns `Buffer`, `var Buffer`,
            // `NonSharedBuffer`, `AllowSharedBuffer`, `BufferConstructor`, `BufferEncoding`, etc. while
            // ambient modules (`"node:buffer"`) cleanly re-export them and file-private helpers
            // (`interface AbortController` / `interface Event` in `web-globals/*.d.ts`) stay isolated!
            var has_globals_hub = false;
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod) or mod.global_augmentations.len == 0) continue;
                const fspec = try self.deriveFileLogicalSpecifier(mod);
                if (std.mem.eql(u8, fspec, "globals") or
                    std.mem.startsWith(u8, fspec, "globals.") or
                    std.mem.startsWith(u8, fspec, "web-globals/"))
                {
                    has_globals_hub = true;
                    break;
                }
            }
            self.has_globals_hub = has_globals_hub;

            if (has_globals_hub) {
                for (self.graph.modules) |mod| {
                    if (self.isBundledLibModule(mod) or mod.global_augmentations.len == 0) continue;
                    const fspec = try self.deriveFileLogicalSpecifier(mod);
                    const g_src_mod: ?u32 = if (std.mem.eql(u8, fspec, "globals")) mod.id else null;
                    const g_idx = try self.getOrCreateCandidate("globals", g_src_mod);
                    for (mod.global_augmentations) |did| {
                        try self.registerCandidateDeclOrForeignExport(g_idx, null, did, null, false);
                    }
                }
            } else {
                for (self.graph.modules) |mod| {
                    if (self.isBundledLibModule(mod) or mod.global_augmentations.len == 0 or mod.ambient_modules.len == 0) continue;
                    const fspec = try self.deriveFileLogicalSpecifier(mod);
                    const g_src_mod: ?u32 = if (std.mem.eql(u8, fspec, "globals")) mod.id else null;
                    const g_idx = try self.getOrCreateCandidate("globals", g_src_mod);
                    for (mod.global_augmentations) |did| {
                        try self.registerCandidateDeclOrForeignExport(g_idx, null, did, null, false);
                    }
                }
            }

            // 1a. Ambient modules (`declare module "node:http" { ... }`): register canonical own
            // declarations first so cross-file ambient re-exports find their owning ambient module.
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                for (mod.ambient_modules) |amb| {
                    const amb_name = self.str(amb.module_name);
                    const c_idx = try self.getOrCreateCandidate(amb_name, null);
                    for (amb.decls) |did| {
                        if (did >= self.graph.decls.len) continue;
                        const d = self.graph.decls[did];
                        if (d.kind == .re_export_decl or d.kind == .import_equals_decl) continue;
                        if (d.module == mod.id and !self.decl_to_cand.contains(did)) {
                            try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, did, null, false);
                        }
                    }
                    if (amb.default_export) |def_id| {
                        if (def_id < self.graph.decls.len) {
                            const dd = self.graph.decls[def_id];
                            if (dd.kind != .re_export_decl and dd.kind != .import_equals_decl and dd.module == mod.id and !self.decl_to_cand.contains(def_id)) {
                                self.candidates.items[c_idx].default_export_decl_id = def_id;
                                try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, def_id, "default", true);
                            }
                        }
                    }
                    if (amb.export_equals) |eq_id| {
                        if (eq_id < self.graph.decls.len) {
                            const ed = self.graph.decls[eq_id];
                            if (ed.kind != .re_export_decl and ed.kind != .import_equals_decl and ed.module == mod.id) {
                                try self.registerExportEqualsForCandidate(c_idx, mod.id, eq_id);
                            }
                        }
                    }
                }
            }

            // 1a-helpers. Route unowned same-file helper declarations (`interface Hid` in
            // `declare module "p2" { interface Hid ... }` or `type ImplicitArrayBuffer` in
            // `buffer.buffer.d.ts` `declare module "node:buffer"`) BEFORE Step 1b processes
            // cross-block re-exports (`buffer.d.ts` `export { ImplicitArrayBuffer }`)!
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                for (mod.ambient_modules) |amb| {
                    const amb_cand = (try self.findAmbientCandidateIdx(self.str(amb.module_name))) orelse continue;
                    var seeds: std.ArrayList(u32) = .empty;
                    defer seeds.deinit(self.scratch);
                    for (amb.decls) |did| {
                        try appendUniqueU32(&seeds, self.scratch, did);
                        if (did < self.graph.decls.len and self.graph.decls[did].kind == .re_export_decl) {
                            if (self.resolveTransitiveReExportTarget(did)) |rtd| {
                                if (rtd < self.graph.decls.len and
                                    self.graph.decls[rtd].module == mod.id and
                                    !self.decl_to_cand.contains(rtd))
                                {
                                    try self.registerCanonicalDeclInCandidate(amb_cand, rtd);
                                    try appendUniqueU32(&seeds, self.scratch, rtd);
                                }
                            }
                        }
                    }
                    if (amb.default_export) |def_id| try appendUniqueU32(&seeds, self.scratch, def_id);
                    if (amb.export_equals) |eq_id| try appendUniqueU32(&seeds, self.scratch, eq_id);
                    try self.claimSameFileAmbientHelpers(amb_cand, mod.id, seeds.items);
                }
            }

            // 1b. Ambient modules: register re-exports and cross-ambient foreign exports.
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                for (mod.ambient_modules) |amb| {
                    const amb_name = self.str(amb.module_name);
                    const c_idx = try self.getOrCreateCandidate(amb_name, null);
                    if (amb.export_equals) |eq_id| {
                        try self.registerExportEqualsForCandidate(c_idx, mod.id, eq_id);
                    }
                    for (amb.decls) |did| {
                        try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, did, null, false);
                    }
                    if (amb.default_export) |def_id| {
                        self.candidates.items[c_idx].default_export_decl_id = def_id;
                        try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, def_id, "default", true);
                    }
                }
            }

            // 2. File-level module exports / star re-exports / export = / remaining global augmentations.
            // Reference-only (`/// <reference path="..." />`) and ambient-only (`declare module "..."`)
            // files do NOT create empty file-level candidates here.
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;

                const fspec = try self.deriveFileLogicalSpecifier(mod);
                const route_globals_to_hub = mod.global_augmentations.len > 0 and
                    (has_globals_hub or mod.ambient_modules.len > 0);

                if (route_globals_to_hub and mod.ambient_modules.len > 0) {
                    // Expose pure type aliases declared inside `declare module "node:<stem>" { global { type ... } }`
                    // (such as `BufferEncoding` in `buffer.d.ts`) on the matching ambient module as well!
                    const g_idx_opt = try self.findAmbientCandidateIdx("globals");
                    for (mod.ambient_modules) |amb| {
                        const amb_spec = stripNodePrefix(self.str(amb.module_name));
                        if (!std.mem.eql(u8, amb_spec, fspec)) continue;
                        if (try self.findAmbientCandidateIdx(self.str(amb.module_name))) |amb_cand| {
                            if (g_idx_opt == null or amb_cand != g_idx_opt.?) {
                                for (mod.global_augmentations) |did| {
                                    if (did >= self.graph.decls.len) continue;
                                    if (self.graph.decls[did].kind == .type_alias_decl) {
                                        try appendUniqueForeignExport(&self.candidates.items[amb_cand].foreign_exports, self.scratch, .{
                                            .decl_id = did,
                                            .wire_name_override = null,
                                            .is_default_export = false,
                                        });
                                    }
                                }
                            }
                        }
                    }
                }

                const has_file_content = mod.exports.len > 0 or
                    mod.star_re_exports.len > 0 or
                    mod.default_export != null or
                    mod.export_equals != null or
                    (!route_globals_to_hub and mod.global_augmentations.len > 0) or
                    (self.source_mod_to_cand.contains(mod.id) and !std.mem.eql(u8, fspec, "globals"));

                if (has_file_content) {
                    const c_idx = self.source_mod_to_cand.get(mod.id) orelse
                        try self.getOrCreateCandidate(fspec, mod.id);

                    for (mod.exports) |did| {
                        try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, did, null, false);
                    }
                    if (mod.default_export) |def_id| {
                        self.candidates.items[c_idx].default_export_decl_id = def_id;
                        try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, def_id, "default", true);
                    }
                    if (mod.export_equals) |eq_id| {
                        try self.registerExportEqualsForCandidate(c_idx, mod.id, eq_id);
                    }
                    if (!route_globals_to_hub) {
                        for (mod.global_augmentations) |did| {
                            try self.registerCandidateDeclOrForeignExport(c_idx, mod.id, did, null, false);
                        }
                    }
                    for (mod.star_re_exports) |target_smid| {
                        try appendUniqueU32(
                            &self.candidates.items[c_idx].star_re_export_source_mods,
                            self.scratch,
                            target_smid,
                        );
                    }
                }
            }

            // 2-globals. When there is no dedicated `"globals"` hub, propagate runtime
            // `declare global { var/function ... }` declarations (such as `MonacoEnvironment` in
            // `monaco-editor/esm/vs/editor/editor.api.d.ts`) to barrel candidates (`monaco-editor`)
            // that re-export declarations (via `export *` or named `export { ... } from ...`) from
            // the owning submodule.
            if (!has_globals_hub) {
                for (0..self.candidates.items.len) |ci| {
                    const c_idx: u32 = @intCast(ci);
                    if (self.candidates.items[ci].source_mod_ids.items.len == 0) continue;

                    var visited_owners: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited_owners.deinit(self.scratch);
                    var owner_queue: std.ArrayList(u32) = .empty;
                    defer owner_queue.deinit(self.scratch);
                    try visited_owners.put(self.scratch, c_idx, {});
                    try owner_queue.append(self.scratch, c_idx);

                    var oq_i: usize = 0;
                    while (oq_i < owner_queue.items.len) : (oq_i += 1) {
                        if (oq_i > 32) break;
                        const cur_c = owner_queue.items[oq_i];
                        if (cur_c >= self.candidates.items.len) continue;

                        for (self.candidates.items[cur_c].foreign_exports.items) |fe| {
                            const oc = self.decl_to_cand.get(fe.decl_id) orelse continue;
                            if (oc < self.candidates.items.len and !(try visited_owners.getOrPut(self.scratch, oc)).found_existing) {
                                try owner_queue.append(self.scratch, oc);
                            }
                        }
                        for (self.candidates.items[cur_c].star_re_export_source_mods.items) |smid| {
                            const oc = self.source_mod_to_cand.get(smid) orelse continue;
                            if (oc < self.candidates.items.len and !(try visited_owners.getOrPut(self.scratch, oc)).found_existing) {
                                try owner_queue.append(self.scratch, oc);
                            }
                        }
                        for (self.candidates.items[cur_c].decl_ids.items) |rdid| {
                            if (rdid >= self.graph.decls.len) continue;
                            const rd = self.graph.decls[rdid];
                            if (rd.kind != .re_export_decl) continue;
                            const re = rd.kind.re_export_decl;
                            if (re.is_type_only) continue;
                            if (re.target_decl) |td| {
                                if (self.decl_to_cand.get(td)) |oc| {
                                    if (oc < self.candidates.items.len and !(try visited_owners.getOrPut(self.scratch, oc)).found_existing) {
                                        try owner_queue.append(self.scratch, oc);
                                    }
                                }
                            }
                            if (re.target_module) |tm| {
                                if (self.source_mod_to_cand.get(tm)) |oc| {
                                    if (oc < self.candidates.items.len and !(try visited_owners.getOrPut(self.scratch, oc)).found_existing) {
                                        try owner_queue.append(self.scratch, oc);
                                    }
                                }
                            }
                        }
                    }

                    for (owner_queue.items[1..]) |owner_cand| {
                        for (self.candidates.items[owner_cand].decl_ids.items) |gdid| {
                            if (!self.global_aug_decls.contains(gdid) or gdid >= self.graph.decls.len) continue;
                            const gd = self.graph.decls[gdid];
                            if (gd.kind != .variable_decl and gd.kind != .function_decl) continue;
                            try appendUniqueForeignExport(&self.candidates.items[ci].foreign_exports, self.scratch, .{
                                .decl_id = gdid,
                                .wire_name_override = null,
                                .is_default_export = false,
                            });
                        }
                    }
                }
            }

            // 2a. Final sweep for any remaining same-file ambient helpers added during Step 1b.
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                for (mod.ambient_modules) |amb| {
                    const amb_cand = (try self.findAmbientCandidateIdx(self.str(amb.module_name))) orelse continue;
                    var seeds: std.ArrayList(u32) = .empty;
                    defer seeds.deinit(self.scratch);
                    for (amb.decls) |did| try appendUniqueU32(&seeds, self.scratch, did);
                    if (amb.default_export) |def_id| try appendUniqueU32(&seeds, self.scratch, def_id);
                    if (amb.export_equals) |eq_id| try appendUniqueU32(&seeds, self.scratch, eq_id);
                    try self.claimSameFileAmbientHelpers(amb_cand, mod.id, seeds.items);
                }
            }

            // 2b. Register declarations from transitively type-imported modules (`import type { X } from "./peer"`)
            // where the extractor recorded `d.module` without populating `mod.exports`.
            for (self.graph.decls) |d| {
                if (self.decl_to_cand.contains(d.id)) continue;
                if (self.deduped_decl_ids.contains(d.id)) continue;
                if (self.ns_child_ids.contains(d.id)) continue;

                var found_mod_idx: ?usize = null;
                if (d.module < self.graph.modules.len and self.graph.modules[d.module].id == d.module) {
                    found_mod_idx = d.module;
                } else {
                    for (self.graph.modules, 0..) |m, midx| {
                        if (m.id == d.module) {
                            found_mod_idx = midx;
                            break;
                        }
                    }
                }
                const mod_idx = found_mod_idx orelse continue;
                const owner_mod = self.graph.modules[mod_idx];
                if (self.isBundledLibModule(owner_mod)) continue;

                const c_idx = try self.resolveOrCreateOwnerCandForFileMod(owner_mod);
                try appendUniqueU32(&self.candidates.items[c_idx].decl_ids, self.scratch, d.id);
                try self.appendDeclRecursiveToCand(d.id, c_idx);
                if (d.modifiers.export_decl and
                    owner_mod.exports.len == 0 and
                    owner_mod.ambient_modules.len == 0 and
                    owner_mod.default_export == null and
                    owner_mod.export_equals == null and
                    owner_mod.global_augmentations.len == 0)
                {
                    try self.markJsExportedDecl(d.id);
                }
            }

            // 2c. Apply `package.json` `"exports"` wire specifier overrides (`"typescript/sync"`,
            // `"typescript/ast/is"`, etc.) ONLY to modules explicitly listed in `"exports"` (plus
            // ambient modules). Internal modules reached via `export *`, `export * as ns`, or
            // named re-exports remain `is_public_export_mod = false` (`is_encapsulated_internal = true`),
            // and only declarations genuinely forwarded under ES module semantics are claimed in
            // `resolveRuntimeWireTargetsAndPruneUnreachable`.
            if (self.options.vfs_specifier_overrides.len > 0) {
                var override_by_vfs: std.StringHashMapUnmanaged([]const u8) = .empty;
                defer override_by_vfs.deinit(self.scratch);
                for (self.options.vfs_specifier_overrides) |ov| {
                    try override_by_vfs.put(self.scratch, ov.vfs_path, ov.wire_specifier);
                }

                for (self.candidates.items) |*cand| {
                    // Ambient module blocks (`declare module "node:fs"`), the canonical `"globals"`
                    // hub, and sibling `-t` inputs outside any `"exports"`-declaring package represent
                    // explicit public surfaces directly.
                    const in_exports_pkg = blk: {
                        if (cand.source_mod_ids.items.len == 0 or std.mem.eql(u8, cand.wire_specifier, "globals")) {
                            break :blk false;
                        }
                        if (self.options.exports_pkg_vfs_prefixes.len == 0) break :blk true;
                        for (cand.source_mod_ids.items) |smid| {
                            const midx = self.findGraphModuleIndexById(smid) orelse continue;
                            const m_fp = self.str(self.graph.modules[midx].file_path);
                            for (self.options.exports_pkg_vfs_prefixes) |epfx| {
                                if (std.mem.startsWith(u8, m_fp, epfx)) break :blk true;
                            }
                        }
                        break :blk false;
                    };
                    cand.is_public_export_mod = !in_exports_pkg;
                    for (cand.source_mod_ids.items) |smid| {
                        const midx = self.findGraphModuleIndexById(smid) orelse continue;
                        const m_fp = self.str(self.graph.modules[midx].file_path);
                        if (override_by_vfs.get(m_fp)) |pub_spec| {
                            cand.wire_specifier = try self.alloc.dupe(u8, pub_spec);
                            cand.substituted_specifier = try applySubstitutions(self.alloc, cand.wire_specifier, self.options.substitutions);
                            cand.is_public_export_mod = true;
                            break;
                        }
                    }
                }
            }

            if (self.options.types_only_vfs_prefixes.len > 0) {
                for (self.candidates.items) |*cand| {
                    if (cand.source_mod_ids.items.len == 0 or std.mem.eql(u8, cand.wire_specifier, "globals")) continue;
                    var all_types_only = true;
                    for (cand.source_mod_ids.items) |smid| {
                        const midx = self.findGraphModuleIndexById(smid) orelse {
                            all_types_only = false;
                            break;
                        };
                        const m_fp = self.str(self.graph.modules[midx].file_path);
                        var matched_prefix = false;
                        for (self.options.types_only_vfs_prefixes) |pfx| {
                            if (std.mem.startsWith(u8, m_fp, pfx)) {
                                matched_prefix = true;
                                break;
                            }
                        }
                        if (!matched_prefix) {
                            all_types_only = false;
                            break;
                        }
                    }
                    if (all_types_only) {
                        cand.is_public_export_mod = false;
                    }
                }
            }

            // 3. Support dotted namespace `-m` filters such as `-m monaco.editor`.
            for (self.options.modules) |mod_pat| {
                var already_matched = false;
                for (self.candidates.items) |cand| {
                    if (moduleMatchesPattern(cand.wire_specifier, cand.substituted_specifier, mod_pat)) {
                        already_matched = true;
                        break;
                    }
                }
                if (!already_matched) {
                    if (self.findDottedNamespaceDecls(mod_pat)) |ns_decls| {
                        const c_idx = try self.getOrCreateCandidate(mod_pat, null);
                        for (ns_decls) |did| {
                            try appendUniqueU32(&self.candidates.items[c_idx].decl_ids, self.scratch, did);
                            try self.markJsExportedDecl(did);
                            // Point these decls to the synthesized dotted namespace module.
                            try self.decl_to_cand.put(self.scratch, did, c_idx);
                        }
                    }
                }
            }
        }

        fn claimSameFileAmbientHelpers(
            self: *Self,
            amb_cand: u32,
            mod_id: u32,
            seed_decls: []const u32,
        ) error{OutOfMemory}!void {
            var worklist: std.ArrayList(u32) = .empty;
            defer worklist.deinit(self.scratch);

            var visited_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_decls.deinit(self.scratch);

            var visited_types: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_types.deinit(self.scratch);

            for (seed_decls) |did| {
                if (did >= self.graph.decls.len) continue;
                if (self.decl_to_cand.get(did) == amb_cand) {
                    try worklist.append(self.scratch, did);
                    for (self.graph.decls[did].merged_with) |mid| {
                        if (mid < self.graph.decls.len and self.decl_to_cand.get(mid) == amb_cand) {
                            try worklist.append(self.scratch, mid);
                        }
                    }
                }
            }

            const HelperClaimVisitor = struct {
                amb_cand: u32,
                mod_id: u32,
                worklist: *std.ArrayList(u32),

                fn onDeclRef(v: *@This(), ctx: *Self, target_did: u32) error{OutOfMemory}!void {
                    var root_did = target_did;
                    var hops: usize = 0;
                    while (hops < ctx.graph.decls.len) : (hops += 1) {
                        const p_ns = ctx.child_to_parent_ns.get(root_did) orelse break;
                        if (p_ns == root_did) break;
                        root_did = p_ns;
                    }
                    if (root_did >= ctx.graph.decls.len) return;
                    if (ctx.decl_to_cand.contains(root_did)) return;
                    const rd = ctx.graph.decls[root_did];
                    if (rd.module != v.mod_id) return;

                    try ctx.registerCanonicalDeclInCandidate(v.amb_cand, root_did);
                    try v.worklist.append(ctx.scratch, root_did);
                    for (rd.merged_with) |mid| {
                        if (mid < ctx.graph.decls.len and ctx.graph.decls[mid].module == v.mod_id) {
                            try v.worklist.append(ctx.scratch, mid);
                        }
                    }
                }

                fn onModuleIdRef(_: *@This(), _: *Self, _: u32) error{OutOfMemory}!void {}
                fn onModuleSpecRef(_: *@This(), _: *Self, _: []const u8) error{OutOfMemory}!void {}
            };

            var visitor = HelperClaimVisitor{
                .amb_cand = amb_cand,
                .mod_id = mod_id,
                .worklist = &worklist,
            };

            var cursor: usize = 0;
            while (cursor < worklist.items.len) : (cursor += 1) {
                const cur_did = worklist.items[cursor];
                if (visited_decls.contains(cur_did)) continue;
                try visited_decls.put(self.scratch, cur_did, {});
                try self.walkDeclRefs(cur_did, &visited_types, &visitor);
            }
        }

        fn walkTypeRefs(
            self: *Self,
            ty_id: u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            if (ty_id >= self.graph.types.len) return;
            if (visited_types.contains(ty_id)) return;
            try visited_types.put(self.scratch, ty_id, {});

            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .reference => |ref| {
                    if (!self.isBuiltinMappedReference(self.str(ref.target_name), ref.type_args.len, ref.target_decl)) {
                        if (ref.target_decl) |td| {
                            try visitor.onDeclRef(self, td);
                        } else if (tn.resolved_type) |rt| {
                            if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                        }
                    }
                    for (ref.type_args) |arg_ty| {
                        try self.walkTypeRefs(arg_ty, visited_types, visitor);
                    }
                },
                .typeof_query => |tq| {
                    if (tq.target_decl) |td| {
                        try visitor.onDeclRef(self, td);
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                    for (tq.type_args) |arg_ty| {
                        try self.walkTypeRefs(arg_ty, visited_types, visitor);
                    }
                },
                .import_type => |it| {
                    try visitor.onModuleSpecRef(self, self.str(it.module_specifier));
                    for (it.type_args) |arg_ty| {
                        try self.walkTypeRefs(arg_ty, visited_types, visitor);
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                },
                .template_literal => |tl| {
                    for (tl.spans) |sp| try self.walkTypeRefs(sp.ty, visited_types, visitor);
                },
                .array, .readonly_array, .keyof_type => |inner| {
                    try self.walkTypeRefs(inner, visited_types, visitor);
                },
                .tuple, .readonly_tuple => |elems| {
                    for (elems) |el| try self.walkTypeRefs(el.ty, visited_types, visitor);
                },
                .union_type, .intersection => |arms| {
                    for (arms) |arm| try self.walkTypeRefs(arm, visited_types, visitor);
                },
                .object_literal => |obj| {
                    try self.walkPropsRefs(obj.properties, visited_types, visitor);
                    for (obj.call_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    for (obj.construct_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    for (obj.index_signatures) |isig| {
                        try self.walkTypeRefs(isig.key_type, visited_types, visitor);
                        try self.walkTypeRefs(isig.value_type, visited_types, visitor);
                    }
                },
                .function_type, .constructor_type => |sid| {
                    try self.walkSigRefs(sid, visited_types, visitor);
                },
                .indexed_access => |ia| {
                    try self.walkTypeRefs(ia.object_ty, visited_types, visitor);
                    try self.walkTypeRefs(ia.index_ty, visited_types, visitor);
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                },
                .conditional => |cond| {
                    try self.walkTypeRefs(cond.check_type, visited_types, visitor);
                    try self.walkTypeRefs(cond.extends_type, visited_types, visitor);
                    try self.walkTypeRefs(cond.true_type, visited_types, visitor);
                    try self.walkTypeRefs(cond.false_type, visited_types, visitor);
                    try self.walkTypeParamsRefs(cond.infer_params, visited_types, visitor);
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                },
                .mapped => |mp| {
                    try self.walkTypeParamsRefs(&.{mp.type_param}, visited_types, visitor);
                    if (mp.name_type) |nt| try self.walkTypeRefs(nt, visited_types, visitor);
                    try self.walkTypeRefs(mp.value_type, visited_types, visitor);
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                },
                .type_predicate => |tp| {
                    if (tp.target_type) |tt| try self.walkTypeRefs(tt, visited_types, visitor);
                },
                else => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) try self.walkTypeRefs(rt, visited_types, visitor);
                    }
                },
            }
        }

        fn walkTypeParamsRefs(
            self: *Self,
            tp_ids: []const u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            for (tp_ids) |tp_id| {
                if (tp_id >= self.graph.type_params.len) continue;
                const tp = self.graph.type_params[tp_id];
                if (tp.constraint) |ct| try self.walkTypeRefs(ct, visited_types, visitor);
                if (tp.default_type) |dt| try self.walkTypeRefs(dt, visited_types, visitor);
            }
        }

        fn walkPropsRefs(
            self: *Self,
            prop_ids: []const u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            for (prop_ids) |pid| {
                if (pid >= self.graph.properties.len) continue;
                const prop = self.graph.properties[pid];
                if (prop.modifiers.private_mod or prop.modifiers.protected_mod) continue;
                if (prop.computed_symbol) |cs| {
                    if (cs == .unique) try visitor.onDeclRef(self, cs.unique);
                }
                try self.walkTypeRefs(prop.ty, visited_types, visitor);
                if (prop.setter_ty) |sty| try self.walkTypeRefs(sty, visited_types, visitor);
            }
        }

        fn walkHeritageRefs(
            self: *Self,
            hc: anytype,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            if (hc.target_decl) |td| try visitor.onDeclRef(self, td);
            try self.walkTypeRefs(hc.target_type, visited_types, visitor);
            for (hc.type_args) |arg_ty| try self.walkTypeRefs(arg_ty, visited_types, visitor);
        }

        fn walkSigRefs(
            self: *Self,
            sig_id: u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            if (sig_id >= self.graph.signatures.len) return;
            const sig = self.graph.signatures[sig_id];
            try self.walkTypeParamsRefs(sig.type_params, visited_types, visitor);
            if (sig.this_param) |tp| try self.walkTypeRefs(tp, visited_types, visitor);
            for (sig.params) |p| try self.walkTypeRefs(p.ty, visited_types, visitor);
            try self.walkTypeRefs(sig.return_type, visited_types, visitor);
            if (sig.type_predicate) |tpred| {
                if (tpred.target_type) |tt| try self.walkTypeRefs(tt, visited_types, visitor);
            }
        }

        fn walkDeclRefs(
            self: *Self,
            decl_id: u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            var visited_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_decls.deinit(self.scratch);
            try self.walkDeclRefsInner(decl_id, &visited_decls, visited_types, visitor);
        }

        fn walkDeclRefsInner(
            self: *Self,
            decl_id: u32,
            visited_decls: *std.AutoHashMapUnmanaged(u32, void),
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            visitor: anytype,
        ) error{OutOfMemory}!void {
            if (decl_id >= self.graph.decls.len) return;
            if (visited_decls.contains(decl_id)) return;
            try visited_decls.put(self.scratch, decl_id, {});

            const d = self.graph.decls[decl_id];
            try self.walkTypeParamsRefs(d.type_params, visited_types, visitor);
            for (d.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].module == d.module) {
                    try visitor.onDeclRef(self, mid);
                }
            }
            switch (d.kind) {
                .function_decl => |sigs| {
                    for (sigs) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                },
                .variable_decl => |ty| try self.walkTypeRefs(ty, visited_types, visitor),
                .type_alias_decl => |ty| try self.walkTypeRefs(ty, visited_types, visitor),
                .interface_decl => |iface| {
                    for (iface.extends_clauses) |hc| try self.walkHeritageRefs(hc, visited_types, visitor);
                    try self.walkPropsRefs(iface.properties, visited_types, visitor);
                    for (iface.methods) |m| {
                        if (m.modifiers.private_mod or m.modifiers.protected_mod) continue;
                        if (m.computed_symbol) |cs| {
                            if (cs == .unique) try visitor.onDeclRef(self, cs.unique);
                        }
                        for (m.signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    }
                    for (iface.call_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    for (iface.construct_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    for (iface.index_signatures) |isig| {
                        try self.walkTypeRefs(isig.key_type, visited_types, visitor);
                        try self.walkTypeRefs(isig.value_type, visited_types, visitor);
                    }
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.module == d.module and md.kind == .variable_decl) {
                            try self.walkTypeRefs(md.kind.variable_decl, visited_types, visitor);
                        } else if (md.kind == .interface_decl) {
                            const miface = md.kind.interface_decl;
                            for (miface.extends_clauses) |hc| try self.walkHeritageRefs(hc, visited_types, visitor);
                            try self.walkPropsRefs(miface.properties, visited_types, visitor);
                            for (miface.methods) |m| {
                                for (m.signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                            }
                            for (miface.call_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                            for (miface.construct_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                            for (miface.index_signatures) |isig| {
                                try self.walkTypeRefs(isig.key_type, visited_types, visitor);
                                try self.walkTypeRefs(isig.value_type, visited_types, visitor);
                            }
                        } else if (md.module == d.module and md.kind == .function_decl) {
                            for (md.kind.function_decl) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                        } else if (md.module == d.module and md.kind == .namespace_decl) {
                            for (md.kind.namespace_decl) |cid| try visitor.onDeclRef(self, cid);
                        }
                    }
                },
                .class_decl => |cls| {
                    if (cls.extends_clause) |hc| try self.walkHeritageRefs(hc, visited_types, visitor);
                    for (cls.implements_clauses) |hc| try self.walkHeritageRefs(hc, visited_types, visitor);
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind == .interface_decl) {
                            const miface = md.kind.interface_decl;
                            for (miface.extends_clauses) |hc| try self.walkHeritageRefs(hc, visited_types, visitor);
                            try self.walkPropsRefs(miface.properties, visited_types, visitor);
                            for (miface.methods) |m| {
                                for (m.signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                            }
                            for (miface.call_signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                            for (miface.index_signatures) |isig| {
                                try self.walkTypeRefs(isig.key_type, visited_types, visitor);
                                try self.walkTypeRefs(isig.value_type, visited_types, visitor);
                            }
                        } else if (md.module == d.module and md.kind == .namespace_decl) {
                            for (md.kind.namespace_decl) |cid| try visitor.onDeclRef(self, cid);
                        }
                    }
                    for (cls.constructors) |sid| {
                        if (sid < self.graph.signatures.len) {
                            const csig = self.graph.signatures[sid];
                            if (csig.modifiers.private_mod or csig.modifiers.protected_mod) continue;
                        }
                        try self.walkSigRefs(sid, visited_types, visitor);
                    }
                    try self.walkPropsRefs(cls.properties, visited_types, visitor);
                    for (cls.methods) |m| {
                        if (m.modifiers.private_mod or m.modifiers.protected_mod) continue;
                        if (m.computed_symbol) |cs| {
                            if (cs == .unique) try visitor.onDeclRef(self, cs.unique);
                        }
                        for (m.signatures) |sid| try self.walkSigRefs(sid, visited_types, visitor);
                    }
                    for (cls.index_signatures) |isig| {
                        try self.walkTypeRefs(isig.key_type, visited_types, visitor);
                        try self.walkTypeRefs(isig.value_type, visited_types, visitor);
                    }
                },
                .namespace_decl => |children| {
                    for (children) |cid| try self.walkDeclRefsInner(cid, visited_decls, visited_types, visitor);
                },
                .re_export_decl => |re| {
                    if (re.target_module) |tmid| try visitor.onModuleIdRef(self, tmid);
                    if (re.target_decl) |tdid| {
                        try visitor.onDeclRef(self, tdid);
                    } else if (re.target_module == null) {
                        try visitor.onModuleSpecRef(self, self.str(re.module_specifier));
                    }
                },
                .import_equals_decl => |ie| {
                    if (ie.target_decl) |tdid| {
                        try visitor.onDeclRef(self, tdid);
                    } else if (ie.module_specifier) |msid| {
                        try visitor.onModuleSpecRef(self, self.str(msid));
                    }
                },
                .enum_decl => {},
            }
        }

        fn collectReferencedCandsFromDecl(
            self: *Self,
            decl_id: u32,
            visited_types: *std.AutoHashMapUnmanaged(u32, void),
            queue: *std.ArrayList(u32),
        ) error{OutOfMemory}!void {
            const CandReachVisitor = struct {
                queue: *std.ArrayList(u32),
                from_cand: ?u32,

                fn markCand(v: *@This(), ctx: *Self, dep_cand: u32) error{OutOfMemory}!void {
                    if (!ctx.candidates.items[dep_cand].included) {
                        ctx.candidates.items[dep_cand].included = true;
                        try v.queue.append(ctx.scratch, dep_cand);
                    }
                }

                fn onDeclRef(v: *@This(), ctx: *Self, td: u32) error{OutOfMemory}!void {
                    if (ctx.decl_to_cand.get(td)) |dep_cand| {
                        try v.markCand(ctx, dep_cand);
                    }
                }

                fn onModuleIdRef(v: *@This(), ctx: *Self, tmid: u32) error{OutOfMemory}!void {
                    if (ctx.source_mod_to_cand.get(tmid)) |dep_cand| {
                        try v.markCand(ctx, dep_cand);
                    }
                }

                fn onModuleSpecRef(v: *@This(), ctx: *Self, mspec: []const u8) error{OutOfMemory}!void {
                    if (try ctx.resolveSpecFromCandToCandidateIdx(v.from_cand, mspec)) |dep_cand| {
                        try v.markCand(ctx, dep_cand);
                    }
                }
            };

            var visitor = CandReachVisitor{
                .queue = queue,
                .from_cand = self.decl_to_cand.get(decl_id),
            };
            try self.walkDeclRefs(decl_id, visited_types, &visitor);
        }

        fn resolveRelativeVfsPath(allocator: std.mem.Allocator, from_file_path: []const u8, rel_path: []const u8) ![]u8 {
            const dir_part = if (std.mem.lastIndexOfScalar(u8, from_file_path, '/')) |slash|
                (if (slash == 0) "/" else from_file_path[0..slash])
            else
                "/";
            const joined = if (rel_path.len > 0 and rel_path[0] == '/')
                try allocator.dupe(u8, rel_path)
            else if (std.mem.eql(u8, dir_part, "/"))
                try std.fmt.allocPrint(allocator, "/{s}", .{rel_path})
            else
                try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir_part, rel_path });
            defer allocator.free(joined);

            var parts: std.ArrayList([]const u8) = .empty;
            defer parts.deinit(allocator);

            var start: usize = 0;
            var i: usize = 0;
            while (i <= joined.len) : (i += 1) {
                const is_sep = (i == joined.len) or (joined[i] == '/') or (joined[i] == '\\');
                if (!is_sep) continue;
                const seg = joined[start..i];
                start = i + 1;
                if (seg.len == 0 or std.mem.eql(u8, seg, ".")) continue;
                if (std.mem.eql(u8, seg, "..")) {
                    if (parts.items.len > 0) _ = parts.pop();
                    continue;
                }
                try parts.append(allocator, seg);
            }

            if (parts.items.len == 0) return try allocator.dupe(u8, "/");
            var out: std.ArrayList(u8) = .empty;
            errdefer out.deinit(allocator);
            for (parts.items) |seg| {
                try out.append(allocator, '/');
                try out.appendSlice(allocator, seg);
            }
            return try out.toOwnedSlice(allocator);
        }

        fn runReachabilityClosure(self: *Self, queue: *std.ArrayList(u32)) error{OutOfMemory}!void {
            var visited_types: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_types.deinit(self.scratch);

            var q_head: usize = 0;
            while (q_head < queue.items.len) : (q_head += 1) {
                const c_idx = queue.items[q_head];
                const star_targets = try self.scratch.dupe(u32, self.candidates.items[c_idx].star_re_export_source_mods.items);
                defer self.scratch.free(star_targets);
                for (star_targets) |smid| {
                    if (self.source_mod_to_cand.get(smid)) |dep_cand| {
                        if (!self.candidates.items[dep_cand].included) {
                            self.candidates.items[dep_cand].included = true;
                            try queue.append(self.scratch, dep_cand);
                        }
                    }
                }

                const star_specs = try self.scratch.dupe([]const u8, self.candidates.items[c_idx].star_re_export_specs.items);
                defer self.scratch.free(star_specs);
                for (star_specs) |mspec| {
                    if (try self.resolveSpecToCandidateIdx(mspec)) |dep_cand| {
                        if (!self.candidates.items[dep_cand].included) {
                            self.candidates.items[dep_cand].included = true;
                            try queue.append(self.scratch, dep_cand);
                        }
                    }
                }

                const foreign_snapshot = try self.scratch.dupe(ForeignExportEntry, self.candidates.items[c_idx].foreign_exports.items);
                defer self.scratch.free(foreign_snapshot);
                for (foreign_snapshot) |fe| {
                    if (self.decl_to_cand.get(fe.decl_id)) |dep_cand| {
                        if (!self.candidates.items[dep_cand].included) {
                            self.candidates.items[dep_cand].included = true;
                            try queue.append(self.scratch, dep_cand);
                        }
                    }
                }

                const decl_snapshot = try self.scratch.dupe(u32, self.candidates.items[c_idx].decl_ids.items);
                defer self.scratch.free(decl_snapshot);
                for (decl_snapshot) |did| {
                    try self.collectReferencedCandsFromDecl(did, &visited_types, queue);
                }
            }
        }

        fn findAmbientCandidateIdx(self: *Self, amb_name: []const u8) !?u32 {
            const sub_spec = try applySubstitutions(self.scratch, amb_name, self.options.substitutions);
            defer self.scratch.free(sub_spec);
            const slash_spec = try self.scratch.dupe(u8, sub_spec);
            defer self.scratch.free(slash_spec);
            for (slash_spec) |*ch| {
                if (ch.* == '.') ch.* = '/';
            }
            const rel_zig_path = try naming.sanitizeModuleRelPath(self.scratch, slash_spec);
            defer self.scratch.free(rel_zig_path);

            for (self.candidates.items, 0..) |cand, idx| {
                if (std.mem.eql(u8, cand.rel_zig_path, rel_zig_path)) {
                    return @intCast(idx);
                }
            }
            return null;
        }

        fn resolveSpecFromCandToCandidateIdx(
            self: *Self,
            from_cand_opt: ?u32,
            mspec: []const u8,
        ) error{OutOfMemory}!?u32 {
            const trimmed = std.mem.trim(u8, mspec, " \t\r\n");
            if (trimmed.len == 0) return null;

            if (std.mem.startsWith(u8, trimmed, "./") or std.mem.startsWith(u8, trimmed, "../")) {
                if (from_cand_opt) |fc_idx| {
                    if (fc_idx < self.candidates.items.len) {
                        const fcand = &self.candidates.items[fc_idx];
                        for (fcand.source_mod_ids.items) |smid| {
                            const sm_idx = self.findGraphModuleIndexById(smid) orelse continue;
                            const from_fp = self.str(self.graph.modules[sm_idx].file_path);
                            const base_vfs = try resolveRelativeVfsPath(self.scratch, from_fp, trimmed);
                            defer self.scratch.free(base_vfs);

                            const suffixes = [_][]const u8{ "", ".d.ts", ".ts", "/index.d.ts", "/index.ts" };
                            for (suffixes) |sfx| {
                                const probe = if (sfx.len == 0)
                                    base_vfs
                                else
                                    try std.fmt.allocPrint(self.scratch, "{s}{s}", .{ base_vfs, sfx });
                                defer if (sfx.len > 0) self.scratch.free(probe);

                                for (self.graph.modules) |gm| {
                                    if (std.mem.eql(u8, self.str(gm.file_path), probe)) {
                                        if (self.source_mod_to_cand.get(gm.id)) |dep_cand| {
                                            return dep_cand;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return self.resolveSpecToCandidateIdx(trimmed);
        }

        fn resolveSpecToCandidateIdx(self: *Self, mspec: []const u8) error{OutOfMemory}!?u32 {
            const trimmed = std.mem.trim(u8, mspec, " \t\r\n");
            if (trimmed.len == 0) return null;

            for (self.candidates.items, 0..) |cand, idx| {
                if (std.mem.eql(u8, cand.wire_specifier, trimmed) or
                    std.mem.eql(u8, cand.substituted_specifier, trimmed))
                {
                    return @intCast(idx);
                }
            }

            if (try self.findAmbientCandidateIdx(trimmed)) |amb_idx| {
                return amb_idx;
            }

            for (self.candidates.items, 0..) |cand, idx| {
                if (moduleMatchesPattern(cand.wire_specifier, cand.substituted_specifier, trimmed)) {
                    return @intCast(idx);
                }
            }

            return null;
        }

        fn createEmptyFallbackCandidate(self: *Self) !u32 {
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                if (self.isPrimaryVfsPath(self.str(mod.file_path))) {
                    const wire_spec = try self.deriveFileLogicalSpecifier(mod);
                    return try self.getOrCreateCandidate(wire_spec, mod.id);
                }
            }
            for (self.graph.modules) |mod| {
                if (self.isBundledLibModule(mod)) continue;
                const wire_spec = try self.deriveFileLogicalSpecifier(mod);
                return try self.getOrCreateCandidate(wire_spec, mod.id);
            }
            return try self.getOrCreateCandidate("index", null);
        }

        fn filterAndCloseDependencies(self: *Self) LowerError![]u32 {
            if (self.options.modules.len > 0) {
                var queue: std.ArrayList(u32) = .empty;
                defer queue.deinit(self.scratch);

                for (self.candidates.items, 0..) |*cand, idx| {
                    for (self.options.modules) |pat| {
                        if (moduleMatchesPattern(cand.wire_specifier, cand.substituted_specifier, pat)) {
                            cand.is_primary = true;
                            cand.included = true;
                            try queue.append(self.scratch, @intCast(idx));
                            break;
                        }
                    }
                }

                if (queue.items.len == 0) {
                    return error.NoMatchingModules;
                }

                try self.runReachabilityClosure(&queue);
            } else if (self.options.primary_vfs_paths.len > 0) {
                var queue: std.ArrayList(u32) = .empty;
                defer queue.deinit(self.scratch);

                var primary_mod_ids: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer primary_mod_ids.deinit(self.scratch);

                var ref_path_mod_ids: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer ref_path_mod_ids.deinit(self.scratch);

                var mod_bfs: std.ArrayList(u32) = .empty;
                defer mod_bfs.deinit(self.scratch);

                for (self.graph.modules) |mod| {
                    if (self.isBundledLibModule(mod)) continue;
                    if (self.isPrimaryVfsPath(self.str(mod.file_path))) {
                        try primary_mod_ids.put(self.scratch, mod.id, {});
                        try ref_path_mod_ids.put(self.scratch, mod.id, {});
                        try mod_bfs.append(self.scratch, mod.id);
                    }
                }

                // Compute transitive `/// <reference path="..." />` closure (explicitly NOT
                // `triple_slash_types` to external `node_modules`!) starting from `primary_vfs_paths`.
                var mb_head: usize = 0;
                while (mb_head < mod_bfs.items.len) : (mb_head += 1) {
                    const mid = mod_bfs.items[mb_head];
                    const midx = self.findGraphModuleIndexById(mid) orelse continue;
                    const cur_mod = self.graph.modules[midx];
                    const cur_fp = self.str(cur_mod.file_path);
                    for (cur_mod.triple_slash_paths) |ref_sid| {
                        const ref_rel = self.str(ref_sid);
                        if (ref_rel.len == 0) continue;
                        const resolved_fp = try resolveRelativeVfsPath(self.scratch, cur_fp, ref_rel);
                        defer self.scratch.free(resolved_fp);
                        const resolved_dts = try std.fmt.allocPrint(self.scratch, "{s}.d.ts", .{resolved_fp});
                        defer self.scratch.free(resolved_dts);
                        const resolved_ts = try std.fmt.allocPrint(self.scratch, "{s}.ts", .{resolved_fp});
                        defer self.scratch.free(resolved_ts);
                        const resolved_idx_dts = try std.fmt.allocPrint(self.scratch, "{s}/index.d.ts", .{resolved_fp});
                        defer self.scratch.free(resolved_idx_dts);
                        const resolved_idx_ts = try std.fmt.allocPrint(self.scratch, "{s}/index.ts", .{resolved_fp});
                        defer self.scratch.free(resolved_idx_ts);

                        for (self.graph.modules) |other| {
                            if (self.isBundledLibModule(other)) continue;
                            const ofp = self.str(other.file_path);
                            if (std.mem.eql(u8, ofp, resolved_fp) or
                                std.mem.eql(u8, ofp, resolved_dts) or
                                std.mem.eql(u8, ofp, resolved_ts) or
                                std.mem.eql(u8, ofp, resolved_idx_dts) or
                                std.mem.eql(u8, ofp, resolved_idx_ts))
                            {
                                if (!ref_path_mod_ids.contains(other.id)) {
                                    try ref_path_mod_ids.put(self.scratch, other.id, {});
                                    try mod_bfs.append(self.scratch, other.id);
                                }
                            }
                        }
                    }
                }

                // 1. Mark non-empty file-level candidates directly owned by `primary_vfs_paths` as primary.
                for (self.candidates.items, 0..) |*cand, idx| {
                    for (cand.source_mod_ids.items) |smid| {
                        if (primary_mod_ids.contains(smid)) {
                            cand.is_primary = true;
                            if (!cand.included) {
                                cand.included = true;
                                try queue.append(self.scratch, @intCast(idx));
                            }
                            break;
                        }
                    }
                }

                // 2. Mark every ambient module (`declare module "..."`) and `declare global` / script
                // globals module in the `primary_vfs_paths + triple_slash_paths` closure as primary!
                for (mod_bfs.items) |mid| {
                    const midx = self.findGraphModuleIndexById(mid) orelse continue;
                    const m = self.graph.modules[midx];
                    if (m.global_augmentations.len > 0) {
                        const route_globals_to_hub = self.has_globals_hub or m.ambient_modules.len > 0;
                        const g_idx_opt = try self.findAmbientCandidateIdx("globals");
                        const m_has_own_exports = m.exports.len > 0 or
                            m.star_re_exports.len > 0 or
                            m.default_export != null or
                            m.export_equals != null;
                        if (route_globals_to_hub) {
                            if (g_idx_opt) |g_idx| {
                                self.candidates.items[g_idx].is_primary = true;
                                if (!self.candidates.items[g_idx].included) {
                                    self.candidates.items[g_idx].included = true;
                                    try queue.append(self.scratch, g_idx);
                                }
                            }
                            if (self.source_mod_to_cand.get(mid)) |c_idx| {
                                if ((g_idx_opt == null or c_idx != g_idx_opt.?) and (m_has_own_exports or primary_mod_ids.contains(mid))) {
                                    self.candidates.items[c_idx].is_primary = true;
                                    if (!self.candidates.items[c_idx].included) {
                                        self.candidates.items[c_idx].included = true;
                                        try queue.append(self.scratch, c_idx);
                                    }
                                }
                            }
                        } else if (self.source_mod_to_cand.get(mid)) |c_idx| {
                            self.candidates.items[c_idx].is_primary = true;
                            if (!self.candidates.items[c_idx].included) {
                                self.candidates.items[c_idx].included = true;
                                try queue.append(self.scratch, c_idx);
                            }
                        } else if (g_idx_opt) |g_idx| {
                            self.candidates.items[g_idx].is_primary = true;
                            if (!self.candidates.items[g_idx].included) {
                                self.candidates.items[g_idx].included = true;
                                try queue.append(self.scratch, g_idx);
                            }
                        }
                    } else if (!primary_mod_ids.contains(mid)) {
                        if (self.source_mod_to_cand.get(mid)) |c_idx| {
                            if (!self.candidates.items[c_idx].included) {
                                self.candidates.items[c_idx].included = true;
                                try queue.append(self.scratch, c_idx);
                            }
                        }
                    }
                    for (m.ambient_modules) |amb| {
                        if (try self.findAmbientCandidateIdx(self.str(amb.module_name))) |amb_cand_idx| {
                            var ac = &self.candidates.items[amb_cand_idx];
                            ac.is_primary = true;
                            if (!ac.included) {
                                ac.included = true;
                                try queue.append(self.scratch, amb_cand_idx);
                            }
                        }
                    }
                }

                if (queue.items.len == 0) {
                    // Only emit an empty fallback module when the entire package would otherwise
                    // emit zero modules!
                    const fb_idx = try self.createEmptyFallbackCandidate();
                    self.candidates.items[fb_idx].is_primary = true;
                    self.candidates.items[fb_idx].included = true;
                } else {
                    var has_any_primary = false;
                    for (queue.items) |q_idx| {
                        if (self.candidates.items[q_idx].is_primary) {
                            has_any_primary = true;
                            break;
                        }
                    }
                    if (!has_any_primary) {
                        for (queue.items) |q_idx| {
                            self.candidates.items[q_idx].is_primary = true;
                        }
                    }
                    try self.runReachabilityClosure(&queue);
                }
            } else {
                if (self.candidates.items.len == 0) {
                    _ = try self.createEmptyFallbackCandidate();
                }
                for (self.candidates.items) |*cand| {
                    cand.is_primary = true;
                    cand.included = true;
                }
            }

            var selected: std.ArrayList(u32) = .empty;
            errdefer selected.deinit(self.alloc);
            for (self.candidates.items, 0..) |cand, idx| {
                if (cand.included) {
                    try selected.append(self.alloc, @intCast(idx));
                }
            }
            return try selected.toOwnedSlice(self.alloc);
        }

        fn declNameStyle(self: *const Self, d: anytype) naming.NameStyle {
            const wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
            if (isPureDollarOrUnderscoreIdent(wire)) return .preserve;
            return switch (d.kind) {
                .function_decl => .camel,
                .interface_decl, .class_decl, .enum_decl, .type_alias_decl, .namespace_decl => .pascal,
                .variable_decl => blk: {
                    const raw = self.str(d.name);
                    if (isAllUpperOrUnderscore(raw)) break :blk .preserve;
                    break :blk .snake;
                },
                .import_equals_decl, .re_export_decl => .preserve,
            };
        }

        fn prebindScopeDecls(
            self: *Self,
            final_mod_idx: u32,
            decl_ids: []const u32,
            scope: *naming.ScopeNamer,
            prefix_path: []const []const u8,
            prebound_names: *std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *std.AutoHashMapUnmanaged(u32, []naming.BoundName),
        ) error{OutOfMemory}!void {
            var visited_ns: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_ns.deinit(self.scratch);
            try self.prebindScopeDeclsInner(
                final_mod_idx,
                decl_ids,
                scope,
                prefix_path,
                prebound_names,
                prebound_overloads,
                &visited_ns,
            );
        }

        fn prebindScopeDeclsInner(
            self: *Self,
            final_mod_idx: u32,
            decl_ids: []const u32,
            scope: *naming.ScopeNamer,
            prefix_path: []const []const u8,
            prebound_names: *std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *std.AutoHashMapUnmanaged(u32, []naming.BoundName),
            visited_ns: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            // 1. Detect class + interface declaration merging in the same scope so merged interface
            // members fold cleanly into the class struct rather than colliding as `Foo_2`!
            for (decl_ids) |did| {
                if (did >= self.graph.decls.len) continue;
                const d = self.graph.decls[did];
                if (d.kind == .class_decl) {
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len or mid == did) continue;
                        if (self.graph.decls[mid].kind == .interface_decl) {
                            for (decl_ids) |other| {
                                if (other == mid) {
                                    try self.merged_iface_consumed.put(self.scratch, mid, {});
                                }
                            }
                        }
                    }
                } else if (d.kind == .interface_decl and !self.merged_iface_consumed.contains(did)) {
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len or mid <= did) continue;
                        if (self.graph.decls[mid].kind == .interface_decl) {
                            for (decl_ids) |other| {
                                if (other == mid) {
                                    try self.merged_iface_consumed.put(self.scratch, mid, {});
                                }
                            }
                        }
                    }
                }
            }

            // 2. Detect interface/class/enum/namespace + namespace/function declaration merging in the same scope:
            //    - When `d.type_params.len == 0` (`const Foo = struct { ... }`), consume the merged
            //      `namespace_decl` directly into `Foo`'s nested declarations!
            //    - When `d.type_params.len > 0` (`fn Foo(comptime T: type) type`), Zig 0.17 does NOT
            //      allow `Foo.Bar` field access on a generic type constructor function! Keep the
            //      merged `namespace_decl` as a concrete module/scope sibling (`Foo_2`, marked in
            //      `merged_generic_ns_set`) AND also alias its children inside `Foo(T)`!
            //    - Multi-block `namespace Foo` + `namespace Foo` with identical wire names merge
            //      into the primary `namespace_decl`.
            //    - `enum Color` + `namespace Color` folds the namespace children into `Color`.
            //    - `function $` + `namespace $` / `interface $` where `.camel(wire)` == `.pascal(wire)`
            //      consumes the colliding top-level `function_decl` into the struct's static `call(...)`.
            for (decl_ids) |did| {
                if (did >= self.graph.decls.len) continue;
                if (self.merged_iface_consumed.contains(did)) continue;
                const d = self.graph.decls[did];
                const d_wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                if (d.kind == .interface_decl or d.kind == .class_decl) {
                    const has_merged_tps = self.hasMergedTypeParams(did);
                    if (d.kind == .interface_decl) {
                        const icls = try self.classifyDecl(did);
                        if (icls.companion_var_decl_id) |var_did| {
                            for (decl_ids) |other| {
                                if (other == var_did) {
                                    if (!has_merged_tps) {
                                        try self.merged_ctor_var_consumed.put(self.scratch, var_did, {});
                                    } else {
                                        try self.merged_generic_ctor_var_peer.put(self.scratch, did, var_did);
                                    }
                                }
                            }
                        }
                        if (!has_merged_tps and try merge_decls.fnAndNamespaceIdentCollide(self.scratch, d_wire)) {
                            for (d.merged_with) |mid| {
                                if (mid >= self.graph.decls.len or mid == did) continue;
                                const md = self.graph.decls[mid];
                                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                                if (md.kind == .function_decl and merge_decls.sameWireName(d_wire, m_wire)) {
                                    for (decl_ids) |other| {
                                        if (other == mid) {
                                            try self.merged_fn_consumed.put(self.scratch, mid, {});
                                        }
                                    }
                                }
                            }
                        }
                    }
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len or mid == did) continue;
                        const md = self.graph.decls[mid];
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (md.kind == .namespace_decl and merge_decls.sameWireName(d_wire, m_wire)) {
                            for (decl_ids) |other| {
                                if (other == mid) {
                                    if (!has_merged_tps) {
                                        try self.merged_ns_consumed.put(self.scratch, mid, {});
                                    } else {
                                        try self.merged_generic_ns_peer.put(self.scratch, did, mid);
                                        try self.merged_generic_ns_set.put(self.scratch, mid, {});
                                    }
                                }
                            }
                        }
                    }
                } else if (d.kind == .enum_decl) {
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len or mid == did) continue;
                        const md = self.graph.decls[mid];
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (md.kind == .namespace_decl and merge_decls.sameWireName(d_wire, m_wire)) {
                            for (decl_ids) |other| {
                                if (other == mid) {
                                    try self.merged_ns_consumed.put(self.scratch, mid, {});
                                }
                            }
                        }
                    }
                }
            }

            // 2b. Multi-block `namespace Foo` + `namespace Foo` and `namespace $` + `function $`
            //     (after interface/class/enum have claimed their merged namespaces).
            for (decl_ids) |did| {
                if (did >= self.graph.decls.len) continue;
                if (self.merged_ns_consumed.contains(did)) continue;
                const d = self.graph.decls[did];
                if (d.kind != .namespace_decl) continue;
                const d_wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                const fn_collides = try merge_decls.fnAndNamespaceIdentCollide(self.scratch, d_wire);
                for (d.merged_with) |mid| {
                    if (mid >= self.graph.decls.len or mid == did) continue;
                    const md = self.graph.decls[mid];
                    const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                    if (!merge_decls.sameWireName(d_wire, m_wire)) continue;
                    if (md.kind == .namespace_decl and mid > did and !self.merged_generic_ns_set.contains(mid)) {
                        for (decl_ids) |other| {
                            if (other == mid) {
                                try self.merged_ns_consumed.put(self.scratch, mid, {});
                            }
                        }
                    } else if (md.kind == .function_decl and fn_collides) {
                        for (decl_ids) |other| {
                            if (other == mid) {
                                try self.merged_fn_consumed.put(self.scratch, mid, {});
                            }
                        }
                    }
                }
            }

            for (decl_ids) |did| {
                if (did >= self.graph.decls.len) continue;
                if (self.merged_ns_consumed.contains(did)) continue;
                if (self.merged_iface_consumed.contains(did)) continue;
                if (self.merged_ctor_var_consumed.contains(did)) continue;
                if (self.merged_fn_consumed.contains(did)) continue;
                if (prebound_names.get(did)) |existing| {
                    try scope.reserve(existing.logical_name);
                    if (prebound_overloads.get(did)) |ovs| {
                        for (ovs) |ov| try scope.reserve(ov.logical_name);
                    }
                    continue;
                }

                const d = self.graph.decls[did];
                if (d.kind == .import_equals_decl and !d.modifiers.export_decl) continue;
                const wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                if (d.kind == .re_export_decl and d.kind.re_export_decl.is_namespace and std.mem.eql(u8, wire, "*")) continue;
                const bound = try scope.bind(wire, self.declNameStyle(d));

                // Duplicate into arena so `PackageIr` owns all strings.
                const owned_bound = naming.BoundName{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_name = try self.alloc.dupe(u8, bound.wire_name),
                };
                bound.deinit(self.scratch);
                try prebound_names.put(self.scratch, did, owned_bound);

                var full_path = try self.alloc.alloc([]const u8, prefix_path.len + 1);
                @memcpy(full_path[0..prefix_path.len], prefix_path);
                full_path[prefix_path.len] = owned_bound.zig_ident;

                const merged_tp_info = try self.collectMergedDeclTypeParamInfo(did);

                const loc = DeclLocation{
                    .module_index = final_mod_idx,
                    .zig_path = full_path,
                    .type_param_names = merged_tp_info.names,
                    .type_param_defaults = merged_tp_info.defaults,
                };
                try self.decl_locations.put(self.scratch, did, loc);

                // Point consumed merged interfaces, namespaces, functions, and companion constructor vars at the owning decl location too!
                if (d.kind == .class_decl) {
                    for (d.merged_with) |mid| {
                        if (self.merged_iface_consumed.contains(mid) or self.merged_ns_consumed.contains(mid)) {
                            try self.decl_locations.put(self.scratch, mid, loc);
                        }
                    }
                } else if (d.kind == .interface_decl) {
                    for (d.merged_with) |mid| {
                        if (self.merged_ctor_var_consumed.contains(mid) or
                            self.merged_iface_consumed.contains(mid) or
                            self.merged_ns_consumed.contains(mid) or
                            self.merged_fn_consumed.contains(mid))
                        {
                            try self.decl_locations.put(self.scratch, mid, loc);
                        }
                    }
                } else if (d.kind == .enum_decl or d.kind == .namespace_decl) {
                    for (d.merged_with) |mid| {
                        if (mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (!merge_decls.sameWireName(wire, m_wire)) continue;
                        if (self.merged_ns_consumed.contains(mid) or self.merged_fn_consumed.contains(mid)) {
                            try self.decl_locations.put(self.scratch, mid, loc);
                        }
                    }
                }

                switch (d.kind) {
                    .namespace_decl => |children| {
                        if (!visited_ns.contains(did)) {
                            try visited_ns.put(self.scratch, did, {});
                            var nested_scope = naming.ScopeNamer.initContainer(self.scratch, scope);
                            defer nested_scope.deinit();
                            try nested_scope.reserve("zigar_js");
                            try self.prebindScopeDeclsInner(
                                final_mod_idx,
                                children,
                                &nested_scope,
                                full_path,
                                prebound_names,
                                prebound_overloads,
                                visited_ns,
                            );
                            for (d.merged_with) |mid| {
                                if (mid == did or mid >= self.graph.decls.len) continue;
                                const md = self.graph.decls[mid];
                                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                                if (!merge_decls.sameWireName(wire, m_wire)) continue;
                                if (self.merged_ns_consumed.contains(mid) and !visited_ns.contains(mid)) {
                                    try visited_ns.put(self.scratch, mid, {});
                                    try self.prebindScopeDeclsInner(
                                        final_mod_idx,
                                        md.kind.namespace_decl,
                                        &nested_scope,
                                        full_path,
                                        prebound_names,
                                        prebound_overloads,
                                        visited_ns,
                                    );
                                }
                            }
                        }
                    },
                    .enum_decl => |en| {
                        var nested_scope = naming.ScopeNamer.initContainer(self.scratch, scope);
                        defer nested_scope.deinit();
                        try nested_scope.reserve("zigar_js");
                        try nested_scope.reserve("__zigar_value");
                        try nested_scope.reserve("deinit");
                        try nested_scope.reserve("toSlice");
                        try nested_scope.reserve("fromSlice");
                        try nested_scope.reserve("toInt");
                        try nested_scope.reserve("fromInt");
                        for (en.members) |em| {
                            const emb = try nested_scope.bind(self.str(em.name), .snake);
                            emb.deinit(self.scratch);
                        }
                        for (d.merged_with) |mid| {
                            if (mid == did or mid >= self.graph.decls.len) continue;
                            const md = self.graph.decls[mid];
                            const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                            if (!merge_decls.sameWireName(wire, m_wire)) continue;
                            if (self.merged_ns_consumed.contains(mid) and !visited_ns.contains(mid)) {
                                try visited_ns.put(self.scratch, mid, {});
                                try self.prebindScopeDeclsInner(
                                    final_mod_idx,
                                    md.kind.namespace_decl,
                                    &nested_scope,
                                    full_path,
                                    prebound_names,
                                    prebound_overloads,
                                    visited_ns,
                                );
                            }
                        }
                    },
                    .interface_decl, .class_decl => {
                        const preview_tps = try self.collectMergedDeclTypeParamInfo(did);
                        var preview_tp_scope = naming.ScopeNamer.initParam(self.scratch, scope);
                        defer preview_tp_scope.deinit();
                        for (preview_tps.ids) |tp_id| {
                            const raw_tp = if (tp_id < self.graph.type_params.len)
                                self.str(self.graph.type_params[tp_id].name)
                            else
                                "T";
                            const tb = try preview_tp_scope.bindWithFallbackSuffix(raw_tp, .pascal, "T");
                            tb.deinit(self.scratch);
                        }
                        var nested_scope = naming.ScopeNamer.initContainer(self.scratch, &preview_tp_scope);
                        defer nested_scope.deinit();
                        try nested_scope.reserve("zigar_js");
                        for (d.merged_with) |mid| {
                            if (self.merged_ns_consumed.contains(mid) and !visited_ns.contains(mid)) {
                                try visited_ns.put(self.scratch, mid, {});
                                const mchildren = self.graph.decls[mid].kind.namespace_decl;
                                try self.prebindScopeDeclsInner(
                                    final_mod_idx,
                                    mchildren,
                                    &nested_scope,
                                    full_path,
                                    prebound_names,
                                    prebound_overloads,
                                    visited_ns,
                                );
                            }
                        }
                    },
                    else => {},
                }
            }
        }

        fn jsdocIsExperimentalOrDeprecated(self: *const Self, opt_jsdoc: anytype) bool {
            const jd = opt_jsdoc orelse return false;
            if (jd.is_deprecated) return true;
            for (jd.tags) |tag| {
                const tag_name = self.str(tag.name);
                if (std.mem.eql(u8, tag_name, "experimental") or
                    std.mem.eql(u8, tag_name, "beta") or
                    std.mem.eql(u8, tag_name, "alpha") or
                    std.mem.eql(u8, tag_name, "deprecated"))
                {
                    return true;
                }
            }
            return false;
        }

        fn methodIsExperimentalOrDeprecated(self: *const Self, m: anytype) bool {
            if (self.jsdocIsExperimentalOrDeprecated(m.jsdoc)) return true;
            for (m.signatures) |sid| {
                if (sid < self.graph.signatures.len) {
                    if (self.jsdocIsExperimentalOrDeprecated(self.graph.signatures[sid].jsdoc)) return true;
                }
            }
            return false;
        }

        fn lowerJsDoc(self: *Self, opt_jsdoc: anytype) !?JsDocIr {
            const jd = opt_jsdoc orelse return null;
            const summary = if (jd.summary) |s_id| self.str(s_id) else "";

            var params: std.ArrayList(JsDocParamIr) = .empty;
            var returns_txt: ?[]const u8 = null;
            var throws: std.ArrayList([]const u8) = .empty;
            var examples: std.ArrayList([]const u8) = .empty;

            for (jd.tags) |tag| {
                const tag_name = self.str(tag.name);
                const raw_text = if (tag.text) |tid| std.mem.trim(u8, self.str(tid), " \t\r\n") else "";
                if (std.mem.eql(u8, tag_name, "param") or std.mem.eql(u8, tag_name, "arg") or std.mem.eql(u8, tag_name, "argument")) {
                    var p_name: []const u8 = "";
                    var p_desc: []const u8 = raw_text;
                    if (raw_text.len > 0) {
                        var sp: usize = 0;
                        while (sp < raw_text.len and raw_text[sp] != ' ' and raw_text[sp] != '\t' and raw_text[sp] != '\r' and raw_text[sp] != '\n') : (sp += 1) {}
                        p_name = raw_text[0..sp];
                        p_desc = std.mem.trimStart(u8, raw_text[sp..], " \t-:");
                    }
                    try params.append(self.alloc, .{
                        .name = try self.alloc.dupe(u8, p_name),
                        .description = try self.alloc.dupe(u8, p_desc),
                    });
                } else if (std.mem.eql(u8, tag_name, "returns") or std.mem.eql(u8, tag_name, "return")) {
                    if (raw_text.len > 0 and returns_txt == null) {
                        returns_txt = try self.alloc.dupe(u8, raw_text);
                    }
                } else if (std.mem.eql(u8, tag_name, "throws") or std.mem.eql(u8, tag_name, "exception")) {
                    if (raw_text.len > 0) {
                        try throws.append(self.alloc, try self.alloc.dupe(u8, raw_text));
                    }
                } else if (std.mem.eql(u8, tag_name, "example")) {
                    if (raw_text.len > 0) {
                        try examples.append(self.alloc, try self.alloc.dupe(u8, raw_text));
                    }
                }
            }

            const has_any = summary.len > 0 or
                params.items.len > 0 or
                returns_txt != null or
                jd.is_deprecated or
                throws.items.len > 0 or
                examples.items.len > 0;
            if (!has_any) return null;

            const deprecated: ?[]const u8 = if (jd.is_deprecated)
                (if (jd.deprecation_message) |dm_id|
                    try self.alloc.dupe(u8, self.str(dm_id))
                else
                    "")
            else
                null;

            return .{
                .summary = try self.alloc.dupe(u8, summary),
                .params = try params.toOwnedSlice(self.alloc),
                .returns = returns_txt,
                .deprecated = deprecated,
                .throws = try throws.toOwnedSlice(self.alloc),
                .examples = try examples.toOwnedSlice(self.alloc),
            };
        }

        fn isBundledLibDecl(self: *const Self, did: u32) bool {
            if (did >= self.graph.decls.len) return false;
            const mid = self.findGraphModuleIndexById(self.graph.decls[did].module) orelse return false;
            return self.isBundledLibModule(self.graph.modules[mid]);
        }

        fn curCandHasLocalImportBinding(self: *const Self, root_ident: []const u8) bool {
            if (root_ident.len == 0) return false;
            const cidx = self.cur_cand_idx orelse return false;
            if (cidx >= self.candidates.items.len) return false;
            const cand = &self.candidates.items[cidx];

            for (cand.decl_ids.items) |did| {
                if (did >= self.graph.decls.len) continue;
                const d = self.graph.decls[did];
                if (d.kind == .import_equals_decl and std.mem.eql(u8, self.str(d.name), root_ident)) {
                    return true;
                }
            }

            if (self.vfs_sources.count() == 0) return false;
            for (cand.source_mod_ids.items) |smid| {
                const mid = self.findGraphModuleIndexById(smid) orelse continue;
                const fpath = self.str(self.graph.modules[mid].file_path);
                if (self.vfs_sources.get(fpath)) |src| {
                    if (lower_types.sourceHasLocalImportBinding(src, root_ident)) return true;
                } else if (fpath.len > 0 and fpath[0] == '/') {
                    if (self.vfs_sources.get(fpath[1..])) |src| {
                        if (lower_types.sourceHasLocalImportBinding(src, root_ident)) return true;
                    }
                }
            }
            return false;
        }

        fn isRefShadowedByUnresolvedImport(
            self: *const Self,
            ref_name: []const u8,
            target_decl: ?u32,
            module_specifier: ?u32,
        ) bool {
            if (target_decl != null) return false;
            if (std.mem.startsWith(u8, ref_name, "globalThis.")) return false;
            if (module_specifier != null) return true;
            const stripped = lower_types.stripGlobalQualifier(ref_name);
            const root_ident = if (std.mem.indexOfScalar(u8, stripped, '.')) |dot|
                stripped[0..dot]
            else
                stripped;
            return self.curCandHasLocalImportBinding(root_ident);
        }

        fn lowerBuiltinPropertyKeyType(
            self: *Self,
            active_tps: []const ActiveTypeParam,
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            needs_runtime.* = true;
            if (self.cur_mod_property_key_loc) |hloc| {
                return self.makeHoistedDeclRef(hloc);
            }
            const variants = try self.alloc.alloc(UnionVariantIr, 3);
            variants[0] = .{
                .zig_ident = try self.alloc.dupe(u8, "str"),
                .logical_name = try self.alloc.dupe(u8, "str"),
                .wire_tag = try self.alloc.dupe(u8, "str"),
                .payload = try self.makeType(.string_type),
            };
            variants[1] = .{
                .zig_ident = try self.alloc.dupe(u8, "num"),
                .logical_name = try self.alloc.dupe(u8, "num"),
                .wire_tag = try self.alloc.dupe(u8, "num"),
                .payload = try self.makeType(.f64_type),
            };
            variants[2] = .{
                .zig_ident = try self.alloc.dupe(u8, "symbol"),
                .logical_name = try self.alloc.dupe(u8, "symbol"),
                .wire_tag = try self.alloc.dupe(u8, "symbol"),
                .payload = try self.makeType(.js_symbol),
            };
            if (self.cur_mod_decls_out != null and self.cur_mod_root_scope != null) {
                const h = try self.allocFreshAnonHelperName("__zigar_PropertyKey", active_tps);
                const hloc = DeclLocation{
                    .module_index = self.cur_mod_idx,
                    .zig_path = h.path,
                    .type_param_defaults = &.{},
                };
                self.cur_mod_property_key_loc = hloc;
                try self.cur_mod_decls_out.?.append(self.alloc, .{
                    .source_decl_id = null,
                    .zig_ident = h.zig_ident,
                    .logical_name = h.logical,
                    .wire_name = h.logical,
                    .is_exported = false,
                    .is_js_exported = false,
                    .is_default_export = false,
                    .jsdoc = null,
                    .kind = .{
                        .union_decl = .{
                            .type_params = &.{},
                            .discriminant_prop = null,
                            .variants = variants,
                        },
                    },
                });
                return self.makeHoistedDeclRef(hloc);
            }
            return self.makeType(.{ .tagged_union = .{ .discriminant_prop = null, .variants = variants } });
        }

        fn lowerBuiltinArrayBufferViewType(
            self: *Self,
            active_tps: []const ActiveTypeParam,
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            needs_runtime.* = true;
            if (self.cur_mod_array_buffer_view_loc) |hloc| {
                return self.makeHoistedDeclRef(hloc);
            }
            const view_specs = [_]struct { ident: []const u8, bvk: lower_types.BinaryViewKind }{
                .{ .ident = "int8_array", .bvk = .int8_array },
                .{ .ident = "uint8_array", .bvk = .uint8_array },
                .{ .ident = "uint8_clamped_array", .bvk = .uint8_clamped_array },
                .{ .ident = "int16_array", .bvk = .int16_array },
                .{ .ident = "uint16_array", .bvk = .uint16_array },
                .{ .ident = "int32_array", .bvk = .int32_array },
                .{ .ident = "uint32_array", .bvk = .uint32_array },
                .{ .ident = "float16_array", .bvk = .float16_array },
                .{ .ident = "float32_array", .bvk = .float32_array },
                .{ .ident = "float64_array", .bvk = .float64_array },
                .{ .ident = "big_int64_array", .bvk = .big_int64_array },
                .{ .ident = "big_uint64_array", .bvk = .big_uint64_array },
                .{ .ident = "data_view", .bvk = .data_view },
            };
            const variants = try self.alloc.alloc(UnionVariantIr, view_specs.len);
            for (view_specs, 0..) |spec, idx| {
                variants[idx] = .{
                    .zig_ident = try self.alloc.dupe(u8, spec.ident),
                    .logical_name = try self.alloc.dupe(u8, spec.ident),
                    .wire_tag = try self.alloc.dupe(u8, spec.ident),
                    .payload = try self.makeType(.{ .binary_view = spec.bvk }),
                };
            }
            if (self.cur_mod_decls_out != null and self.cur_mod_root_scope != null) {
                const h = try self.allocFreshAnonHelperName("__zigar_ArrayBufferView", active_tps);
                const hloc = DeclLocation{
                    .module_index = self.cur_mod_idx,
                    .zig_path = h.path,
                    .type_param_defaults = &.{},
                };
                self.cur_mod_array_buffer_view_loc = hloc;
                try self.cur_mod_decls_out.?.append(self.alloc, .{
                    .source_decl_id = null,
                    .zig_ident = h.zig_ident,
                    .logical_name = h.logical,
                    .wire_name = h.logical,
                    .is_exported = false,
                    .is_js_exported = false,
                    .is_default_export = false,
                    .jsdoc = null,
                    .kind = .{
                        .union_decl = .{
                            .type_params = &.{},
                            .discriminant_prop = null,
                            .variants = variants,
                        },
                    },
                });
                return self.makeHoistedDeclRef(hloc);
            }
            return self.makeType(.{ .tagged_union = .{ .discriminant_prop = null, .variants = variants } });
        }

        fn lookupDeclLocation(self: *const Self, td: u32) ?struct { id: u32, loc: DeclLocation } {
            if (self.decl_locations.get(td)) |loc| {
                return .{ .id = td, .loc = loc };
            }
            if (td < self.graph.decls.len) {
                const d = self.graph.decls[td];
                for (d.merged_with) |mid| {
                    if (self.decl_locations.get(mid)) |mloc| {
                        return .{ .id = mid, .loc = mloc };
                    }
                }
            }
            return null;
        }

        fn computeTypeRefCounts(self: *Self) error{OutOfMemory}!void {
            const n = self.graph.types.len;
            const counts = try self.scratch.alloc(u32, n);
            @memset(counts, 0);
            const closed_cache = try self.scratch.alloc(u8, n);
            @memset(closed_cache, 0);

            const bump = struct {
                fn call(c: []u32, tid: u32) void {
                    if (tid < c.len) c[tid] +|= 1;
                }
            }.call;

            for (self.graph.types, 0..) |tn, idx| {
                const self_id: u32 = @intCast(idx);
                if (tn.resolved_type) |rt| {
                    if (rt != self_id) bump(counts, rt);
                }
                switch (tn.kind) {
                    .array, .readonly_array, .keyof_type => |inner| bump(counts, inner),
                    .tuple, .readonly_tuple => |elems| {
                        for (elems) |el| bump(counts, el.ty);
                    },
                    .union_type, .intersection => |arms| {
                        for (arms) |aid| bump(counts, aid);
                    },
                    .reference => |ref| {
                        for (ref.type_args) |ta| bump(counts, ta);
                    },
                    .typeof_query => |tq| {
                        if (tq.target_decl) |td| {
                            if (td < self.graph.decls.len and self.graph.decls[td].kind == .variable_decl) {
                                bump(counts, self.graph.decls[td].kind.variable_decl);
                            }
                        }
                        for (tq.type_args) |ta| bump(counts, ta);
                    },
                    .import_type => |it| {
                        for (it.type_args) |ta| bump(counts, ta);
                    },
                    .template_literal => |tl| {
                        for (tl.spans) |sp| bump(counts, sp.ty);
                    },
                    .indexed_access => |ia| {
                        bump(counts, ia.object_ty);
                        bump(counts, ia.index_ty);
                    },
                    .conditional => |cond| {
                        bump(counts, cond.check_type);
                        bump(counts, cond.extends_type);
                        bump(counts, cond.true_type);
                        bump(counts, cond.false_type);
                    },
                    .mapped => |mp| {
                        if (mp.name_type) |nt| bump(counts, nt);
                        bump(counts, mp.value_type);
                    },
                    .type_predicate => |tp| {
                        if (tp.target_type) |tt| bump(counts, tt);
                    },
                    .object_literal => |obj| {
                        for (obj.index_signatures) |isig| {
                            bump(counts, isig.key_type);
                            bump(counts, isig.value_type);
                            if (!isig.is_readonly) {
                                bump(counts, isig.key_type);
                                bump(counts, isig.value_type);
                            }
                        }
                    },
                    else => {},
                }
            }
            for (self.graph.properties) |p| {
                if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                bump(counts, p.ty);
                if (p.setter_ty) |sty| bump(counts, sty);
            }
            for (self.graph.signatures) |sig| {
                if (sig.modifiers.private_mod or sig.modifiers.protected_mod) continue;
                if (sig.this_param) |tp| bump(counts, tp);
                for (sig.params) |p| bump(counts, p.ty);
                bump(counts, sig.return_type);
                if (sig.type_predicate) |pred| {
                    if (pred.target_type) |tt| bump(counts, tt);
                }
            }
            for (self.graph.type_params) |tp| {
                if (tp.constraint) |ct| bump(counts, ct);
                if (tp.default_type) |dt| bump(counts, dt);
            }
            for (self.graph.decls) |d| {
                switch (d.kind) {
                    .variable_decl, .type_alias_decl => |ty| bump(counts, ty),
                    .interface_decl => |iface| {
                        for (iface.index_signatures) |isig| {
                            bump(counts, isig.key_type);
                            bump(counts, isig.value_type);
                            if (!isig.is_readonly) {
                                bump(counts, isig.key_type);
                                bump(counts, isig.value_type);
                            }
                        }
                    },
                    .class_decl => |cls| {
                        for (cls.index_signatures) |isig| {
                            bump(counts, isig.key_type);
                            bump(counts, isig.value_type);
                            if (!isig.is_readonly) {
                                bump(counts, isig.key_type);
                                bump(counts, isig.value_type);
                            }
                        }
                    },
                    else => {},
                }
            }

            self.type_ref_counts = counts;
            self.type_closed_cache = closed_cache;
        }

        fn isClosedTypeSubgraph(self: *Self, ty_id: u32) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len) return true;
            if (ty_id < self.type_closed_cache.len) {
                const cached = self.type_closed_cache[ty_id];
                if (cached == 2) return true;
                if (cached == 3) return false;
            }
            var bound_tps: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer bound_tps.deinit(self.scratch);
            var visiting: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visiting.deinit(self.scratch);
            return self.isClosedTypeInner(ty_id, &bound_tps, &visiting);
        }

        fn isClosedTypeInner(
            self: *Self,
            ty_id: u32,
            bound_tps: *std.AutoHashMapUnmanaged(u32, void),
            visiting: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len) return true;
            const can_cache = (bound_tps.count() == 0) and (ty_id < self.type_closed_cache.len);
            if (can_cache) {
                const cached = self.type_closed_cache[ty_id];
                if (cached == 2) return true;
                if (cached == 3) return false;
            }
            if (visiting.contains(ty_id)) return true;
            try visiting.put(self.scratch, ty_id, {});
            defer _ = visiting.remove(ty_id);

            const tn = self.graph.types[ty_id];
            const res: bool = switch (tn.kind) {
                .this_type, .infer_type => false,
                .type_param => |tp_id| bound_tps.contains(tp_id),
                .array, .readonly_array, .keyof_type => |inner| try self.isClosedTypeInner(inner, bound_tps, visiting),
                .tuple, .readonly_tuple => |elems| blk: {
                    for (elems) |el| {
                        if (!try self.isClosedTypeInner(el.ty, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .union_type, .intersection => |arms| blk: {
                    for (arms) |aid| {
                        if (!try self.isClosedTypeInner(aid, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .reference => |ref| blk: {
                    for (ref.type_args) |ta| {
                        if (!try self.isClosedTypeInner(ta, bound_tps, visiting)) break :blk false;
                    }
                    if (ref.target_decl == null and ref.type_args.len == 0 and tn.resolved_type == null) {
                        break :blk false;
                    }
                    if (self.lookupDeclLocation(ref.target_decl orelse std.math.maxInt(u32)) == null) {
                        if (ref.target_decl == null or (ref.target_decl.? < self.graph.decls.len and self.graph.decls[ref.target_decl.?].kind == .type_alias_decl)) {
                            if (tn.resolved_type) |rt| {
                                if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                            }
                        }
                    }
                    break :blk true;
                },
                .function_type, .constructor_type => |sid| try self.isClosedSigInner(sid, bound_tps, visiting),
                .object_literal => |obj| blk: {
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                        if (!try self.isClosedTypeInner(p.ty, bound_tps, visiting)) break :blk false;
                        if (p.setter_ty) |sty| {
                            if (!try self.isClosedTypeInner(sty, bound_tps, visiting)) break :blk false;
                        }
                    }
                    for (obj.call_signatures) |sid| {
                        if (!try self.isClosedSigInner(sid, bound_tps, visiting)) break :blk false;
                    }
                    for (obj.construct_signatures) |sid| {
                        if (!try self.isClosedSigInner(sid, bound_tps, visiting)) break :blk false;
                    }
                    for (obj.index_signatures) |isig| {
                        if (!try self.isClosedTypeInner(isig.key_type, bound_tps, visiting)) break :blk false;
                        if (!try self.isClosedTypeInner(isig.value_type, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .typeof_query => |tq| blk: {
                    for (tq.type_args) |ta| {
                        if (!try self.isClosedTypeInner(ta, bound_tps, visiting)) break :blk false;
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .indexed_access => |ia| blk: {
                    if (!try self.isClosedTypeInner(ia.object_ty, bound_tps, visiting)) break :blk false;
                    if (!try self.isClosedTypeInner(ia.index_ty, bound_tps, visiting)) break :blk false;
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .conditional => |cond| blk: {
                    var added: std.ArrayList(u32) = .empty;
                    defer {
                        for (added.items) | id_rm | _ = bound_tps.remove(id_rm);
                        added.deinit(self.scratch);
                    }
                    for (cond.infer_params) |tp_id| {
                        if (!bound_tps.contains(tp_id)) {
                            try bound_tps.put(self.scratch, tp_id, {});
                            try added.append(self.scratch, tp_id);
                        }
                    }
                    if (!try self.isClosedTypeInner(cond.check_type, bound_tps, visiting)) break :blk false;
                    if (!try self.isClosedTypeInner(cond.extends_type, bound_tps, visiting)) break :blk false;
                    if (!try self.isClosedTypeInner(cond.true_type, bound_tps, visiting)) break :blk false;
                    if (!try self.isClosedTypeInner(cond.false_type, bound_tps, visiting)) break :blk false;
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                .mapped => |mp| blk: {
                    const was_new = !bound_tps.contains(mp.type_param);
                    if (was_new) try bound_tps.put(self.scratch, mp.type_param, {});
                    defer if (was_new) {
                        _ = bound_tps.remove(mp.type_param);
                    };
                    if (mp.name_type) |nt| {
                        if (!try self.isClosedTypeInner(nt, bound_tps, visiting)) break :blk false;
                    }
                    if (!try self.isClosedTypeInner(mp.value_type, bound_tps, visiting)) break :blk false;
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
                else => blk: {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and !try self.isClosedTypeInner(rt, bound_tps, visiting)) break :blk false;
                    }
                    break :blk true;
                },
            };

            if (can_cache and visiting.count() == 1) {
                self.type_closed_cache[ty_id] = if (res) 2 else 3;
            }
            return res;
        }

        fn isClosedSigInner(
            self: *Self,
            sid: u32,
            bound_tps: *std.AutoHashMapUnmanaged(u32, void),
            visiting: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!bool {
            if (sid >= self.graph.signatures.len) return true;
            const sig = self.graph.signatures[sid];
            var added: std.ArrayList(u32) = .empty;
            defer {
                for (added.items) |id_rm| _ = bound_tps.remove(id_rm);
                added.deinit(self.scratch);
            }
            for (sig.type_params) |tp_id| {
                if (!bound_tps.contains(tp_id)) {
                    try bound_tps.put(self.scratch, tp_id, {});
                    try added.append(self.scratch, tp_id);
                }
            }
            for (sig.type_params) |tp_id| {
                if (tp_id >= self.graph.type_params.len) continue;
                const tp = self.graph.type_params[tp_id];
                if (tp.constraint) |ct| {
                    if (!try self.isClosedTypeInner(ct, bound_tps, visiting)) return false;
                }
                if (tp.default_type) |dt| {
                    if (!try self.isClosedTypeInner(dt, bound_tps, visiting)) return false;
                }
            }
            for (sig.params) |p| {
                if (!try self.isClosedTypeInner(p.ty, bound_tps, visiting)) return false;
            }
            if (!try self.isClosedTypeInner(sig.return_type, bound_tps, visiting)) return false;
            return true;
        }

        fn isSafeToShareTypeIrPtr(ty: *const TypeIr) bool {
            return switch (ty.*) {
                .void_type,
                .noreturn_type,
                .bool_type,
                .f64_type,
                .i64_type,
                .string_type,
                .bytes_type,
                .typed_slice,
                .js_value,
                .js_any,
                .js_unknown,
                .js_object,
                .js_function,
                .js_symbol,
                .js_bigint,
                .js_string,
                .js_date,
                .js_regexp,
                .js_disposable,
                .js_async_disposable,
                .binary_view,
                .slice,
                .pointer_const,
                .fn_ptr,
                .promise,
                .js_iterator,
                .js_async_iterator,
                .js_map,
                .js_record,
                .mapped_values_op,
                .intersect_op,
                => true,
                .optional => |opt| isSafeToShareTypeIrPtr(opt.child),
                else => false,
            };
        }

        fn allocFreshAnonHelperName(
            self: *Self,
            prefix: []const u8,
            active_tps: []const ActiveTypeParam,
        ) error{OutOfMemory}!struct { zig_ident: []const u8, logical: []const u8, path: []const []const u8 } {
            const rs = self.cur_mod_root_scope.?;
            while (true) {
                self.cur_mod_anon_counter += 1;
                const raw = try std.fmt.allocPrint(self.scratch, "{s}_{d}", .{ prefix, self.cur_mod_anon_counter });
                defer self.scratch.free(raw);
                if (rs.isTaken(raw)) continue;
                var collides_tp = false;
                for (active_tps) |tp| {
                    if (std.mem.eql(u8, tp.zig_ident, raw) or std.mem.eql(u8, tp.ts_name, raw)) {
                        collides_tp = true;
                        break;
                    }
                }
                if (collides_tp) continue;
                const b = try rs.bind(raw, .preserve);
                const zig_ident = try self.alloc.dupe(u8, b.zig_ident);
                const logical = try self.alloc.dupe(u8, b.logical_name);
                b.deinit(self.scratch);
                var path = try self.alloc.alloc([]const u8, 1);
                path[0] = zig_ident;
                return .{ .zig_ident = zig_ident, .logical = logical, .path = path };
            }
        }

        fn makeHoistedDeclRef(self: *Self, loc: DeclLocation) error{OutOfMemory}!*TypeIr {
            return self.makeType(.{
                .decl_ref = .{
                    .module_index = loc.module_index,
                    .decl_zig_path = loc.zig_path,
                    .target_decl_id = loc.target_decl_id,
                    .type_args = &.{},
                },
            });
        }

        fn makeType(self: *Self, val: TypeIr) !*TypeIr {
            const ptr = try self.alloc.create(TypeIr);
            ptr.* = val;
            return ptr;
        }

        const MergedDeclTypeParamInfo = struct {
            ids: []const u32,
            names: []const []const u8,
            defaults: []const ?u32,
        };

        fn resolveTransitiveReExportTarget(self: *const Self, start_did: u32) ?u32 {
            var cur = start_did;
            var hops: usize = 0;
            while (hops < 16) : (hops += 1) {
                if (cur >= self.graph.decls.len) return null;
                const cd = self.graph.decls[cur];
                switch (cd.kind) {
                    .re_export_decl => |re| {
                        if (re.is_namespace) return null;
                        cur = re.target_decl orelse return null;
                    },
                    .import_equals_decl => |ie| {
                        cur = ie.target_decl orelse return cur;
                    },
                    else => return cur,
                }
            }
            return null;
        }

        fn hasMergedTypeParams(self: *const Self, did: u32) bool {
            if (did >= self.graph.decls.len) return false;
            const d = self.graph.decls[did];
            if (d.type_params.len > 0) return true;
            if (d.kind != .interface_decl and d.kind != .class_decl) return false;
            const wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
            for (d.merged_with) |mid| {
                if (mid == did or mid >= self.graph.decls.len) continue;
                const md = self.graph.decls[mid];
                if (md.kind != .interface_decl and md.kind != .class_decl) continue;
                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                if (!merge_decls.sameWireName(wire, m_wire)) continue;
                if (md.type_params.len > 0) return true;
            }
            return false;
        }

        fn isEmptyObjectOrNeverGraphType(self: *const Self, tid: u32) bool {
            if (tid >= self.graph.types.len) return false;
            return switch (self.graph.types[tid].kind) {
                .never_type => true,
                .object_literal => |obj| obj.properties.len == 0 and
                    obj.call_signatures.len == 0 and
                    obj.construct_signatures.len == 0 and
                    obj.index_signatures.len == 0,
                else => false,
            };
        }

        fn isConstructorLikeTargetDecl(self: *const Self, td: u32) bool {
            if (td >= self.graph.decls.len) return false;
            const d = self.graph.decls[td];
            if (d.kind == .class_decl) return true;
            if (self.merged_ctor_var_consumed.contains(td)) return true;
            if (d.kind == .interface_decl) {
                for (d.merged_with) |mid| {
                    if (mid < self.graph.decls.len and
                        (self.graph.decls[mid].kind == .class_decl or self.merged_ctor_var_consumed.contains(mid)))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        fn unwrapExportTargetDecl(self: *const Self, start_did: u32) u32 {
            var did = start_did;
            var hops: usize = 0;
            while (hops < 16 and did < self.graph.decls.len) : (hops += 1) {
                switch (self.graph.decls[did].kind) {
                    .re_export_decl => |re| {
                        if (re.target_decl) |td| {
                            did = td;
                            continue;
                        }
                        break;
                    },
                    .import_equals_decl => |ie| {
                        if (ie.target_decl) |td| {
                            did = td;
                            continue;
                        }
                        break;
                    },
                    else => break,
                }
            }
            return did;
        }

        fn resolveImportTypeTargetDecl(
            self: *Self,
            mspec: []const u8,
            qualifier: []const u32,
            prefer_value: bool,
        ) error{OutOfMemory}!?u32 {
            if (qualifier.len == 0) return null;
            const cand_idx = (try self.resolveSpecFromCandToCandidateIdx(self.cur_cand_idx, mspec)) orelse return null;
            const cand = &self.candidates.items[cand_idx];
            const first_seg = self.str(qualifier[0]);

            var cur_did: ?u32 = null;
            if (std.mem.eql(u8, first_seg, "default")) {
                if (cand.default_export_decl_id orelse cand.export_equals_decl_id) |raw_def| {
                    cur_did = self.unwrapExportTargetDecl(raw_def);
                }
            } else {
                var v_smods: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer v_smods.deinit(self.scratch);
                var v_cands: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer v_cands.deinit(self.scratch);
                var hit_cyc = false;
                const summary = try self.getCandStarSummary(cand_idx, &v_smods, &v_cands, &hit_cyc);

                var fallback_did: ?u32 = null;
                for (summary.exported_items) |ri| {
                    if (!std.mem.eql(u8, ri.export_wire, first_seg)) continue;
                    const did = self.unwrapExportTargetDecl(ri.item.decl_id);
                    if (did >= self.graph.decls.len) continue;
                    const dk = self.graph.decls[did].kind;
                    const is_val = self.isConstructorLikeTargetDecl(did) or
                        dk == .variable_decl or dk == .function_decl or dk == .namespace_decl or dk == .enum_decl;
                    const is_ty = dk == .class_decl or dk == .interface_decl or dk == .type_alias_decl or dk == .enum_decl;
                    if ((prefer_value and is_val) or (!prefer_value and is_ty)) {
                        cur_did = did;
                        break;
                    }
                    if (fallback_did == null) fallback_did = did;
                }
                if (cur_did == null) cur_did = fallback_did;

                if (cur_did == null) {
                    for (cand.same_mod_export_equals_children.items) |raw_did| {
                        const did = self.unwrapExportTargetDecl(raw_did);
                        if (did >= self.graph.decls.len) continue;
                        const raw_d = self.graph.decls[raw_did];
                        const dwire = if (raw_d.export_name) |esid| self.str(esid) else self.str(raw_d.name);
                        if (std.mem.eql(u8, dwire, first_seg)) {
                            cur_did = did;
                            break;
                        }
                    }
                }
            }

            var step_idx: usize = 1;
            while (step_idx < qualifier.len) : (step_idx += 1) {
                const parent_id = cur_did orelse return null;
                if (parent_id >= self.graph.decls.len) return null;
                const seg = self.str(qualifier[step_idx]);
                var next_did: ?u32 = null;

                var ns_peers: [8]u32 = undefined;
                var ns_count: usize = 0;
                const pd = self.graph.decls[parent_id];
                if (pd.kind == .namespace_decl) {
                    ns_peers[ns_count] = parent_id;
                    ns_count += 1;
                }
                for (pd.merged_with) |mid| {
                    if (ns_count < ns_peers.len and mid < self.graph.decls.len and self.graph.decls[mid].kind == .namespace_decl) {
                        ns_peers[ns_count] = mid;
                        ns_count += 1;
                    }
                }

                outer_ns: for (ns_peers[0..ns_count]) |ns_id| {
                    for (self.graph.decls[ns_id].kind.namespace_decl) |cid| {
                        if (cid >= self.graph.decls.len) continue;
                        const cd = self.graph.decls[cid];
                        const cwire = if (cd.export_name) |esid| self.str(esid) else self.str(cd.name);
                        if (!std.mem.eql(u8, cwire, seg)) continue;
                        next_did = switch (cd.kind) {
                            .re_export_decl => |re| re.target_decl orelse cid,
                            .import_equals_decl => |ie| ie.target_decl orelse cid,
                            else => cid,
                        };
                        break :outer_ns;
                    }
                }
                cur_did = next_did;
            }
            return cur_did;
        }

        fn openConditionalSingleObjectBranch(self: *const Self, cond: anytype) bool {
            const non_never_id: u32 = blk: {
                if (cond.false_type < self.graph.types.len and self.graph.types[cond.false_type].kind == .never_type) {
                    break :blk cond.true_type;
                }
                if (cond.true_type < self.graph.types.len and self.graph.types[cond.true_type].kind == .never_type) {
                    break :blk cond.false_type;
                }
                return false;
            };
            if (non_never_id >= self.graph.types.len) return false;
            return switch (self.graph.types[non_never_id].kind) {
                .object_literal => |obj| obj.call_signatures.len == 0 and obj.construct_signatures.len == 0,
                .object_type, .mapped => true,
                .reference => |ref| blk_ref: {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            break :blk_ref switch (self.graph.decls[td].kind) {
                                .interface_decl => |iface| iface.call_signatures.len == 0 and iface.construct_signatures.len == 0,
                                .class_decl => true,
                                else => false,
                            };
                        }
                    }
                    break :blk_ref false;
                },
                else => false,
            };
        }

        /// Merges type parameters across same-symbol `class_decl` / `interface_decl` merges
        /// (`interface Foo<T>` + `interface Foo<T = string, U = number>`), preserving trailing
        /// defaulted parameters and filling in omitted defaults from merged peer declarations.
        fn collectMergedDeclTypeParamInfo(self: *Self, did: u32) error{OutOfMemory}!MergedDeclTypeParamInfo {
            if (did >= self.graph.decls.len) {
                return .{ .ids = &.{}, .names = &.{}, .defaults = &.{} };
            }
            const d = self.graph.decls[did];
            const wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);

            var max_len: usize = d.type_params.len;
            if (d.kind == .interface_decl or d.kind == .class_decl) {
                for (d.merged_with) |mid| {
                    if (mid == did or mid >= self.graph.decls.len) continue;
                    const md = self.graph.decls[mid];
                    if (md.kind != .interface_decl and md.kind != .class_decl) continue;
                    const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                    if (!merge_decls.sameWireName(wire, m_wire)) continue;
                    if (md.type_params.len > max_len) max_len = md.type_params.len;
                }
            }
            if (max_len == 0) {
                return .{ .ids = &.{}, .names = &.{}, .defaults = &.{} };
            }

            var ids = try self.alloc.alloc(u32, max_len);
            var names = try self.alloc.alloc([]const u8, max_len);
            var defaults = try self.alloc.alloc(?u32, max_len);

            for (0..max_len) |idx| {
                var chosen_id: u32 = if (idx < d.type_params.len) d.type_params[idx] else std.math.maxInt(u32);
                var chosen_default: ?u32 = if (chosen_id < self.graph.type_params.len)
                    self.graph.type_params[chosen_id].default_type
                else
                    null;

                if (d.kind == .interface_decl or d.kind == .class_decl) {
                    for (d.merged_with) |mid| {
                        if (mid == did or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .interface_decl and md.kind != .class_decl) continue;
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (!merge_decls.sameWireName(wire, m_wire)) continue;
                        if (idx < md.type_params.len) {
                            const peer_tp_id = md.type_params[idx];
                            if (chosen_id == std.math.maxInt(u32)) chosen_id = peer_tp_id;
                            if (chosen_default == null and peer_tp_id < self.graph.type_params.len) {
                                chosen_default = self.graph.type_params[peer_tp_id].default_type;
                            }
                        }
                    }
                }

                // If a merged peer supplies the default_type (or constraint) missing on `chosen_id`,
                // prefer the peer `tp_id` when `chosen_id` lacks a `default_type`.
                if (chosen_id < self.graph.type_params.len and
                    self.graph.type_params[chosen_id].default_type == null and
                    chosen_default != null)
                {
                    for (d.merged_with) |mid| {
                        if (mid == did or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .interface_decl and md.kind != .class_decl) continue;
                        if (idx < md.type_params.len) {
                            const peer_tp_id = md.type_params[idx];
                            if (peer_tp_id < self.graph.type_params.len and
                                self.graph.type_params[peer_tp_id].default_type != null)
                            {
                                chosen_id = peer_tp_id;
                                break;
                            }
                        }
                    }
                }

                ids[idx] = chosen_id;
                names[idx] = if (chosen_id < self.graph.type_params.len)
                    try self.alloc.dupe(u8, self.str(self.graph.type_params[chosen_id].name))
                else
                    "T";
                defaults[idx] = chosen_default;
            }

            return .{ .ids = ids, .names = names, .defaults = defaults };
        }

        fn typeIrMentionsSelfOrTypeParamsFrom(
            ty: *const TypeIr,
            tps: []const TypeParamIr,
            from_idx: usize,
            depth: usize,
        ) bool {
            if (depth >= 24) return true;
            return switch (ty.*) {
                .self_type => true,
                .type_param_ref => |id| blk: {
                    for (tps[from_idx..]) |tp| {
                        if (std.mem.eql(u8, tp.zig_ident, id)) break :blk true;
                    }
                    break :blk false;
                },
                .optional => |opt| typeIrMentionsSelfOrTypeParamsFrom(opt.child, tps, from_idx, depth + 1),
                .pointer_const, .slice, .promise, .js_iterator, .js_async_iterator => |inner| typeIrMentionsSelfOrTypeParamsFrom(inner, tps, from_idx, depth + 1),
                .js_map => |m| typeIrMentionsSelfOrTypeParamsFrom(m.key, tps, from_idx, depth + 1) or
                    typeIrMentionsSelfOrTypeParamsFrom(m.value, tps, from_idx, depth + 1),
                .js_record => |r| typeIrMentionsSelfOrTypeParamsFrom(r.key, tps, from_idx, depth + 1) or
                    typeIrMentionsSelfOrTypeParamsFrom(r.value, tps, from_idx, depth + 1),
                .mapped_values_op => |mv| typeIrMentionsSelfOrTypeParamsFrom(mv.target, tps, from_idx, depth + 1) or
                    typeIrMentionsSelfOrTypeParamsFrom(mv.value, tps, from_idx, depth + 1),
                .unary_type_op => |uo| typeIrMentionsSelfOrTypeParamsFrom(uo.operand, tps, from_idx, depth + 1),
                .key_filter_op => |kfo| typeIrMentionsSelfOrTypeParamsFrom(kfo.target, tps, from_idx, depth + 1) or
                    (switch (kfo.keys) {
                        .ty => |kt| typeIrMentionsSelfOrTypeParamsFrom(kt, tps, from_idx, depth + 1),
                        else => false,
                    }),
                .index_access_op => |iao| typeIrMentionsSelfOrTypeParamsFrom(iao.object_ty, tps, from_idx, depth + 1) or
                    (switch (iao.index_spec) {
                        .ty => |kt| typeIrMentionsSelfOrTypeParamsFrom(kt, tps, from_idx, depth + 1),
                        else => false,
                    }) or
                    (if (iao.fallback_ty) |ft| typeIrMentionsSelfOrTypeParamsFrom(ft, tps, from_idx, depth + 1) else false),
                .empty_object_extends_op => |eoe| typeIrMentionsSelfOrTypeParamsFrom(eoe.target_ty, tps, from_idx, depth + 1) or
                    typeIrMentionsSelfOrTypeParamsFrom(eoe.true_ty, tps, from_idx, depth + 1) or
                    typeIrMentionsSelfOrTypeParamsFrom(eoe.false_ty, tps, from_idx, depth + 1),
                .intersect_op => |arms| blk: {
                    for (arms) |arm| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(arm, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .tuple => |elems| blk: {
                    for (elems) |el| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(el.ty, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .fn_ptr => |fp| blk: {
                    if (fp.this_param) |thp| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(thp, tps, from_idx, depth + 1)) break :blk true;
                    }
                    for (fp.params) |pt| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(pt, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk typeIrMentionsSelfOrTypeParamsFrom(fp.return_type, tps, from_idx, depth + 1);
                },
                .anon_struct => |fields| blk: {
                    for (fields) |f| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(f.ty, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .tagged_union => |tu| blk: {
                    for (tu.variants) |v| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(v.payload, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .decl_ref => |dr| blk: {
                    for (dr.type_args) |ta| {
                        if (typeIrMentionsSelfOrTypeParamsFrom(ta, tps, from_idx, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn lowerTypeParams(
            self: *Self,
            raw_tp_ids: []const u32,
            tp_scope: *naming.ScopeNamer,
            outer_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!LoweredTypeParams {
            return self.lowerTypeParamsWithSkip(
                raw_tp_ids,
                &.{},
                tp_scope,
                outer_active_tps,
                self_ident_opt,
                imports_used,
                needs_runtime,
            );
        }

        fn lowerTypeParamsWithSkip(
            self: *Self,
            raw_tp_ids: []const u32,
            skip_tp_ids: []const u32,
            tp_scope: *naming.ScopeNamer,
            outer_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!LoweredTypeParams {
            var kept_tp_ids: std.ArrayList(u32) = .empty;
            defer kept_tp_ids.deinit(self.scratch);
            for (raw_tp_ids) |tp_id| {
                var skipped = false;
                for (skip_tp_ids) |sid| {
                    if (sid == tp_id) {
                        skipped = true;
                        break;
                    }
                }
                if (!skipped) try kept_tp_ids.append(self.scratch, tp_id);
            }
            const eff_tp_ids = kept_tp_ids.items;

            var ir_list = try self.alloc.alloc(TypeParamIr, eff_tp_ids.len);
            var combined_active = try self.alloc.alloc(ActiveTypeParam, outer_active_tps.len + eff_tp_ids.len);
            @memcpy(combined_active[0..outer_active_tps.len], outer_active_tps);

            // Bind all type parameter names first so mutual constraints (`<T extends U, U>`) resolve cleanly.
            for (eff_tp_ids, 0..) |tp_id, idx| {
                const has_tp = tp_id < self.graph.type_params.len;
                const raw_name = if (has_tp)
                    self.str(self.graph.type_params[tp_id].name)
                else
                    "T";
                const bound = try tp_scope.bindWithFallbackSuffix(raw_name, .pascal, "T");
                const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                const logical = try self.alloc.dupe(u8, bound.logical_name);
                const wire = try self.alloc.dupe(u8, bound.wire_name);
                bound.deinit(self.scratch);

                ir_list[idx] = .{
                    .zig_ident = zig_ident,
                    .logical_name = logical,
                    .wire_name = wire,
                    .constraint = null,
                    .default_type = null,
                    .is_const = if (has_tp) self.graph.type_params[tp_id].is_const else false,
                    .variance = if (has_tp)
                        lower_generics.classifyVariance(
                            self.graph.type_params[tp_id].in_variance,
                            self.graph.type_params[tp_id].out_variance,
                        )
                    else
                        .invariant,
                    .enforce_constraint = false,
                };
                combined_active[outer_active_tps.len + idx] = .{
                    .ts_name = wire,
                    .zig_ident = zig_ident,
                };
            }

            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);

            for (eff_tp_ids, 0..) |tp_id, idx| {
                if (tp_id >= self.graph.type_params.len) continue;
                const tp = self.graph.type_params[tp_id];
                if (tp.constraint) |ct| {
                    visited.clearRetainingCapacity();
                    const lowered_ct = try self.lowerType(
                        ct,
                        true,
                        combined_active,
                        self_ident_opt,
                        &visited,
                        imports_used,
                        needs_runtime,
                    );
                    ir_list[idx].constraint = lowered_ct;
                    const trivial_ct = switch (lowered_ct.*) {
                        .js_any, .js_unknown, .js_value, .void_type => true,
                        else => false,
                    };
                    if (!trivial_ct and !typeIrMentionsSelfOrTypeParamsFrom(lowered_ct, ir_list, idx, 0)) {
                        ir_list[idx].enforce_constraint = true;
                        needs_runtime.* = true;
                    }
                }
                if (tp.default_type) |dt| {
                    if (dt < self.graph.types.len and self.graph.types[dt].kind == .never_type) {
                        needs_runtime.* = true;
                        ir_list[idx].default_type = try self.makeType(.js_any);
                    } else {
                        visited.clearRetainingCapacity();
                        ir_list[idx].default_type = try self.lowerGenericTypeArg(
                            dt,
                            combined_active,
                            self_ident_opt,
                            &visited,
                            imports_used,
                            needs_runtime,
                        );
                    }
                }
            }

            return .{ .ir = ir_list, .active = combined_active };
        }

        fn graphTypeIsInsideNoInfer(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth >= 8 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .reference => |ref| blk: {
                    const ref_name = lower_types.stripGlobalQualifier(self.str(ref.target_name));
                    if ((ref.target_decl == null or self.isBundledLibDecl(ref.target_decl.?)) and
                        std.mem.eql(u8, ref_name, "NoInfer"))
                    {
                        break :blk true;
                    }
                    break :blk false;
                },
                .union_type => |arms| blk: {
                    for (arms) |aid| {
                        if (self.graphTypeIsInsideNoInfer(aid, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn classifyParamForTypeParamInference(
            ty: *const TypeIr,
            tps: []const TypeParamIr,
        ) lower_generics.ParamTypeParamShape {
            switch (ty.*) {
                .type_param_ref => |id| {
                    for (tps, 0..) |tp, idx| {
                        if (std.mem.eql(u8, tp.zig_ident, id)) return .{ .direct = idx };
                    }
                },
                .slice => |el| {
                    if (el.* == .type_param_ref) {
                        for (tps, 0..) |tp, idx| {
                            if (std.mem.eql(u8, tp.zig_ident, el.type_param_ref)) return .{ .slice_elem = idx };
                        }
                    }
                },
                .optional => |opt| {
                    if (!opt.is_pure_nullish and opt.child.* == .type_param_ref) {
                        for (tps, 0..) |tp, idx| {
                            if (std.mem.eql(u8, tp.zig_ident, opt.child.type_param_ref)) return .{ .optional_child = idx };
                        }
                    }
                },
                .promise => |inner| {
                    if (inner.* == .type_param_ref) {
                        for (tps, 0..) |tp, idx| {
                            if (std.mem.eql(u8, tp.zig_ident, inner.type_param_ref)) return .{ .promise_payload = idx };
                        }
                    }
                },
                .js_iterator, .js_async_iterator => |inner| {
                    if (inner.* == .type_param_ref) {
                        for (tps, 0..) |tp, idx| {
                            if (std.mem.eql(u8, tp.zig_ident, inner.type_param_ref)) return .{ .iterator_elem = idx };
                        }
                    }
                },
                .decl_ref => |dr| {
                    for (dr.type_args) |ta| {
                        if (ta.* == .type_param_ref) {
                            for (tps, 0..) |tp, idx| {
                                if (std.mem.eql(u8, tp.zig_ident, ta.type_param_ref) and isPropertyKeyConstrainedTypeParam(tp)) {
                                    return .{ .literal_key = idx };
                                }
                            }
                        }
                    }
                },
                else => {},
            }
            return .none;
        }

        fn isPropertyKeyConstrainedTypeParam(tp: TypeParamIr) bool {
            const ct = tp.constraint orelse return false;
            return isPropertyKeyLikeTypeIr(ct, 0);
        }

        fn isPropertyKeyLikeTypeIr(ty: *const TypeIr, depth: usize) bool {
            if (depth >= 6) return false;
            return switch (ty.*) {
                .string_type, .js_string, .f64_type, .js_symbol, .inline_enum, .open_literal_union, .template_pattern => true,
                .unary_type_op => |uo| uo.op == .keyof,
                .decl_ref => |dr| dr.decl_zig_path.len == 1 and std.mem.startsWith(u8, dr.decl_zig_path[0], "__zigar_PropertyKey"),
                .tagged_union => |tu| blk: {
                    if (tu.variants.len == 0) break :blk false;
                    for (tu.variants) |v| {
                        if (!isPropertyKeyLikeTypeIr(v.payload, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                else => false,
            };
        }

        fn typeTreeMentionsActiveTypeParam(
            self: *const Self,
            ty_id: u32,
            active_tps: []const ActiveTypeParam,
            locally_bound_tp_ids: []const u32,
            depth: usize,
        ) bool {
            if (active_tps.len == 0 or depth >= 20 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .type_param, .infer_type => |tp_id| blk: {
                    for (locally_bound_tp_ids) |bid| {
                        if (bid == tp_id) break :blk false;
                    }
                    const tp_name = if (tp_id < self.graph.type_params.len)
                        self.str(self.graph.type_params[tp_id].name)
                    else
                        "";
                    for (active_tps) |atp| {
                        if (std.mem.eql(u8, atp.ts_name, tp_name)) break :blk true;
                    }
                    break :blk false;
                },
                .array, .readonly_array, .keyof_type => |inner| self.typeTreeMentionsActiveTypeParam(inner, active_tps, locally_bound_tp_ids, depth + 1),
                .tuple, .readonly_tuple => |elems| blk: {
                    for (elems) |el| {
                        if (self.typeTreeMentionsActiveTypeParam(el.ty, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .union_type, .intersection => |arms| blk: {
                    for (arms) |aid| {
                        if (self.typeTreeMentionsActiveTypeParam(aid, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .reference => |ref| blk: {
                    const ref_name = self.str(ref.target_name);
                    var shadowed = false;
                    for (locally_bound_tp_ids) |bid| {
                        if (bid < self.graph.type_params.len and
                            std.mem.eql(u8, self.str(self.graph.type_params[bid].name), ref_name))
                        {
                            shadowed = true;
                            break;
                        }
                    }
                    if (!shadowed) {
                        for (active_tps) |atp| {
                            if (std.mem.eql(u8, atp.ts_name, ref_name)) break :blk true;
                        }
                    }
                    for (ref.type_args) |ta| {
                        if (self.typeTreeMentionsActiveTypeParam(ta, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const dd = self.graph.decls[td];
                            if (dd.kind == .type_alias_decl and dd.type_params.len == 0) {
                                break :blk self.typeTreeMentionsActiveTypeParam(dd.kind.type_alias_decl, active_tps, locally_bound_tp_ids, depth + 1);
                            }
                        }
                    }
                    break :blk false;
                },
                .indexed_access => |ia| self.typeTreeMentionsActiveTypeParam(ia.object_ty, active_tps, locally_bound_tp_ids, depth + 1) or
                    self.typeTreeMentionsActiveTypeParam(ia.index_ty, active_tps, locally_bound_tp_ids, depth + 1),
                .mapped => |mp| blk: {
                    if (mp.type_param < self.graph.type_params.len) {
                        if (self.graph.type_params[mp.type_param].constraint) |ct| {
                            if (self.typeTreeMentionsActiveTypeParam(ct, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                        }
                    }
                    var ext_buf: [16]u32 = undefined;
                    const ext_slice: []const u32 = if (locally_bound_tp_ids.len < ext_buf.len) sblk: {
                        @memcpy(ext_buf[0..locally_bound_tp_ids.len], locally_bound_tp_ids);
                        ext_buf[locally_bound_tp_ids.len] = mp.type_param;
                        break :sblk ext_buf[0 .. locally_bound_tp_ids.len + 1];
                    } else locally_bound_tp_ids;
                    if (mp.name_type) |nt| {
                        if (self.typeTreeMentionsActiveTypeParam(nt, active_tps, ext_slice, depth + 1)) break :blk true;
                    }
                    break :blk self.typeTreeMentionsActiveTypeParam(mp.value_type, active_tps, ext_slice, depth + 1);
                },
                .conditional => |cond| blk: {
                    if (self.typeTreeMentionsActiveTypeParam(cond.check_type, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    var ext_buf: [16]u32 = undefined;
                    const ext_slice: []const u32 = if (locally_bound_tp_ids.len + cond.infer_params.len <= ext_buf.len) sblk: {
                        @memcpy(ext_buf[0..locally_bound_tp_ids.len], locally_bound_tp_ids);
                        @memcpy(ext_buf[locally_bound_tp_ids.len .. locally_bound_tp_ids.len + cond.infer_params.len], cond.infer_params);
                        break :sblk ext_buf[0 .. locally_bound_tp_ids.len + cond.infer_params.len];
                    } else locally_bound_tp_ids;
                    if (self.typeTreeMentionsActiveTypeParam(cond.extends_type, active_tps, ext_slice, depth + 1)) break :blk true;
                    if (self.typeTreeMentionsActiveTypeParam(cond.true_type, active_tps, ext_slice, depth + 1)) break :blk true;
                    break :blk self.typeTreeMentionsActiveTypeParam(cond.false_type, active_tps, ext_slice, depth + 1);
                },
                .template_literal => |tl| blk: {
                    for (tl.spans) |sp| {
                        if (self.typeTreeMentionsActiveTypeParam(sp.ty, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .typeof_query => |tq| blk: {
                    for (tq.type_args) |ta| {
                        if (self.typeTreeMentionsActiveTypeParam(ta, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .import_type => |it| blk: {
                    for (it.type_args) |ta| {
                        if (self.typeTreeMentionsActiveTypeParam(ta, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .function_type, .constructor_type => |sid| blk: {
                    if (sid >= self.graph.signatures.len) break :blk false;
                    const sig = self.graph.signatures[sid];
                    var ext_buf: [16]u32 = undefined;
                    const ext_slice: []const u32 = if (locally_bound_tp_ids.len + sig.type_params.len <= ext_buf.len) sblk: {
                        @memcpy(ext_buf[0..locally_bound_tp_ids.len], locally_bound_tp_ids);
                        @memcpy(ext_buf[locally_bound_tp_ids.len .. locally_bound_tp_ids.len + sig.type_params.len], sig.type_params);
                        break :sblk ext_buf[0 .. locally_bound_tp_ids.len + sig.type_params.len];
                    } else locally_bound_tp_ids;
                    if (sig.this_param) |thp| {
                        if (self.typeTreeMentionsActiveTypeParam(thp, active_tps, ext_slice, depth + 1)) break :blk true;
                    }
                    for (sig.params) |p| {
                        if (self.typeTreeMentionsActiveTypeParam(p.ty, active_tps, ext_slice, depth + 1)) break :blk true;
                    }
                    break :blk self.typeTreeMentionsActiveTypeParam(sig.return_type, active_tps, ext_slice, depth + 1);
                },
                .object_literal => |obj| blk: {
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                        if (self.typeTreeMentionsActiveTypeParam(p.ty, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                        if (p.setter_ty) |sty| {
                            if (self.typeTreeMentionsActiveTypeParam(sty, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                        }
                    }
                    for (obj.index_signatures) |isig| {
                        if (self.typeTreeMentionsActiveTypeParam(isig.key_type, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                        if (self.typeTreeMentionsActiveTypeParam(isig.value_type, active_tps, locally_bound_tp_ids, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn graphTypesSameSymbolOrNode(self: *const Self, a_id: u32, b_id: u32) bool {
            if (a_id == b_id) return true;
            if (a_id >= self.graph.types.len or b_id >= self.graph.types.len) return false;
            const name_a: ?[]const u8 = switch (self.graph.types[a_id].kind) {
                .type_param, .infer_type => |tp_id| if (tp_id < self.graph.type_params.len) self.str(self.graph.type_params[tp_id].name) else null,
                .reference => |r| if (r.type_args.len == 0) self.str(r.target_name) else null,
                else => null,
            };
            const name_b: ?[]const u8 = switch (self.graph.types[b_id].kind) {
                .type_param, .infer_type => |tp_id| if (tp_id < self.graph.type_params.len) self.str(self.graph.type_params[tp_id].name) else null,
                .reference => |r| if (r.type_args.len == 0) self.str(r.target_name) else null,
                else => null,
            };
            if (name_a != null and name_b != null) return std.mem.eql(u8, name_a.?, name_b.?);
            return false;
        }

        fn isPureNullishGraphType(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth >= 8 or ty_id >= self.graph.types.len) return false;
            return switch (self.graph.types[ty_id].kind) {
                .null_type, .undefined_type, .void_type => true,
                .union_type => |arms| blk: {
                    if (arms.len == 0) break :blk false;
                    for (arms) |aid| {
                        if (!self.isPureNullishGraphType(aid, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                else => false,
            };
        }

        fn lowerKeyFilterSpec(
            self: *Self,
            key_ty_id: u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!KeyFilterSpecIr {
            if (!self.typeTreeMentionsActiveTypeParam(key_ty_id, active_tps, &.{}, 0)) {
                if (try self.extractClosedLiteralFromType(key_ty_id, 0)) |cl| {
                    switch (cl) {
                        .str => |s| return .{ .str_lit = try self.alloc.dupe(u8, s) },
                        else => {},
                    }
                }
                const eff_id = if (key_ty_id < self.graph.types.len and self.graph.types[key_ty_id].resolved_type != null)
                    self.graph.types[key_ty_id].resolved_type.?
                else
                    key_ty_id;
                var finite_strs: std.ArrayList([]const u8) = .empty;
                defer finite_strs.deinit(self.alloc);
                if (try self.tryExpandFiniteStringSet(eff_id, &finite_strs, 0) and finite_strs.items.len > 0) {
                    if (finite_strs.items.len == 1) {
                        return .{ .str_lit = try self.alloc.dupe(u8, finite_strs.items[0]) };
                    }
                    const out = try self.alloc.alloc([]const u8, finite_strs.items.len);
                    for (finite_strs.items, 0..) |s, idx| {
                        out[idx] = try self.alloc.dupe(u8, s);
                    }
                    return .{ .str_list = out };
                }
            }
            const kt = try self.lowerType(key_ty_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
            return .{ .ty = kt };
        }

        fn lowerIndexAccessSpec(
            self: *Self,
            idx_ty_id: u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!IndexAccessSpecIr {
            if (!self.typeTreeMentionsActiveTypeParam(idx_ty_id, active_tps, &.{}, 0)) {
                if (try self.extractClosedLiteralFromType(idx_ty_id, 0)) |cl| {
                    switch (cl) {
                        .str => |s| return .{ .str_lit = try self.alloc.dupe(u8, s) },
                        .num => |n| {
                            if (n >= 0 and @trunc(n) == n and n <= @as(f64, @floatFromInt(std.math.maxInt(u32)))) {
                                return .{ .int_lit = @intFromFloat(n) };
                            }
                        },
                        else => {},
                    }
                }
                const eff_id = if (idx_ty_id < self.graph.types.len and self.graph.types[idx_ty_id].resolved_type != null)
                    self.graph.types[idx_ty_id].resolved_type.?
                else
                    idx_ty_id;
                var finite_strs: std.ArrayList([]const u8) = .empty;
                defer finite_strs.deinit(self.alloc);
                if (try self.tryExpandFiniteStringSet(eff_id, &finite_strs, 0) and finite_strs.items.len > 0) {
                    if (finite_strs.items.len == 1) {
                        return .{ .str_lit = try self.alloc.dupe(u8, finite_strs.items[0]) };
                    }
                    const out = try self.alloc.alloc([]const u8, finite_strs.items.len);
                    for (finite_strs.items, 0..) |s, idx| {
                        out[idx] = try self.alloc.dupe(u8, s);
                    }
                    return .{ .str_list = out };
                }
            }
            const kt = try self.lowerType(idx_ty_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
            return .{ .ty = kt };
        }

        fn lowerType(
            self: *Self,
            ty_id: u32,
            is_return_pos: bool,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            if (ty_id >= self.graph.types.len) {
                needs_runtime.* = true;
                return self.makeType(.js_any);
            }
            if (!is_return_pos or !self.typeHasTopLevelPositionalIterable(ty_id, 0)) {
                if (self.cur_mod_hoisted_locs.get(ty_id)) |hloc| {
                    return self.makeHoistedDeclRef(hloc);
                }
            }
            if (!is_return_pos) {
                if (self.cur_mod_closed_types.get(ty_id)) |cached_ty| {
                    return cached_ty;
                }
            }
            if (visited.contains(ty_id)) {
                needs_runtime.* = true;
                return self.makeType(.js_any);
            }
            try visited.put(self.scratch, ty_id, {});
            defer _ = visited.remove(ty_id);

            const tn = self.graph.types[ty_id];
            const ref_cnt: u32 = if (ty_id < self.type_ref_counts.len) self.type_ref_counts[ty_id] else 1;
            const can_hoist_in_mod = (self.cur_mod_decls_out != null and self.cur_mod_root_scope != null);
            const no_free_vars = (active_tps.len == 0 and self_ident_opt == null);

            switch (tn.kind) {
                .void_type, .undefined_type => return self.makeType(.void_type),
                .never_type => {
                    if (is_return_pos) return self.makeType(.noreturn_type);
                    return self.makeType(.void_type);
                },
                .null_type => {
                    needs_runtime.* = true;
                    const inner = try self.makeType(.js_any);
                    return self.makeType(.{ .optional = .{ .child = inner, .nullish_kind = .null_only, .is_pure_nullish = true } });
                },
                .boolean_type => return self.makeType(.bool_type),
                .number_type => return self.makeType(.f64_type),
                .bigint_type => return self.makeType(.i64_type),
                .string_type => return self.makeType(.string_type),
                .intrinsic => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) {
                            return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        }
                    }
                    return self.makeType(.string_type);
                },
                .template_literal => |tl| {
                    return self.lowerTemplateLiteralInline(
                        ty_id,
                        tl,
                        tn.resolved_type,
                        ref_cnt,
                        can_hoist_in_mod,
                        no_free_vars,
                        active_tps,
                        self_ident_opt,
                        visited,
                        imports_used,
                        needs_runtime,
                    );
                },
                .symbol_type, .unique_symbol => {
                    needs_runtime.* = true;
                    return self.makeType(.js_symbol);
                },
                .any_type => {
                    needs_runtime.* = true;
                    return self.makeType(.js_any);
                },
                .unknown_type => {
                    needs_runtime.* = true;
                    return self.makeType(.js_unknown);
                },
                .object_type => {
                    needs_runtime.* = true;
                    return self.makeType(.js_object);
                },
                .this_type => {
                    if (self_ident_opt) |sid| {
                        const self_t = try self.makeType(.{ .self_type = sid });
                        if (self.in_handle_struct) return self_t;
                        return self.makeType(.{ .pointer_const = self_t });
                    }
                    needs_runtime.* = true;
                    return self.makeType(.js_any);
                },
                .literal => |lit| return switch (lit) {
                    .str => self.makeType(.string_type),
                    .num => self.makeType(.f64_type),
                    .bigint_literal => self.makeType(.i64_type),
                    .boolean => self.makeType(.bool_type),
                },
                .type_param, .infer_type => |tp_id| {
                    const tp_name = if (tp_id < self.graph.type_params.len)
                        self.str(self.graph.type_params[tp_id].name)
                    else
                        "";
                    var i: usize = active_tps.len;
                    while (i > 0) {
                        i -= 1;
                        if (std.mem.eql(u8, active_tps[i].ts_name, tp_name)) {
                            if (active_tps[i].subst_ty) |sub| return sub;
                            return self.makeType(.{ .type_param_ref = active_tps[i].zig_ident });
                        }
                    }
                    needs_runtime.* = true;
                    return self.makeType(.js_any);
                },
                .array, .readonly_array => |elem_id| {
                    const elem = try self.lowerType(elem_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                    const res = try self.makeType(.{ .slice = elem });
                    if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                    }
                    return res;
                },
                .tuple, .readonly_tuple => |elems| {
                    var tup_scope = naming.ScopeNamer.initContainer(self.scratch, null);
                    defer tup_scope.deinit();
                    try tup_scope.reserve("zigar_js");
                    try tup_scope.reserve("zigar_js_tuple");

                    var out_elems = try self.alloc.alloc(TupleElemIr, elems.len);
                    for (elems, 0..) |el, idx| {
                        const raw_lbl = if (el.label) |lsid| self.str(lsid) else null;
                        const fallback_lbl = if (raw_lbl) |l| l else try std.fmt.allocPrint(self.alloc, "{d}", .{idx});
                        const bound = try tup_scope.bind(fallback_lbl, if (raw_lbl != null) .snake else .preserve);
                        const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                        bound.deinit(self.scratch);

                        var elem_ty = try self.lowerType(el.ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        if (el.variadic) {
                            if (!self.isAlreadySliceTypeIr(elem_ty, 0)) {
                                elem_ty = try self.makeType(.{ .slice = elem_ty });
                            }
                        } else if (el.optional) {
                            elem_ty = try self.wrapOptionalWithNullish(elem_ty, .undefined_only);
                        }
                        out_elems[idx] = .{
                            .zig_ident = zig_ident,
                            .wire_label = if (raw_lbl) |l| try self.alloc.dupe(u8, l) else null,
                            .ty = elem_ty,
                            .is_optional = el.optional and !el.variadic,
                            .is_variadic = el.variadic,
                            .nullish_kind = if (!el.variadic and elem_ty.* == .optional) elem_ty.optional.nullish_kind else .none,
                        };
                    }
                    const tup_ir = try self.makeType(.{ .tuple = out_elems });
                    if (ref_cnt > 1 and elems.len > 0 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                        const h = try self.allocFreshAnonHelperName("__zigar_AnonTuple", active_tps);
                        const hloc = DeclLocation{
                            .module_index = self.cur_mod_idx,
                            .zig_path = h.path,
                            .type_param_defaults = &.{},
                        };
                        try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{ .type_alias = .{ .type_params = &.{}, .target = tup_ir } },
                        });
                        return self.makeHoistedDeclRef(hloc);
                    }
                    return tup_ir;
                },
                .union_type => |arms| {
                    return self.lowerUnionTypeInline(
                        ty_id,
                        arms,
                        is_return_pos,
                        ref_cnt,
                        can_hoist_in_mod,
                        no_free_vars,
                        active_tps,
                        self_ident_opt,
                        visited,
                        imports_used,
                        needs_runtime,
                    );
                },
                .reference => |ref| {
                    const ref_name = self.str(ref.target_name);

                    // Check active generic type parameter first in case TS emitted a reference node.
                    {
                        var i: usize = active_tps.len;
                        while (i > 0) {
                            i -= 1;
                            if (std.mem.eql(u8, active_tps[i].ts_name, ref_name)) {
                                if (active_tps[i].subst_ty) |sub| return sub;
                                return self.makeType(.{ .type_param_ref = active_tps[i].zig_ident });
                            }
                        }
                    }

                    // Built-in JS/Node binary buffer & view types and boxed global wrappers (`BigInt`, `String`, `Symbol`, `Object`).
                    if (!self.isRefShadowedByUnresolvedImport(ref_name, ref.target_decl, ref.module_specifier) and
                        self.isBuiltinMappedReference(ref_name, ref.type_args.len, ref.target_decl))
                    {
                        needs_runtime.* = true;
                        if (lower_types.BinaryViewKind.fromTypeName(ref_name)) |bvk| {
                            const res = try self.makeType(.{ .binary_view = bvk });
                            if (ref_cnt > 1 and can_hoist_in_mod and no_free_vars) {
                                try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                            }
                            return res;
                        }
                        if (lower_types.BoxedIntrinsicKind.fromTypeName(ref_name)) |bik| {
                            const tag: TypeIr = switch (bik) {
                                .bigint => .js_bigint,
                                .string => .js_string,
                                .symbol => .js_symbol,
                                .object => .js_object,
                                .date => .js_date,
                                .regexp => .js_regexp,
                                .function => .js_function,
                            };
                            const res = try self.makeType(tag);
                            if (ref_cnt > 1 and can_hoist_in_mod and no_free_vars) {
                                try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                            }
                            return res;
                        }
                    }

                    // Built-in ES iteration & resource disposal protocols (`Iterable<T>`, `Iterator<T>`,
                    // `AsyncIterable<T>`, `AsyncIterator<T>`, `Disposable`, `AsyncDisposable`, etc.).
                    if (!self.isRefShadowedByUnresolvedImport(ref_name, ref.target_decl, ref.module_specifier)) {
                        if (self.classifyBuiltinProtocolReference(ref_name, ref.target_decl)) |pkind| {
                            switch (pkind) {
                                .disposable => {
                                    needs_runtime.* = true;
                                    const res = try self.makeType(.js_disposable);
                                    if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and no_free_vars) {
                                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                                    }
                                    return res;
                                },
                                .async_disposable => {
                                    needs_runtime.* = true;
                                    const res = try self.makeType(.js_async_disposable);
                                    if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and no_free_vars) {
                                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                                    }
                                    return res;
                                },
                                .iterable => {
                                    const elem = if (ref.type_args.len > 0)
                                        try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                                    else blk: {
                                        needs_runtime.* = true;
                                        break :blk try self.makeType(.js_value);
                                    };
                                    if (is_return_pos) {
                                        needs_runtime.* = true;
                                        return self.makeType(.{ .js_iterator = elem });
                                    }
                                    const res = try self.makeType(.{ .slice = elem });
                                    if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                                    }
                                    return res;
                                },
                                .iterator => {
                                    needs_runtime.* = true;
                                    const elem = if (ref.type_args.len > 0)
                                        try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                                    else
                                        try self.makeType(.js_value);
                                    const res = try self.makeType(.{ .js_iterator = elem });
                                    if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                                    }
                                    return res;
                                },
                                .async_iterable, .async_iterator => {
                                    needs_runtime.* = true;
                                    const elem = if (ref.type_args.len > 0)
                                        try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                                    else
                                        try self.makeType(.js_value);
                                    const res = try self.makeType(.{ .js_async_iterator = elem });
                                    if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                                        try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                                    }
                                    return res;
                                },
                            }
                        }
                    }

                    if (ref.target_decl) |td| {
                        if (self.lookupDeclLocation(td)) |found| {
                            const loc = found.loc;
                            try imports_used.put(self.scratch, loc.module_index, {});

                            const expected_len = loc.type_param_defaults.len;
                            const final_len = if (expected_len > 0) expected_len else ref.type_args.len;
                            var lowered_args = try self.alloc.alloc(*const TypeIr, final_len);

                            for (0..final_len) |ai| {
                                if (ai < ref.type_args.len) {
                                    lowered_args[ai] = try self.lowerGenericTypeArg(ref.type_args[ai], active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                } else if (ai < loc.type_param_defaults.len and loc.type_param_defaults[ai] != null) {
                                    // Evaluate omitted trailing defaults in a clean target-declaration scope
                                    // (`0..ai`) so caller type parameters NEVER leak into callee defaults!
                                    const def_tps = try self.scratch.alloc(ActiveTypeParam, ai);
                                    defer self.scratch.free(def_tps);
                                    for (0..ai) |j| {
                                        def_tps[j] = .{
                                            .ts_name = if (j < loc.type_param_names.len) loc.type_param_names[j] else "",
                                            .zig_ident = "",
                                            .subst_ty = @constCast(lowered_args[j]),
                                        };
                                    }
                                    var def_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                                    defer def_visited.deinit(self.scratch);
                                    lowered_args[ai] = try self.lowerGenericTypeArg(loc.type_param_defaults[ai].?, def_tps, null, &def_visited, imports_used, needs_runtime);
                                } else {
                                    needs_runtime.* = true;
                                    lowered_args[ai] = try self.makeType(.js_value);
                                }
                            }

                            if (is_return_pos and found.id < self.graph.decls.len and self.graph.decls[found.id].kind == .type_alias_decl) {
                                const bd = self.graph.decls[found.id];
                                const alias_rhs = bd.kind.type_alias_decl;
                                if (!visited.contains(alias_rhs) and self.typeShouldUnwrapAliasInReturnPos(alias_rhs, 0)) {
                                    const alias_tps = try self.scratch.alloc(ActiveTypeParam, bd.type_params.len);
                                    defer self.scratch.free(alias_tps);
                                    for (bd.type_params, 0..) |tp_id, i| {
                                        const tp_name = if (tp_id < self.graph.type_params.len)
                                            self.str(self.graph.type_params[tp_id].name)
                                        else
                                            "";
                                        alias_tps[i] = .{
                                            .ts_name = tp_name,
                                            .zig_ident = "",
                                            .subst_ty = if (i < lowered_args.len)
                                                @constCast(lowered_args[i])
                                            else
                                                try self.makeType(.js_any),
                                        };
                                    }
                                    return self.lowerType(alias_rhs, true, alias_tps, null, visited, imports_used, needs_runtime);
                                }
                            }

                            return self.makeType(.{
                                .decl_ref = .{
                                    .module_index = loc.module_index,
                                    .decl_zig_path = loc.zig_path,
                                    .target_decl_id = found.id,
                                    .type_args = lowered_args,
                                },
                            });
                        }
                    }

                    // Built-in JS / TypeScript standard library types.
                    const stripped_stdlib_name = lower_types.stripGlobalQualifier(ref_name);
                    const is_unshadowed_stdlib = !self.isRefShadowedByUnresolvedImport(ref_name, ref.target_decl, ref.module_specifier) and
                        self.isBuiltinProtocolTarget(ref.target_decl);
                    if (is_unshadowed_stdlib and
                        (std.mem.eql(u8, stripped_stdlib_name, "Array") or std.mem.eql(u8, stripped_stdlib_name, "ReadonlyArray") or
                            std.mem.eql(u8, stripped_stdlib_name, "ArrayLike") or
                            std.mem.eql(u8, stripped_stdlib_name, "Set") or std.mem.eql(u8, stripped_stdlib_name, "ReadonlySet")))
                    {
                        const elem = if (ref.type_args.len > 0)
                            try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                        else blk: {
                            needs_runtime.* = true;
                            break :blk try self.makeType(.js_value);
                        };
                        const res = try self.makeType(.{ .slice = elem });
                        if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                            try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                        }
                        return res;
                    }
                    if (is_unshadowed_stdlib and (std.mem.eql(u8, stripped_stdlib_name, "Promise") or std.mem.eql(u8, stripped_stdlib_name, "PromiseLike"))) {
                        needs_runtime.* = true;
                        const inner = if (ref.type_args.len > 0)
                            try self.lowerType(ref.type_args[0], is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                        else
                            try self.makeType(.void_type);
                        const res = try self.makeType(.{ .promise = inner });
                        if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                            try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                        }
                        return res;
                    }
                    if (is_unshadowed_stdlib and std.mem.eql(u8, stripped_stdlib_name, "ArrayBufferLike") and tn.resolved_type == null) {
                        needs_runtime.* = true;
                        return self.makeType(.{ .binary_view = .array_buffer });
                    }
                    if (is_unshadowed_stdlib and (std.mem.eql(u8, stripped_stdlib_name, "Map") or std.mem.eql(u8, stripped_stdlib_name, "ReadonlyMap"))) {
                        needs_runtime.* = true;
                        const k = if (ref.type_args.len > 0)
                            try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                        else
                            try self.makeType(.js_any);
                        const v = if (ref.type_args.len > 1)
                            try self.lowerType(ref.type_args[1], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime)
                        else
                            try self.makeType(.js_any);
                        const res = try self.makeType(.{ .js_map = .{ .key = k, .value = v } });
                        if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                            try self.cur_mod_closed_types.put(self.scratch, ty_id, res);
                        }
                        return res;
                    }

                    // Built-in TypeScript utility types (`NoInfer`, `Partial`, `Required`, `Readonly`,
                    // `Pick`, `Omit`, `Record`, `NonNullable`, `Awaited`, `Exclude`, `Extract`, etc.).
                    const is_stdlib_utility_target = !self.isRefShadowedByUnresolvedImport(ref_name, ref.target_decl, ref.module_specifier) and
                        (if (ref.target_decl) |td|
                            (self.isBundledLibDecl(td) or (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl))
                        else
                            true);
                    const mentions_open_tp = self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0);

                    if (is_stdlib_utility_target) {
                        if (type_ops.classifyBuiltinUtility(stripped_stdlib_name, ref.type_args.len)) |util_kind| {
                            switch (util_kind) {
                                .no_infer => {
                                    if (ref.type_args.len >= 1) {
                                        return self.lowerType(ref.type_args[0], is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                    }
                                },
                                .partial,
                                .required,
                                .readonly_type,
                                .non_nullable,
                                .awaited,
                                .instance_type,
                                .parameters,
                                .return_type,
                                .constructor_parameters,
                                => {
                                    if (ref.type_args.len >= 1 and (mentions_open_tp or tn.resolved_type == null or tn.resolved_type.? == ty_id)) {
                                        needs_runtime.* = true;
                                        const op_kind: type_ops.UnaryTypeOp = switch (util_kind) {
                                            .partial => .partial,
                                            .required => .required,
                                            .readonly_type => .readonly_type,
                                            .non_nullable => .non_nullable,
                                            .awaited => .awaited,
                                            .instance_type => .instance_type,
                                            .parameters => .parameters,
                                            .return_type => .return_type,
                                            .constructor_parameters => .constructor_parameters,
                                            else => unreachable,
                                        };
                                        const operand = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                        return self.makeType(.{ .unary_type_op = .{ .op = op_kind, .operand = operand } });
                                    }
                                },
                                .pick, .omit => {
                                    if (ref.type_args.len >= 2 and (mentions_open_tp or tn.resolved_type == null or tn.resolved_type.? == ty_id)) {
                                        needs_runtime.* = true;
                                        const target = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                        const keys = try self.lowerKeyFilterSpec(ref.type_args[1], active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                        return self.makeType(.{
                                            .key_filter_op = .{
                                                .kind = if (util_kind == .pick) .pick else .omit,
                                                .target = target,
                                                .keys = keys,
                                            },
                                        });
                                    }
                                },
                                .record => {
                                    if (ref.type_args.len >= 2) {
                                        const resolved_has_concrete_props = if (!mentions_open_tp and tn.resolved_type != null and tn.resolved_type.? < self.graph.types.len) blk: {
                                            const rt_kind = self.graph.types[tn.resolved_type.?].kind;
                                            break :blk (rt_kind == .object_literal and rt_kind.object_literal.properties.len > 0);
                                        } else false;
                                        if (!resolved_has_concrete_props) {
                                            needs_runtime.* = true;
                                            const k = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                            const v = try self.lowerType(ref.type_args[1], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                            return self.makeType(.{ .js_record = .{ .key = k, .value = v } });
                                        }
                                    }
                                },
                                else => {},
                            }
                        }
                    }

                    // ONLY follow `resolved_type` when closed (`!mentions_open_tp`) AND (`ref.target_decl == null` OR `target_decl` is a `type_alias_decl`)!
                    // Never inline `resolved_type` for unselected/external `class_decl`/`interface_decl`s (`H3`) or open generic expansions!
                    const allow_resolved = !mentions_open_tp and (if (ref.target_decl) |td|
                        (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl)
                    else
                        true);
                    if (allow_resolved) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }

                    if (is_unshadowed_stdlib and std.mem.eql(u8, stripped_stdlib_name, "Record") and ref.type_args.len == 2) {
                        needs_runtime.* = true;
                        const k = try self.lowerType(ref.type_args[0], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        const v = try self.lowerType(ref.type_args[1], false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        return self.makeType(.{ .js_record = .{ .key = k, .value = v } });
                    }

                    if (is_unshadowed_stdlib and std.mem.eql(u8, stripped_stdlib_name, "TemplateStringsArray") and ref.type_args.len == 0) {
                        const str_ty = try self.makeType(.string_type);
                        return self.makeType(.{ .slice = str_ty });
                    }

                    if (is_unshadowed_stdlib and std.mem.eql(u8, stripped_stdlib_name, "PropertyKey") and ref.type_args.len == 0) {
                        return self.lowerBuiltinPropertyKeyType(active_tps, needs_runtime);
                    }

                    if (is_unshadowed_stdlib and std.mem.eql(u8, stripped_stdlib_name, "ArrayBufferView") and ref.type_args.len <= 1) {
                        return self.lowerBuiltinArrayBufferViewType(active_tps, needs_runtime);
                    }

                    const is_resolved_bundled_lib = if (ref.target_decl) |td| self.isBundledLibDecl(td) else false;
                    const is_unshadowed_builtin_global = is_resolved_bundled_lib or
                        (is_unshadowed_stdlib and
                            (lower_types.isStandardBuiltinGlobalType(stripped_stdlib_name) or
                                (self.in_synthesized_resolved_depth > 0 and
                                    lower_types.isSynthesizedIntlOrTemporalMember(stripped_stdlib_name))));
                    if (is_unshadowed_builtin_global) {
                        needs_runtime.* = true;
                        return self.makeType(.js_object);
                    }

                    try self.recordFallback(.unresolved_type_ref, ref_name);
                    needs_runtime.* = true;
                    return self.makeType(.js_object);
                },
                .function_type, .constructor_type => |sig_id| {
                    if (sig_id < self.graph.signatures.len) {
                        const sig = self.graph.signatures[sig_id];
                        // Generic function types cannot be bare Zig function pointers; represent as JsFunction.
                        if (sig.type_params.len == 0) {
                            const fp = try self.lowerGraphSigToFnPtrIr(sig_id, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const fp_ir = try self.makeType(.{ .fn_ptr = fp });
                            if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                                const h = try self.allocFreshAnonHelperName("__zigar_AnonFn", active_tps);
                                const hloc = DeclLocation{
                                    .module_index = self.cur_mod_idx,
                                    .zig_path = h.path,
                                    .type_param_defaults = &.{},
                                };
                                try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                                try self.cur_mod_decls_out.?.append(self.alloc, .{
                                    .source_decl_id = null,
                                    .zig_ident = h.zig_ident,
                                    .logical_name = h.logical,
                                    .wire_name = h.logical,
                                    .is_exported = false,
                                    .is_js_exported = false,
                                    .is_default_export = false,
                                    .jsdoc = null,
                                    .kind = .{ .type_alias = .{ .type_params = &.{}, .target = fp_ir } },
                                });
                                return self.makeHoistedDeclRef(hloc);
                            }
                            return fp_ir;
                        }
                    }
                    try self.recordFallback(
                        .generic_function_type,
                        if (tn.kind == .constructor_type)
                            "generic constructor signature -> zigar_js.JsFunction"
                        else
                            "generic function signature -> zigar_js.JsFunction",
                    );
                    needs_runtime.* = true;
                    return self.makeType(.js_function);
                },
                .object_literal => |obj| {
                    if (obj.properties.len == 0 and obj.call_signatures.len == 1 and
                        obj.construct_signatures.len == 0 and obj.index_signatures.len == 0)
                    {
                        const sid = obj.call_signatures[0];
                        if (sid < self.graph.signatures.len and self.graph.signatures[sid].type_params.len == 0) {
                            const fp = try self.lowerGraphSigToFnPtrIr(sid, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const fp_ir = try self.makeType(.{ .fn_ptr = fp });
                            if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                                const h = try self.allocFreshAnonHelperName("__zigar_AnonFn", active_tps);
                                const hloc = DeclLocation{
                                    .module_index = self.cur_mod_idx,
                                    .zig_path = h.path,
                                    .type_param_defaults = &.{},
                                };
                                try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                                try self.cur_mod_decls_out.?.append(self.alloc, .{
                                    .source_decl_id = null,
                                    .zig_ident = h.zig_ident,
                                    .logical_name = h.logical,
                                    .wire_name = h.logical,
                                    .is_exported = false,
                                    .is_js_exported = false,
                                    .is_default_export = false,
                                    .jsdoc = null,
                                    .kind = .{ .type_alias = .{ .type_params = &.{}, .target = fp_ir } },
                                });
                                return self.makeHoistedDeclRef(hloc);
                            }
                            return fp_ir;
                        }
                        try self.recordFallback(.generic_function_type, "generic call-signature object -> zigar_js.JsFunction");
                        needs_runtime.* = true;
                        return self.makeType(.js_function);
                    }
                    const obj_cls = self.classifyObjectLiteral(obj);
                    const has_non_index_members = obj.properties.len > 0 or
                        obj.call_signatures.len > 0 or
                        obj.construct_signatures.len > 0;
                    if (obj_cls.kind == .handle_wrapper and has_non_index_members) {
                        const is_closed = no_free_vars or try self.isClosedTypeSubgraph(ty_id);
                        if (can_hoist_in_mod and is_closed and self.cur_mod_root_scope != null) {
                            const h = try self.allocFreshAnonHelperName("__zigar_AnonHandle", active_tps);
                            const hloc = DeclLocation{
                                .module_index = self.cur_mod_idx,
                                .zig_path = h.path,
                                .type_param_defaults = &.{},
                            };
                            try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);

                            var empty_names: std.AutoHashMapUnmanaged(u32, naming.BoundName) = .empty;
                            var empty_ovs: std.AutoHashMapUnmanaged(u32, []naming.BoundName) = .empty;
                            var empty_active: std.AutoHashMapUnmanaged(u32, void) = .empty;
                            defer empty_active.deinit(self.scratch);

                            const saved_depth = self.inline_anon_depth;
                            self.inline_anon_depth = 0;
                            defer self.inline_anon_depth = saved_depth;

                            const split = try self.splitObjectLiteralPropsAndMethods(obj.properties);
                            const sourced_calls = try self.wrapUnsourcedSigs(obj.call_signatures);
                            const sourced_ctors = try self.wrapUnsourcedSigs(obj.construct_signatures);
                            const sourced_index_sigs = try self.wrapUnsourcedIndexSigs(obj.index_signatures);

                            const struct_ir = try self.lowerStructDecl(
                                self.cur_mod_idx,
                                std.math.maxInt(u32),
                                obj_cls,
                                false,
                                false,
                                &.{},
                                &.{},
                                &.{},
                                split.props,
                                &.{},
                                split.methods,
                                sourced_calls,
                                sourced_ctors,
                                sourced_index_sigs,
                                &.{},
                                &.{},
                                self.cur_mod_root_scope.?,
                                &empty_names,
                                &empty_ovs,
                                &.{},
                                imports_used,
                                needs_runtime,
                                &empty_active,
                            );
                            try self.cur_mod_decls_out.?.append(self.alloc, .{
                                .source_decl_id = null,
                                .zig_ident = h.zig_ident,
                                .logical_name = h.logical,
                                .wire_name = h.logical,
                                .is_exported = false,
                                .is_js_exported = false,
                                .is_default_export = false,
                                .jsdoc = null,
                                .kind = .{ .struct_decl = struct_ir },
                            });
                            return self.makeHoistedDeclRef(hloc);
                        }
                        needs_runtime.* = true;
                        return self.makeType(if (obj_cls.is_callable_handle) .js_function else .js_object);
                    }
                    if (obj.properties.len > 0) {
                        const is_closed = no_free_vars or try self.isClosedTypeSubgraph(ty_id);
                        // Hoist closed shared/multi-member/nested `object_literal`s (`H3`) once per module
                        // so DAGs like `typeof EventEmitter` or `http2` never re-inline exponentially!
                        if (can_hoist_in_mod and is_closed and (ref_cnt > 1 or obj.properties.len > 2 or self.inline_anon_depth >= 1)) {
                            const h = try self.allocFreshAnonHelperName("__zigar_AnonObj", active_tps);
                            const hloc = DeclLocation{
                                .module_index = self.cur_mod_idx,
                                .zig_path = h.path,
                                .type_param_defaults = &.{},
                            };
                            // Register in `cur_mod_hoisted_locs` BEFORE lowering fields so mutual/self
                            // cycles resolve immediately to `hloc` without re-entering!
                            try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);

                            var anon_scope = naming.ScopeNamer.initContainer(self.scratch, null);
                            defer anon_scope.deinit();
                            try anon_scope.reserve("zigar_js");

                            var fresh_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                            defer fresh_visited.deinit(self.scratch);
                            const saved_depth = self.inline_anon_depth;
                            self.inline_anon_depth = 0;
                            defer self.inline_anon_depth = saved_depth;

                            const fields = try self.lowerFields(
                                obj.properties,
                                false,
                                &anon_scope,
                                &.{},
                                null,
                                &fresh_visited,
                                imports_used,
                                needs_runtime,
                            );
                            const target_ty = if (fields.len > 0)
                                try self.makeType(.{ .anon_struct = fields })
                            else blk: {
                                needs_runtime.* = true;
                                break :blk try self.makeType(.js_object);
                            };
                            try self.cur_mod_decls_out.?.append(self.alloc, .{
                                .source_decl_id = null,
                                .zig_ident = h.zig_ident,
                                .logical_name = h.logical,
                                .wire_name = h.logical,
                                .is_exported = false,
                                .is_js_exported = false,
                                .is_default_export = false,
                                .jsdoc = null,
                                .kind = .{ .type_alias = .{ .type_params = &.{}, .target = target_ty } },
                            });
                            return self.makeHoistedDeclRef(hloc);
                        }

                        // Enforce inline nesting & member budget for un-hoistable open generic object literals (`H3`).
                        if (self.inline_anon_depth >= 3 or obj.properties.len > 48) {
                            try self.recordFallback(.object_literal_budget, "open anonymous object exceeded inline budget -> zigar_js.Object");
                            needs_runtime.* = true;
                            return self.makeType(.js_object);
                        }

                        var anon_scope = naming.ScopeNamer.initContainer(self.scratch, null);
                        defer anon_scope.deinit();
                        try anon_scope.reserve("zigar_js");
                        self.inline_anon_depth += 1;
                        defer self.inline_anon_depth -= 1;
                        const fields = try self.lowerFields(obj.properties, false, &anon_scope, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        if (fields.len == 0) {
                            needs_runtime.* = true;
                            return self.makeType(.js_object);
                        }
                        return self.makeType(.{ .anon_struct = fields });
                    }
                    needs_runtime.* = true;
                    return self.makeType(.js_object);
                },
                .intersection => |parts| {
                    return self.lowerIntersectionInline(
                        ty_id,
                        parts,
                        ref_cnt,
                        can_hoist_in_mod,
                        no_free_vars,
                        active_tps,
                        self_ident_opt,
                        visited,
                        imports_used,
                        needs_runtime,
                    );
                },
                .keyof_type => |inner_id| {
                    if (self.typeTreeMentionsActiveTypeParam(inner_id, active_tps, &.{}, 0)) {
                        needs_runtime.* = true;
                        const operand = try self.lowerType(inner_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        return self.makeType(.{ .unary_type_op = .{ .op = .keyof, .operand = operand } });
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id and rt < self.graph.types.len) {
                            // Preserve 1-property closed `keyof { id: number }` as a 1-member string enum
                            // rather than letting `.literal` widen to `[]const u8`!
                            if (try self.extractClosedLiteralFromType(rt, 0)) |cl| {
                                switch (cl) {
                                    .str => |s| {
                                        const single = [_][]const u8{s};
                                        const enum_ir = try self.buildStringEnumFromUniqueStrings(&single);
                                        if (enum_ir.members.len == 1) {
                                            return self.makeType(.{ .inline_enum = enum_ir });
                                        }
                                    },
                                    else => {},
                                }
                            }
                            return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        }
                    }
                    needs_runtime.* = true;
                    const operand = try self.lowerType(inner_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                    return self.makeType(.{ .unary_type_op = .{ .op = .keyof, .operand = operand } });
                },
                .indexed_access => |ia| {
                    const is_open = self.typeTreeMentionsActiveTypeParam(ia.object_ty, active_tps, &.{}, 0) or
                        self.typeTreeMentionsActiveTypeParam(ia.index_ty, active_tps, &.{}, 0);
                    if (!is_open) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    needs_runtime.* = true;
                    const obj_ty = try self.lowerType(ia.object_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                    const spec = try self.lowerIndexAccessSpec(ia.index_ty, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                    return self.makeType(.{ .index_access_op = .{ .object_ty = obj_ty, .index_spec = spec } });
                },
                .mapped => |mp| {
                    if (!self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0)) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    var value_mentions_iter = false;
                    if (mp.type_param < self.graph.type_params.len) {
                        const iter_tp = [_]ActiveTypeParam{.{
                            .ts_name = self.str(self.graph.type_params[mp.type_param].name),
                            .zig_ident = "",
                        }};
                        value_mentions_iter = self.typeTreeMentionsActiveTypeParam(mp.value_type, &iter_tp, &.{}, 0);
                    }
                    const pat = type_ops.recognizeOpenMappedPattern(self.graph, mp, value_mentions_iter);
                    needs_runtime.* = true;
                    switch (pat) {
                        .homomorphic_partial => |kt_id| {
                            const operand = try self.lowerType(kt_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{ .unary_type_op = .{ .op = .partial, .operand = operand } });
                        },
                        .homomorphic_required => |kt_id| {
                            const operand = try self.lowerType(kt_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{ .unary_type_op = .{ .op = .required, .operand = operand } });
                        },
                        .homomorphic_readonly => |kt_id| {
                            const operand = try self.lowerType(kt_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{ .unary_type_op = .{ .op = .readonly_type, .operand = operand } });
                        },
                        .homomorphic_mapped_values => |hmv| {
                            const t_ir = try self.lowerType(hmv.target_obj_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const v_ir = try self.lowerType(hmv.value_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const mv_ir = try self.makeType(.{ .mapped_values_op = .{ .target = t_ir, .value = v_ir } });
                            return switch (hmv.optional_mod) {
                                .none => mv_ir,
                                .add => self.makeType(.{ .unary_type_op = .{ .op = .partial, .operand = mv_ir } }),
                                .remove => self.makeType(.{ .unary_type_op = .{ .op = .required, .operand = mv_ir } }),
                            };
                        },
                        .uniform_record => |ur| {
                            const k_ir = try self.lowerType(ur.key_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const v_ir = try self.lowerType(ur.value_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const rec_ir = try self.makeType(.{ .js_record = .{ .key = k_ir, .value = v_ir } });
                            if (ur.make_partial) {
                                return self.makeType(.{ .unary_type_op = .{ .op = .partial, .operand = rec_ir } });
                            }
                            return rec_ir;
                        },
                        .dynamic_object => {},
                    }
                    try self.recordFallback(.unsupported_mapped_type, "open mapped type -> zigar_js.Object");
                    return self.makeType(.js_object);
                },
                .conditional => |cond| {
                    if (!self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0)) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                self.in_synthesized_resolved_depth += 1;
                                defer self.in_synthesized_resolved_depth -= 1;
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    // When the condition (`check_type extends extends_type`) has no open type
                    // parameters or `infer` bindings (e.g. `typeof globalThis extends { onmessage: any } ? {} : webstreams.ReadableStream<R>`),
                    // the TypeScript checker has already evaluated which branch wins in `tn.resolved_type`;
                    // lower the winning AST branch directly so nominal generic references stay intact!
                    if (cond.infer_params.len == 0 and
                        !self.typeTreeMentionsActiveTypeParam(cond.check_type, active_tps, &.{}, 0) and
                        !self.typeTreeMentionsActiveTypeParam(cond.extends_type, active_tps, &.{}, 0))
                    {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id and rt < self.graph.types.len) {
                                if (self.isEmptyObjectOrNeverGraphType(cond.true_type) and !self.isEmptyObjectOrNeverGraphType(rt)) {
                                    return self.lowerType(cond.false_type, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                }
                                if (self.isEmptyObjectOrNeverGraphType(cond.false_type) and !self.isEmptyObjectOrNeverGraphType(rt)) {
                                    return self.lowerType(cond.true_type, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                }
                            }
                        }
                    }
                    const pat = type_ops.recognizeOpenConditionalPattern(self.graph, cond);
                    needs_runtime.* = true;
                    switch (pat) {
                        .non_nullable => |check_id| {
                            const operand = try self.lowerType(check_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{ .unary_type_op = .{ .op = .non_nullable, .operand = operand } });
                        },
                        .awaited => |check_id| {
                            const operand = try self.lowerType(check_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{ .unary_type_op = .{ .op = .awaited, .operand = operand } });
                        },
                        .empty_object_extends => |eoe| {
                            const target_ir = try self.lowerType(eoe.target_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const true_ir = try self.lowerType(eoe.true_ty, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const false_ir = try self.lowerType(eoe.false_ty, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{
                                .empty_object_extends_op = .{
                                    .target_ty = target_ir,
                                    .true_ty = true_ir,
                                    .false_ty = false_ir,
                                },
                            });
                        },
                        .conditional_index_access => |cia| {
                            const obj_ir = try self.lowerType(cia.object_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const key_ir = try self.lowerType(cia.key_ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const fb_ir = try self.lowerType(cia.fallback_ty, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            return self.makeType(.{
                                .index_access_op = .{
                                    .object_ty = obj_ir,
                                    .index_spec = .{ .ty = key_ir },
                                    .fallback_ty = fb_ir,
                                },
                            });
                        },
                        .conditional_promise_return => |check_id| {
                            const operand = try self.lowerType(check_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            const payload = try self.makeType(.{
                                .unary_type_op = .{
                                    .op = .infer_callback_promise_payload,
                                    .operand = operand,
                                },
                            });
                            return self.makeType(.{ .promise = payload });
                        },
                        .dynamic_any => {
                            if (self.openConditionalSingleObjectBranch(cond)) {
                                return self.makeType(.js_object);
                            }
                            try self.recordFallback(.erased_conditional_type, "open conditional type -> zigar_js.Any");
                            return self.makeType(.js_any);
                        },
                    }
                },
                .typeof_query => |tq| {
                    const mentions_open_tp = self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0);
                    if (tq.type_args.len == 0 and !mentions_open_tp) {
                        if (tq.target_decl) |td| {
                            if (td < self.graph.decls.len and
                                self.graph.decls[td].kind == .variable_decl and
                                self.graph.decls[td].merged_with.len == 0)
                            {
                                if (self.decl_locations.get(td)) |v_loc| {
                                    if (v_loc.module_index == self.cur_mod_idx) {
                                        const v_ty_id = self.graph.decls[td].kind.variable_decl;
                                        return self.lowerType(v_ty_id, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                    }
                                }
                            }
                        }
                    }
                    if (tq.target_decl) |td| {
                        if (td < self.graph.decls.len and self.graph.decls[td].kind == .class_decl) {
                            if (self.lookupDeclLocation(td) != null) {
                                const inst_ty = try self.lowerClassInstanceFromTypeof(td, tq.type_args, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                if (!mentions_open_tp) {
                                    if (tn.resolved_type) |rt| {
                                        if (rt != ty_id) {
                                            self.in_synthesized_resolved_depth += 1;
                                            defer self.in_synthesized_resolved_depth -= 1;
                                            const resolved_ir = try self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                            if (resolved_ir.* == .decl_ref) {
                                                if (self.cur_mod_decls_out) |decls_out| {
                                                    if (resolved_ir.decl_ref.module_index == self.cur_mod_idx and resolved_ir.decl_ref.decl_zig_path.len == 1) {
                                                        const target_id = resolved_ir.decl_ref.decl_zig_path[0];
                                                        for (decls_out.items) |*hd| {
                                                            if (hd.kind == .struct_decl and std.mem.eql(u8, hd.zig_ident, target_id)) {
                                                                hd.kind.struct_decl.instance_ty = inst_ty;
                                                                break;
                                                            }
                                                        }
                                                    }
                                                }
                                                return resolved_ir;
                                            }
                                        }
                                    }
                                }
                                needs_runtime.* = true;
                                return self.makeType(.{
                                    .unary_type_op = .{
                                        .op = .constructor_of,
                                        .operand = inst_ty,
                                    },
                                });
                            }
                        }
                    }
                    if (!mentions_open_tp) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                self.in_synthesized_resolved_depth += 1;
                                defer self.in_synthesized_resolved_depth -= 1;
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    if (tq.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            switch (self.graph.decls[td].kind) {
                                .variable_decl => |v_ty_id| {
                                    return self.lowerType(v_ty_id, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                },
                                .function_decl => |sigs| {
                                    if (sigs.len == 1 and sigs[0] < self.graph.signatures.len and
                                        self.graph.signatures[sigs[0]].type_params.len == 0)
                                    {
                                        const fp = try self.lowerGraphSigToFnPtrIr(sigs[0], active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                        return self.makeType(.{ .fn_ptr = fp });
                                    }
                                    needs_runtime.* = true;
                                    return self.makeType(.js_function);
                                },
                                .class_decl, .namespace_decl, .enum_decl => {
                                    needs_runtime.* = true;
                                    return self.makeType(.js_object);
                                },
                                else => {},
                            }
                        }
                    }
                    needs_runtime.* = true;
                    return self.makeType(.js_value);
                },
                .import_type => |it| {
                    const mentions_open_tp = self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0);
                    if (it.qualifier.len == 0) {
                        needs_runtime.* = true;
                        return self.makeType(.js_object);
                    }
                    if (try self.resolveImportTypeTargetDecl(self.str(it.module_specifier), it.qualifier, it.is_type_of)) |td| {
                        if (!it.is_type_of) {
                            if (self.lookupDeclLocation(td) != null) {
                                return self.lowerClassInstanceFromTypeof(td, it.type_args, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                            if (!mentions_open_tp and td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id) {
                                        return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                    }
                                }
                            }
                        } else {
                            if (self.isConstructorLikeTargetDecl(td) and self.lookupDeclLocation(td) != null) {
                                const inst_ty = try self.lowerClassInstanceFromTypeof(td, it.type_args, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                needs_runtime.* = true;
                                return self.makeType(.{
                                    .unary_type_op = .{
                                        .op = .constructor_of,
                                        .operand = inst_ty,
                                    },
                                });
                            }
                            if (!mentions_open_tp) {
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id) {
                                        return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                    }
                                }
                            }
                            if (td < self.graph.decls.len) {
                                switch (self.graph.decls[td].kind) {
                                    .variable_decl => |v_ty_id| {
                                        return self.lowerType(v_ty_id, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                    },
                                    .function_decl => |sigs| {
                                        if (sigs.len == 1 and sigs[0] < self.graph.signatures.len and
                                            self.graph.signatures[sigs[0]].type_params.len == 0)
                                        {
                                            const fp = try self.lowerGraphSigToFnPtrIr(sigs[0], active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                                            return self.makeType(.{ .fn_ptr = fp });
                                        }
                                        needs_runtime.* = true;
                                        return self.makeType(.js_function);
                                    },
                                    .class_decl, .interface_decl, .namespace_decl, .enum_decl => {
                                        needs_runtime.* = true;
                                        return self.makeType(.js_object);
                                    },
                                    else => {},
                                }
                            }
                        }
                    }
                    if (!mentions_open_tp) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    try self.recordFallback(.unsupported_type_node, @tagName(tn.kind));
                    needs_runtime.* = true;
                    return self.makeType(.js_value);
                },
                else => {
                    if (!self.typeTreeMentionsActiveTypeParam(ty_id, active_tps, &.{}, 0)) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                return self.lowerType(rt, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            }
                        }
                    }
                    try self.recordFallback(.unsupported_type_node, @tagName(tn.kind));
                    needs_runtime.* = true;
                    return self.makeType(.js_value);
                },
            }
        }

        fn lowerClassInstanceFromTypeof(
            self: *Self,
            td: u32,
            type_args: []const u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            const found = self.lookupDeclLocation(td) orelse {
                needs_runtime.* = true;
                return self.makeType(.js_object);
            };
            const loc = found.loc;
            try imports_used.put(self.scratch, loc.module_index, {});

            const expected_len = loc.type_param_defaults.len;
            const final_len = if (expected_len > 0) expected_len else type_args.len;
            var lowered_args = try self.alloc.alloc(*const TypeIr, final_len);

            for (0..final_len) |ai| {
                if (ai < type_args.len) {
                    lowered_args[ai] = try self.lowerGenericTypeArg(type_args[ai], active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                } else if (ai < loc.type_param_defaults.len and loc.type_param_defaults[ai] != null) {
                    const def_tps = try self.scratch.alloc(ActiveTypeParam, ai);
                    defer self.scratch.free(def_tps);
                    for (0..ai) |j| {
                        def_tps[j] = .{
                            .ts_name = if (j < loc.type_param_names.len) loc.type_param_names[j] else "",
                            .zig_ident = "",
                            .subst_ty = @constCast(lowered_args[j]),
                        };
                    }
                    var def_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer def_visited.deinit(self.scratch);
                    lowered_args[ai] = try self.lowerGenericTypeArg(loc.type_param_defaults[ai].?, def_tps, null, &def_visited, imports_used, needs_runtime);
                } else {
                    needs_runtime.* = true;
                    lowered_args[ai] = try self.makeType(.js_value);
                }
            }

            return self.makeType(.{
                .decl_ref = .{
                    .module_index = loc.module_index,
                    .decl_zig_path = loc.zig_path,
                    .target_decl_id = found.id,
                    .type_args = lowered_args,
                },
            });
        }

        const GraphSliceEnv = struct {
            tp_ids: []const u32,
            ir_args: []const *const TypeIr = &.{},
            graph_args: []const u32 = &.{},
            arg_env: ?*const GraphSliceEnv = null,
        };

        fn isGraphTypeSliceEnv(
            self: *const Self,
            ty_id: u32,
            env: ?*const GraphSliceEnv,
            depth: usize,
        ) bool {
            if (depth >= 24 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .array, .readonly_array => true,
                .type_param => |tp_id| blk: {
                    if (env) |e| {
                        for (e.tp_ids, 0..) |cand_id, idx| {
                            if (cand_id == tp_id) {
                                if (e.ir_args.len > 0) {
                                    if (idx < e.ir_args.len) {
                                        break :blk self.isAlreadySliceTypeIr(e.ir_args[idx], depth + 1);
                                    }
                                } else if (idx < e.graph_args.len) {
                                    break :blk self.isGraphTypeSliceEnv(e.graph_args[idx], e.arg_env, depth + 1);
                                }
                                if (tp_id < self.graph.type_params.len) {
                                    if (self.graph.type_params[tp_id].default_type) |def_id| {
                                        break :blk self.isGraphTypeSliceEnv(def_id, e, depth + 1);
                                    }
                                }
                                break :blk false;
                            }
                        }
                    }
                    break :blk false;
                },
                .reference => |ref| blk: {
                    const ref_name = self.str(ref.target_name);
                    if (env) |e| {
                        for (e.tp_ids, 0..) |cand_id, idx| {
                            if (cand_id < self.graph.type_params.len and
                                std.mem.eql(u8, self.str(self.graph.type_params[cand_id].name), ref_name))
                            {
                                if (e.ir_args.len > 0) {
                                    if (idx < e.ir_args.len) {
                                        break :blk self.isAlreadySliceTypeIr(e.ir_args[idx], depth + 1);
                                    }
                                } else if (idx < e.graph_args.len) {
                                    break :blk self.isGraphTypeSliceEnv(e.graph_args[idx], e.arg_env, depth + 1);
                                }
                                if (self.graph.type_params[cand_id].default_type) |def_id| {
                                    break :blk self.isGraphTypeSliceEnv(def_id, e, depth + 1);
                                }
                                break :blk false;
                            }
                        }
                    }
                    if (ref.target_decl) |td_id| {
                        if (td_id < self.graph.decls.len and self.graph.decls[td_id].kind == .type_alias_decl) {
                            const alias_decl = self.graph.decls[td_id];
                            const next_env = GraphSliceEnv{
                                .tp_ids = alias_decl.type_params,
                                .graph_args = ref.type_args,
                                .arg_env = env,
                            };
                            break :blk self.isGraphTypeSliceEnv(
                                alias_decl.kind.type_alias_decl,
                                if (alias_decl.type_params.len > 0) &next_env else null,
                                depth + 1,
                            );
                        }
                    }
                    const stripped_arr_name = lower_types.stripGlobalQualifier(ref_name);
                    if ((ref.target_decl == null or self.isBundledLibDecl(ref.target_decl.?)) and
                        (std.mem.eql(u8, stripped_arr_name, "Array") or std.mem.eql(u8, stripped_arr_name, "ReadonlyArray")))
                    {
                        break :blk true;
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) break :blk self.isGraphTypeSliceEnv(rt, env, depth + 1);
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn isAlreadySliceTypeIr(self: *const Self, ty: *const TypeIr, depth: usize) bool {
            if (depth >= 24) return false;
            return switch (ty.*) {
                .slice, .typed_slice => true,
                .decl_ref => |dr| blk: {
                    if (dr.indirect or dr.target_decl_id >= self.graph.decls.len) break :blk false;
                    const td = self.graph.decls[dr.target_decl_id];
                    if (td.kind == .type_alias_decl) {
                        const env = GraphSliceEnv{
                            .tp_ids = td.type_params,
                            .ir_args = dr.type_args,
                        };
                        break :blk self.isGraphTypeSliceEnv(
                            td.kind.type_alias_decl,
                            if (td.type_params.len > 0) &env else null,
                            depth + 1,
                        );
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn wrapOptionalWithNullish(self: *Self, inner: *TypeIr, kind: lower_types.NullishKind) !*TypeIr {
            const eff_kind: lower_types.NullishKind = if (kind == .none) .null_or_undefined else kind;
            switch (inner.*) {
                .void_type, .noreturn_type => return inner,
                .optional => |opt| {
                    const merged = opt.nullish_kind.merge(eff_kind);
                    if (merged == opt.nullish_kind) return inner;
                    return self.makeType(.{
                        .optional = .{
                            .child = opt.child,
                            .nullish_kind = merged,
                            .is_pure_nullish = opt.is_pure_nullish,
                        },
                    });
                },
                else => return self.makeType(.{ .optional = .{ .child = inner, .nullish_kind = eff_kind } }),
            }
        }

        fn wrapOptional(self: *Self, inner: *TypeIr) !*TypeIr {
            return self.wrapOptionalWithNullish(inner, .undefined_only);
        }

        fn allArmsSameScalarKind(self: *const Self, arm_ids: []const u32) ?TypeIr {
            var expected: ?TypeIr = null;
            for (arm_ids) |aid| {
                const k = self.graph.types[aid].kind;
                const mapped: TypeIr = switch (k) {
                    .string_type, .template_literal => .string_type,
                    .number_type => .f64_type,
                    .boolean_type => .bool_type,
                    .bigint_type => .i64_type,
                    .literal => |lit| switch (lit) {
                        .str => .string_type,
                        .num => .f64_type,
                        .bigint_literal => .i64_type,
                        .boolean => .bool_type,
                    },
                    else => return null,
                };
                if (expected) |exp| {
                    if (@as(std.meta.Tag(TypeIr), exp) != @as(std.meta.Tag(TypeIr), mapped)) return null;
                } else {
                    expected = mapped;
                }
            }
            return expected;
        }

        fn lowerFields(
            self: *Self,
            prop_ids: []const u32,
            only_instance: bool,
            field_scope: *naming.ScopeNamer,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}![]FieldIr {
            var list: std.ArrayList(FieldIr) = .empty;
            errdefer list.deinit(self.alloc);

            for (prop_ids) |pid| {
                if (pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                if (only_instance and p.modifiers.static_mod) continue;
                const wire = self.str(p.name);
                const bound = try field_scope.bind(wire, .snake);
                const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                const logical = try self.alloc.dupe(u8, bound.logical_name);
                const wire_copy = try self.alloc.dupe(u8, bound.wire_name);
                bound.deinit(self.scratch);

                var f_ty = try self.lowerType(p.ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                var lit_constraint: ?FieldLiteralConstraintIr = null;
                if (p.modifiers.optional_mod) {
                    f_ty = try self.wrapOptional(f_ty);
                } else {
                    lit_constraint = try self.extractCompatibleFieldLiteralConstraint(p.ty, f_ty);
                }

                try list.append(self.alloc, .{
                    .zig_ident = zig_ident,
                    .logical_name = logical,
                    .wire_name = wire_copy,
                    .ty = f_ty,
                    .is_optional = p.modifiers.optional_mod,
                    .is_readonly = p.modifiers.readonly_mod,
                    .nullish_kind = if (f_ty.* == .optional) f_ty.optional.nullish_kind else .none,
                    .literal_constraint = lit_constraint,
                    .jsdoc = try self.lowerJsDoc(p.jsdoc),
                });
            }

            return try list.toOwnedSlice(self.alloc);
        }

        fn isVoidGraphType(self: *const Self, ty_id: u32) bool {
            return self.isVoidGraphTypeInner(ty_id, 0);
        }

        fn isVoidGraphTypeInner(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth > 4 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .void_type, .undefined_type => return true,
                .union_type => |arms| {
                    if (arms.len == 0) return false;
                    for (arms) |arm_id| {
                        if (!self.isVoidGraphTypeInner(arm_id, depth + 1)) return false;
                    }
                    return true;
                },
                .reference => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.isVoidGraphTypeInner(rt, depth + 1);
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn lowerGraphSigToFnPtrIr(
            self: *Self,
            sig_id: u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!FnPtrIr {
            needs_runtime.* = true;
            const sig = self.graph.signatures[sig_id];
            var this_ty: ?*const TypeIr = null;
            if (sig.this_param) |this_tid| {
                if (!self.isVoidGraphType(this_tid)) {
                    this_ty = try self.lowerType(this_tid, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                }
            }
            var p_types = try self.alloc.alloc(*const TypeIr, sig.params.len);
            var has_rest = false;
            var rest_seq_ty: ?*const TypeIr = null;
            for (sig.params, 0..) |p, idx| {
                var pt = try self.lowerType(p.ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                if (p.rest) {
                    has_rest = true;
                    if (!self.isAlreadySliceTypeIr(pt, 0)) {
                        if (sig.params.len == 1 and this_ty == null and self.isOpenRestSequenceTypeIr(pt, 0)) {
                            rest_seq_ty = pt;
                        } else {
                            pt = try self.makeType(.{ .slice = pt });
                        }
                    }
                } else if (p.optional) {
                    pt = try self.wrapOptional(pt);
                }
                p_types[idx] = pt;
            }
            const ret = if (sig.type_predicate) |pred|
                (if (pred.asserts) try self.makeType(.void_type) else try self.makeType(.bool_type))
            else
                try self.lowerType(sig.return_type, true, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
            return .{
                .this_param = this_ty,
                .params = p_types,
                .return_type = ret,
                .has_rest = has_rest,
                .rest_sequence_ty = rest_seq_ty,
            };
        }

        fn isOpenRestSequenceTypeIr(self: *const Self, ty: *const TypeIr, depth: usize) bool {
            if (depth >= 8) return false;
            return switch (ty.*) {
                .type_param_ref, .index_access_op, .empty_object_extends_op, .tuple => true,
                .decl_ref => |dr| blk: {
                    if (dr.type_args.len == 0 or dr.target_decl_id >= self.graph.decls.len) break :blk false;
                    break :blk self.graph.decls[dr.target_decl_id].kind == .type_alias_decl;
                },
                else => false,
            };
        }

        fn graphTypeResolvesToCallableAlias(self: *const Self, ty_id: u32, depth: usize) bool {
            if (depth >= 12 or ty_id >= self.graph.types.len) return false;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .function_type => true,
                .object_literal => |obj| obj.properties.len == 0 and obj.call_signatures.len > 0 and
                    obj.construct_signatures.len == 0 and obj.index_signatures.len == 0,
                .union_type => |arms| blk: {
                    var saw_callable = false;
                    for (arms) |aid| {
                        if (aid >= self.graph.types.len) break :blk false;
                        const ak = self.graph.types[aid].kind;
                        if (ak == .null_type or ak == .undefined_type or ak == .void_type or ak == .never_type) continue;
                        if (!self.graphTypeResolvesToCallableAlias(aid, depth + 1)) break :blk false;
                        saw_callable = true;
                    }
                    break :blk saw_callable;
                },
                .conditional => |cond| blk: {
                    const true_never = cond.true_type < self.graph.types.len and self.graph.types[cond.true_type].kind == .never_type;
                    const false_never = cond.false_type < self.graph.types.len and self.graph.types[cond.false_type].kind == .never_type;
                    if (true_never and false_never) break :blk false;
                    if (!true_never and !self.graphTypeResolvesToCallableAlias(cond.true_type, depth + 1)) break :blk false;
                    if (!false_never and !self.graphTypeResolvesToCallableAlias(cond.false_type, depth + 1)) break :blk false;
                    break :blk true;
                },
                .reference => |ref| blk: {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                            const alias_tid = self.graph.decls[td].kind.type_alias_decl;
                            if (self.graphTypeResolvesToCallableAlias(alias_tid, depth + 1)) break :blk true;
                            if (alias_tid < self.graph.types.len and self.graph.types[alias_tid].kind == .conditional) {
                                const cond = self.graph.types[alias_tid].kind.conditional;
                                // Also handle `Listener<K, T, F>` where `true_type` is type param `F` supplied via `ref.type_args`:
                                const td_tps = self.graph.decls[td].type_params;
                                if (td_tps.len == ref.type_args.len) {
                                    var true_ok = cond.true_type < self.graph.types.len and self.graph.types[cond.true_type].kind == .never_type;
                                    if (!true_ok) {
                                        true_ok = self.graphTypeResolvesToCallableAliasWithArgs(cond.true_type, td_tps, ref.type_args, depth + 1);
                                    }
                                    var false_ok = cond.false_type < self.graph.types.len and self.graph.types[cond.false_type].kind == .never_type;
                                    if (!false_ok) {
                                        false_ok = self.graphTypeResolvesToCallableAliasWithArgs(cond.false_type, td_tps, ref.type_args, depth + 1);
                                    }
                                    if (true_ok and false_ok) break :blk true;
                                }
                            }
                        }
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn graphTypeResolvesToCallableAliasWithArgs(
            self: *const Self,
            ty_id: u32,
            tp_ids: []const u32,
            type_args: []const u32,
            depth: usize,
        ) bool {
            if (depth >= 12 or ty_id >= self.graph.types.len) return false;
            for (tp_ids, 0..) |tp_id, idx| {
                if (type_ops.typeNodeMatchesTypeParam(self.graph, ty_id, tp_id)) {
                    return self.graphTypeResolvesToCallableAlias(type_args[idx], depth + 1);
                }
            }
            return self.graphTypeResolvesToCallableAlias(ty_id, depth + 1);
        }

        fn findGraphCallbackSigId(self: *const Self, ty_id: u32, depth: usize) ?u32 {
            if (depth > 8 or ty_id >= self.graph.types.len) return null;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .function_type => |sid| {
                    if (sid < self.graph.signatures.len and self.graph.signatures[sid].type_params.len == 0) return sid;
                    return null;
                },
                .object_literal => |obj| {
                    if (obj.properties.len == 0 and obj.call_signatures.len == 1 and
                        obj.construct_signatures.len == 0 and obj.index_signatures.len == 0)
                    {
                        const sid = obj.call_signatures[0];
                        if (sid < self.graph.signatures.len and self.graph.signatures[sid].type_params.len == 0) return sid;
                    }
                    return null;
                },
                .union_type => |arms| {
                    var found: ?u32 = null;
                    for (arms) |arm_id| {
                        if (arm_id >= self.graph.types.len) return null;
                        const ak = self.graph.types[arm_id].kind;
                        if (ak == .null_type or ak == .undefined_type or ak == .void_type) continue;
                        if (found != null) return null;
                        found = self.findGraphCallbackSigId(arm_id, depth + 1) orelse return null;
                    }
                    return found;
                },
                .reference => |ref| {
                    if (ref.type_args.len == 0) {
                        if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len) {
                                const td_node = self.graph.decls[td];
                                if (td_node.type_params.len == 0) {
                                    switch (td_node.kind) {
                                        .type_alias_decl => |alias_tid| return self.findGraphCallbackSigId(alias_tid, depth + 1),
                                        .interface_decl => |id_data| {
                                            if (td_node.merged_with.len == 0 and
                                                id_data.extends_clauses.len == 0 and
                                                id_data.properties.len == 0 and
                                                id_data.methods.len == 0 and
                                                id_data.construct_signatures.len == 0 and
                                                id_data.index_signatures.len == 0 and
                                                id_data.call_signatures.len == 1)
                                            {
                                                const sid = id_data.call_signatures[0];
                                                if (sid < self.graph.signatures.len and self.graph.signatures[sid].type_params.len == 0) {
                                                    return sid;
                                                }
                                            }
                                        },
                                        else => {},
                                    }
                                }
                            }
                        }
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) return self.findGraphCallbackSigId(rt, depth + 1);
                        }
                    }
                    return null;
                },
                else => return null,
            }
        }

        fn extractCallbackSigFromParam(
            self: *Self,
            graph_ty_id: u32,
            lowered_pt: *const TypeIr,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!?FnPtrIr {
            if (lowered_pt.* == .fn_ptr) return lowered_pt.fn_ptr;
            if (lowered_pt.* == .optional and lowered_pt.optional.child.* == .fn_ptr) {
                return lowered_pt.optional.child.fn_ptr;
            }
            if (self.findGraphCallbackSigId(graph_ty_id, 0)) |cb_sid| {
                var cb_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer cb_visited.deinit(self.scratch);
                return try self.lowerGraphSigToFnPtrIr(
                    cb_sid,
                    active_tps,
                    self_ident_opt,
                    &cb_visited,
                    imports_used,
                    needs_runtime,
                );
            }
            return null;
        }

        const BoundSigCompanions = struct {
            alloc_ident: ?[]const u8 = null,
            slice_ident: ?[]const u8 = null,
            slice_alloc_ident: ?[]const u8 = null,
            narrow_ident: ?[]const u8 = null,
            narrow_alloc_ident: ?[]const u8 = null,
            default_ident: ?[]const u8 = null,
            default_alloc_ident: ?[]const u8 = null,
            infer_ident: ?[]const u8 = null,
            infer_alloc_ident: ?[]const u8 = null,
        };

        const BoundGenericTypeCompanions = struct {
            default_ident: ?[]const u8 = null,
            with_ident: ?[]const u8 = null,
        };

        fn bindGenericTypeCompanions(
            self: *Self,
            scope: *naming.ScopeNamer,
            logical_name: []const u8,
            type_params: []const TypeParamIr,
        ) error{OutOfMemory}!BoundGenericTypeCompanions {
            var res: BoundGenericTypeCompanions = .{};
            if (type_params.len == 0) return res;

            var has_defaults = try self.scratch.alloc(bool, type_params.len);
            defer self.scratch.free(has_defaults);
            for (type_params, 0..) |tp, idx| has_defaults[idx] = tp.default_type != null;
            const dp = lower_generics.analyzeDefaultPrefix(has_defaults);

            if (dp.emit_default_companion) {
                const raw_def = try std.fmt.allocPrint(self.scratch, "{s}Default", .{logical_name});
                defer self.scratch.free(raw_def);
                const db = try scope.bind(raw_def, .pascal);
                res.default_ident = try self.alloc.dupe(u8, db.zig_ident);
                db.deinit(self.scratch);
            }
            if (dp.emit_with_companion) {
                const raw_with = try std.fmt.allocPrint(self.scratch, "{s}With", .{logical_name});
                defer self.scratch.free(raw_with);
                const wb = try scope.bind(raw_with, .pascal);
                res.with_ident = try self.alloc.dupe(u8, wb.zig_ident);
                wb.deinit(self.scratch);
            }
            return res;
        }

        fn bindSigCompanions(
            self: *Self,
            scope: *naming.ScopeNamer,
            logical_name: []const u8,
            sig_ir: *const SignatureIr,
        ) error{OutOfMemory}!BoundSigCompanions {
            var res: BoundSigCompanions = .{};
            if (try self.typeMayAllocateOnDecode(sig_ir.return_type)) {
                const raw_alloc = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{logical_name});
                defer self.scratch.free(raw_alloc);
                const ab = try scope.bind(raw_alloc, .camel);
                res.alloc_ident = try self.alloc.dupe(u8, ab.zig_ident);
                ab.deinit(self.scratch);
            }
            if (sig_ir.params.len > 0 and sig_ir.params[sig_ir.params.len - 1].is_rest) {
                const vs = try lower_functions.bindVariadicSliceCompanions(
                    self.alloc,
                    self.scratch,
                    scope,
                    logical_name,
                    res.alloc_ident != null,
                );
                res.slice_ident = vs.slice_ident;
                res.slice_alloc_ident = vs.slice_alloc_ident;
            }
            if (sig_ir.type_predicate_target) |tpt| {
                const pn = try lower_functions.bindPredicateNarrowCompanions(
                    self.alloc,
                    self.scratch,
                    scope,
                    logical_name,
                    sig_ir.type_predicate_asserts,
                    tpt.target_allocates,
                );
                res.narrow_ident = pn.narrow_ident;
                res.narrow_alloc_ident = pn.narrow_alloc_ident;
            }
            if (sig_ir.default_prefix.emit_default_companion) {
                const raw_def = try std.fmt.allocPrint(self.scratch, "{s}Default", .{logical_name});
                defer self.scratch.free(raw_def);
                const db = try scope.bind(raw_def, .camel);
                res.default_ident = try self.alloc.dupe(u8, db.zig_ident);
                db.deinit(self.scratch);
                if (res.alloc_ident != null) {
                    const raw_da = try std.fmt.allocPrint(self.scratch, "{s}DefaultAlloc", .{logical_name});
                    defer self.scratch.free(raw_da);
                    const dab = try scope.bind(raw_da, .camel);
                    res.default_alloc_ident = try self.alloc.dupe(u8, dab.zig_ident);
                    dab.deinit(self.scratch);
                }
            }
            if (sig_ir.infer_bindings != null) {
                const raw_inf = try std.fmt.allocPrint(self.scratch, "{s}Infer", .{logical_name});
                defer self.scratch.free(raw_inf);
                const ib = try scope.bind(raw_inf, .camel);
                res.infer_ident = try self.alloc.dupe(u8, ib.zig_ident);
                ib.deinit(self.scratch);
                if (res.alloc_ident != null) {
                    const raw_ia = try std.fmt.allocPrint(self.scratch, "{s}InferAlloc", .{logical_name});
                    defer self.scratch.free(raw_ia);
                    const iab = try scope.bind(raw_ia, .camel);
                    res.infer_alloc_ident = try self.alloc.dupe(u8, iab.zig_ident);
                    iab.deinit(self.scratch);
                }
            }
            return res;
        }

        const SplitPromiseSig = struct {
            awaited: SignatureIr,
            promise_companion: SignatureIr,
        };

        /// Splits an async signature returning `Promise<T>` (or nested `Promise<Promise<T>>`)
        /// into an auto-awaiting primary signature (`return_type = T`, `awaits_promise = true`)
        /// and a non-awaiting `*Promise` companion signature (`return_type = Promise<T>`).
        fn prepareAwaitedAndPromiseSig(
            self: *Self,
            raw_sig: SignatureIr,
        ) error{OutOfMemory}!?SplitPromiseSig {
            if (raw_sig.has_type_predicate) return null;
            if (raw_sig.return_type.* != .promise) {
                if (raw_sig.return_type.* == .decl_ref) {
                    const dr = raw_sig.return_type.decl_ref;
                    if (dr.target_decl_id < self.graph.decls.len) {
                        const td = self.graph.decls[dr.target_decl_id];
                        if (td.kind == .type_alias_decl and td.type_params.len == dr.type_args.len) {
                            const alias_tid = td.kind.type_alias_decl;
                            if (alias_tid < self.graph.types.len and self.graph.types[alias_tid].kind == .conditional) {
                                const pat = type_ops.recognizeOpenConditionalPattern(
                                    self.graph,
                                    self.graph.types[alias_tid].kind.conditional,
                                );
                                if (pat == .conditional_promise_return) {
                                    const check_tid = pat.conditional_promise_return;
                                    for (td.type_params, 0..) |tp_id, tp_idx| {
                                        if (type_ops.typeNodeMatchesTypeParam(self.graph, check_tid, tp_id)) {
                                            const payload = try self.makeType(.{
                                                .unary_type_op = .{
                                                    .op = .infer_callback_promise_payload,
                                                    .operand = dr.type_args[tp_idx],
                                                },
                                            });
                                            var awaited = raw_sig;
                                            awaited.return_type = payload;
                                            awaited.awaits_promise = true;

                                            var prom_comp = raw_sig;
                                            prom_comp.params = try self.alloc.dupe(ParamIr, raw_sig.params);
                                            prom_comp.awaits_promise = false;
                                            return .{ .awaited = awaited, .promise_companion = prom_comp };
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return null;
            }
            var payload = raw_sig.return_type.promise;
            while (payload.* == .promise) {
                payload = payload.promise;
            }
            var awaited = raw_sig;
            awaited.return_type = payload;
            awaited.awaits_promise = true;

            var prom_comp = raw_sig;
            prom_comp.params = try self.alloc.dupe(ParamIr, raw_sig.params);
            prom_comp.return_type = if (raw_sig.return_type.promise == payload)
                raw_sig.return_type
            else
                try self.makeType(.{ .promise = payload });
            prom_comp.awaits_promise = false;

            return .{ .awaited = awaited, .promise_companion = prom_comp };
        }

        fn refreshSigParamsAgainstScope(
            self: *Self,
            sig_ir: *SignatureIr,
            enclosing_scope: *const naming.ScopeNamer,
        ) error{OutOfMemory}!void {
            var fn_scope = naming.ScopeNamer.initParam(self.scratch, enclosing_scope);
            defer fn_scope.deinit();
            try fn_scope.reserve("zigar_js");
            try fn_scope.reserve("zigar_js_tuple");
            try fn_scope.reserve("__zigar_prom");
            for (sig_ir.type_params) |tp| {
                try fn_scope.reserve(tp.logical_name);
            }
            if (sig_ir.self_param_ident != null) {
                const sb = try fn_scope.bindWithFallbackSuffix("self", .snake, "arg");
                sig_ir.self_param_ident = try self.alloc.dupe(u8, sb.zig_ident);
                sb.deinit(self.scratch);
            }
            if (sig_ir.this_param) |*thp| {
                const tb = try fn_scope.bindWithFallbackSuffix("this_arg", .snake, "arg");
                thp.zig_ident = try self.alloc.dupe(u8, tb.zig_ident);
                tb.deinit(self.scratch);
            }
            if (sig_ir.params.len > 0) {
                var new_params = try self.alloc.alloc(ParamIr, sig_ir.params.len);
                for (sig_ir.params, 0..) |orig_p, pidx| {
                    var p = orig_p;
                    const fallback = if (p.wire_name.len == 0 or std.mem.eql(u8, p.wire_name, "_")) "arg" else p.wire_name;
                    const bound = try fn_scope.bindWithFallbackSuffix(fallback, .snake, "arg");
                    p.zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                    p.logical_name = try self.alloc.dupe(u8, bound.logical_name);
                    bound.deinit(self.scratch);
                    new_params[pidx] = p;
                }
                sig_ir.params = new_params;
            }
            const ab = try fn_scope.bindWithFallbackSuffix("allocator", .snake, "arg");
            sig_ir.alloc_param_ident = try self.alloc.dupe(u8, ab.zig_ident);
            ab.deinit(self.scratch);
        }

        fn tryLowerSingleLiteralParam(self: *Self, p_ty_id: u32) error{OutOfMemory}!?*TypeIr {
            if (self.inline_anon_depth >= 3 or p_ty_id >= self.graph.types.len) return null;
            var nullish: lower_types.NullishKind = .none;
            const leaf_tid: u32 = switch (self.graph.types[p_ty_id].kind) {
                .literal => p_ty_id,
                .union_type => |arms| blk: {
                    var non_null: std.ArrayList(u32) = .empty;
                    defer non_null.deinit(self.scratch);
                    try self.collectFlattenedUnionArms(arms, &non_null, &nullish, 0);
                    if (non_null.items.len != 1) return null;
                    if (non_null.items[0] >= self.graph.types.len or self.graph.types[non_null.items[0]].kind != .literal) return null;
                    break :blk non_null.items[0];
                },
                else => return null,
            };
            const clv = (try self.extractClosedLiteralFromType(leaf_tid, 0)) orelse return null;
            const enum_ir = try self.buildEnumMembersFromClosedLiterals(&.{clv});
            const base_ty = try self.makeType(.{ .inline_enum = enum_ir });
            return if (nullish != .none) try self.wrapOptionalWithNullish(base_ty, nullish) else base_ty;
        }

        fn lowerSignature(
            self: *Self,
            sig_id: u32,
            enclosing_scope: *const naming.ScopeNamer,
            has_self_receiver: bool,
            receiver_binds_js_this: bool,
            allow_single_literal_enum: bool,
            outer_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!SignatureIr {
            return self.lowerSignatureWithSkip(
                sig_id,
                &.{},
                enclosing_scope,
                has_self_receiver,
                receiver_binds_js_this,
                allow_single_literal_enum,
                outer_active_tps,
                self_ident_opt,
                imports_used,
                needs_runtime,
            );
        }

        fn lowerSignatureWithSkip(
            self: *Self,
            sig_id: u32,
            skip_tp_ids: []const u32,
            enclosing_scope: *const naming.ScopeNamer,
            has_self_receiver: bool,
            receiver_binds_js_this: bool,
            allow_single_literal_enum: bool,
            outer_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!SignatureIr {
            if (sig_id >= self.graph.signatures.len) {
                var fallback_self_ident: ?[]const u8 = null;
                if (has_self_receiver) {
                    var fn_scope_fb = naming.ScopeNamer.initParam(self.scratch, enclosing_scope);
                    defer fn_scope_fb.deinit();
                    try fn_scope_fb.reserve("zigar_js");
                    try fn_scope_fb.reserve("zigar_js_tuple");
                    try fn_scope_fb.reserve("__zigar_prom");
                    const sb = try fn_scope_fb.bindWithFallbackSuffix("self", .snake, "arg");
                    fallback_self_ident = try self.alloc.dupe(u8, sb.zig_ident);
                    sb.deinit(self.scratch);
                }
                return .{
                    .self_param_ident = fallback_self_ident,
                    .type_params = &.{},
                    .params = &.{},
                    .return_type = try self.makeType(.void_type),
                    .has_type_predicate = false,
                    .type_predicate_asserts = false,
                    .jsdoc = null,
                };
            }

            const sig = self.graph.signatures[sig_id];
            var fn_scope = naming.ScopeNamer.initParam(self.scratch, enclosing_scope);
            defer fn_scope.deinit();
            try fn_scope.reserve("zigar_js");
            try fn_scope.reserve("zigar_js_tuple");
            try fn_scope.reserve("__zigar_prom");

            var self_param_ident: ?[]const u8 = null;
            if (has_self_receiver) {
                const sb = try fn_scope.bindWithFallbackSuffix("self", .snake, "arg");
                self_param_ident = try self.alloc.dupe(u8, sb.zig_ident);
                sb.deinit(self.scratch);
            }

            const tp_res = try self.lowerTypeParamsWithSkip(
                sig.type_params,
                skip_tp_ids,
                &fn_scope,
                outer_active_tps,
                self_ident_opt,
                imports_used,
                needs_runtime,
            );

            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);

            var this_param_ir: ?ThisParamIr = null;
            if (sig.this_param) |this_tid| {
                const is_this_void = self.isVoidGraphType(this_tid);
                if (lower_functions.shouldBindExplicitThis(
                    has_self_receiver,
                    receiver_binds_js_this and !has_self_receiver,
                    is_this_void,
                )) {
                    const tb = try fn_scope.bindWithFallbackSuffix("this_arg", .snake, "arg");
                    const this_zig_ident = try self.alloc.dupe(u8, tb.zig_ident);
                    tb.deinit(self.scratch);
                    visited.clearRetainingCapacity();
                    const this_ty = try self.lowerType(this_tid, false, tp_res.active, self_ident_opt, &visited, imports_used, needs_runtime);
                    this_param_ir = .{
                        .zig_ident = this_zig_ident,
                        .ty = this_ty,
                        .is_optional = this_ty.* == .optional,
                        .nullish_kind = if (this_ty.* == .optional) this_ty.optional.nullish_kind else .none,
                    };
                }
            }

            var params = try self.alloc.alloc(ParamIr, sig.params.len);
            for (sig.params, 0..) |p, idx| {
                const raw_pname = self.str(p.name);
                const fallback = if (raw_pname.len == 0 or std.mem.eql(u8, raw_pname, "_")) "arg" else raw_pname;
                const bound = try fn_scope.bindWithFallbackSuffix(fallback, .snake, "arg");
                const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                const logical = try self.alloc.dupe(u8, bound.logical_name);
                bound.deinit(self.scratch);

                visited.clearRetainingCapacity();
                var pt: *TypeIr = if (!p.rest and allow_single_literal_enum)
                    (try self.tryLowerSingleLiteralParam(p.ty)) orelse
                        try self.lowerType(p.ty, false, tp_res.active, self_ident_opt, &visited, imports_used, needs_runtime)
                else
                    try self.lowerType(p.ty, false, tp_res.active, self_ident_opt, &visited, imports_used, needs_runtime);
                var is_open_rest_seq = false;
                if (p.rest) {
                    if (!self.isAlreadySliceTypeIr(pt, 0)) {
                        if (self.isOpenRestSequenceTypeIr(pt, 0)) {
                            is_open_rest_seq = true;
                            needs_runtime.* = true;
                        } else {
                            pt = try self.makeType(.{ .slice = pt });
                        }
                    }
                } else if (p.optional) {
                    pt = try self.wrapOptional(pt);
                }

                const cb_sig: ?FnPtrIr = if (!p.rest)
                    try self.extractCallbackSigFromParam(
                        p.ty,
                        pt,
                        tp_res.active,
                        self_ident_opt,
                        imports_used,
                        needs_runtime,
                    )
                else
                    null;

                const is_open_cb = !p.rest and cb_sig == null and self.graphTypeResolvesToCallableAlias(p.ty, 0);
                if (is_open_cb) needs_runtime.* = true;

                params[idx] = .{
                    .zig_ident = zig_ident,
                    .logical_name = logical,
                    .wire_name = try self.alloc.dupe(u8, raw_pname),
                    .ty = pt,
                    .is_optional = p.optional,
                    .is_rest = p.rest,
                    .is_open_callback = is_open_cb,
                    .is_open_rest_sequence = is_open_rest_seq,
                    .nullish_kind = if (!p.rest and pt.* == .optional) pt.optional.nullish_kind else .none,
                    .callback_sig = cb_sig,
                };
            }

            const alloc_bound = try fn_scope.bindWithFallbackSuffix("allocator", .snake, "arg");
            const alloc_param_ident = try self.alloc.dupe(u8, alloc_bound.zig_ident);
            alloc_bound.deinit(self.scratch);

            visited.clearRetainingCapacity();
            const has_pred = sig.type_predicate != null;
            const pred_asserts = if (sig.type_predicate) |pred| pred.asserts else false;
            const ret_ty = if (has_pred)
                (if (pred_asserts) try self.makeType(.void_type) else try self.makeType(.bool_type))
            else
                try self.lowerType(sig.return_type, true, tp_res.active, self_ident_opt, &visited, imports_used, needs_runtime);

            var pred_target_ir: ?TypePredicateTargetIr = null;
            if (sig.type_predicate) |pred| {
                if (pred.target_type) |target_tid| {
                    var wire_names = try self.scratch.alloc([]const u8, params.len);
                    defer self.scratch.free(wire_names);
                    for (params, 0..) |pm, pidx| wire_names[pidx] = pm.wire_name;

                    if (lower_functions.resolvePredicateSubject(
                        self.str(pred.param_name),
                        pred.param_index,
                        wire_names,
                        has_self_receiver,
                        this_param_ir != null,
                    )) |subj| {
                        const subject_ok = switch (subj) {
                            .param_index => |pidx| pidx < params.len and !params[pidx].is_rest,
                            .self_receiver, .explicit_this => true,
                        };
                        if (subject_ok) {
                            visited.clearRetainingCapacity();
                            const target_ty = try self.lowerType(
                                target_tid,
                                true,
                                tp_res.active,
                                self_ident_opt,
                                &visited,
                                imports_used,
                                needs_runtime,
                            );
                            if (target_ty.* != .void_type and target_ty.* != .noreturn_type) {
                                pred_target_ir = .{
                                    .subject = subj,
                                    .target_ty = target_ty,
                                    .target_allocates = try self.typeMayAllocateOnDecode(target_ty),
                                };
                            }
                        }
                    }
                }
            }

            var default_prefix: lower_generics.DefaultPrefixInfo = .{
                .required_count = 0,
                .defaulted_count = 0,
                .emit_default_companion = false,
                .emit_with_companion = false,
            };
            var infer_bindings: ?[]const lower_generics.InferBinding = null;
            if (tp_res.ir.len > 0) {
                const has_defaults = try self.scratch.alloc(bool, tp_res.ir.len);
                defer self.scratch.free(has_defaults);
                for (tp_res.ir, 0..) |tp, idx| has_defaults[idx] = tp.default_type != null;
                default_prefix = lower_generics.analyzeDefaultPrefix(has_defaults);

                var param_shapes = try self.scratch.alloc(lower_generics.ParamTypeParamShape, params.len);
                defer self.scratch.free(param_shapes);
                for (params, 0..) |pm, pidx| {
                    if (pm.is_rest or (pidx < sig.params.len and self.graphTypeIsInsideNoInfer(sig.params[pidx].ty, 0))) {
                        param_shapes[pidx] = .none;
                        continue;
                    }
                    param_shapes[pidx] = classifyParamForTypeParamInference(pm.ty, tp_res.ir);
                }
                if (try lower_generics.solveTypeParamInferenceWithDefaults(self.alloc, tp_res.ir.len, has_defaults, param_shapes)) |solved| {
                    needs_runtime.* = true;
                    infer_bindings = solved;
                }
            }

            return .{
                .self_param_ident = self_param_ident,
                .alloc_param_ident = alloc_param_ident,
                .this_param = this_param_ir,
                .type_params = tp_res.ir,
                .default_prefix = default_prefix,
                .infer_bindings = infer_bindings,
                .params = params,
                .return_type = ret_ty,
                .has_type_predicate = has_pred,
                .type_predicate_asserts = pred_asserts,
                .type_predicate_target = pred_target_ir,
                .jsdoc = try self.lowerJsDoc(sig.jsdoc),
            };
        }

        fn typeMayAllocateOnDecode(self: *Self, ty: *const TypeIr) error{OutOfMemory}!bool {
            return switch (ty.*) {
                .string_type,
                .bytes_type,
                .typed_slice,
                .slice,
                .pointer_const,
                .type_param_ref,
                .template_pattern,
                .key_filter_op,
                .index_access_op,
                .empty_object_extends_op,
                .intersect_op,
                => true,
                .unary_type_op => |uo| uo.op != .constructor_of,
                .js_record => |r| r.key.* != .string_type and (r.key.* == .type_param_ref or try self.typeMayAllocateOnDecode(r.value)),
                .mapped_values_op => |mv| mv.target.* == .type_param_ref or mv.target.* == .slice or try self.typeMayAllocateOnDecode(mv.value),
                .inline_enum => false,
                .open_literal_union => |olu| olu.base_kind == .str,
                .optional => |opt| try self.typeMayAllocateOnDecode(opt.child),
                .tuple => |elems| blk: {
                    for (elems) |el| {
                        if (try self.typeMayAllocateOnDecode(el.ty)) break :blk true;
                    }
                    break :blk false;
                },
                .anon_struct => |fields| blk: {
                    for (fields) |f| {
                        if (try self.typeMayAllocateOnDecode(f.ty)) break :blk true;
                    }
                    break :blk false;
                },
                .tagged_union => |tu| blk: {
                    for (tu.variants) |v| {
                        if (try self.typeMayAllocateOnDecode(v.payload)) break :blk true;
                    }
                    break :blk false;
                },
                .decl_ref => |dr| blk: {
                    if (dr.indirect) break :blk true;
                    if (dr.target_decl_id == std.math.maxInt(u32)) {
                        if (dr.decl_zig_path.len == 1 and
                            (std.mem.startsWith(u8, dr.decl_zig_path[0], "__zigar_AnonHandle") or
                                std.mem.startsWith(u8, dr.decl_zig_path[0], "__zigar_AnonFn") or
                                std.mem.startsWith(u8, dr.decl_zig_path[0], "__zigar_ArrayBufferView")))
                        {
                            break :blk false;
                        }
                    } else if (dr.target_decl_id < self.graph.decls.len) {
                        const td_kind = self.graph.decls[dr.target_decl_id].kind;
                        if (td_kind == .enum_decl) break :blk false;
                        if ((try self.classifyDecl(dr.target_decl_id)).kind == .handle_wrapper) {
                            break :blk false;
                        }
                    }
                    break :blk true;
                },
                else => false,
            };
        }

        const EnumMemberLookup = struct {
            enum_decl_id: u32,
            member_idx: usize,
            tag_zig_ident: []const u8,
            tag_logical_name: []const u8,
            value: EnumValueIr,
        };

        fn resolveEnumMemberReference(self: *Self, ty_id: u32) error{OutOfMemory}!?EnumMemberLookup {
            if (ty_id >= self.graph.types.len) return null;
            const tn = self.graph.types[ty_id];
            if (tn.kind != .reference) return null;
            const ref = tn.kind.reference;
            const td = ref.target_decl orelse return null;
            if (td >= self.graph.decls.len) return null;
            const decl = self.graph.decls[td];
            if (decl.kind != .enum_decl) return null;
            const en = decl.kind.enum_decl;
            if (en.members.len == 0) return null;

            const ref_name = self.str(ref.target_name);
            const dot_idx = std.mem.lastIndexOfScalar(u8, ref_name, '.') orelse return null;
            const member_suffix = ref_name[dot_idx + 1 ..];
            if (member_suffix.len == 0) return null;

            // Verify every member in the parent enum has a known value; otherwise runtime representation is a struct wrapper.
            for (en.members) |m| {
                const mv = m.value orelse return null;
                switch (mv) {
                    .num => |n| if (!std.math.isFinite(n)) return null,
                    .str, .boolean, .bigint_literal => {},
                }
            }

            var target_member_idx: ?usize = null;
            for (en.members, 0..) |m, idx| {
                if (std.mem.eql(u8, self.str(m.name), member_suffix)) {
                    target_member_idx = idx;
                    break;
                }
            }
            const found_idx = target_member_idx orelse return null;

            // Replay exact member ScopeNamer binding order so aliased/deduplicated tag names match 1-for-1!
            var member_scope = naming.ScopeNamer.initContainer(self.scratch, null);
            defer member_scope.deinit();
            try member_scope.reserve("zigar_js");
            try member_scope.reserve("__zigar_value");

            var chosen_zig_ident: []const u8 = "";
            var chosen_logical_name: []const u8 = "";
            for (en.members, 0..) |m, idx| {
                const mb = try member_scope.bind(self.str(m.name), .snake);
                if (idx == found_idx) {
                    chosen_zig_ident = try self.alloc.dupe(u8, mb.zig_ident);
                    chosen_logical_name = try self.alloc.dupe(u8, mb.logical_name);
                }
                mb.deinit(self.scratch);
            }

            const mv = en.members[found_idx].value.?;
            const val_ir: EnumValueIr = switch (mv) {
                .num => |n| .{ .num = n },
                .str => |sid| .{ .str = self.str(sid) },
                .boolean => |b| .{ .boolean = b },
                .bigint_literal => |sid| .{ .bigint_val = self.str(sid) },
            };

            return .{
                .enum_decl_id = td,
                .member_idx = found_idx,
                .tag_zig_ident = chosen_zig_ident,
                .tag_logical_name = chosen_logical_name,
                .value = val_ir,
            };
        }

        fn extractClosedLiteralFromType(
            self: *Self,
            ty_id: u32,
            depth: usize,
        ) error{OutOfMemory}!?lower_unions.ClosedLiteralValue {
            if (ty_id >= self.graph.types.len or depth > 8) return null;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .literal => |lit| return switch (lit) {
                    .str => |sid| .{ .str = self.str(sid) },
                    .num => |n| if (std.math.isFinite(n)) .{ .num = n } else null,
                    .boolean => |b| .{ .boolean = b },
                    .bigint_literal => |sid| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, self.str(sid)) },
                },
                .template_literal => |tl| {
                    if (tl.spans.len == 0) return .{ .str = self.str(tl.head) };
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.extractClosedLiteralFromType(rt, depth + 1);
                    }
                    return null;
                },
                .intrinsic => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.extractClosedLiteralFromType(rt, depth + 1);
                    }
                    return null;
                },
                .reference => |ref| {
                    if (try self.resolveEnumMemberReference(ty_id)) |em| {
                        return switch (em.value) {
                            .str => |s| .{ .str = s },
                            .num => |n| .{ .num = n },
                            .boolean => |b| .{ .boolean = b },
                            .bigint_val => |bi| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, bi) },
                            .unknown => null,
                        };
                    }
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const d = self.graph.decls[td];
                            if (d.kind == .type_alias_decl and d.type_params.len == 0) {
                                return self.extractClosedLiteralFromType(d.kind.type_alias_decl, depth + 1);
                            }
                        }
                    } else if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.extractClosedLiteralFromType(rt, depth + 1);
                    }
                    return null;
                },
                else => return null,
            }
        }

        fn resolveUnderlyingBuiltinKind(self: *const Self, ty: *const TypeIr, depth: usize) std.meta.Tag(TypeIr) {
            if (depth > 8) return @as(std.meta.Tag(TypeIr), ty.*);
            if (ty.* == .decl_ref) {
                const dr = ty.decl_ref;
                if (!dr.indirect and dr.type_args.len == 0 and dr.target_decl_id < self.graph.decls.len) {
                    const d = self.graph.decls[dr.target_decl_id];
                    if (d.kind == .type_alias_decl) {
                        const target_ty_id = d.kind.type_alias_decl;
                        if (target_ty_id < self.graph.types.len) {
                            switch (self.graph.types[target_ty_id].kind) {
                                .literal => |lit| return switch (lit) {
                                    .str => .string_type,
                                    .num => .f64_type,
                                    .boolean => .bool_type,
                                    .bigint_literal => .i64_type,
                                },
                                .string_type => return .string_type,
                                .number_type => return .f64_type,
                                .boolean_type => return .bool_type,
                                .bigint_type => return .i64_type,
                                else => {},
                            }
                        }
                    }
                }
            }
            return @as(std.meta.Tag(TypeIr), ty.*);
        }

        fn extractCompatibleFieldLiteralConstraint(
            self: *Self,
            raw_ty_id: u32,
            lowered_ty: *const TypeIr,
        ) error{OutOfMemory}!?FieldLiteralConstraintIr {
            if (try self.resolveEnumMemberReference(raw_ty_id)) |em| {
                if (lowered_ty.* == .decl_ref and !lowered_ty.decl_ref.indirect and lowered_ty.decl_ref.target_decl_id == em.enum_decl_id) {
                    return .{
                        .enum_member = .{
                            .enum_decl_id = em.enum_decl_id,
                            .tag_zig_ident = em.tag_zig_ident,
                            .tag_logical_name = em.tag_logical_name,
                        },
                    };
                }
                return null;
            }

            // Do not attach a literal default when `raw_ty_id` is a reference to a multi-member or nominal enum/alias
            // unless `lowered_ty` actually lowered to the corresponding scalar type!
            const underlying_tag = self.resolveUnderlyingBuiltinKind(lowered_ty, 0);
            const clv = (try self.extractClosedLiteralFromType(raw_ty_id, 0)) orelse return null;
            switch (clv) {
                .str => |s| {
                    if (underlying_tag != .string_type) return null;
                    return .{ .str = try self.alloc.dupe(u8, s) };
                },
                .num => |n| {
                    if (underlying_tag != .f64_type) return null;
                    return .{ .num = n };
                },
                .boolean => |b| {
                    if (underlying_tag != .bool_type) return null;
                    return .{ .boolean = b };
                },
                .bigint_val => |bi| {
                    if (underlying_tag != .i64_type) return null;
                    _ = std.fmt.parseInt(i64, bi, 0) catch return null;
                    return .{ .bigint_val = bi };
                },
            }
        }

        fn isEmptyObjectMarkerType(self: *const Self, ty_id: u32, depth: usize) bool {
            if (ty_id >= self.graph.types.len or depth > 4) return false;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .object_literal => |obj| {
                    return obj.properties.len == 0 and
                        obj.call_signatures.len == 0 and
                        obj.construct_signatures.len == 0 and
                        obj.index_signatures.len == 0;
                },
                .reference => |ref| {
                    const rname = self.str(ref.target_name);
                    if (std.mem.eql(u8, rname, "Record") and ref.type_args.len == 2) {
                        const k_id = ref.type_args[0];
                        if (k_id < self.graph.types.len and self.graph.types[k_id].kind == .never_type) return true;
                    }
                    if (ref.target_decl == null) {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) return self.isEmptyObjectMarkerType(rt, depth + 1);
                        }
                    }
                    return false;
                },
                else => return false,
            }
        }

        const BrandedPrimitiveKind = enum {
            str,
            num,
            bigint,
            boolean,
            symbol,
        };

        fn detectOpenPrimitiveIntersection(self: *const Self, parts: []const u32) ?lower_unions.OpenPrimitiveKind {
            if (parts.len < 2) return null;
            var prim_opt: ?lower_unions.OpenPrimitiveKind = null;
            var saw_empty_obj = false;
            for (parts) |pid| {
                if (pid >= self.graph.types.len) return null;
                switch (self.graph.types[pid].kind) {
                    .string_type => {
                        if (prim_opt != null and prim_opt.? != .str) return null;
                        prim_opt = .str;
                    },
                    .number_type => {
                        if (prim_opt != null and prim_opt.? != .num) return null;
                        prim_opt = .num;
                    },
                    .bigint_type => {
                        if (prim_opt != null and prim_opt.? != .bigint) return null;
                        prim_opt = .bigint;
                    },
                    else => {
                        if (self.isEmptyObjectMarkerType(pid, 0)) {
                            saw_empty_obj = true;
                        } else {
                            return null;
                        }
                    },
                }
            }
            if (saw_empty_obj) return prim_opt;
            return null;
        }

        /// Detects inhabited branded scalar intersections such as
        /// `string & { readonly __brand: "UserId" }`, `number & Brand<"Port">`, or
        /// `NonNegative & { readonly __port: true }`, which at JS runtime are always
        /// the underlying primitive scalar (`[]const u8`, `f64`, `i64`, `bool`, `Symbol`).
        fn detectBrandedPrimitiveIntersection(
            self: *const Self,
            parts: []const u32,
            depth: usize,
        ) ?BrandedPrimitiveKind {
            if (parts.len < 2 or depth > 8) return null;
            var prim_opt: ?BrandedPrimitiveKind = null;
            var saw_brand_obj = false;
            for (parts) |pid| {
                if (!self.classifyBrandedPrimitiveArm(pid, &prim_opt, &saw_brand_obj, depth)) return null;
            }
            if (saw_brand_obj) return prim_opt;
            return null;
        }

        fn classifyBrandedPrimitiveArm(
            self: *const Self,
            arm_id: u32,
            prim_opt: *?BrandedPrimitiveKind,
            saw_brand_obj: *bool,
            depth: usize,
        ) bool {
            if (arm_id >= self.graph.types.len or depth > 8) return false;
            const tn = self.graph.types[arm_id];
            switch (tn.kind) {
                .string_type, .template_literal => {
                    if (prim_opt.* != null and prim_opt.*.? != .str) return false;
                    prim_opt.* = .str;
                    return true;
                },
                .number_type => {
                    if (prim_opt.* != null and prim_opt.*.? != .num) return false;
                    prim_opt.* = .num;
                    return true;
                },
                .bigint_type => {
                    if (prim_opt.* != null and prim_opt.*.? != .bigint) return false;
                    prim_opt.* = .bigint;
                    return true;
                },
                .boolean_type => {
                    if (prim_opt.* != null and prim_opt.*.? != .boolean) return false;
                    prim_opt.* = .boolean;
                    return true;
                },
                .symbol_type, .unique_symbol => {
                    if (prim_opt.* != null and prim_opt.*.? != .symbol) return false;
                    prim_opt.* = .symbol;
                    return true;
                },
                .literal => |lit| {
                    const lk: BrandedPrimitiveKind = switch (lit) {
                        .str => .str,
                        .num => .num,
                        .bigint_literal => .bigint,
                        .boolean => .boolean,
                    };
                    if (prim_opt.* != null and prim_opt.*.? != lk) return false;
                    prim_opt.* = lk;
                    return true;
                },
                .intersection => |sub_parts| {
                    if (sub_parts.len == 0) return false;
                    for (sub_parts) |spid| {
                        if (!self.classifyBrandedPrimitiveArm(spid, prim_opt, saw_brand_obj, depth + 1)) return false;
                    }
                    return true;
                },
                .object_literal, .mapped => {
                    saw_brand_obj.* = true;
                    return true;
                },
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const d = self.graph.decls[td];
                            if (d.kind == .type_alias_decl and d.type_params.len == 0 and ref.type_args.len == 0) {
                                return self.classifyBrandedPrimitiveArm(d.kind.type_alias_decl, prim_opt, saw_brand_obj, depth + 1);
                            }
                            if (d.kind == .interface_decl or d.kind == .type_alias_decl) {
                                saw_brand_obj.* = true;
                                return true;
                            }
                        }
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn classifyOpenSlotType(self: *const Self, ty_id: u32, depth: usize) ?lower_unions.TemplatePlaceholderKind {
            if (ty_id >= self.graph.types.len or depth > 6) return null;
            const tn = self.graph.types[ty_id];
            return switch (tn.kind) {
                .string_type, .any_type => .any_string,
                .number_type => .number,
                .bigint_type => .bigint,
                .boolean_type => .boolean,
                .intersection => |parts| blk: {
                    if (self.detectOpenPrimitiveIntersection(parts)) |opk| {
                        break :blk switch (opk) {
                            .str => .any_string,
                            .num => .number,
                            .bigint => .bigint,
                        };
                    }
                    break :blk null;
                },
                .reference => |ref| blk: {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and ref.type_args.len == 0) {
                            const d = self.graph.decls[td];
                            if (d.kind == .type_alias_decl and d.type_params.len == 0) {
                                break :blk self.classifyOpenSlotType(d.kind.type_alias_decl, depth + 1);
                            }
                        }
                    }
                    break :blk null;
                },
                else => null,
            };
        }

        fn tryExpandFiniteStringSet(
            self: *Self,
            ty_id: u32,
            out: *std.ArrayList([]const u8),
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len or depth > 8) return false;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .never_type => return true,
                .null_type => {
                    try out.append(self.alloc, "null");
                    return out.items.len <= lower_unions.max_template_expansion;
                },
                .undefined_type => {
                    try out.append(self.alloc, "undefined");
                    return out.items.len <= lower_unions.max_template_expansion;
                },
                .boolean_type => {
                    try out.append(self.alloc, "false");
                    try out.append(self.alloc, "true");
                    return out.items.len <= lower_unions.max_template_expansion;
                },
                .literal => |lit| {
                    switch (lit) {
                        .str => |sid| try out.append(self.alloc, self.str(sid)),
                        .boolean => |b| try out.append(self.alloc, if (b) "true" else "false"),
                        .num => |n| {
                            if (!std.math.isFinite(n)) return false;
                            if (lower_unions.exactIntI64(n)) |iv| {
                                try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{iv}));
                            } else {
                                try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{n}));
                            }
                        },
                        .bigint_literal => |sid| {
                            const clean = try lower_types.normalizeBigIntLiteral(self.alloc, self.str(sid));
                            if (std.fmt.parseInt(i128, clean, 0)) |iv| {
                                try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{iv}));
                            } else |_| {
                                try out.append(self.alloc, clean);
                            }
                        },
                    }
                    return out.items.len <= lower_unions.max_template_expansion;
                },
                .union_type => |arms| {
                    for (arms) |aid| {
                        if (!try self.tryExpandFiniteStringSet(aid, out, depth + 1)) return false;
                        if (out.items.len > lower_unions.max_template_expansion) return false;
                    }
                    return true;
                },
                .template_literal => |tl| {
                    if (tl.spans.len == 0) {
                        try out.append(self.alloc, self.str(tl.head));
                        return out.items.len <= lower_unions.max_template_expansion;
                    }
                    var span_alts = try self.scratch.alloc([]const []const u8, tl.spans.len);
                    defer self.scratch.free(span_alts);
                    var seps = try self.scratch.alloc([]const u8, tl.spans.len);
                    defer self.scratch.free(seps);

                    for (tl.spans, 0..) |sp, idx| {
                        var sub: std.ArrayList([]const u8) = .empty;
                        if (!try self.tryExpandFiniteStringSet(sp.ty, &sub, depth + 1)) {
                            sub.deinit(self.alloc);
                            return false;
                        }
                        span_alts[idx] = try sub.toOwnedSlice(self.alloc);
                        seps[idx] = self.str(sp.literal);
                    }
                    const expanded = (try lower_unions.expandTemplateCrossProduct(
                        self.alloc,
                        self.str(tl.head),
                        span_alts,
                        seps,
                    )) orelse return false;
                    defer self.alloc.free(expanded);
                    for (expanded) |s| {
                        try out.append(self.alloc, s);
                        if (out.items.len > lower_unions.max_template_expansion) return false;
                    }
                    return true;
                },
                .intrinsic => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.tryExpandFiniteStringSet(rt, out, depth + 1);
                    }
                    return false;
                },
                .reference => |ref| {
                    if (try self.resolveEnumMemberReference(ty_id)) |em| {
                        switch (em.value) {
                            .str => |s| try out.append(self.alloc, s),
                            .num => |n| {
                                if (!std.math.isFinite(n)) return false;
                                if (lower_unions.exactIntI64(n)) |iv| {
                                    try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{iv}));
                                } else {
                                    try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{n}));
                                }
                            },
                            .boolean => |b| try out.append(self.alloc, if (b) "true" else "false"),
                            .bigint_val => |bi| try out.append(self.alloc, bi),
                            .unknown => return false,
                        }
                        return out.items.len <= lower_unions.max_template_expansion;
                    }
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and ref.type_args.len == 0) {
                            const d = self.graph.decls[td];
                            switch (d.kind) {
                                .type_alias_decl => |alias_ty| {
                                    if (d.type_params.len == 0) {
                                        return self.tryExpandFiniteStringSet(alias_ty, out, depth + 1);
                                    }
                                },
                                .enum_decl => |en| {
                                    if (en.members.len == 0 or en.members.len > lower_unions.max_template_expansion) return false;
                                    const saved_len = out.items.len;
                                    for (en.members) |m| {
                                        const mv = m.value orelse {
                                            out.shrinkRetainingCapacity(saved_len);
                                            return false;
                                        };
                                        switch (mv) {
                                            .str => |sid| try out.append(self.alloc, self.str(sid)),
                                            .num => |n| {
                                                if (!std.math.isFinite(n)) {
                                                    out.shrinkRetainingCapacity(saved_len);
                                                    return false;
                                                }
                                                if (lower_unions.exactIntI64(n)) |iv| {
                                                    try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{iv}));
                                                } else {
                                                    try out.append(self.alloc, try std.fmt.allocPrint(self.alloc, "{d}", .{n}));
                                                }
                                            },
                                            else => {
                                                out.shrinkRetainingCapacity(saved_len);
                                                return false;
                                            },
                                        }
                                        if (out.items.len > lower_unions.max_template_expansion) return false;
                                    }
                                    return true;
                                },
                                else => {},
                            }
                        }
                    } else if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.tryExpandFiniteStringSet(rt, out, depth + 1);
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn buildStringEnumFromUniqueStrings(self: *Self, strs: []const []const u8) error{OutOfMemory}!InlineEnumIr {
            var unique: std.ArrayList([]const u8) = .empty;
            defer unique.deinit(self.scratch);
            for (strs) |s| {
                var dup = false;
                for (unique.items) |u| {
                    if (std.mem.eql(u8, u, s)) {
                        dup = true;
                        break;
                    }
                }
                if (!dup) try unique.append(self.scratch, s);
            }

            var tag_scope = naming.ScopeNamer.init(self.scratch, null);
            defer tag_scope.deinit();
            try tag_scope.reserve("zigar_js");

            var members = try self.alloc.alloc(EnumMemberIr, unique.items.len);
            for (unique.items, 0..) |raw_s, idx| {
                const hint = try lower_unions.formatLiteralTagHint(self.scratch, .{ .str = raw_s });
                defer self.scratch.free(hint);
                const bound = try tag_scope.bind(hint, .snake);
                const dup_s = try self.alloc.dupe(u8, raw_s);
                members[idx] = .{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_name = dup_s,
                    .value = .{ .str = dup_s },
                    .jsdoc = null,
                };
                bound.deinit(self.scratch);
            }
            return .{ .backing = .none, .members = members };
        }

        const PendingTemplateSpan = struct {
            placeholder: lower_unions.TemplatePlaceholderKind,
            choices: []const []const u8,
            tail: std.ArrayList(u8),
        };

        fn tryBuildDirectTemplatePattern(self: *Self, tl: anytype) error{OutOfMemory}!?TemplatePatternIr {
            if (tl.spans.len == 0 or tl.spans.len > lower_unions.max_template_pattern_spans) return null;
            var prefix_buf: std.ArrayList(u8) = .empty;
            errdefer prefix_buf.deinit(self.alloc);
            try prefix_buf.appendSlice(self.alloc, self.str(tl.head));

            var pending: std.ArrayList(PendingTemplateSpan) = .empty;
            defer {
                for (pending.items) |*ps| ps.tail.deinit(self.alloc);
                pending.deinit(self.scratch);
            }

            for (tl.spans) |sp| {
                var finite_strs: std.ArrayList([]const u8) = .empty;
                if (try self.tryExpandFiniteStringSet(sp.ty, &finite_strs, 0) and finite_strs.items.len > 0) {
                    var unique: std.ArrayList([]const u8) = .empty;
                    defer unique.deinit(self.scratch);
                    for (finite_strs.items) |s| {
                        var dup = false;
                        for (unique.items) |u| {
                            if (std.mem.eql(u8, u, s)) {
                                dup = true;
                                break;
                            }
                        }
                        if (!dup) try unique.append(self.scratch, s);
                    }
                    finite_strs.deinit(self.alloc);

                    if (unique.items.len == 1) {
                        const fold_target = if (pending.items.len > 0) &pending.items[pending.items.len - 1].tail else &prefix_buf;
                        try fold_target.appendSlice(self.alloc, unique.items[0]);
                        try fold_target.appendSlice(self.alloc, self.str(sp.literal));
                        continue;
                    }
                    var owned_choices = try self.alloc.alloc([]const u8, unique.items.len);
                    for (unique.items, 0..) |u, ci| {
                        owned_choices[ci] = try self.alloc.dupe(u8, u);
                    }
                    var tb: std.ArrayList(u8) = .empty;
                    try tb.appendSlice(self.alloc, self.str(sp.literal));
                    try pending.append(self.scratch, .{
                        .placeholder = .literal_set,
                        .choices = owned_choices,
                        .tail = tb,
                    });
                    continue;
                }
                finite_strs.deinit(self.alloc);

                if (self.classifyOpenSlotType(sp.ty, 0)) |slot_kind| {
                    var tb: std.ArrayList(u8) = .empty;
                    try tb.appendSlice(self.alloc, self.str(sp.literal));
                    try pending.append(self.scratch, .{
                        .placeholder = slot_kind,
                        .choices = &.{},
                        .tail = tb,
                    });
                } else {
                    prefix_buf.deinit(self.alloc);
                    return null;
                }
            }

            if (pending.items.len == 0) {
                prefix_buf.deinit(self.alloc);
                return null;
            }

            var out_spans = try self.alloc.alloc(TemplateSpanIr, pending.items.len);
            for (pending.items, 0..) |*ps, idx| {
                out_spans[idx] = .{
                    .placeholder = ps.placeholder,
                    .choices = ps.choices,
                    .literal_tail = try ps.tail.toOwnedSlice(self.alloc),
                };
            }
            return .{
                .head = try prefix_buf.toOwnedSlice(self.alloc),
                .spans = out_spans,
            };
        }

        fn lowerTemplateLiteralInline(
            self: *Self,
            ty_id: u32,
            tl: anytype,
            resolved_opt: ?u32,
            ref_cnt: u32,
            can_hoist_in_mod: bool,
            no_free_vars: bool,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            if (tl.spans.len == 0) return self.makeType(.string_type);

            var finite_strs: std.ArrayList([]const u8) = .empty;
            defer finite_strs.deinit(self.alloc);
            if (try self.tryExpandFiniteStringSet(ty_id, &finite_strs, 0)) {
                if (finite_strs.items.len <= 1) return self.makeType(.string_type);
                const enum_ir = try self.buildStringEnumFromUniqueStrings(finite_strs.items);
                if (enum_ir.members.len <= 1) return self.makeType(.string_type);
                if (can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id)) and (ref_cnt > 1 or enum_ir.members.len > 8)) {
                    const h = try self.allocFreshAnonHelperName("__zigar_AnonEnum", active_tps);
                    const hloc = DeclLocation{
                        .module_index = self.cur_mod_idx,
                        .zig_path = h.path,
                        .type_param_defaults = &.{},
                    };
                    try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                    try self.cur_mod_decls_out.?.append(self.alloc, .{
                        .source_decl_id = null,
                        .zig_ident = h.zig_ident,
                        .logical_name = h.logical,
                        .wire_name = h.logical,
                        .is_exported = false,
                        .is_js_exported = false,
                        .is_default_export = false,
                        .jsdoc = null,
                        .kind = .{ .literal_enum_decl = enum_ir },
                    });
                    return self.makeHoistedDeclRef(hloc);
                }
                if (self.inline_anon_depth >= 3 or enum_ir.members.len > 64) {
                    return self.makeType(.string_type);
                }
                return self.makeType(.{ .inline_enum = enum_ir });
            }

            if (try self.tryBuildDirectTemplatePattern(tl)) |pat_ir| {
                needs_runtime.* = true;
                if (can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id)) and ref_cnt > 1) {
                    const h = try self.allocFreshAnonHelperName("__zigar_AnonTemplate", active_tps);
                    const hloc = DeclLocation{
                        .module_index = self.cur_mod_idx,
                        .zig_path = h.path,
                        .type_param_defaults = &.{},
                    };
                    try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                    try self.cur_mod_decls_out.?.append(self.alloc, .{
                        .source_decl_id = null,
                        .zig_ident = h.zig_ident,
                        .logical_name = h.logical,
                        .wire_name = h.logical,
                        .is_exported = false,
                        .is_js_exported = false,
                        .is_default_export = false,
                        .jsdoc = null,
                        .kind = .{ .template_pattern_decl = pat_ir },
                    });
                    return self.makeHoistedDeclRef(hloc);
                }
                if (self.inline_anon_depth >= 3) {
                    return self.makeType(.string_type);
                }
                return self.makeType(.{ .template_pattern = pat_ir });
            }

            // If TypeScript Checker distributed a union inside a template literal (`${"http"|"https"}://${string}`),
            // delegate to the resolved union!
            if (resolved_opt) |rt| {
                if (rt != ty_id and rt < self.graph.types.len and self.graph.types[rt].kind == .union_type) {
                    return self.lowerType(rt, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                }
            }
            return self.makeType(.string_type);
        }

        const MergedPropSpec = struct {
            prop_id: u32,
            name_sid: u32,
            wire: []const u8,
            ty: u32,
            optional: bool,
            readonly: bool,
            jsdoc: @TypeOf(@as(*const anyopaque, undefined)),
        };

        const RawObjectPropItem = struct {
            name_sid: u32,
            wire: []const u8,
            ty: u32,
            optional: bool,
            readonly: bool,
            source_prop_id: u32,
        };

        fn typeHasNarrowerLiteralInfo(self: *Self, ty_id: u32, depth: usize) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len or depth > 6) return false;
            if ((try self.extractClosedLiteralFromType(ty_id, 0)) != null) return true;
            const tn = self.graph.types[ty_id];
            if (tn.kind == .union_type) {
                for (tn.kind.union_type) |aid| {
                    if (aid < self.graph.types.len) {
                        const ak = self.graph.types[aid].kind;
                        if (ak == .never_type) continue;
                        if ((try self.extractClosedLiteralFromType(aid, 0)) == null) return false;
                    }
                }
                return tn.kind.union_type.len > 0;
            }
            return false;
        }

        fn mergePropIntoList(
            self: *Self,
            list: *std.ArrayList(RawObjectPropItem),
            item: RawObjectPropItem,
        ) error{OutOfMemory}!void {
            for (list.items) |*existing| {
                if (std.mem.eql(u8, existing.wire, item.wire)) {
                    existing.optional = existing.optional and item.optional;
                    existing.readonly = existing.readonly and item.readonly;
                    const item_narrow = try self.typeHasNarrowerLiteralInfo(item.ty, 0);
                    const exist_narrow = try self.typeHasNarrowerLiteralInfo(existing.ty, 0);
                    if (item_narrow and !exist_narrow) {
                        existing.ty = item.ty;
                        existing.source_prop_id = item.source_prop_id;
                    } else if (!exist_narrow) {
                        existing.ty = item.ty;
                        existing.source_prop_id = item.source_prop_id;
                    }
                    return;
                }
            }
            try list.append(self.scratch, item);
        }

        fn collectObjectArmProps(
            self: *Self,
            ty_id: u32,
            allow_class_decl: bool,
            out: *std.ArrayList(RawObjectPropItem),
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len or depth > 8) return false;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .object_literal => |obj| {
                    if (obj.call_signatures.len > 0 or obj.construct_signatures.len > 0) return false;
                    if (!allow_class_decl and self.classifyObjectLiteral(obj).kind == .handle_wrapper) return false;
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.computed_symbol != null) return false;
                        if (p.modifiers.method_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.modifiers.static_mod) continue;
                        try self.mergePropIntoList(out, .{
                            .name_sid = p.name,
                            .wire = self.str(p.name),
                            .ty = p.ty,
                            .optional = p.modifiers.optional_mod,
                            .readonly = p.modifiers.readonly_mod,
                            .source_prop_id = pid,
                        });
                    }
                    return true;
                },
                .intersection => |parts| {
                    if (parts.len == 0) return false;
                    for (parts) |pid| {
                        if (!try self.collectObjectArmProps(pid, allow_class_decl, out, depth + 1)) return false;
                    }
                    return true;
                },
                .reference => |ref| {
                    if (self.isBuiltinMappedReference(self.str(ref.target_name), ref.type_args.len, ref.target_decl)) return false;
                    const rname = self.str(ref.target_name);
                    if (self.classifyBuiltinProtocolReference(rname, ref.target_decl) != null) return false;
                    if (std.mem.eql(u8, rname, "Array") or std.mem.eql(u8, rname, "ReadonlyArray") or
                        std.mem.eql(u8, rname, "Promise") or std.mem.eql(u8, rname, "PromiseLike") or
                        std.mem.eql(u8, rname, "Map") or std.mem.eql(u8, rname, "ReadonlyMap") or
                        std.mem.eql(u8, rname, "Set") or std.mem.eql(u8, rname, "ReadonlySet"))
                    {
                        return false;
                    }
                    if (ref.target_decl) |td| {
                        if (td >= self.graph.decls.len) return false;
                        const d = self.graph.decls[td];
                        // For generic references (`Box<T>`), only inspect when 0 type args or resolved_type is concrete (closed).
                        if (d.type_params.len > 0 and ref.type_args.len > 0) {
                            if (d.kind == .type_alias_decl) {
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id and (try self.isClosedTypeSubgraph(ty_id))) {
                                        return self.collectObjectArmProps(rt, allow_class_decl, out, depth + 1);
                                    }
                                }
                            }
                            return false;
                        }
                        switch (d.kind) {
                            .interface_decl => |iface| {
                                if (iface.call_signatures.len > 0 or iface.construct_signatures.len > 0) return false;
                                if (!allow_class_decl and (try self.classifyDecl(td)).kind == .handle_wrapper) {
                                    return false;
                                }
                                for (iface.extends_clauses) |hc| {
                                    _ = try self.collectObjectArmProps(hc.target_type, allow_class_decl, out, depth + 1);
                                }
                                for (iface.properties) |pid| {
                                    if (pid >= self.graph.properties.len) continue;
                                    const p = self.graph.properties[pid];
                                    if (p.modifiers.private_mod or p.modifiers.protected_mod or p.modifiers.static_mod) continue;
                                    try self.mergePropIntoList(out, .{
                                        .name_sid = p.name,
                                        .wire = self.str(p.name),
                                        .ty = p.ty,
                                        .optional = p.modifiers.optional_mod,
                                        .readonly = p.modifiers.readonly_mod,
                                        .source_prop_id = pid,
                                    });
                                }
                                return true;
                            },
                            .class_decl => |cls| {
                                if (!allow_class_decl) return false;
                                if (cls.extends_clause) |hc| {
                                    _ = try self.collectObjectArmProps(hc.target_type, allow_class_decl, out, depth + 1);
                                }
                                for (cls.implements_clauses) |hc| {
                                    _ = try self.collectObjectArmProps(hc.target_type, allow_class_decl, out, depth + 1);
                                }
                                for (cls.properties) |pid| {
                                    if (pid >= self.graph.properties.len) continue;
                                    const p = self.graph.properties[pid];
                                    if (p.modifiers.private_mod or p.modifiers.protected_mod or p.modifiers.static_mod) continue;
                                    try self.mergePropIntoList(out, .{
                                        .name_sid = p.name,
                                        .wire = self.str(p.name),
                                        .ty = p.ty,
                                        .optional = p.modifiers.optional_mod,
                                        .readonly = p.modifiers.readonly_mod,
                                        .source_prop_id = pid,
                                    });
                                }
                                return true;
                            },
                            .type_alias_decl => |alias_ty| {
                                return self.collectObjectArmProps(alias_ty, allow_class_decl, out, depth + 1);
                            },
                            else => return false,
                        }
                    } else if (tn.resolved_type) |rt| {
                        if (rt != ty_id) return self.collectObjectArmProps(rt, allow_class_decl, out, depth + 1);
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn lowerMergedRawProps(
            self: *Self,
            raw_props: []const RawObjectPropItem,
            field_scope: *naming.ScopeNamer,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}![]FieldIr {
            var list: std.ArrayList(FieldIr) = .empty;
            errdefer list.deinit(self.alloc);

            for (raw_props) |rp| {
                const bound = try field_scope.bind(rp.wire, .snake);
                const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                const logical = try self.alloc.dupe(u8, bound.logical_name);
                const wire_copy = try self.alloc.dupe(u8, bound.wire_name);
                bound.deinit(self.scratch);

                var f_ty = try self.lowerType(rp.ty, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                var lit_constraint: ?FieldLiteralConstraintIr = null;
                if (rp.optional) {
                    f_ty = try self.wrapOptional(f_ty);
                } else {
                    lit_constraint = try self.extractCompatibleFieldLiteralConstraint(rp.ty, f_ty);
                }
                const jsdoc = if (rp.source_prop_id < self.graph.properties.len)
                    try self.lowerJsDoc(self.graph.properties[rp.source_prop_id].jsdoc)
                else
                    null;

                try list.append(self.alloc, .{
                    .zig_ident = zig_ident,
                    .logical_name = logical,
                    .wire_name = wire_copy,
                    .ty = f_ty,
                    .is_optional = rp.optional,
                    .is_readonly = rp.readonly,
                    .nullish_kind = if (f_ty.* == .optional) f_ty.optional.nullish_kind else .none,
                    .literal_constraint = lit_constraint,
                    .jsdoc = jsdoc,
                });
            }
            return try list.toOwnedSlice(self.alloc);
        }

        fn typeArmHasOpenDynamicKeys(
            self: *const Self,
            arm_id: u32,
            active_tps: []const ActiveTypeParam,
            depth: usize,
        ) bool {
            if (active_tps.len == 0 or arm_id >= self.graph.types.len or depth >= 12) return false;
            if (!self.typeTreeMentionsActiveTypeParam(arm_id, active_tps, &.{}, 0)) return false;
            const tn = self.graph.types[arm_id];
            return switch (tn.kind) {
                .type_param,
                .mapped,
                .indexed_access,
                .conditional,
                .keyof_type,
                => true,
                .intersection => |parts| blk: {
                    for (parts) |pid| {
                        if (self.typeArmHasOpenDynamicKeys(pid, active_tps, depth + 1)) break :blk true;
                    }
                    break :blk false;
                },
                .reference => |ref| blk: {
                    const rname = self.str(ref.target_name);
                    if (type_ops.classifyBuiltinUtility(rname, ref.type_args.len) != null) break :blk true;
                    if (self.isBuiltinMappedReference(rname, ref.type_args.len, ref.target_decl)) break :blk true;
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const bd = self.graph.decls[td];
                            if (bd.kind == .type_alias_decl and bd.type_params.len > 0) {
                                // Check whether the target generic alias's body has open dynamic keys
                                // with respect to its own type parameters.
                                var stack_buf: [8]ActiveTypeParam = undefined;
                                const n_tps = @min(bd.type_params.len, stack_buf.len);
                                for (0..n_tps) |ti| {
                                    const tp_id = bd.type_params[ti];
                                    const tp_name = if (tp_id < self.graph.type_params.len)
                                        self.str(self.graph.type_params[tp_id].name)
                                    else
                                        "";
                                    stack_buf[ti] = .{ .ts_name = tp_name };
                                }
                                break :blk self.typeArmHasOpenDynamicKeys(bd.kind.type_alias_decl, stack_buf[0..n_tps], depth + 1);
                            }
                        }
                    }
                    break :blk false;
                },
                else => false,
            };
        }

        fn lowerIntersectionInline(
            self: *Self,
            ty_id: u32,
            parts: []const u32,
            ref_cnt: u32,
            can_hoist_in_mod: bool,
            no_free_vars: bool,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            if (self.detectOpenPrimitiveIntersection(parts)) |opk| {
                return switch (opk) {
                    .str => self.makeType(.string_type),
                    .num => self.makeType(.f64_type),
                    .bigint => self.makeType(.i64_type),
                };
            }
            if (self.detectBrandedPrimitiveIntersection(parts, 0)) |bpk| {
                return switch (bpk) {
                    .str => self.makeType(.string_type),
                    .num => self.makeType(.f64_type),
                    .bigint => self.makeType(.i64_type),
                    .boolean => self.makeType(.bool_type),
                    .symbol => blk: {
                        needs_runtime.* = true;
                        break :blk self.makeType(.js_symbol);
                    },
                };
            }

            const inter_cls = try self.classifyObjectType(ty_id);
            if (!no_free_vars and parts.len >= 2 and parts.len <= 16 and self.inline_anon_depth < 3) {
                var has_open_dynamic_arm = false;
                for (parts) |pid| {
                    if (self.typeArmHasOpenDynamicKeys(pid, active_tps, 0)) {
                        has_open_dynamic_arm = true;
                        break;
                    }
                }
                if (has_open_dynamic_arm) {
                    var lowered_arms = try self.alloc.alloc(*const TypeIr, parts.len);
                    self.inline_anon_depth += 1;
                    defer self.inline_anon_depth -= 1;
                    var degraded_handle_arm = false;
                    for (parts, 0..) |pid, ai| {
                        lowered_arms[ai] = try self.lowerType(pid, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        if (inter_cls.kind == .handle_wrapper and lowered_arms[ai].* == .js_object) {
                            degraded_handle_arm = true;
                        }
                    }
                    if (!degraded_handle_arm) {
                        needs_runtime.* = true;
                        return self.makeType(.{ .intersect_op = lowered_arms });
                    }
                }
            }

            var merged_props: std.ArrayList(RawObjectPropItem) = .empty;
            defer merged_props.deinit(self.scratch);
            if (try self.collectObjectArmProps(ty_id, false, &merged_props, 0) and merged_props.items.len > 0) {
                if (ref_cnt > 1 and can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                    const h = try self.allocFreshAnonHelperName("__zigar_AnonObj", active_tps);
                    const hloc = DeclLocation{
                        .module_index = self.cur_mod_idx,
                        .zig_path = h.path,
                        .type_param_defaults = &.{},
                    };
                    try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);

                    var anon_scope = naming.ScopeNamer.initContainer(self.scratch, null);
                    defer anon_scope.deinit();
                    try anon_scope.reserve("zigar_js");

                    var fresh_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer fresh_visited.deinit(self.scratch);
                    const saved_depth = self.inline_anon_depth;
                    self.inline_anon_depth = 0;
                    defer self.inline_anon_depth = saved_depth;

                    const fields = try self.lowerMergedRawProps(
                        merged_props.items,
                        &anon_scope,
                        &.{},
                        null,
                        &fresh_visited,
                        imports_used,
                        needs_runtime,
                    );
                    const target_ty = try self.makeType(.{ .anon_struct = fields });
                    try self.cur_mod_decls_out.?.append(self.alloc, .{
                        .source_decl_id = null,
                        .zig_ident = h.zig_ident,
                        .logical_name = h.logical,
                        .wire_name = h.logical,
                        .is_exported = false,
                        .is_js_exported = false,
                        .is_default_export = false,
                        .jsdoc = null,
                        .kind = .{ .type_alias = .{ .type_params = &.{}, .target = target_ty } },
                    });
                    return self.makeHoistedDeclRef(hloc);
                }

                if (self.inline_anon_depth >= 3 or merged_props.items.len > 48) {
                    needs_runtime.* = true;
                    return self.makeType(.js_object);
                }

                var anon_scope = naming.ScopeNamer.initContainer(self.scratch, null);
                defer anon_scope.deinit();
                try anon_scope.reserve("zigar_js");
                self.inline_anon_depth += 1;
                defer self.inline_anon_depth -= 1;

                const fields = try self.lowerMergedRawProps(
                    merged_props.items,
                    &anon_scope,
                    active_tps,
                    self_ident_opt,
                    visited,
                    imports_used,
                    needs_runtime,
                );
                return self.makeType(.{ .anon_struct = fields });
            }

            if (inter_cls.kind == .handle_wrapper) {
                var inter_props: std.ArrayList(SourcedProp) = .empty;
                defer inter_props.deinit(self.scratch);
                var inter_methods: std.ArrayList(SourcedMethod) = .empty;
                defer inter_methods.deinit(self.scratch);
                var inter_calls: std.ArrayList(SourcedSig) = .empty;
                defer inter_calls.deinit(self.scratch);
                var inter_ctors: std.ArrayList(SourcedSig) = .empty;
                defer inter_ctors.deinit(self.scratch);
                var inter_index_sigs: std.ArrayList(SourcedIndexSig) = .empty;
                defer inter_index_sigs.deinit(self.scratch);

                if (try self.collectObjectIntersectionMembers(
                    ty_id,
                    &inter_props,
                    &inter_methods,
                    &inter_calls,
                    &inter_ctors,
                    &inter_index_sigs,
                ) and (inter_props.items.len > 0 or inter_methods.items.len > 0 or
                    inter_calls.items.len > 0 or inter_ctors.items.len > 0 or
                    inter_index_sigs.items.len > 0 or self.hasProtocolInGraphTypes(parts, 0)))
                {
                    const is_closed = no_free_vars or try self.isClosedTypeSubgraph(ty_id);
                    if (can_hoist_in_mod and is_closed and self.cur_mod_root_scope != null) {
                        const h = try self.allocFreshAnonHelperName("__zigar_AnonHandle", active_tps);
                        const hloc = DeclLocation{
                            .module_index = self.cur_mod_idx,
                            .zig_path = h.path,
                            .type_param_defaults = &.{},
                        };
                        try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);

                        var empty_names: std.AutoHashMapUnmanaged(u32, naming.BoundName) = .empty;
                        var empty_ovs: std.AutoHashMapUnmanaged(u32, []naming.BoundName) = .empty;
                        var empty_active: std.AutoHashMapUnmanaged(u32, void) = .empty;
                        defer empty_active.deinit(self.scratch);

                        const saved_depth = self.inline_anon_depth;
                        self.inline_anon_depth = 0;
                        defer self.inline_anon_depth = saved_depth;

                        const sourced_bases = try self.wrapUnsourcedBases(parts);
                        const struct_ir = try self.lowerStructDecl(
                            self.cur_mod_idx,
                            std.math.maxInt(u32),
                            inter_cls,
                            false,
                            false,
                            &.{},
                            &.{},
                            &.{},
                            inter_props.items,
                            &.{},
                            inter_methods.items,
                            inter_calls.items,
                            inter_ctors.items,
                            inter_index_sigs.items,
                            sourced_bases,
                            &.{},
                            self.cur_mod_root_scope.?,
                            &empty_names,
                            &empty_ovs,
                            &.{},
                            imports_used,
                            needs_runtime,
                            &empty_active,
                        );
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{ .struct_decl = struct_ir },
                        });
                        return self.makeHoistedDeclRef(hloc);
                    }
                    if (parts.len >= 2 and parts.len <= 16 and self.inline_anon_depth < 3) {
                        var lowered_arms = try self.alloc.alloc(*const TypeIr, parts.len);
                        self.inline_anon_depth += 1;
                        defer self.inline_anon_depth -= 1;
                        var degraded_handle_arm = false;
                        for (parts, 0..) |pid, ai| {
                            lowered_arms[ai] = try self.lowerType(pid, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                            if (lowered_arms[ai].* == .js_object) {
                                degraded_handle_arm = true;
                            }
                        }
                        if (!degraded_handle_arm) {
                            needs_runtime.* = true;
                            return self.makeType(.{ .intersect_op = lowered_arms });
                        }
                    }
                    needs_runtime.* = true;
                    return self.makeType(if (inter_cls.is_callable_handle) .js_function else .js_object);
                }
            }

            if (ty_id < self.graph.types.len) {
                if (self.graph.types[ty_id].resolved_type) |rt| {
                    if (rt != ty_id and rt < self.graph.types.len and self.graph.types[rt].kind == .object_literal) {
                        var safe_to_follow = true;
                        for (parts) |pid| {
                            if (pid < self.graph.types.len and self.graph.types[pid].kind == .reference) {
                                if (self.graph.types[pid].kind.reference.target_decl) |td| {
                                    if (self.lookupDeclLocation(td) == null and
                                        (td >= self.graph.decls.len or self.graph.decls[td].kind != .type_alias_decl))
                                    {
                                        safe_to_follow = false;
                                        break;
                                    }
                                }
                            }
                        }
                        if (safe_to_follow) {
                            return self.lowerType(rt, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                        }
                    }
                }
            }

            needs_runtime.* = true;
            return self.makeType(.js_value);
        }

        fn collectFlattenedUnionArms(
            self: *const Self,
            arms: []const u32,
            non_null: *std.ArrayList(u32),
            nullish: *lower_types.NullishKind,
            depth: usize,
        ) error{OutOfMemory}!void {
            if (depth > 8) return;
            for (arms) |arm_id| {
                if (arm_id >= self.graph.types.len) continue;
                switch (self.graph.types[arm_id].kind) {
                    .null_type => nullish.* = nullish.merge(.null_only),
                    .undefined_type, .void_type => nullish.* = nullish.merge(.undefined_only),
                    .never_type => {},
                    .union_type => |sub_arms| try self.collectFlattenedUnionArms(sub_arms, non_null, nullish, depth + 1),
                    else => try non_null.append(self.scratch, arm_id),
                }
            }
        }

        fn closedLiteralToEnumValue(self: *Self, clv: lower_unions.ClosedLiteralValue) error{OutOfMemory}!EnumValueIr {
            return switch (clv) {
                .str => |s| .{ .str = try self.alloc.dupe(u8, s) },
                .num => |n| .{ .num = n },
                .boolean => |b| .{ .boolean = b },
                .bigint_val => |bi| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, bi) },
            };
        }

        const ClosedLiteralItem = struct {
            val: lower_unions.ClosedLiteralValue,
            member_name: ?[]const u8 = null,
        };

        fn buildEnumMembersFromClosedLiteralItems(
            self: *Self,
            items: []const ClosedLiteralItem,
        ) error{OutOfMemory}!InlineEnumIr {
            var vals = try self.scratch.alloc(lower_unions.ClosedLiteralValue, items.len);
            defer self.scratch.free(vals);
            for (items, 0..) |it, idx| vals[idx] = it.val;

            const analysis = try lower_unions.analyzeClosedEnumValues(self.scratch, vals);
            defer analysis.deinit(self.scratch);

            var tag_scope = naming.ScopeNamer.init(self.scratch, null);
            defer tag_scope.deinit();
            try tag_scope.reserve("zigar_js");

            var members = try self.alloc.alloc(EnumMemberIr, items.len);
            for (items, 0..) |item, idx| {
                const v = item.val;
                const fmt_hint = if (item.member_name == null)
                    try lower_unions.formatLiteralTagHint(self.scratch, v)
                else
                    null;
                defer if (fmt_hint) |fh| self.scratch.free(fh);
                const hint = item.member_name orelse fmt_hint.?;
                const bound = try tag_scope.bind(hint, .snake);
                const wire_str: []const u8 = switch (v) {
                    .str => |s| try self.alloc.dupe(u8, s),
                    else => if (item.member_name) |mname|
                        try self.alloc.dupe(u8, mname)
                    else
                        try self.alloc.dupe(u8, bound.logical_name),
                };
                members[idx] = .{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_name = wire_str,
                    .value = try self.closedLiteralToEnumValue(v),
                    .int_backing_val = analysis.layouts[idx].int_tag_value,
                    .alias_of_zig_ident = if (analysis.layouts[idx].alias_of_index) |pidx| members[pidx].zig_ident else null,
                    .alias_of_logical_name = if (analysis.layouts[idx].alias_of_index) |pidx| members[pidx].logical_name else null,
                    .jsdoc = null,
                };
                bound.deinit(self.scratch);
            }
            return .{ .backing = analysis.backing, .members = members };
        }

        fn buildEnumMembersFromClosedLiterals(
            self: *Self,
            vals: []const lower_unions.ClosedLiteralValue,
        ) error{OutOfMemory}!InlineEnumIr {
            var items = try self.scratch.alloc(ClosedLiteralItem, vals.len);
            defer self.scratch.free(items);
            for (vals, 0..) |v, idx| items[idx] = .{ .val = v };
            return self.buildEnumMembersFromClosedLiteralItems(items);
        }

        fn appendUniqueClosedLiteral(
            self: *Self,
            list: *std.ArrayList(lower_unions.ClosedLiteralValue),
            val: lower_unions.ClosedLiteralValue,
        ) error{OutOfMemory}!void {
            for (list.items) |existing| {
                if (lower_unions.closedLiteralEql(existing, val)) return;
            }
            try list.append(self.scratch, val);
        }

        fn appendUniqueClosedLiteralItem(
            self: *Self,
            list: *std.ArrayList(ClosedLiteralItem),
            item: ClosedLiteralItem,
        ) error{OutOfMemory}!void {
            for (list.items) |*existing| {
                if (lower_unions.closedLiteralEql(existing.val, item.val)) {
                    if (existing.member_name == null and item.member_name != null) {
                        existing.member_name = item.member_name;
                    }
                    return;
                }
            }
            try list.append(self.scratch, item);
        }

        fn enumMemberClosedLiteralItem(
            self: *Self,
            em: anytype,
        ) error{OutOfMemory}!?ClosedLiteralItem {
            const clv: lower_unions.ClosedLiteralValue = switch (em.value) {
                .str => |s| .{ .str = s },
                .num => |n| .{ .num = n },
                .boolean => |b| .{ .boolean = b },
                .bigint_val => |bi| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, bi) },
                .unknown => return null,
            };
            var mname_opt: ?[]const u8 = null;
            if (em.enum_decl_id < self.graph.decls.len) {
                const ed = self.graph.decls[em.enum_decl_id];
                if (ed.kind == .enum_decl and em.member_idx < ed.kind.enum_decl.members.len) {
                    const raw_mname = self.str(ed.kind.enum_decl.members[em.member_idx].name);
                    if (raw_mname.len > 0) mname_opt = raw_mname;
                }
            }
            return .{ .val = clv, .member_name = mname_opt };
        }

        fn lowerGenericTypeArg(
            self: *Self,
            arg_ty_id: u32,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            if (self.cur_mod_decls_out != null and self.cur_mod_root_scope != null) {
                if (try self.resolveEnumMemberReference(arg_ty_id)) |em| {
                    if (try self.enumMemberClosedLiteralItem(em)) |item| {
                        const cache_key: u64 = (@as(u64, em.enum_decl_id) << 32) | @as(u64, @intCast(em.member_idx));
                        if (self.cur_mod_enum_member_types.get(cache_key)) |cached_loc| {
                            return self.makeHoistedDeclRef(cached_loc);
                        }
                        const enum_ir = try self.buildEnumMembersFromClosedLiteralItems(&.{item});
                        const h = try self.allocFreshAnonHelperName("__zigar_EnumMember", active_tps);
                        const hloc = DeclLocation{
                            .module_index = self.cur_mod_idx,
                            .zig_path = h.path,
                            .type_param_defaults = &.{},
                        };
                        try self.cur_mod_enum_member_types.put(self.scratch, cache_key, hloc);
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{ .literal_enum_decl = enum_ir },
                        });
                        return self.makeHoistedDeclRef(hloc);
                    }
                }
                if (arg_ty_id < self.graph.types.len and self.graph.types[arg_ty_id].kind == .literal) {
                    if (try self.extractClosedLiteralFromType(arg_ty_id, 0)) |clv| {
                        if (clv == .str or clv == .num) {
                            const cache_key = switch (clv) {
                                .str => |s| try std.fmt.allocPrint(self.scratch, "s:{s}", .{s}),
                                .num => |n| try std.fmt.allocPrint(self.scratch, "n:{x}", .{@as(u64, @bitCast(if (n == 0.0) @as(f64, 0.0) else n))}),
                                else => unreachable,
                            };
                            if (self.cur_mod_unit_literal_types.get(cache_key)) |cached_loc| {
                                return self.makeHoistedDeclRef(cached_loc);
                            }
                            const enum_ir = try self.buildEnumMembersFromClosedLiteralItems(&.{.{ .val = clv }});
                            const h = try self.allocFreshAnonHelperName("__zigar_UnitLit", active_tps);
                            const hloc = DeclLocation{
                                .module_index = self.cur_mod_idx,
                                .zig_path = h.path,
                                .type_param_defaults = &.{},
                            };
                            try self.cur_mod_unit_literal_types.put(self.scratch, cache_key, hloc);
                            try self.cur_mod_decls_out.?.append(self.alloc, .{
                                .source_decl_id = null,
                                .zig_ident = h.zig_ident,
                                .logical_name = h.logical,
                                .wire_name = h.logical,
                                .is_exported = false,
                                .is_js_exported = false,
                                .is_default_export = false,
                                .jsdoc = null,
                                .kind = .{ .literal_enum_decl = enum_ir },
                            });
                            return self.makeHoistedDeclRef(hloc);
                        }
                    }
                }
            }
            return self.lowerType(arg_ty_id, false, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
        }

        fn tryCollectClosedLiteralsFromArm(
            self: *Self,
            arm_id: u32,
            out: *std.ArrayList(ClosedLiteralItem),
            expand_alias_refs: bool,
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (arm_id >= self.graph.types.len or depth > 12) return false;
            const tn = self.graph.types[arm_id];
            switch (tn.kind) {
                .literal => {
                    if (try self.extractClosedLiteralFromType(arm_id, 0)) |clv| {
                        try self.appendUniqueClosedLiteralItem(out, .{ .val = clv });
                        return out.items.len <= 512;
                    }
                    return false;
                },
                .template_literal => {
                    var strs: std.ArrayList([]const u8) = .empty;
                    defer strs.deinit(self.alloc);
                    if (!try self.tryExpandFiniteStringSet(arm_id, &strs, 0)) return false;
                    for (strs.items) |s| {
                        try self.appendUniqueClosedLiteralItem(out, .{ .val = .{ .str = s } });
                        if (out.items.len > 512) return false;
                    }
                    return true;
                },
                .intrinsic => {
                    if (tn.resolved_type) |rt| {
                        if (rt != arm_id) return self.tryCollectClosedLiteralsFromArm(rt, out, expand_alias_refs, depth + 1);
                    }
                    return false;
                },
                .union_type => |sub_arms| {
                    for (sub_arms) |sa| {
                        if (sa < self.graph.types.len and self.graph.types[sa].kind == .never_type) continue;
                        if (!try self.tryCollectClosedLiteralsFromArm(sa, out, expand_alias_refs, depth + 1)) return false;
                    }
                    return true;
                },
                .reference => |ref| {
                    if (try self.resolveEnumMemberReference(arm_id)) |em| {
                        const item = (try self.enumMemberClosedLiteralItem(em)) orelse return false;
                        try self.appendUniqueClosedLiteralItem(out, item);
                        return out.items.len <= 512;
                    }
                    if (expand_alias_refs) {
                        if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len and ref.type_args.len == 0) {
                                const d = self.graph.decls[td];
                                if (d.kind == .type_alias_decl and d.type_params.len == 0) {
                                    return self.tryCollectClosedLiteralsFromArm(d.kind.type_alias_decl, out, true, depth + 1);
                                }
                            }
                        } else if (tn.resolved_type) |rt| {
                            if (rt != arm_id) return self.tryCollectClosedLiteralsFromArm(rt, out, true, depth + 1);
                        }
                    } else if (ref.target_decl == null) {
                        if (tn.resolved_type) |rt| {
                            if (rt != arm_id) return self.tryCollectClosedLiteralsFromArm(rt, out, false, depth + 1);
                        }
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn isExactBooleanPairItems(items: []const ClosedLiteralItem) bool {
            if (items.len != 2) return false;
            if (items[0].val != .boolean or items[1].val != .boolean) return false;
            return items[0].val.boolean != items[1].val.boolean;
        }

        fn tryBuildClosedLiteralEnum(
            self: *Self,
            non_null_arms: []const u32,
        ) error{OutOfMemory}!?InlineEnumIr {
            if (non_null_arms.len == 0) return null;
            var items: std.ArrayList(ClosedLiteralItem) = .empty;
            defer items.deinit(self.scratch);
            for (non_null_arms) |aid| {
                if (!try self.tryCollectClosedLiteralsFromArm(aid, &items, true, 0)) return null;
            }
            if (items.items.len < 2) return null;
            if (isExactBooleanPairItems(items.items)) return null;
            return try self.buildEnumMembersFromClosedLiteralItems(items.items);
        }

        fn tryBuildOpenLiteralUnion(
            self: *Self,
            non_null_arms: []const u32,
        ) error{OutOfMemory}!?OpenLiteralUnionIr {
            if (non_null_arms.len < 2) return null;
            var open_prim_opt: ?lower_unions.OpenPrimitiveKind = null;
            var vals: std.ArrayList(ClosedLiteralItem) = .empty;
            defer vals.deinit(self.scratch);

            for (non_null_arms) |aid| {
                if (aid >= self.graph.types.len) return null;
                const tn = self.graph.types[aid];
                if (tn.kind == .intersection) {
                    if (self.detectOpenPrimitiveIntersection(tn.kind.intersection)) |opk| {
                        if (open_prim_opt != null and open_prim_opt.? != opk) return null;
                        open_prim_opt = opk;
                        continue;
                    }
                }
                if (!try self.tryCollectClosedLiteralsFromArm(aid, &vals, true, 0)) return null;
            }

            const open_prim = open_prim_opt orelse return null;
            if (vals.items.len == 0 or vals.items.len > 128) return null;

            for (vals.items) |item| {
                const v = item.val;
                const matches_prim = switch (open_prim) {
                    .str => v == .str,
                    .num => v == .num,
                    .bigint => blk: {
                        if (v != .bigint_val) break :blk false;
                        _ = std.fmt.parseInt(i64, v.bigint_val, 0) catch break :blk false;
                        break :blk true;
                    },
                };
                if (!matches_prim) return null;
            }

            var tag_scope = naming.ScopeNamer.init(self.scratch, null);
            defer tag_scope.deinit();
            try tag_scope.reserve("zigar_js");

            var known_members = try self.alloc.alloc(EnumMemberIr, vals.items.len);
            for (vals.items, 0..) |item, idx| {
                const v = item.val;
                const fmt_hint = if (item.member_name == null)
                    try lower_unions.formatLiteralTagHint(self.scratch, v)
                else
                    null;
                defer if (fmt_hint) |fh| self.scratch.free(fh);
                const hint = item.member_name orelse fmt_hint.?;
                const bound = try tag_scope.bind(hint, .snake);
                const wire_str: []const u8 = switch (v) {
                    .str => |s| try self.alloc.dupe(u8, s),
                    else => if (item.member_name) |mname|
                        try self.alloc.dupe(u8, mname)
                    else
                        try self.alloc.dupe(u8, bound.logical_name),
                };
                known_members[idx] = .{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_name = wire_str,
                    .value = try self.closedLiteralToEnumValue(v),
                    .jsdoc = null,
                };
                bound.deinit(self.scratch);
            }

            const custom_bound = try tag_scope.bind("custom", .snake);
            const custom_ident = try self.alloc.dupe(u8, custom_bound.zig_ident);
            const custom_logical = try self.alloc.dupe(u8, custom_bound.logical_name);
            custom_bound.deinit(self.scratch);

            const custom_payload = switch (open_prim) {
                .str => try self.makeType(.string_type),
                .num => try self.makeType(.f64_type),
                .bigint => try self.makeType(.i64_type),
            };

            return .{
                .base_kind = open_prim,
                .known_members = known_members,
                .custom_tag_ident = custom_ident,
                .custom_logical_name = custom_logical,
                .custom_payload = custom_payload,
            };
        }

        fn fieldConstraintEql(a: ?FieldLiteralConstraintIr, b: ?FieldLiteralConstraintIr) bool {
            if (a == null and b == null) return true;
            if (a == null or b == null) return false;
            const va = a.?;
            const vb = b.?;
            if (@as(std.meta.Tag(FieldLiteralConstraintIr), va) != @as(std.meta.Tag(FieldLiteralConstraintIr), vb)) return false;
            return switch (va) {
                .str => |sa| std.mem.eql(u8, sa, vb.str),
                .num => |na| na == vb.num,
                .boolean => |ba| ba == vb.boolean,
                .bigint_val => |bia| std.mem.eql(u8, bia, vb.bigint_val),
                .enum_member => |ema| ema.enum_decl_id == vb.enum_member.enum_decl_id and
                    std.mem.eql(u8, ema.tag_logical_name, vb.enum_member.tag_logical_name),
            };
        }

        fn keyFilterSpecEql(a: KeyFilterSpecIr, b: KeyFilterSpecIr, depth: usize) bool {
            if (@as(std.meta.Tag(KeyFilterSpecIr), a) != @as(std.meta.Tag(KeyFilterSpecIr), b)) return false;
            return switch (a) {
                .str_lit => |sa| std.mem.eql(u8, sa, b.str_lit),
                .str_list => |la| blk: {
                    const lb = b.str_list;
                    if (la.len != lb.len) break :blk false;
                    for (la, lb) |xa, xb| {
                        if (!std.mem.eql(u8, xa, xb)) break :blk false;
                    }
                    break :blk true;
                },
                .ty => |ta| typeIrEql(ta, b.ty, depth + 1),
            };
        }

        fn indexAccessSpecEql(a: IndexAccessSpecIr, b: IndexAccessSpecIr, depth: usize) bool {
            if (@as(std.meta.Tag(IndexAccessSpecIr), a) != @as(std.meta.Tag(IndexAccessSpecIr), b)) return false;
            return switch (a) {
                .str_lit => |sa| std.mem.eql(u8, sa, b.str_lit),
                .str_list => |la| blk: {
                    const lb = b.str_list;
                    if (la.len != lb.len) break :blk false;
                    for (la, lb) |xa, xb| {
                        if (!std.mem.eql(u8, xa, xb)) break :blk false;
                    }
                    break :blk true;
                },
                .int_lit => |ia| ia == b.int_lit,
                .ty => |ta| typeIrEql(ta, b.ty, depth + 1),
            };
        }

        fn typeIrEql(a: *const TypeIr, b: *const TypeIr, depth: usize) bool {
            if (a == b) return true;
            if (depth > 8) return false;
            if (@as(std.meta.Tag(TypeIr), a.*) != @as(std.meta.Tag(TypeIr), b.*)) return false;
            return switch (a.*) {
                .void_type,
                .noreturn_type,
                .bool_type,
                .f64_type,
                .i64_type,
                .string_type,
                .bytes_type,
                .js_value,
                .js_any,
                .js_unknown,
                .js_object,
                .js_function,
                .js_symbol,
                .js_bigint,
                .js_string,
                .js_date,
                .js_regexp,
                .js_disposable,
                .js_async_disposable,
                => true,
                .typed_slice => |pa| pa == b.typed_slice,
                .binary_view => |ba| ba == b.binary_view,
                .self_type => |sa| std.mem.eql(u8, sa, b.self_type),
                .type_param_ref => |ta| std.mem.eql(u8, ta, b.type_param_ref),
                .optional => |oa| oa.nullish_kind == b.optional.nullish_kind and oa.is_pure_nullish == b.optional.is_pure_nullish and typeIrEql(oa.child, b.optional.child, depth + 1),
                .pointer_const => |ia| typeIrEql(ia, b.pointer_const, depth + 1),
                .slice => |sa| typeIrEql(sa, b.slice, depth + 1),
                .promise => |pa| typeIrEql(pa, b.promise, depth + 1),
                .js_iterator => |ia| typeIrEql(ia, b.js_iterator, depth + 1),
                .js_async_iterator => |ia| typeIrEql(ia, b.js_async_iterator, depth + 1),
                .js_map => |ma| typeIrEql(ma.key, b.js_map.key, depth + 1) and typeIrEql(ma.value, b.js_map.value, depth + 1),
                .js_record => |ra| typeIrEql(ra.key, b.js_record.key, depth + 1) and typeIrEql(ra.value, b.js_record.value, depth + 1),
                .mapped_values_op => |ma| typeIrEql(ma.target, b.mapped_values_op.target, depth + 1) and typeIrEql(ma.value, b.mapped_values_op.value, depth + 1),
                .unary_type_op => |ua| ua.op == b.unary_type_op.op and typeIrEql(ua.operand, b.unary_type_op.operand, depth + 1),
                .key_filter_op => |ka| ka.kind == b.key_filter_op.kind and typeIrEql(ka.target, b.key_filter_op.target, depth + 1) and keyFilterSpecEql(ka.keys, b.key_filter_op.keys, depth + 1),
                .index_access_op => |ia| typeIrEql(ia.object_ty, b.index_access_op.object_ty, depth + 1) and
                    indexAccessSpecEql(ia.index_spec, b.index_access_op.index_spec, depth + 1) and
                    ((ia.fallback_ty != null) == (b.index_access_op.fallback_ty != null)) and
                    (if (ia.fallback_ty) |fa| typeIrEql(fa, b.index_access_op.fallback_ty.?, depth + 1) else true),
                .empty_object_extends_op => |ea| typeIrEql(ea.target_ty, b.empty_object_extends_op.target_ty, depth + 1) and
                    typeIrEql(ea.true_ty, b.empty_object_extends_op.true_ty, depth + 1) and
                    typeIrEql(ea.false_ty, b.empty_object_extends_op.false_ty, depth + 1),
                .intersect_op => |aa| blk: {
                    const ab = b.intersect_op;
                    if (aa.len != ab.len) break :blk false;
                    for (aa, ab) |ea, eb| {
                        if (!typeIrEql(ea, eb, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                .decl_ref => |da| blk: {
                    const db = b.decl_ref;
                    if (da.module_index != db.module_index or da.target_decl_id != db.target_decl_id or da.indirect != db.indirect) break :blk false;
                    if (da.decl_zig_path.len != db.decl_zig_path.len or da.type_args.len != db.type_args.len) break :blk false;
                    for (da.decl_zig_path, db.decl_zig_path) |sa, sb| {
                        if (!std.mem.eql(u8, sa, sb)) break :blk false;
                    }
                    for (da.type_args, db.type_args) |taa, tab| {
                        if (!typeIrEql(taa, tab, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                .tuple => |ta| blk: {
                    const tb = b.tuple;
                    if (ta.len != tb.len) break :blk false;
                    for (ta, tb) |ea, eb| {
                        if (ea.is_optional != eb.is_optional or ea.is_variadic != eb.is_variadic or ea.nullish_kind != eb.nullish_kind) break :blk false;
                        if (!typeIrEql(ea.ty, eb.ty, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                .anon_struct => |fa| blk: {
                    const fb = b.anon_struct;
                    if (fa.len != fb.len) break :blk false;
                    for (fa, fb) |xa, xb| {
                        if (!std.mem.eql(u8, xa.wire_name, xb.wire_name) or xa.is_optional != xb.is_optional) break :blk false;
                        if (!fieldConstraintEql(xa.literal_constraint, xb.literal_constraint)) break :blk false;
                        if (!typeIrEql(xa.ty, xb.ty, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                .fn_ptr => |fa| blk: {
                    const fb = b.fn_ptr;
                    if ((fa.this_param != null) != (fb.this_param != null)) break :blk false;
                    if (fa.this_param) |tha| {
                        if (!typeIrEql(tha, fb.this_param.?, depth + 1)) break :blk false;
                    }
                    if (fa.params.len != fb.params.len) break :blk false;
                    for (fa.params, fb.params) |pa, pb| {
                        if (!typeIrEql(pa, pb, depth + 1)) break :blk false;
                    }
                    break :blk typeIrEql(fa.return_type, fb.return_type, depth + 1);
                },
                .template_pattern => |pa| blk: {
                    const pb = b.template_pattern;
                    if (!std.mem.eql(u8, pa.head, pb.head) or pa.spans.len != pb.spans.len) break :blk false;
                    for (pa.spans, pb.spans) |sa, sb| {
                        if (sa.placeholder != sb.placeholder or
                            !std.mem.eql(u8, sa.literal_tail, sb.literal_tail) or
                            sa.choices.len != sb.choices.len) break :blk false;
                        for (sa.choices, sb.choices) |ca, cb| {
                            if (!std.mem.eql(u8, ca, cb)) break :blk false;
                        }
                    }
                    break :blk true;
                },
                else => false,
            };
        }

        const LoweredArmEntry = struct {
            ast_arm_id: u32,
            ty: *TypeIr,
        };

        const GeneralUnionOutcome = struct {
            extra_nullish: lower_types.NullishKind = .none,
            body: union(enum) {
                single: *TypeIr,
                tagged: TaggedUnionIr,
            },
        };

        fn trySelectDiscriminantForArms(
            self: *Self,
            arms: []const LoweredArmEntry,
        ) error{OutOfMemory}!?lower_unions.SelectedDiscriminant {
            if (arms.len < 2) return null;

            var arm_prop_lists = try self.scratch.alloc([]const lower_unions.CandidateDiscProp, arms.len);
            var prop_SubSlices: std.ArrayList([]lower_unions.CandidateDiscProp) = .empty;
            var val_SubSlices: std.ArrayList([]lower_unions.ClosedLiteralValue) = .empty;
            defer {
                for (val_SubSlices.items) |s| self.scratch.free(s);
                val_SubSlices.deinit(self.scratch);
                for (prop_SubSlices.items) |s| self.scratch.free(s);
                prop_SubSlices.deinit(self.scratch);
                self.scratch.free(arm_prop_lists);
            }

            for (arms, 0..) |entry, idx| {
                // Only consider plain/class object arms for object-property discriminant dispatch.
                switch (entry.ty.*) {
                    .anon_struct, .decl_ref => {},
                    else => return null,
                }
                var raw_props: std.ArrayList(RawObjectPropItem) = .empty;
                defer raw_props.deinit(self.scratch);
                if (!try self.collectObjectArmProps(entry.ast_arm_id, true, &raw_props, 0)) return null;
                if (raw_props.items.len == 0) return null;

                var infos: std.ArrayList(lower_unions.CandidateDiscProp) = .empty;
                for (raw_props.items) |rp| {
                    if (rp.optional) continue;
                    var enum_hint_opt: ?[]const u8 = null;
                    if (try self.resolveEnumMemberReference(rp.ty)) |em| {
                        enum_hint_opt = em.tag_logical_name;
                    }
                    var lits: std.ArrayList(ClosedLiteralItem) = .empty;
                    defer lits.deinit(self.scratch);
                    if (try self.tryCollectClosedLiteralsFromArm(rp.ty, &lits, true, 0) and lits.items.len > 0) {
                        const lit_slice = try self.scratch.alloc(lower_unions.ClosedLiteralValue, lits.items.len);
                        for (lits.items, 0..) |it, li| lit_slice[li] = it.val;
                        try val_SubSlices.append(self.scratch, lit_slice);
                        try infos.append(self.scratch, .{
                            .wire_name = rp.wire,
                            .values = lit_slice,
                            .enum_member_hint = enum_hint_opt,
                        });
                    }
                }
                if (infos.items.len == 0) {
                    infos.deinit(self.scratch);
                    return null;
                }
                const info_slice = try infos.toOwnedSlice(self.scratch);
                try prop_SubSlices.append(self.scratch, info_slice);
                arm_prop_lists[idx] = info_slice;
            }

            return try lower_unions.selectDiscriminantProperty(self.alloc, arm_prop_lists);
        }

        fn buildGeneralUnionOutcome(
            self: *Self,
            non_null_arms: []const u32,
            is_return_pos: bool,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!GeneralUnionOutcome {
            var has_open_str = false;
            var has_open_num = false;
            var has_open_bigint = false;
            var has_open_bool = false;

            for (non_null_arms) |aid| {
                const k = self.graph.types[aid].kind;
                switch (k) {
                    .string_type => has_open_str = true,
                    .number_type => has_open_num = true,
                    .bigint_type => has_open_bigint = true,
                    .boolean_type => has_open_bool = true,
                    .intersection => |parts| {
                        if (self.detectOpenPrimitiveIntersection(parts)) |opk| {
                            switch (opk) {
                                .str => has_open_str = true,
                                .num => has_open_num = true,
                                .bigint => has_open_bigint = true,
                            }
                        }
                    },
                    else => {},
                }
            }

            var raw_lits: std.ArrayList(lower_unions.ClosedLiteralValue) = .empty;
            defer raw_lits.deinit(self.scratch);
            var other_arm_ids: std.ArrayList(u32) = .empty;
            defer other_arm_ids.deinit(self.scratch);
            var first_bool_lit_arm: ?u32 = null;

            for (non_null_arms) |aid| {
                var arm_lits: std.ArrayList(ClosedLiteralItem) = .empty;
                defer arm_lits.deinit(self.scratch);
                if (try self.tryCollectClosedLiteralsFromArm(aid, &arm_lits, false, 0) and arm_lits.items.len > 0) {
                    for (arm_lits.items) |item| {
                        const clv = item.val;
                        if (clv == .boolean and first_bool_lit_arm == null) {
                            first_bool_lit_arm = aid;
                        }
                        try self.appendUniqueClosedLiteral(&raw_lits, clv);
                    }
                } else {
                    try other_arm_ids.append(self.scratch, aid);
                }
            }

            // Detect `true | false` pair among literal arms -> promote to open `boolean`!
            var saw_true = false;
            var saw_false = false;
            for (raw_lits.items) |clv| {
                if (clv == .boolean) {
                    if (clv.boolean) saw_true = true else saw_false = true;
                }
            }
            const promote_bool_pair = !has_open_bool and saw_true and saw_false;
            if (promote_bool_pair) has_open_bool = true;

            var rem_lits: std.ArrayList(lower_unions.ClosedLiteralValue) = .empty;
            defer rem_lits.deinit(self.scratch);
            for (raw_lits.items) |clv| {
                const absorbed = switch (clv) {
                    .str => has_open_str,
                    .num => has_open_num,
                    .boolean => has_open_bool,
                    .bigint_val => has_open_bigint,
                };
                if (!absorbed) try rem_lits.append(self.scratch, clv);
            }

            var deduped_others: std.ArrayList(LoweredArmEntry) = .empty;
            defer deduped_others.deinit(self.scratch);

            if (promote_bool_pair) {
                try deduped_others.append(self.scratch, .{
                    .ast_arm_id = first_bool_lit_arm orelse non_null_arms[0],
                    .ty = try self.makeType(.bool_type),
                });
            }

            var extra_nullish: lower_types.NullishKind = .none;
            for (other_arm_ids.items) |aid| {
                var arm_visited = try visited.clone(self.scratch);
                defer arm_visited.deinit(self.scratch);
                var payload = try self.lowerType(aid, is_return_pos, active_tps, self_ident_opt, &arm_visited, imports_used, needs_runtime);
                if (payload.* == .noreturn_type) continue;
                if (payload.* == .void_type) {
                    extra_nullish = extra_nullish.merge(.undefined_only);
                    continue;
                }
                if (payload.* == .optional) {
                    const was_pure_nullish = payload.optional.is_pure_nullish;
                    extra_nullish = extra_nullish.merge(payload.optional.nullish_kind);
                    if (was_pure_nullish) continue;
                    payload = try self.makeType(payload.optional.child.*);
                    if (payload.* == .void_type or payload.* == .noreturn_type) continue;
                }
                switch (payload.*) {
                    .string_type => has_open_str = true,
                    .f64_type => has_open_num = true,
                    .i64_type => has_open_bigint = true,
                    .bool_type => has_open_bool = true,
                    else => {},
                }
                var is_dup = false;
                for (deduped_others.items) |existing| {
                    if (typeIrEql(existing.ty, payload, 0)) {
                        is_dup = true;
                        break;
                    }
                }
                if (!is_dup) {
                    try deduped_others.append(self.scratch, .{ .ast_arm_id = aid, .ty = payload });
                }
            }

            // Re-filter `rem_lits` in case a substituted type param or alias lowered to an open scalar!
            {
                var write_idx: usize = 0;
                for (rem_lits.items) |clv| {
                    const absorbed = switch (clv) {
                        .str => has_open_str,
                        .num => has_open_num,
                        .boolean => has_open_bool,
                        .bigint_val => has_open_bigint,
                    };
                    if (!absorbed) {
                        rem_lits.items[write_idx] = clv;
                        write_idx += 1;
                    }
                }
                rem_lits.items.len = write_idx;
            }

            if (rem_lits.items.len == 0 and deduped_others.items.len == 1) {
                return .{ .extra_nullish = extra_nullish, .body = .{ .single = deduped_others.items[0].ty } };
            }
            if (deduped_others.items.len == 0 and rem_lits.items.len > 0 and rem_lits.items.len <= 64) {
                const inline_en = try self.buildEnumMembersFromClosedLiterals(rem_lits.items);
                return .{ .extra_nullish = extra_nullish, .body = .{ .single = try self.makeType(.{ .inline_enum = inline_en }) } };
            }
            if (rem_lits.items.len == 0 and deduped_others.items.len == 0) {
                if (extra_nullish == .null_only or extra_nullish == .null_or_undefined) {
                    needs_runtime.* = true;
                    const pure_opt = try self.makeType(.{
                        .optional = .{
                            .child = try self.makeType(.js_any),
                            .nullish_kind = extra_nullish,
                            .is_pure_nullish = true,
                        },
                    });
                    return .{ .extra_nullish = extra_nullish, .body = .{ .single = pure_opt } };
                }
                return .{ .extra_nullish = .none, .body = .{ .single = try self.makeType(.void_type) } };
            }

            needs_runtime.* = true;

            var disc_sel_opt: ?lower_unions.SelectedDiscriminant = null;
            defer if (disc_sel_opt) |ds| ds.deinit(self.alloc);
            if (rem_lits.items.len == 0 and deduped_others.items.len >= 2) {
                disc_sel_opt = try self.trySelectDiscriminantForArms(deduped_others.items);
            }

            var var_scope = naming.ScopeNamer.init(self.scratch, null);
            defer var_scope.deinit();
            try var_scope.reserve("zigar_js");

            var variants: std.ArrayList(UnionVariantIr) = .empty;
            errdefer variants.deinit(self.alloc);

            if (rem_lits.items.len > 0 and rem_lits.items.len <= 16) {
                const void_ty = try self.makeType(.void_type);
                for (rem_lits.items) |clv| {
                    const hint = try lower_unions.formatLiteralTagHint(self.scratch, clv);
                    defer self.scratch.free(hint);
                    const bound = try var_scope.bind(hint, .snake);
                    const wire_str: []const u8 = switch (clv) {
                        .str => |s| try self.alloc.dupe(u8, s),
                        else => try self.alloc.dupe(u8, bound.logical_name),
                    };
                    try variants.append(self.alloc, .{
                        .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                        .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                        .wire_tag = wire_str,
                        .payload = void_ty,
                        .unit_literal = try self.closedLiteralToEnumValue(clv),
                    });
                    bound.deinit(self.scratch);
                }
            } else if (rem_lits.items.len > 16) {
                const inline_en = try self.buildEnumMembersFromClosedLiterals(rem_lits.items);
                const en_ty = try self.makeType(.{ .inline_enum = inline_en });
                const bound = try var_scope.bind("literal", .snake);
                try variants.append(self.alloc, .{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_tag = try self.alloc.dupe(u8, bound.wire_name),
                    .payload = en_ty,
                });
                bound.deinit(self.scratch);
            }

            for (deduped_others.items, 0..) |entry, idx| {
                var disc_vals_ir: []VariantDiscriminantValueIr = &.{};
                var hint: []const u8 = "";
                var free_hint = false;

                if (disc_sel_opt) |ds| {
                    const arm_dvals = ds.arm_values[idx];
                    disc_vals_ir = try self.alloc.alloc(VariantDiscriminantValueIr, arm_dvals.len);
                    for (arm_dvals, 0..) |dv, di| {
                        disc_vals_ir[di] = switch (dv) {
                            .str => |s| .{ .str = try self.alloc.dupe(u8, s) },
                            .num => |n| .{ .num = n },
                            .boolean => |b| .{ .boolean = b },
                            .bigint_val => |bi| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, bi) },
                        };
                    }
                    if (self.graph.types[entry.ast_arm_id].kind == .reference) {
                        const rname = self.str(self.graph.types[entry.ast_arm_id].kind.reference.target_name);
                        hint = lower_types.stripGlobalQualifier(rname);
                    } else {
                        hint = try lower_unions.formatDiscriminantVariantHint(
                            self.scratch,
                            ds.wire_name,
                            arm_dvals,
                            ds.arm_hints[idx],
                        );
                        free_hint = true;
                    }
                } else {
                    hint = self.deriveVariantTagHint(entry.ast_arm_id, entry.ty, idx);
                }
                defer if (free_hint) self.scratch.free(hint);

                const bound = try var_scope.bind(hint, .snake);
                try variants.append(self.alloc, .{
                    .zig_ident = try self.alloc.dupe(u8, bound.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, bound.logical_name),
                    .wire_tag = try self.alloc.dupe(u8, bound.wire_name),
                    .payload = entry.ty,
                    .disc_values = disc_vals_ir,
                });
                bound.deinit(self.scratch);
            }

            const disc_prop_copy: ?[]const u8 = if (disc_sel_opt) |ds|
                try self.alloc.dupe(u8, ds.wire_name)
            else
                null;

            return .{
                .extra_nullish = extra_nullish,
                .body = .{
                    .tagged = .{
                        .discriminant_prop = disc_prop_copy,
                        .variants = try variants.toOwnedSlice(self.alloc),
                    },
                },
            };
        }

        fn lowerUnionTypeInline(
            self: *Self,
            ty_id: u32,
            arms: []const u32,
            is_return_pos: bool,
            ref_cnt: u32,
            can_hoist_in_mod: bool,
            no_free_vars: bool,
            active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!*TypeIr {
            var non_null: std.ArrayList(u32) = .empty;
            defer non_null.deinit(self.scratch);
            var nullish: lower_types.NullishKind = .none;
            try self.collectFlattenedUnionArms(arms, &non_null, &nullish, 0);

            if (non_null.items.len == 0) {
                if (nullish != .none) {
                    needs_runtime.* = true;
                    const jv = try self.makeType(.js_any);
                    return self.makeType(.{ .optional = .{ .child = jv, .nullish_kind = nullish, .is_pure_nullish = true } });
                }
                return self.makeType(.void_type);
            }

            if (non_null.items.len == 1) {
                const base_ty = try self.lowerType(non_null.items[0], is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                const final_u = if (nullish != .none) try self.wrapOptionalWithNullish(base_ty, nullish) else base_ty;
                if (!is_return_pos and ref_cnt > 1 and can_hoist_in_mod and isSafeToShareTypeIrPtr(final_u) and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                    try self.cur_mod_closed_types.put(self.scratch, ty_id, final_u);
                }
                return final_u;
            }

            // 1. Open-literal autocomplete union (`"red" | "green" | (string & {})`)!
            if (try self.tryBuildOpenLiteralUnion(non_null.items)) |olu| {
                const base_ty: *TypeIr = if (can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id)) and ref_cnt > 1) blk: {
                    const h = try self.allocFreshAnonHelperName("__zigar_AnonUnion", active_tps);
                    const hloc = DeclLocation{
                        .module_index = self.cur_mod_idx,
                        .zig_path = h.path,
                        .type_param_defaults = &.{},
                    };
                    if (nullish == .none) try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                    try self.cur_mod_decls_out.?.append(self.alloc, .{
                        .source_decl_id = null,
                        .zig_ident = h.zig_ident,
                        .logical_name = h.logical,
                        .wire_name = h.logical,
                        .is_exported = false,
                        .is_js_exported = false,
                        .is_default_export = false,
                        .jsdoc = null,
                        .kind = .{ .open_literal_decl = olu },
                    });
                    break :blk try self.makeHoistedDeclRef(hloc);
                } else if (self.inline_anon_depth >= 3)
                    switch (olu.base_kind) {
                        .str => try self.makeType(.string_type),
                        .num => try self.makeType(.f64_type),
                        .bigint => try self.makeType(.i64_type),
                    }
                else
                    try self.makeType(.{ .open_literal_union = olu });

                return if (nullish != .none) try self.wrapOptionalWithNullish(base_ty, nullish) else base_ty;
            }

            // 2. Closed scalar literal union (`"a" | "b"`, `200 | 404`, `"auto" | 0 | false | 10n`)!
            if (try self.tryBuildClosedLiteralEnum(non_null.items)) |enum_ir| {
                const base_ty: *TypeIr = if (can_hoist_in_mod and (no_free_vars or try self.isClosedTypeSubgraph(ty_id)) and (ref_cnt > 1 or enum_ir.members.len > 8)) blk: {
                    const h = try self.allocFreshAnonHelperName("__zigar_AnonEnum", active_tps);
                    const hloc = DeclLocation{
                        .module_index = self.cur_mod_idx,
                        .zig_path = h.path,
                        .type_param_defaults = &.{},
                    };
                    if (nullish == .none) try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);
                    try self.cur_mod_decls_out.?.append(self.alloc, .{
                        .source_decl_id = null,
                        .zig_ident = h.zig_ident,
                        .logical_name = h.logical,
                        .wire_name = h.logical,
                        .is_exported = false,
                        .is_js_exported = false,
                        .is_default_export = false,
                        .jsdoc = null,
                        .kind = .{ .literal_enum_decl = enum_ir },
                    });
                    break :blk try self.makeHoistedDeclRef(hloc);
                } else if (self.inline_anon_depth >= 3 or enum_ir.members.len > 64) blk: {
                    if (self.allArmsSameScalarKind(non_null.items)) |scalar_ty| {
                        break :blk try self.makeType(scalar_ty);
                    }
                    needs_runtime.* = true;
                    break :blk try self.makeType(.js_any);
                } else try self.makeType(.{ .inline_enum = enum_ir });

                return if (nullish != .none) try self.wrapOptionalWithNullish(base_ty, nullish) else base_ty;
            }

            // 3. Exact `true | false` or absorbed homogeneous scalar union (`string | "foo"`, `number | 0`).
            if (self.allArmsSameScalarKind(non_null.items)) |scalar_ty| {
                const base_ty = try self.makeType(scalar_ty);
                const final_u = if (nullish != .none) try self.wrapOptionalWithNullish(base_ty, nullish) else base_ty;
                if (ref_cnt > 1 and can_hoist_in_mod and isSafeToShareTypeIrPtr(final_u) and (no_free_vars or try self.isClosedTypeSubgraph(ty_id))) {
                    try self.cur_mod_closed_types.put(self.scratch, ty_id, final_u);
                }
                return final_u;
            }

            // 4. Discriminated or heterogeneous multi-arm union (`A | B`, `Buffer | string`, etc.)!
            if (non_null.items.len > 32) {
                needs_runtime.* = true;
                const jv = try self.makeType(.js_any);
                return if (nullish != .none) try self.wrapOptionalWithNullish(jv, nullish) else jv;
            }

            const can_hoist_union = can_hoist_in_mod and ref_cnt > 1 and !is_return_pos and !self.typeHasTopLevelPositionalIterable(ty_id, 0) and (no_free_vars or try self.isClosedTypeSubgraph(ty_id));
            if (can_hoist_union and nullish == .none) {
                const h = try self.allocFreshAnonHelperName("__zigar_AnonUnion", active_tps);
                const hloc = DeclLocation{
                    .module_index = self.cur_mod_idx,
                    .zig_path = h.path,
                    .type_param_defaults = &.{},
                };
                try self.cur_mod_hoisted_locs.put(self.scratch, ty_id, hloc);

                var fresh_visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer fresh_visited.deinit(self.scratch);
                const saved_depth = self.inline_anon_depth;
                self.inline_anon_depth = 0;
                defer self.inline_anon_depth = saved_depth;

                const outcome = try self.buildGeneralUnionOutcome(non_null.items, false, &.{}, null, &fresh_visited, imports_used, needs_runtime);
                switch (outcome.body) {
                    .single => |single_ty| {
                        const eff_single = if (outcome.extra_nullish != .none)
                            try self.wrapOptionalWithNullish(single_ty, outcome.extra_nullish)
                        else
                            single_ty;
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{ .type_alias = .{ .type_params = &.{}, .target = eff_single } },
                        });
                        return self.makeHoistedDeclRef(hloc);
                    },
                    .tagged => |tu| {
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{
                                .union_decl = .{
                                    .type_params = &.{},
                                    .discriminant_prop = tu.discriminant_prop,
                                    .variants = tu.variants,
                                },
                            },
                        });
                        const href = try self.makeHoistedDeclRef(hloc);
                        if (outcome.extra_nullish != .none) {
                            _ = self.cur_mod_hoisted_locs.remove(ty_id);
                            return self.wrapOptionalWithNullish(href, outcome.extra_nullish);
                        }
                        return href;
                    },
                }
            }

            if (!can_hoist_union and self.inline_anon_depth >= 3) {
                needs_runtime.* = true;
                const jv = try self.makeType(.js_any);
                return if (nullish != .none) try self.wrapOptionalWithNullish(jv, nullish) else jv;
            }

            self.inline_anon_depth += 1;
            defer self.inline_anon_depth -= 1;

            const outcome = try self.buildGeneralUnionOutcome(non_null.items, is_return_pos, active_tps, self_ident_opt, visited, imports_used, needs_runtime);
            const eff_nullish = nullish.merge(outcome.extra_nullish);
            const base_ty: *TypeIr = switch (outcome.body) {
                .single => |single_ty| single_ty,
                .tagged => |tu| blk: {
                    if (can_hoist_union) {
                        const h = try self.allocFreshAnonHelperName("__zigar_AnonUnion", active_tps);
                        const hloc = DeclLocation{
                            .module_index = self.cur_mod_idx,
                            .zig_path = h.path,
                            .type_param_defaults = &.{},
                        };
                        try self.cur_mod_decls_out.?.append(self.alloc, .{
                            .source_decl_id = null,
                            .zig_ident = h.zig_ident,
                            .logical_name = h.logical,
                            .wire_name = h.logical,
                            .is_exported = false,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{
                                .union_decl = .{
                                    .type_params = &.{},
                                    .discriminant_prop = tu.discriminant_prop,
                                    .variants = tu.variants,
                                },
                            },
                        });
                        break :blk try self.makeHoistedDeclRef(hloc);
                    }
                    break :blk try self.makeType(.{ .tagged_union = tu });
                },
            };
            return if (eff_nullish != .none) try self.wrapOptionalWithNullish(base_ty, eff_nullish) else base_ty;
        }

        fn tryLowerUnionDeclVariants(
            self: *Self,
            ty_id: u32,
            active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}!?TaggedUnionIr {
            if (ty_id >= self.graph.types.len) return null;
            const tn = self.graph.types[ty_id];
            const union_arms: []const u32 = if (tn.kind == .union_type)
                tn.kind.union_type
            else if (tn.kind == .template_literal and tn.resolved_type != null and tn.resolved_type.? < self.graph.types.len and self.graph.types[tn.resolved_type.?].kind == .union_type)
                self.graph.types[tn.resolved_type.?].kind.union_type
            else
                return null;

            // Keep nullable unions (`T | null`, `A | B | undefined`) as `?Target` type aliases so `.nullish` metadata is preserved!
            var non_null: std.ArrayList(u32) = .empty;
            defer non_null.deinit(self.scratch);
            var nullish: lower_types.NullishKind = .none;
            try self.collectFlattenedUnionArms(union_arms, &non_null, &nullish, 0);
            if (nullish != .none or non_null.items.len < 2 or non_null.items.len > 64) return null;

            // Let homogeneous scalar unions like `string | "foo"` or `true | false` collapse cleanly to `[]const u8` / `bool`!
            if (self.allArmsSameScalarKind(non_null.items) != null) return null;

            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);
            const outcome = try self.buildGeneralUnionOutcome(non_null.items, false, active_tps, null, &visited, imports_used, needs_runtime);
            if (outcome.extra_nullish != .none) return null;
            return switch (outcome.body) {
                .single => null,
                .tagged => |tu| tu,
            };
        }

        fn deriveVariantTagHint(self: *Self, arm_ty_id: u32, lowered_payload: *const TypeIr, idx: usize) []const u8 {
            const ak = self.graph.types[arm_ty_id].kind;
            switch (ak) {
                .string_type => return "str",
                .number_type => return "num",
                .boolean_type => return "boolean",
                .bigint_type => return "bigint",
                .symbol_type, .unique_symbol => return "symbol",
                .object_type => return "object",
                .array, .readonly_array => return "array",
                .tuple, .readonly_tuple => return "tuple",
                .function_type => return "func",
                .template_literal => return "pattern",
                .reference => |ref| return lower_types.stripGlobalQualifier(self.str(ref.target_name)),
                .intersection => |parts| {
                    if (self.detectOpenPrimitiveIntersection(parts)) |opk| {
                        return switch (opk) {
                            .str => "str",
                            .num => "num",
                            .bigint => "bigint",
                        };
                    }
                    if (self.detectBrandedPrimitiveIntersection(parts, 0)) |bpk| {
                        return switch (bpk) {
                            .str => "str",
                            .num => "num",
                            .bigint => "bigint",
                            .boolean => "boolean",
                            .symbol => "symbol",
                        };
                    }
                },
                .object_literal => |obj| {
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        const pname = self.str(p.name);
                        if (p.ty < self.graph.types.len and self.graph.types[p.ty].kind == .literal) {
                            const lit = self.graph.types[p.ty].kind.literal;
                            switch (lit) {
                                .str => |sid| return self.str(sid),
                                .boolean => |b| {
                                    return std.fmt.allocPrint(self.alloc, "{s}_{s}", .{ pname, if (b) "true" else "false" }) catch "variant";
                                },
                                else => {},
                            }
                        }
                    }
                },
                else => {},
            }
            switch (lowered_payload.*) {
                .bool_type => return "boolean",
                .string_type => return "str",
                .f64_type => return "num",
                .i64_type => return "bigint",
                .binary_view => |bvk| return bvk.zigTypeIdent(),
                .slice => return "array",
                .tuple => return "tuple",
                .fn_ptr => return "func",
                .anon_struct => return "record",
                .js_object => return "object",
                .js_function => return "func",
                .js_map => return "map",
                .js_record, .mapped_values_op, .intersect_op => return "record",
                .promise => return "promise",
                .js_iterator => return "iterator",
                .js_async_iterator => return "async_iterator",
                .js_disposable => return "disposable",
                .js_async_disposable => return "async_disposable",
                else => {},
            }
            return std.fmt.allocPrint(self.alloc, "variant_{d}", .{idx}) catch "variant";
        }

        fn lowerDeclIntoList(
            self: *Self,
            final_mod_idx: u32,
            decl_id: u32,
            is_top_level: bool,
            scope: *naming.ScopeNamer,
            prebound_names: *const std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *const std.AutoHashMapUnmanaged(u32, []naming.BoundName),
            outer_active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            out_list: *std.ArrayList(DeclIr),
        ) error{OutOfMemory}!void {
            var active_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer active_decls.deinit(self.scratch);
            try self.lowerDeclIntoListInner(
                final_mod_idx,
                decl_id,
                is_top_level,
                scope,
                prebound_names,
                prebound_overloads,
                outer_active_tps,
                imports_used,
                needs_runtime,
                out_list,
                &active_decls,
            );
        }

        fn lowerDeclIntoListInner(
            self: *Self,
            final_mod_idx: u32,
            decl_id: u32,
            is_top_level: bool,
            scope: *naming.ScopeNamer,
            prebound_names: *const std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *const std.AutoHashMapUnmanaged(u32, []naming.BoundName),
            outer_active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            out_list: *std.ArrayList(DeclIr),
            active_decls: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            if (decl_id >= self.graph.decls.len) return;
            if (self.merged_ns_consumed.contains(decl_id)) return;
            if (self.merged_iface_consumed.contains(decl_id)) return;
            if (self.merged_ctor_var_consumed.contains(decl_id)) return;
            if (self.merged_fn_consumed.contains(decl_id)) return;
            if (active_decls.contains(decl_id)) return;
            try active_decls.put(self.scratch, decl_id, {});
            defer _ = active_decls.remove(decl_id);

            const d = self.graph.decls[decl_id];
            const bound = prebound_names.get(decl_id) orelse return;
            const top_jsdoc = try self.lowerJsDoc(d.jsdoc);
            const is_exported = !d.modifiers.private_mod and !d.modifiers.protected_mod;
            const suppress_js_export = self.merged_generic_ns_set.contains(decl_id) or
                self.pure_export_equals_ns.contains(decl_id);

            var companion_exported = false;
            var companion_default = false;
            var companion_global = false;
            for (d.merged_with) |mid| {
                if (mid == decl_id or mid >= self.graph.decls.len) continue;
                const vd = self.graph.decls[mid];
                const v_wire = if (vd.export_name) |esid| self.str(esid) else self.str(vd.name);
                if (!merge_decls.sameWireName(bound.wire_name, v_wire)) continue;
                const is_generic_ctor_peer = if (self.merged_generic_ctor_var_peer.get(decl_id)) |pvid| pvid == mid else false;
                if (is_generic_ctor_peer or
                    self.merged_ctor_var_consumed.contains(mid) or
                    self.merged_iface_consumed.contains(mid) or
                    self.merged_ns_consumed.contains(mid) or
                    self.merged_fn_consumed.contains(mid))
                {
                    if (vd.modifiers.export_decl or self.js_exported_decls.contains(mid)) companion_exported = true;
                    if (vd.modifiers.default_export) companion_default = true;
                    if (self.global_aug_decls.contains(mid)) companion_global = true;
                }
            }

            const is_js_exported = if (suppress_js_export)
                false
            else if (is_top_level)
                (is_exported and (self.js_exported_decls.contains(decl_id) or companion_exported))
            else
                (is_exported and (d.modifiers.export_decl or companion_exported));
            const is_default_export = d.modifiers.default_export or companion_default or
                (is_top_level and is_js_exported and std.mem.eql(u8, bound.wire_name, "default"));
            const is_global_scope = self.global_aug_decls.contains(decl_id) or companion_global;

            const saved_decl_name = self.cur_decl_logical_name;
            const saved_decl_notes = self.cur_decl_fallback_notes;
            self.cur_decl_logical_name = bound.logical_name;
            var local_fallback_notes: std.ArrayList([]const u8) = .empty;
            defer local_fallback_notes.deinit(self.scratch);
            self.cur_decl_fallback_notes = &local_fallback_notes;
            defer {
                self.cur_decl_logical_name = saved_decl_name;
                self.cur_decl_fallback_notes = saved_decl_notes;
            }
            const out_start_idx = out_list.items.len;

            switch (d.kind) {
                .function_decl => |sigs| {
                    needs_runtime.* = true;
                    if (sigs.len == 0) {
                        const empty_sig = SignatureIr{
                            .self_param_ident = null,
                            .alloc_param_ident = "allocator",
                            .type_params = &.{},
                            .params = &.{},
                            .return_type = try self.makeType(.void_type),
                            .has_type_predicate = false,
                            .type_predicate_asserts = false,
                            .jsdoc = top_jsdoc,
                        };
                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = is_js_exported,
                            .is_default_export = is_default_export,
                            .is_global_scope = is_global_scope,
                            .jsdoc = top_jsdoc,
                            .kind = .{ .function_decl = empty_sig },
                        });
                        return;
                    }

                    var raw_sigs = try self.scratch.alloc(SignatureIr, sigs.len);
                    defer self.scratch.free(raw_sigs);
                    for (sigs, 0..) |sid, s_idx| {
                        raw_sigs[s_idx] = try self.lowerSignature(
                            sid,
                            scope,
                            false,
                            false,
                            sigs.len > 1,
                            outer_active_tps,
                            null,
                            imports_used,
                            needs_runtime,
                        );
                    }
                    const kept = try overloads.deduplicateSubsumedIndices(self.scratch, self.scratch, raw_sigs);
                    defer self.scratch.free(kept);

                    if (kept.len == 1) {
                        const raw_one = raw_sigs[kept[0]];
                        const split_opt = try self.prepareAwaitedAndPromiseSig(raw_one);
                        var sig_ir = if (split_opt) |sp| sp.awaited else raw_one;
                        const comps = try self.bindSigCompanions(scope, bound.logical_name, &sig_ir);

                        var prom_decl_opt: ?DeclIr = null;
                        if (split_opt) |sp| {
                            var prom_sig = sp.promise_companion;
                            const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{bound.logical_name});
                            defer self.scratch.free(raw_prom);
                            const pb = try scope.bind(raw_prom, .camel);
                            const prom_zig = try self.alloc.dupe(u8, pb.zig_ident);
                            const prom_logical = try self.alloc.dupe(u8, pb.logical_name);
                            pb.deinit(self.scratch);
                            const prom_comps = try self.bindSigCompanions(scope, prom_logical, &prom_sig);
                            try self.refreshSigParamsAgainstScope(&prom_sig, scope);
                            prom_decl_opt = .{
                                .source_decl_id = decl_id,
                                .zig_ident = prom_zig,
                                .logical_name = prom_logical,
                                .wire_name = bound.wire_name,
                                .is_exported = is_exported,
                                .is_js_exported = false,
                                .is_default_export = is_default_export,
                                .is_global_scope = is_global_scope,
                                .is_synthetic_companion = !is_global_scope,
                                .alloc_companion_ident = prom_comps.alloc_ident,
                                .slice_companion_ident = prom_comps.slice_ident,
                                .slice_alloc_companion_ident = prom_comps.slice_alloc_ident,
                                .narrow_companion_ident = prom_comps.narrow_ident,
                                .narrow_alloc_companion_ident = prom_comps.narrow_alloc_ident,
                                .default_companion_ident = prom_comps.default_ident,
                                .default_alloc_companion_ident = prom_comps.default_alloc_ident,
                                .infer_companion_ident = prom_comps.infer_ident,
                                .infer_alloc_companion_ident = prom_comps.infer_alloc_ident,
                                .jsdoc = prom_sig.jsdoc orelse top_jsdoc,
                                .kind = .{ .function_decl = prom_sig },
                            };
                        }

                        try self.refreshSigParamsAgainstScope(&sig_ir, scope);
                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = is_js_exported,
                            .is_default_export = is_default_export,
                            .is_global_scope = is_global_scope,
                            .alloc_companion_ident = comps.alloc_ident,
                            .slice_companion_ident = comps.slice_ident,
                            .slice_alloc_companion_ident = comps.slice_alloc_ident,
                            .narrow_companion_ident = comps.narrow_ident,
                            .narrow_alloc_companion_ident = comps.narrow_alloc_ident,
                            .default_companion_ident = comps.default_ident,
                            .default_alloc_companion_ident = comps.default_alloc_ident,
                            .infer_companion_ident = comps.infer_ident,
                            .infer_alloc_companion_ident = comps.infer_alloc_ident,
                            .jsdoc = sig_ir.jsdoc orelse top_jsdoc,
                            .kind = .{ .function_decl = sig_ir },
                        });
                        if (prom_decl_opt) |pd| {
                            try out_list.append(self.alloc, pd);
                        }
                    } else {
                        var kept_sigs = try self.scratch.alloc(SignatureIr, kept.len);
                        defer self.scratch.free(kept_sigs);
                        var prom_sigs_list: std.ArrayList(SignatureIr) = .empty;
                        defer prom_sigs_list.deinit(self.scratch);

                        for (kept, 0..) |orig_idx, ki| {
                            if (try self.prepareAwaitedAndPromiseSig(raw_sigs[orig_idx])) |sp| {
                                kept_sigs[ki] = sp.awaited;
                                try prom_sigs_list.append(self.scratch, sp.promise_companion);
                            } else {
                                kept_sigs[ki] = raw_sigs[orig_idx];
                            }
                        }

                        const sem_names = try overloads.assignSemanticOverloadNames(
                            self.alloc,
                            self.scratch,
                            scope,
                            bound.logical_name,
                            kept_sigs,
                        );
                        var kept_comps = try self.scratch.alloc(BoundSigCompanions, kept.len);
                        defer self.scratch.free(kept_comps);
                        var any_alloc = false;
                        for (0..kept.len) |ki| {
                            kept_comps[ki] = try self.bindSigCompanions(scope, sem_names[ki].logical_name, &kept_sigs[ki]);
                            if (kept_comps[ki].alloc_ident != null) any_alloc = true;
                        }
                        var disp_alloc_ident: ?[]const u8 = null;
                        if (any_alloc) {
                            const raw_da = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{bound.logical_name});
                            defer self.scratch.free(raw_da);
                            const dab = try scope.bind(raw_da, .camel);
                            disp_alloc_ident = try self.alloc.dupe(u8, dab.zig_ident);
                            dab.deinit(self.scratch);
                        }

                        // Pre-bind `*Promise` companion names into `scope` BEFORE `refreshSigParamsAgainstScope`!
                        var prom_primary_zig: ?[]const u8 = null;
                        var prom_primary_logical: ?[]const u8 = null;
                        var prom_sem_names: []overloads.BoundOverloadIdent = &.{};
                        var prom_comps: []BoundSigCompanions = &.{};
                        defer if (prom_comps.len > 0) self.scratch.free(prom_comps);
                        var prom_disp_alloc_ident: ?[]const u8 = null;

                        if (prom_sigs_list.items.len > 0) {
                            const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{bound.logical_name});
                            defer self.scratch.free(raw_prom);
                            const pb = try scope.bind(raw_prom, .camel);
                            prom_primary_zig = try self.alloc.dupe(u8, pb.zig_ident);
                            prom_primary_logical = try self.alloc.dupe(u8, pb.logical_name);
                            pb.deinit(self.scratch);

                            if (prom_sigs_list.items.len == 1) {
                                prom_comps = try self.scratch.alloc(BoundSigCompanions, 1);
                                prom_comps[0] = try self.bindSigCompanions(scope, prom_primary_logical.?, &prom_sigs_list.items[0]);
                            } else {
                                prom_sem_names = try overloads.assignSemanticOverloadNames(
                                    self.alloc,
                                    self.scratch,
                                    scope,
                                    prom_primary_logical.?,
                                    prom_sigs_list.items,
                                );
                                prom_comps = try self.scratch.alloc(BoundSigCompanions, prom_sigs_list.items.len);
                                var prom_any_alloc = false;
                                for (0..prom_sigs_list.items.len) |pi| {
                                    prom_comps[pi] = try self.bindSigCompanions(scope, prom_sem_names[pi].logical_name, &prom_sigs_list.items[pi]);
                                    if (prom_comps[pi].alloc_ident != null) prom_any_alloc = true;
                                }
                                if (prom_any_alloc) {
                                    const raw_pda = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{prom_primary_logical.?});
                                    defer self.scratch.free(raw_pda);
                                    const pdab = try scope.bind(raw_pda, .camel);
                                    prom_disp_alloc_ident = try self.alloc.dupe(u8, pdab.zig_ident);
                                    pdab.deinit(self.scratch);
                                }
                            }
                        }

                        const disp_alloc_param = try lower_objects.chooseNonShadowingParamIdent(
                            scope,
                            self.scratch,
                            self.alloc,
                            "allocator",
                        );

                        var cands = try self.alloc.alloc(OverloadCandidateIr, kept.len);
                        for (0..kept.len) |ki| {
                            try self.refreshSigParamsAgainstScope(&kept_sigs[ki], scope);
                            cands[ki] = .{
                                .target_ident = sem_names[ki].zig_ident,
                                .alloc_target_ident = kept_comps[ki].alloc_ident,
                                .slice_target_ident = kept_comps[ki].slice_ident,
                                .infer_target_ident = kept_comps[ki].infer_ident,
                                .infer_alloc_target_ident = kept_comps[ki].infer_alloc_ident,
                                .default_target_ident = kept_comps[ki].default_ident,
                                .default_alloc_target_ident = kept_comps[ki].default_alloc_ident,
                                .signature = kept_sigs[ki],
                            };
                            try out_list.append(self.alloc, .{
                                .source_decl_id = decl_id,
                                .zig_ident = sem_names[ki].zig_ident,
                                .logical_name = sem_names[ki].logical_name,
                                .wire_name = bound.wire_name,
                                .is_exported = is_exported,
                                .is_js_exported = is_js_exported,
                                .is_default_export = is_default_export and ki == 0,
                                .is_global_scope = is_global_scope,
                                .alloc_companion_ident = kept_comps[ki].alloc_ident,
                                .slice_companion_ident = kept_comps[ki].slice_ident,
                                .slice_alloc_companion_ident = kept_comps[ki].slice_alloc_ident,
                                .narrow_companion_ident = kept_comps[ki].narrow_ident,
                                .narrow_alloc_companion_ident = kept_comps[ki].narrow_alloc_ident,
                                .default_companion_ident = kept_comps[ki].default_ident,
                                .default_alloc_companion_ident = kept_comps[ki].default_alloc_ident,
                                .infer_companion_ident = kept_comps[ki].infer_ident,
                                .infer_alloc_companion_ident = kept_comps[ki].infer_alloc_ident,
                                .jsdoc = kept_sigs[ki].jsdoc orelse top_jsdoc,
                                .kind = .{ .function_decl = kept_sigs[ki] },
                            });
                        }

                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = false,
                            .is_default_export = false,
                            .is_global_scope = is_global_scope,
                            .alloc_companion_ident = disp_alloc_ident,
                            .jsdoc = top_jsdoc orelse kept_sigs[0].jsdoc,
                            .kind = .{
                                .overload_dispatch = .{
                                    .zig_ident = bound.zig_ident,
                                    .logical_name = bound.logical_name,
                                    .alloc_companion_ident = disp_alloc_ident,
                                    .alloc_param_ident = disp_alloc_param,
                                    .is_static = true,
                                    .is_constructor = false,
                                    .mode = overloads.planDispatchMode(kept_sigs),
                                    .candidates = cands,
                                    .jsdoc = top_jsdoc orelse kept_sigs[0].jsdoc,
                                },
                            },
                        });

                        if (prom_sigs_list.items.len == 1) {
                            var psig = prom_sigs_list.items[0];
                            try self.refreshSigParamsAgainstScope(&psig, scope);
                            const pc = prom_comps[0];
                            try out_list.append(self.alloc, .{
                                .source_decl_id = decl_id,
                                .zig_ident = prom_primary_zig.?,
                                .logical_name = prom_primary_logical.?,
                                .wire_name = bound.wire_name,
                                .is_exported = is_exported,
                                .is_js_exported = false,
                                .is_default_export = is_default_export,
                                .is_global_scope = is_global_scope,
                                .is_synthetic_companion = !is_global_scope,
                                .alloc_companion_ident = pc.alloc_ident,
                                .slice_companion_ident = pc.slice_ident,
                                .slice_alloc_companion_ident = pc.slice_alloc_ident,
                                .narrow_companion_ident = pc.narrow_ident,
                                .narrow_alloc_companion_ident = pc.narrow_alloc_ident,
                                .default_companion_ident = pc.default_ident,
                                .default_alloc_companion_ident = pc.default_alloc_ident,
                                .infer_companion_ident = pc.infer_ident,
                                .infer_alloc_companion_ident = pc.infer_alloc_ident,
                                .jsdoc = psig.jsdoc orelse top_jsdoc,
                                .kind = .{ .function_decl = psig },
                            });
                        } else if (prom_sigs_list.items.len > 1) {
                            var prom_cands = try self.alloc.alloc(OverloadCandidateIr, prom_sigs_list.items.len);
                            for (0..prom_sigs_list.items.len) |pi| {
                                const psig = &prom_sigs_list.items[pi];
                                try self.refreshSigParamsAgainstScope(psig, scope);
                                const pc = prom_comps[pi];
                                prom_cands[pi] = .{
                                    .target_ident = prom_sem_names[pi].zig_ident,
                                    .alloc_target_ident = pc.alloc_ident,
                                    .slice_target_ident = pc.slice_ident,
                                    .infer_target_ident = pc.infer_ident,
                                    .infer_alloc_target_ident = pc.infer_alloc_ident,
                                    .default_target_ident = pc.default_ident,
                                    .default_alloc_target_ident = pc.default_alloc_ident,
                                    .signature = psig.*,
                                };
                                try out_list.append(self.alloc, .{
                                    .source_decl_id = decl_id,
                                    .zig_ident = prom_sem_names[pi].zig_ident,
                                    .logical_name = prom_sem_names[pi].logical_name,
                                    .wire_name = bound.wire_name,
                                    .is_exported = is_exported,
                                    .is_js_exported = false,
                                    .is_default_export = is_default_export and pi == 0,
                                    .is_global_scope = is_global_scope,
                                    .is_synthetic_companion = !is_global_scope,
                                    .alloc_companion_ident = pc.alloc_ident,
                                    .slice_companion_ident = pc.slice_ident,
                                    .slice_alloc_companion_ident = pc.slice_alloc_ident,
                                    .narrow_companion_ident = pc.narrow_ident,
                                    .narrow_alloc_companion_ident = pc.narrow_alloc_ident,
                                    .default_companion_ident = pc.default_ident,
                                    .default_alloc_companion_ident = pc.default_alloc_ident,
                                    .infer_companion_ident = pc.infer_ident,
                                    .infer_alloc_companion_ident = pc.infer_alloc_ident,
                                    .jsdoc = psig.jsdoc orelse top_jsdoc,
                                    .kind = .{ .function_decl = psig.* },
                                });
                            }
                            try out_list.append(self.alloc, .{
                                .source_decl_id = decl_id,
                                .zig_ident = prom_primary_zig.?,
                                .logical_name = prom_primary_logical.?,
                                .wire_name = bound.wire_name,
                                .is_exported = is_exported,
                                .is_js_exported = false,
                                .is_default_export = false,
                                .is_global_scope = is_global_scope,
                                .is_synthetic_companion = !is_global_scope,
                                .alloc_companion_ident = prom_disp_alloc_ident,
                                .jsdoc = top_jsdoc orelse prom_sigs_list.items[0].jsdoc,
                                .kind = .{
                                    .overload_dispatch = .{
                                        .zig_ident = prom_primary_zig.?,
                                        .logical_name = prom_primary_logical.?,
                                        .alloc_companion_ident = prom_disp_alloc_ident,
                                        .alloc_param_ident = disp_alloc_param,
                                        .is_static = true,
                                        .is_constructor = false,
                                        .mode = overloads.planDispatchMode(prom_sigs_list.items),
                                        .candidates = prom_cands,
                                        .jsdoc = top_jsdoc orelse prom_sigs_list.items[0].jsdoc,
                                    },
                                },
                            });
                        }
                    }
                },
                .variable_decl => |ty_id| {
                    var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited.deinit(self.scratch);
                    const lowered_ty = try self.lowerType(ty_id, false, outer_active_tps, null, &visited, imports_used, needs_runtime);

                    if (ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .literal) {
                        const lit = self.graph.types[ty_id].kind.literal;
                        const lit_ir: LiteralValueIr = switch (lit) {
                            .str => |sid| .{ .str = try self.alloc.dupe(u8, self.str(sid)) },
                            .num => |n| .{ .num = n },
                            .bigint_literal => |sid| .{ .bigint_val = try self.alloc.dupe(u8, self.str(sid)) },
                            .boolean => |b| .{ .boolean = b },
                        };
                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = is_js_exported,
                            .is_default_export = is_default_export,
                            .is_global_scope = is_global_scope,
                            .jsdoc = top_jsdoc,
                            .kind = .{ .const_literal = .{ .ty = lowered_ty, .value = lit_ir } },
                        });
                    } else {
                        needs_runtime.* = true;
                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = is_js_exported,
                            .is_default_export = is_default_export,
                            .is_global_scope = is_global_scope,
                            .jsdoc = top_jsdoc,
                            .kind = .{ .global_var = lowered_ty },
                        });
                    }
                },
                .interface_decl => |iface| {
                    const icls = try self.classifyDecl(decl_id);

                    var combined_props: std.ArrayList(SourcedProp) = .empty;
                    defer combined_props.deinit(self.scratch);

                    var combined_methods: std.ArrayList(SourcedMethod) = .empty;
                    defer combined_methods.deinit(self.scratch);
                    for (iface.methods) |m| try combined_methods.append(self.scratch, .{ .method = m });

                    var combined_call_sigs: std.ArrayList(SourcedSig) = .empty;
                    defer combined_call_sigs.deinit(self.scratch);
                    for (iface.call_signatures) |sid| try appendUniqueSourcedSig(&combined_call_sigs, self.scratch, .{ .sid = sid });

                    var combined_construct_sigs: std.ArrayList(SourcedSig) = .empty;
                    defer combined_construct_sigs.deinit(self.scratch);
                    for (iface.construct_signatures) |sid| try appendUniqueSourcedSig(&combined_construct_sigs, self.scratch, .{ .sid = sid });

                    var combined_index_sigs: std.ArrayList(SourcedIndexSig) = .empty;
                    defer combined_index_sigs.deinit(self.scratch);
                    for (iface.index_signatures) |isig| try combined_index_sigs.append(self.scratch, .{ .sig = isig });

                    var sourced_bases: std.ArrayList(SourcedBaseClause) = .empty;
                    defer sourced_bases.deinit(self.scratch);
                    for (iface.extends_clauses) |hc| try sourced_bases.append(self.scratch, .{ .target_type = hc.target_type });

                    var seen_methods: std.StringHashMapUnmanaged(void) = .empty;
                    defer seen_methods.deinit(self.scratch);
                    var derived_methods: std.StringHashMapUnmanaged(void) = .empty;
                    defer derived_methods.deinit(self.scratch);

                    for (iface.methods) |m| {
                        if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.computed_symbol != null) continue;
                        const mw = self.str(m.name);
                        try seen_methods.put(self.scratch, mw, {});
                        try derived_methods.put(self.scratch, mw, {});
                    }
                    for (iface.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                        try seen_methods.put(self.scratch, self.str(p.name), {});
                    }
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .interface_decl) continue;
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        const miface = md.kind.interface_decl;
                        for (miface.methods) |m| {
                            try self.appendMethodDedupOverloads(&combined_methods, .{ .method = m });
                            if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.computed_symbol != null) continue;
                            const mw = self.str(m.name);
                            try seen_methods.put(self.scratch, mw, {});
                            try derived_methods.put(self.scratch, mw, {});
                        }
                        for (miface.properties) |pid| {
                            if (pid >= self.graph.properties.len) continue;
                            const p = self.graph.properties[pid];
                            if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                            try seen_methods.put(self.scratch, self.str(p.name), {});
                        }
                        for (miface.call_signatures) |sid| try appendUniqueSourcedSig(&combined_call_sigs, self.scratch, .{ .sid = sid });
                        for (miface.construct_signatures) |sid| try appendUniqueSourcedSig(&combined_construct_sigs, self.scratch, .{ .sid = sid });
                        for (miface.index_signatures) |isig| try combined_index_sigs.append(self.scratch, .{ .sig = isig });
                        for (miface.extends_clauses) |hc| try sourced_bases.append(self.scratch, .{ .target_type = hc.target_type });
                    }

                    var visited_bases: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited_bases.deinit(self.scratch);
                    try visited_bases.put(self.scratch, decl_id, {});
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (md.kind == .interface_decl and merge_decls.sameWireName(bound.wire_name, m_wire)) {
                            try visited_bases.put(self.scratch, mid, {});
                        }
                    }

                    try self.collectInheritedHeritageClauses(
                        null,
                        iface.extends_clauses,
                        &combined_props,
                        &combined_methods,
                        &combined_call_sigs,
                        &combined_construct_sigs,
                        &combined_index_sigs,
                        &seen_methods,
                        &derived_methods,
                        &visited_bases,
                    );
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .interface_decl) continue;
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        try self.collectInheritedHeritageClauses(
                            null,
                            md.kind.interface_decl.extends_clauses,
                            &combined_props,
                            &combined_methods,
                            &combined_call_sigs,
                            &combined_construct_sigs,
                            &combined_index_sigs,
                            &seen_methods,
                            &derived_methods,
                            &visited_bases,
                        );
                    }
                    for (iface.properties) |pid| {
                        try self.upsertPropByWireName(&combined_props, .{ .pid = pid });
                    }
                    for (d.merged_with) |mid| {
                        if (mid == decl_id or mid >= self.graph.decls.len) continue;
                        const md = self.graph.decls[mid];
                        if (md.kind != .interface_decl) continue;
                        const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        const miface = md.kind.interface_decl;
                        for (miface.properties) |pid| try self.upsertPropByWireName(&combined_props, .{ .pid = pid });
                    }

                    // Fold companion constructable `var` (`interface URL` + `declare var URL: URLConstructor`
                    // and generic `interface ReadableStream<R>` + `declare var ReadableStream: { new<R>(...): ReadableStream<R> }`)!
                    var companion_ctors: std.ArrayList(u32) = .empty;
                    defer companion_ctors.deinit(self.scratch);
                    var companion_static_props: std.ArrayList(u32) = .empty;
                    defer companion_static_props.deinit(self.scratch);
                    if (icls.companion_var_decl_id) |var_did| {
                        const is_generic_ctor_peer = if (self.merged_generic_ctor_var_peer.get(decl_id)) |pvid| pvid == var_did else false;
                        if (self.merged_ctor_var_consumed.contains(var_did) or is_generic_ctor_peer) {
                            var companion_static_methods: std.ArrayList(MethodNodeType) = .empty;
                            defer companion_static_methods.deinit(self.scratch);
                            var tmp_cls = classify_decls.Classifier(GraphType).init(self.scratch, &self.graph);
                            defer tmp_cls.deinit();
                            try tmp_cls.collectCompanionVarCtorMembers(
                                var_did,
                                &companion_ctors,
                                &companion_static_props,
                                &companion_static_methods,
                                self.scratch,
                            );
                            for (companion_static_methods.items) |cm| {
                                try self.appendMethodDedupOverloads(&combined_methods, .{ .method = cm });
                            }
                        }
                    }

                    const merged_tp_info = try self.collectMergedDeclTypeParamInfo(decl_id);
                    const struct_ir = try self.lowerStructDecl(
                        final_mod_idx,
                        decl_id,
                        icls,
                        false,
                        false,
                        merged_tp_info.ids,
                        companion_ctors.items,
                        &.{},
                        combined_props.items,
                        companion_static_props.items,
                        combined_methods.items,
                        combined_call_sigs.items,
                        combined_construct_sigs.items,
                        combined_index_sigs.items,
                        sourced_bases.items,
                        d.merged_with,
                        scope,
                        prebound_names,
                        prebound_overloads,
                        outer_active_tps,
                        imports_used,
                        needs_runtime,
                        active_decls,
                    );
                    const iface_gt_comps = try self.bindGenericTypeCompanions(scope, bound.logical_name, struct_ir.type_params);
                    try out_list.append(self.alloc, .{
                        .source_decl_id = decl_id,
                        .zig_ident = bound.zig_ident,
                        .logical_name = bound.logical_name,
                        .wire_name = bound.wire_name,
                        .is_exported = is_exported,
                        .is_js_exported = is_js_exported,
                        .is_default_export = is_default_export,
                        .is_global_scope = is_global_scope,
                        .default_companion_ident = iface_gt_comps.default_ident,
                        .with_companion_ident = iface_gt_comps.with_ident,
                        .jsdoc = top_jsdoc,
                        .kind = .{ .struct_decl = struct_ir },
                    });
                },
                .class_decl => |cls| {
                    const ccls = try self.classifyDecl(decl_id);
                    var combined_props: std.ArrayList(SourcedProp) = .empty;
                    defer combined_props.deinit(self.scratch);

                    var combined_methods: std.ArrayList(SourcedMethod) = .empty;
                    defer combined_methods.deinit(self.scratch);
                    for (cls.methods) |m| try combined_methods.append(self.scratch, .{ .method = m });

                    var combined_call_sigs: std.ArrayList(SourcedSig) = .empty;
                    defer combined_call_sigs.deinit(self.scratch);
                    var ignored_construct_sigs: std.ArrayList(SourcedSig) = .empty;
                    defer ignored_construct_sigs.deinit(self.scratch);
                    var combined_index_sigs: std.ArrayList(SourcedIndexSig) = .empty;
                    defer combined_index_sigs.deinit(self.scratch);
                    for (cls.index_signatures) |isig| try combined_index_sigs.append(self.scratch, .{ .sig = isig });

                    var sourced_bases: std.ArrayList(SourcedBaseClause) = .empty;
                    defer sourced_bases.deinit(self.scratch);
                    if (cls.extends_clause) |hc| try sourced_bases.append(self.scratch, .{ .target_type = hc.target_type });
                    for (cls.implements_clauses) |hc| try sourced_bases.append(self.scratch, .{ .target_type = hc.target_type });

                    var seen_methods: std.StringHashMapUnmanaged(void) = .empty;
                    defer seen_methods.deinit(self.scratch);
                    var derived_methods: std.StringHashMapUnmanaged(void) = .empty;
                    defer derived_methods.deinit(self.scratch);

                    for (cls.methods) |m| {
                        if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.computed_symbol != null) continue;
                        const mw = self.str(m.name);
                        try seen_methods.put(self.scratch, mw, {});
                        try derived_methods.put(self.scratch, mw, {});
                    }
                    for (cls.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                        try seen_methods.put(self.scratch, self.str(p.name), {});
                    }

                    // Fold consumed merged `interface_decl` members FIRST before walking `extends`.
                    for (d.merged_with) |mid| {
                        if (!self.merged_iface_consumed.contains(mid) or mid >= self.graph.decls.len) continue;
                        const mdecl = self.graph.decls[mid];
                        if (mdecl.kind != .interface_decl) continue;
                        const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        const miface = mdecl.kind.interface_decl;
                        for (miface.methods) |m| {
                            try self.appendMethodDedupOverloads(&combined_methods, .{ .method = m });
                            if (m.modifiers.static_mod or m.modifiers.private_mod or m.modifiers.protected_mod or m.computed_symbol != null) continue;
                            const mw = self.str(m.name);
                            try seen_methods.put(self.scratch, mw, {});
                            try derived_methods.put(self.scratch, mw, {});
                        }
                        for (miface.properties) |pid| {
                            if (pid >= self.graph.properties.len) continue;
                            const p = self.graph.properties[pid];
                            if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                            try seen_methods.put(self.scratch, self.str(p.name), {});
                        }
                        for (miface.call_signatures) |sid| try appendUniqueSourcedSig(&combined_call_sigs, self.scratch, .{ .sid = sid });
                        for (miface.index_signatures) |isig| try combined_index_sigs.append(self.scratch, .{ .sig = isig });
                        for (miface.extends_clauses) |hc| try sourced_bases.append(self.scratch, .{ .target_type = hc.target_type });
                    }

                    var visited_bases: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited_bases.deinit(self.scratch);
                    try visited_bases.put(self.scratch, decl_id, {});
                    for (d.merged_with) |mid| {
                        if (mid < self.graph.decls.len and self.graph.decls[mid].kind == .interface_decl) {
                            const md = self.graph.decls[mid];
                            const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                            if (merge_decls.sameWireName(bound.wire_name, m_wire)) {
                                try visited_bases.put(self.scratch, mid, {});
                            }
                        }
                    }

                    if (cls.extends_clause) |hc| {
                        try self.collectInheritedHeritageClause(
                            null,
                            hc,
                            &combined_props,
                            &combined_methods,
                            &combined_call_sigs,
                            &ignored_construct_sigs,
                            &combined_index_sigs,
                            &seen_methods,
                            &derived_methods,
                            &visited_bases,
                        );
                    }
                    for (d.merged_with) |mid| {
                        if (!self.merged_iface_consumed.contains(mid) or mid >= self.graph.decls.len) continue;
                        const mdecl = self.graph.decls[mid];
                        if (mdecl.kind != .interface_decl) continue;
                        const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        try self.collectInheritedHeritageClauses(
                            null,
                            mdecl.kind.interface_decl.extends_clauses,
                            &combined_props,
                            &combined_methods,
                            &combined_call_sigs,
                            &ignored_construct_sigs,
                            &combined_index_sigs,
                            &seen_methods,
                            &derived_methods,
                            &visited_bases,
                        );
                    }

                    // Apply merged interface properties, then own `cls.properties` so derived overrides base!
                    for (d.merged_with) |mid| {
                        if (!self.merged_iface_consumed.contains(mid) or mid >= self.graph.decls.len) continue;
                        const mdecl = self.graph.decls[mid];
                        if (mdecl.kind != .interface_decl) continue;
                        const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                        if (!merge_decls.sameWireName(bound.wire_name, m_wire)) continue;
                        for (mdecl.kind.interface_decl.properties) |pid| {
                            try self.upsertPropByWireName(&combined_props, .{ .pid = pid });
                        }
                    }
                    for (cls.properties) |pid| try self.upsertPropByWireName(&combined_props, .{ .pid = pid });

                    var inherited_ctors: []const SourcedSig = &.{};
                    var allow_default_ctor = (cls.extends_clause == null);
                    if (!d.modifiers.abstract_mod and cls.constructors.len == 0) {
                        if (cls.extends_clause) |hc| {
                            const ctor_res = try self.collectInheritedClassCtors(hc);
                            switch (ctor_res) {
                                .inherited_sigs => |sigs| {
                                    inherited_ctors = sigs;
                                    allow_default_ctor = false;
                                },
                                .default_zero_arg => {
                                    allow_default_ctor = true;
                                },
                                .unknown_external_base => {
                                    allow_default_ctor = false;
                                },
                            }
                        }
                    }

                    const merged_cls_tp_info = try self.collectMergedDeclTypeParamInfo(decl_id);
                    const struct_ir = try self.lowerStructDecl(
                        final_mod_idx,
                        decl_id,
                        ccls,
                        d.modifiers.abstract_mod,
                        allow_default_ctor,
                        merged_cls_tp_info.ids,
                        cls.constructors,
                        inherited_ctors,
                        combined_props.items,
                        &.{},
                        combined_methods.items,
                        combined_call_sigs.items,
                        &.{},
                        combined_index_sigs.items,
                        sourced_bases.items,
                        d.merged_with,
                        scope,
                        prebound_names,
                        prebound_overloads,
                        outer_active_tps,
                        imports_used,
                        needs_runtime,
                        active_decls,
                    );
                    const cls_gt_comps = try self.bindGenericTypeCompanions(scope, bound.logical_name, struct_ir.type_params);
                    try out_list.append(self.alloc, .{
                        .source_decl_id = decl_id,
                        .zig_ident = bound.zig_ident,
                        .logical_name = bound.logical_name,
                        .wire_name = bound.wire_name,
                        .is_exported = is_exported,
                        .is_js_exported = is_js_exported,
                        .is_default_export = is_default_export,
                        .is_global_scope = is_global_scope,
                        .default_companion_ident = cls_gt_comps.default_ident,
                        .with_companion_ident = cls_gt_comps.with_ident,
                        .jsdoc = top_jsdoc,
                        .kind = .{ .struct_decl = struct_ir },
                    });
                },
                .enum_decl => |en| {
                    var member_scope = naming.ScopeNamer.initContainer(self.scratch, scope);
                    defer member_scope.deinit();
                    try member_scope.reserve("zigar_js");
                    try member_scope.reserve("__zigar_value");

                    var has_unknown = (en.members.len == 0);
                    var members = try self.alloc.alloc(EnumMemberIr, en.members.len);
                    for (en.members, 0..) |m, idx| {
                        const m_wire = self.str(m.name);
                        const mb = try member_scope.bind(m_wire, .snake);
                        const val_ir: EnumValueIr = if (m.value) |mv| switch (mv) {
                            .num => |n| blk: {
                                if (!std.math.isFinite(n)) {
                                    has_unknown = true;
                                    break :blk .unknown;
                                }
                                break :blk .{ .num = n };
                            },
                            .str => |sid| .{ .str = try self.alloc.dupe(u8, self.str(sid)) },
                            .boolean => |b| .{ .boolean = b },
                            .bigint_literal => |sid| .{ .bigint_val = try lower_types.normalizeBigIntLiteral(self.alloc, self.str(sid)) },
                        } else blk: {
                            has_unknown = true;
                            break :blk .unknown;
                        };
                        members[idx] = .{
                            .zig_ident = try self.alloc.dupe(u8, mb.zig_ident),
                            .logical_name = try self.alloc.dupe(u8, mb.logical_name),
                            .wire_name = try self.alloc.dupe(u8, mb.wire_name),
                            .value = val_ir,
                            .jsdoc = try self.lowerJsDoc(m.jsdoc),
                        };
                        mb.deinit(self.scratch);
                    }

                    var backing: lower_unions.EnumBackingKind = .none;
                    if (!has_unknown) {
                        var closed_vals = try self.scratch.alloc(lower_unions.ClosedLiteralValue, members.len);
                        defer self.scratch.free(closed_vals);
                        for (members, 0..) |m, idx| {
                            closed_vals[idx] = switch (m.value) {
                                .num => |n| .{ .num = n },
                                .str => |s| .{ .str = s },
                                .boolean => |b| .{ .boolean = b },
                                .bigint_val => |bi| .{ .bigint_val = bi },
                                .unknown => unreachable,
                            };
                        }
                        const analysis = try lower_unions.analyzeClosedEnumValues(self.scratch, closed_vals);
                        defer analysis.deinit(self.scratch);
                        backing = analysis.backing;
                        for (members, 0..) |*m, idx| {
                            m.int_backing_val = analysis.layouts[idx].int_tag_value;
                            if (analysis.layouts[idx].alias_of_index) |pidx| {
                                m.alias_of_zig_ident = members[pidx].zig_ident;
                                m.alias_of_logical_name = members[pidx].logical_name;
                            }
                        }
                    } else {
                        needs_runtime.* = true;
                    }

                    try member_scope.reserve("deinit");
                    try member_scope.reserve("toSlice");
                    try member_scope.reserve("fromSlice");
                    try member_scope.reserve("toInt");
                    try member_scope.reserve("fromInt");

                    var enum_nested_decls: std.ArrayList(DeclIr) = .empty;
                    const enum_ns_children = try self.collectConsumedMergedNamespaceChildren(
                        decl_id,
                        bound.wire_name,
                        d.merged_with,
                        &.{},
                    );
                    for (enum_ns_children) |cid| {
                        if (prebound_names.get(cid)) |cb| try member_scope.reserve(cb.logical_name);
                        if (prebound_overloads.get(cid)) |ovs| {
                            for (ovs) |ov| try member_scope.reserve(ov.logical_name);
                        }
                    }
                    for (enum_ns_children) |cid| {
                        try self.lowerDeclIntoListInner(
                            final_mod_idx,
                            cid,
                            false,
                            &member_scope,
                            prebound_names,
                            prebound_overloads,
                            outer_active_tps,
                            imports_used,
                            needs_runtime,
                            &enum_nested_decls,
                            active_decls,
                        );
                    }
                    try deduplicateDeclIrsInPlace(self.scratch, &enum_nested_decls);

                    try out_list.append(self.alloc, .{
                        .source_decl_id = decl_id,
                        .zig_ident = bound.zig_ident,
                        .logical_name = bound.logical_name,
                        .wire_name = bound.wire_name,
                        .is_exported = is_exported,
                        .is_js_exported = is_js_exported,
                        .is_default_export = is_default_export,
                        .is_global_scope = is_global_scope,
                        .jsdoc = top_jsdoc,
                        .kind = .{
                            .enum_decl = .{
                                .is_const = en.is_const,
                                .has_unknown_values = has_unknown,
                                .backing = backing,
                                .members = members,
                                .nested_decls = try enum_nested_decls.toOwnedSlice(self.alloc),
                            },
                        },
                    });
                },
                .type_alias_decl => |ty_id| {
                    var tp_scope = naming.ScopeNamer.initParam(self.scratch, scope);
                    defer tp_scope.deinit();
                    const tp_res = try self.lowerTypeParams(
                        d.type_params,
                        &tp_scope,
                        outer_active_tps,
                        null,
                        imports_used,
                        needs_runtime,
                    );

                    if (d.type_params.len == 0 and ty_id < self.graph.types.len) {
                        const tn_alias = self.graph.types[ty_id];
                        switch (tn_alias.kind) {
                            .union_type => |u_arms| {
                                var non_null: std.ArrayList(u32) = .empty;
                                defer non_null.deinit(self.scratch);
                                var nullish: lower_types.NullishKind = .none;
                                try self.collectFlattenedUnionArms(u_arms, &non_null, &nullish, 0);

                                if (nullish == .none and non_null.items.len > 0) {
                                    // 1a. Open-literal autocomplete union (`"red" | "green" | (string & {})`)!
                                    if (try self.tryBuildOpenLiteralUnion(non_null.items)) |olu| {
                                        try out_list.append(self.alloc, .{
                                            .source_decl_id = decl_id,
                                            .zig_ident = bound.zig_ident,
                                            .logical_name = bound.logical_name,
                                            .wire_name = bound.wire_name,
                                            .is_exported = is_exported,
                                            .is_js_exported = is_js_exported,
                                            .is_default_export = is_default_export,
                                            .is_global_scope = is_global_scope,
                                            .jsdoc = top_jsdoc,
                                            .kind = .{ .open_literal_decl = olu },
                                        });
                                        return;
                                    }

                                    // 1b. Closed literal / finite-template union -> first-class Zig `enum`!
                                    if (try self.tryBuildClosedLiteralEnum(non_null.items)) |enum_ir| {
                                        try out_list.append(self.alloc, .{
                                            .source_decl_id = decl_id,
                                            .zig_ident = bound.zig_ident,
                                            .logical_name = bound.logical_name,
                                            .wire_name = bound.wire_name,
                                            .is_exported = is_exported,
                                            .is_js_exported = is_js_exported,
                                            .is_default_export = is_default_export,
                                            .is_global_scope = is_global_scope,
                                            .jsdoc = top_jsdoc,
                                            .kind = .{ .literal_enum_decl = enum_ir },
                                        });
                                        return;
                                    }
                                }
                            },
                            .template_literal => |tl| {
                                if (tl.spans.len > 0) {
                                    var finite_strs: std.ArrayList([]const u8) = .empty;
                                    defer finite_strs.deinit(self.alloc);
                                    if (try self.tryExpandFiniteStringSet(ty_id, &finite_strs, 0)) {
                                        if (finite_strs.items.len >= 2) {
                                            const enum_ir = try self.buildStringEnumFromUniqueStrings(finite_strs.items);
                                            if (enum_ir.members.len >= 2) {
                                                try out_list.append(self.alloc, .{
                                                    .source_decl_id = decl_id,
                                                    .zig_ident = bound.zig_ident,
                                                    .logical_name = bound.logical_name,
                                                    .wire_name = bound.wire_name,
                                                    .is_exported = is_exported,
                                                    .is_js_exported = is_js_exported,
                                                    .is_default_export = is_default_export,
                                                    .is_global_scope = is_global_scope,
                                                    .jsdoc = top_jsdoc,
                                                    .kind = .{ .literal_enum_decl = enum_ir },
                                                });
                                                return;
                                            }
                                        }
                                    } else if (try self.tryBuildDirectTemplatePattern(tl)) |pat_ir| {
                                        needs_runtime.* = true;
                                        try out_list.append(self.alloc, .{
                                            .source_decl_id = decl_id,
                                            .zig_ident = bound.zig_ident,
                                            .logical_name = bound.logical_name,
                                            .wire_name = bound.wire_name,
                                            .is_exported = is_exported,
                                            .is_js_exported = is_js_exported,
                                            .is_default_export = is_default_export,
                                            .is_global_scope = is_global_scope,
                                            .jsdoc = top_jsdoc,
                                            .kind = .{ .template_pattern_decl = pat_ir },
                                        });
                                        return;
                                    }
                                }
                            },
                            .reference => {
                                // Single enum-member alias (`export type ExponentiationOperator = SyntaxKind.AsteriskAsteriskToken`)!
                                if (try self.resolveEnumMemberReference(ty_id)) |em| {
                                    if (try self.enumMemberClosedLiteralItem(em)) |item| {
                                        const enum_ir = try self.buildEnumMembersFromClosedLiteralItems(&.{item});
                                        try out_list.append(self.alloc, .{
                                            .source_decl_id = decl_id,
                                            .zig_ident = bound.zig_ident,
                                            .logical_name = bound.logical_name,
                                            .wire_name = bound.wire_name,
                                            .is_exported = is_exported,
                                            .is_js_exported = is_js_exported,
                                            .is_default_export = is_default_export,
                                            .is_global_scope = is_global_scope,
                                            .jsdoc = top_jsdoc,
                                            .kind = .{ .literal_enum_decl = enum_ir },
                                        });
                                        return;
                                    }
                                }
                            },
                            else => {
                                // Closed `keyof`, `T[K]`, `Exclude`, `Extract`, `Uppercase`, or conditional resolving to closed literals!
                                if (tn_alias.resolved_type) |rt| {
                                    if (rt != ty_id and rt < self.graph.types.len) {
                                        const r_tn = self.graph.types[rt];
                                        if (r_tn.kind == .union_type) {
                                            var non_null_r: std.ArrayList(u32) = .empty;
                                            defer non_null_r.deinit(self.scratch);
                                            var nullish_r: lower_types.NullishKind = .none;
                                            try self.collectFlattenedUnionArms(r_tn.kind.union_type, &non_null_r, &nullish_r, 0);
                                            if (nullish_r == .none and non_null_r.items.len > 0) {
                                                if (try self.tryBuildClosedLiteralEnum(non_null_r.items)) |enum_ir| {
                                                    try out_list.append(self.alloc, .{
                                                        .source_decl_id = decl_id,
                                                        .zig_ident = bound.zig_ident,
                                                        .logical_name = bound.logical_name,
                                                        .wire_name = bound.wire_name,
                                                        .is_exported = is_exported,
                                                        .is_js_exported = is_js_exported,
                                                        .is_default_export = is_default_export,
                                                        .is_global_scope = is_global_scope,
                                                        .jsdoc = top_jsdoc,
                                                        .kind = .{ .literal_enum_decl = enum_ir },
                                                    });
                                                    return;
                                                }
                                            }
                                        } else if (tn_alias.kind == .keyof_type and r_tn.kind == .literal and r_tn.kind.literal == .str) {
                                            const key_str = self.str(r_tn.kind.literal.str);
                                            const enum_ir = try self.buildStringEnumFromUniqueStrings(&.{key_str});
                                            try out_list.append(self.alloc, .{
                                                .source_decl_id = decl_id,
                                                .zig_ident = bound.zig_ident,
                                                .logical_name = bound.logical_name,
                                                .wire_name = bound.wire_name,
                                                .is_exported = is_exported,
                                                .is_js_exported = is_js_exported,
                                                .is_default_export = is_default_export,
                                                .is_global_scope = is_global_scope,
                                                .jsdoc = top_jsdoc,
                                                .kind = .{ .literal_enum_decl = enum_ir },
                                            });
                                            return;
                                        }
                                    }
                                }
                            },
                        }
                    }

                    const alias_gt_comps = try self.bindGenericTypeCompanions(scope, bound.logical_name, tp_res.ir);

                    // 2. Multi-arm discriminated/heterogeneous union -> Zig `union(enum)`!
                    if (try self.tryLowerUnionDeclVariants(ty_id, tp_res.active, imports_used, needs_runtime)) |tu| {
                        try out_list.append(self.alloc, .{
                            .source_decl_id = decl_id,
                            .zig_ident = bound.zig_ident,
                            .logical_name = bound.logical_name,
                            .wire_name = bound.wire_name,
                            .is_exported = is_exported,
                            .is_js_exported = is_js_exported,
                            .is_default_export = is_default_export,
                            .is_global_scope = is_global_scope,
                            .default_companion_ident = alias_gt_comps.default_ident,
                            .with_companion_ident = alias_gt_comps.with_ident,
                            .jsdoc = top_jsdoc,
                            .kind = .{
                                .union_decl = .{
                                    .type_params = tp_res.ir,
                                    .discriminant_prop = tu.discriminant_prop,
                                    .variants = tu.variants,
                                },
                            },
                        });
                        return;
                    }

                    // 3a. Object intersection type alias (`type MergedOpts = OptsA & OptsB`,
                    //     `type Inter = { a: number } & { run(): void }`,
                    //     `type Both = LoggerT & { extra: number }`) -> merged `struct` with `.bases`!
                    if (ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .intersection) {
                        const inter_parts = self.graph.types[ty_id].kind.intersection;
                        const inter_cls = try self.classifyDecl(decl_id);
                        var has_open_dynamic_arm = false;
                        if (inter_cls.kind != .handle_wrapper and tp_res.active.len > 0) {
                            for (inter_parts) |pid| {
                                if (self.typeArmHasOpenDynamicKeys(pid, tp_res.active, 0)) {
                                    has_open_dynamic_arm = true;
                                    break;
                                }
                            }
                        }
                        var inter_props: std.ArrayList(SourcedProp) = .empty;
                        defer inter_props.deinit(self.scratch);
                        var inter_methods: std.ArrayList(SourcedMethod) = .empty;
                        defer inter_methods.deinit(self.scratch);
                        var inter_calls: std.ArrayList(SourcedSig) = .empty;
                        defer inter_calls.deinit(self.scratch);
                        var inter_ctors: std.ArrayList(SourcedSig) = .empty;
                        defer inter_ctors.deinit(self.scratch);
                        var inter_index_sigs: std.ArrayList(SourcedIndexSig) = .empty;
                        defer inter_index_sigs.deinit(self.scratch);

                        if (!has_open_dynamic_arm and try self.collectObjectIntersectionMembers(
                            ty_id,
                            &inter_props,
                            &inter_methods,
                            &inter_calls,
                            &inter_ctors,
                            &inter_index_sigs,
                        ) and (inter_props.items.len > 0 or inter_methods.items.len > 0 or
                            inter_calls.items.len > 0 or inter_ctors.items.len > 0 or
                            inter_index_sigs.items.len > 0 or self.hasProtocolInGraphTypes(inter_parts, 0)))
                        {
                            const sourced_bases = try self.wrapUnsourcedBases(inter_parts);
                            const struct_ir = try self.lowerStructDecl(
                                final_mod_idx,
                                decl_id,
                                inter_cls,
                                false,
                                false,
                                d.type_params,
                                &.{},
                                &.{},
                                inter_props.items,
                                &.{},
                                inter_methods.items,
                                inter_calls.items,
                                inter_ctors.items,
                                inter_index_sigs.items,
                                sourced_bases,
                                &.{},
                                scope,
                                prebound_names,
                                prebound_overloads,
                                outer_active_tps,
                                imports_used,
                                needs_runtime,
                                active_decls,
                            );
                            try out_list.append(self.alloc, .{
                                .source_decl_id = decl_id,
                                .zig_ident = bound.zig_ident,
                                .logical_name = bound.logical_name,
                                .wire_name = bound.wire_name,
                                .is_exported = is_exported,
                                .is_js_exported = is_js_exported,
                                .is_default_export = is_default_export,
                                .is_global_scope = is_global_scope,
                                .default_companion_ident = alias_gt_comps.default_ident,
                                .with_companion_ident = alias_gt_comps.with_ident,
                                .jsdoc = top_jsdoc,
                                .kind = .{ .struct_decl = struct_ir },
                            });
                            return;
                        }
                    }

                    // 3b. Inline or checker-resolved object literal type alias (`type Opts = { ... }`, `type Sub = Pick<Opts, "a">`, `type Cfg = typeof cfg`) -> `struct`!
                    const mentions_alias_tp = self.typeTreeMentionsActiveTypeParam(ty_id, tp_res.active, &.{}, 0);
                    const same_mod_typeof_var_obj: ?u32 = blk: {
                        if (!mentions_alias_tp and ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .typeof_query) {
                            const tq = self.graph.types[ty_id].kind.typeof_query;
                            if (tq.type_args.len == 0) {
                                if (tq.target_decl) |td| {
                                    if (td < self.graph.decls.len and
                                        self.graph.decls[td].kind == .variable_decl and
                                        self.graph.decls[td].merged_with.len == 0)
                                    {
                                        if (self.decl_locations.get(td)) |v_loc| {
                                            if (v_loc.module_index == self.cur_mod_idx) {
                                                const v_ty_id = self.graph.decls[td].kind.variable_decl;
                                                if (v_ty_id < self.graph.types.len and self.graph.types[v_ty_id].kind == .object_literal) {
                                                    break :blk v_ty_id;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        break :blk null;
                    };
                    const resolved_obj_id: ?u32 = if (ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .object_literal)
                        ty_id
                    else if (same_mod_typeof_var_obj) |v_oid|
                        v_oid
                    else if (!mentions_alias_tp and ty_id < self.graph.types.len and self.graph.types[ty_id].resolved_type != null and
                        self.graph.types[ty_id].kind != .reference and
                        self.graph.types[ty_id].kind != .import_type and
                        self.graph.types[ty_id].resolved_type.? < self.graph.types.len and
                        self.graph.types[self.graph.types[ty_id].resolved_type.?].kind == .object_literal)
                        self.graph.types[ty_id].resolved_type.?
                    else if (!mentions_alias_tp and ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .typeof_query and
                        self.graph.types[ty_id].kind.typeof_query.target_decl != null and
                        self.graph.types[ty_id].kind.typeof_query.target_decl.? < self.graph.decls.len and
                        self.graph.decls[self.graph.types[ty_id].kind.typeof_query.target_decl.?].kind == .variable_decl and
                        self.graph.decls[self.graph.types[ty_id].kind.typeof_query.target_decl.?].kind.variable_decl < self.graph.types.len and
                        self.graph.types[self.graph.decls[self.graph.types[ty_id].kind.typeof_query.target_decl.?].kind.variable_decl].kind == .object_literal)
                        self.graph.decls[self.graph.types[ty_id].kind.typeof_query.target_decl.?].kind.variable_decl
                    else
                        null;

                    if (resolved_obj_id) |oid| {
                        if (!self.cur_mod_hoisted_locs.contains(oid)) {
                            const obj = self.graph.types[oid].kind.object_literal;
                            if (obj.properties.len > 0 or obj.call_signatures.len > 0 or
                                obj.construct_signatures.len > 0 or obj.index_signatures.len > 0)
                            {
                                if (d.type_params.len == 0) {
                                    if (self.decl_locations.get(decl_id)) |dloc| {
                                        if (dloc.module_index == self.cur_mod_idx) {
                                            var reg_loc = dloc;
                                            reg_loc.target_decl_id = decl_id;
                                            try self.cur_mod_hoisted_locs.put(self.scratch, oid, reg_loc);
                                        }
                                    }
                                }
                                const obj_cls = self.classifyObjectLiteral(obj);
                                const split = try self.splitObjectLiteralPropsAndMethods(obj.properties);
                                const sourced_calls = try self.wrapUnsourcedSigs(obj.call_signatures);
                                const sourced_ctors = try self.wrapUnsourcedSigs(obj.construct_signatures);
                                const sourced_index_sigs = try self.wrapUnsourcedIndexSigs(obj.index_signatures);
                                const struct_ir = try self.lowerStructDecl(
                                    final_mod_idx,
                                    decl_id,
                                    obj_cls,
                                    false,
                                    false,
                                    d.type_params,
                                    &.{},
                                    &.{},
                                    split.props,
                                    &.{},
                                    split.methods,
                                    sourced_calls,
                                    sourced_ctors,
                                    sourced_index_sigs,
                                    &.{},
                                    &.{},
                                    scope,
                                    prebound_names,
                                    prebound_overloads,
                                    outer_active_tps,
                                    imports_used,
                                    needs_runtime,
                                    active_decls,
                                );
                                try out_list.append(self.alloc, .{
                                    .source_decl_id = decl_id,
                                    .zig_ident = bound.zig_ident,
                                    .logical_name = bound.logical_name,
                                    .wire_name = bound.wire_name,
                                    .is_exported = is_exported,
                                    .is_js_exported = is_js_exported,
                                    .is_default_export = is_default_export,
                                    .is_global_scope = is_global_scope,
                                    .default_companion_ident = alias_gt_comps.default_ident,
                                    .with_companion_ident = alias_gt_comps.with_ident,
                                    .jsdoc = top_jsdoc,
                                    .kind = .{ .struct_decl = struct_ir },
                                });
                                return;
                            }
                        }
                    }

                    var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited.deinit(self.scratch);
                    const is_never_alias = (ty_id < self.graph.types.len and self.graph.types[ty_id].kind == .never_type);
                    const target = try self.lowerType(ty_id, is_never_alias, tp_res.active, null, &visited, imports_used, needs_runtime);
                    try out_list.append(self.alloc, .{
                        .source_decl_id = decl_id,
                        .zig_ident = bound.zig_ident,
                        .logical_name = bound.logical_name,
                        .wire_name = bound.wire_name,
                        .is_exported = is_exported,
                        .is_js_exported = is_js_exported,
                        .is_default_export = is_default_export,
                        .is_global_scope = is_global_scope,
                        .default_companion_ident = alias_gt_comps.default_ident,
                        .with_companion_ident = alias_gt_comps.with_ident,
                        .jsdoc = top_jsdoc,
                        .kind = .{ .type_alias = .{ .type_params = tp_res.ir, .target = target } },
                    });
                },
                .namespace_decl => |children| {
                    const merged_children = try self.collectConsumedMergedNamespaceChildren(
                        decl_id,
                        bound.wire_name,
                        d.merged_with,
                        children,
                    );
                    var ns_scope = naming.ScopeNamer.initContainer(self.scratch, scope);
                    defer ns_scope.deinit();
                    try ns_scope.reserve("zigar_js");
                    for (merged_children) |cid| {
                        if (prebound_names.get(cid)) |cb| try ns_scope.reserve(cb.logical_name);
                        if (prebound_overloads.get(cid)) |ovs| {
                            for (ovs) |ov| try ns_scope.reserve(ov.logical_name);
                        }
                    }

                    const merged_call_slots = try self.prebindMergedCallFnSlots(
                        decl_id,
                        bound.wire_name,
                        d.merged_with,
                        true,
                        &ns_scope,
                        outer_active_tps,
                        imports_used,
                        needs_runtime,
                    );

                    var child_irs: std.ArrayList(DeclIr) = .empty;
                    for (merged_children) |cid| {
                        try self.lowerDeclIntoListInner(
                            final_mod_idx,
                            cid,
                            false,
                            &ns_scope,
                            prebound_names,
                            prebound_overloads,
                            outer_active_tps,
                            imports_used,
                            needs_runtime,
                            &child_irs,
                            active_decls,
                        );
                    }
                    try deduplicateDeclIrsInPlace(self.scratch, &child_irs);
                    const merged_call_fns = try self.finishMergedCallFns(
                        bound.wire_name,
                        merged_call_slots,
                        &ns_scope,
                        outer_active_tps,
                        imports_used,
                        needs_runtime,
                    );
                    try out_list.append(self.alloc, .{
                        .source_decl_id = decl_id,
                        .zig_ident = bound.zig_ident,
                        .logical_name = bound.logical_name,
                        .wire_name = bound.wire_name,
                        .is_exported = is_exported,
                        .is_js_exported = is_js_exported,
                        .is_default_export = is_default_export,
                        .is_global_scope = is_global_scope,
                        .jsdoc = top_jsdoc,
                        .kind = .{
                            .namespace_decl = .{
                                .merged_call_fns = merged_call_fns,
                                .children = try child_irs.toOwnedSlice(self.alloc),
                            },
                        },
                    });
                },
                .re_export_decl => |re| {
                    const eff_name = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                    if (re.is_namespace and std.mem.eql(u8, eff_name, "*")) return;
                    if (re.is_namespace) {
                        if (try self.resolveNamespaceReExportTargetMod(re)) |t_mod_idx| {
                            if (t_mod_idx != final_mod_idx) {
                                try imports_used.put(self.scratch, t_mod_idx, {});
                                try out_list.append(self.alloc, .{
                                    .source_decl_id = decl_id,
                                    .zig_ident = bound.zig_ident,
                                    .logical_name = bound.logical_name,
                                    .wire_name = bound.wire_name,
                                    .is_exported = true,
                                    .is_default_export = is_default_export,
                                    .jsdoc = top_jsdoc,
                                    .kind = .{
                                        .namespace_re_export = .{
                                            .target_module_index = t_mod_idx,
                                            .is_type_only = re.is_type_only,
                                        },
                                    },
                                });
                            }
                        }
                        return;
                    }
                    if (try self.resolveNamedReExportTargetLoc(d, re, 0)) |loc| {
                        const is_self_noop = is_top_level and
                            loc.module_index == final_mod_idx and
                            loc.zig_path.len == 1 and
                            (std.mem.eql(u8, loc.zig_path[0], bound.zig_ident) or
                                (re.export_alias == null and std.mem.eql(u8, loc.zig_path[0], bound.wire_name)));
                        if (!is_self_noop and loc.zig_path.len > 0) {
                            if (loc.module_index != final_mod_idx) {
                                try imports_used.put(self.scratch, loc.module_index, {});
                            }
                            try out_list.append(self.alloc, .{
                                .source_decl_id = decl_id,
                                .zig_ident = bound.zig_ident,
                                .logical_name = bound.logical_name,
                                .wire_name = bound.wire_name,
                                .is_exported = true,
                                .is_default_export = is_default_export,
                                .jsdoc = top_jsdoc,
                                .kind = .{
                                    .re_export_decl = .{
                                        .target_module_index = loc.module_index,
                                        .target_zig_path = loc.zig_path,
                                        .is_type_only = re.is_type_only,
                                    },
                                },
                            });
                        }
                    }
                },
                .import_equals_decl => |ie| {
                    if (!d.modifiers.export_decl) return;
                    if (ie.target_decl) |tdid| {
                        if (try self.resolveEffectiveReExportTarget(tdid, 0)) |loc| {
                            const is_self_noop = is_top_level and
                                loc.module_index == final_mod_idx and
                                loc.zig_path.len == 1 and
                                (std.mem.eql(u8, loc.zig_path[0], bound.zig_ident) or
                                    std.mem.eql(u8, loc.zig_path[0], bound.wire_name));
                            if (!is_self_noop and loc.zig_path.len > 0) {
                                if (loc.module_index != final_mod_idx) {
                                    try imports_used.put(self.scratch, loc.module_index, {});
                                }
                                try out_list.append(self.alloc, .{
                                    .source_decl_id = decl_id,
                                    .zig_ident = bound.zig_ident,
                                    .logical_name = bound.logical_name,
                                    .wire_name = bound.wire_name,
                                    .is_exported = true,
                                    .is_default_export = is_default_export,
                                    .jsdoc = top_jsdoc,
                                    .kind = .{
                                        .re_export_decl = .{
                                            .target_module_index = loc.module_index,
                                            .target_zig_path = loc.zig_path,
                                            .is_type_only = ie.is_type_only,
                                        },
                                    },
                                });
                            }
                        }
                    } else if (ie.module_specifier) |msid| {
                        if (try self.resolveSpecToCandidateIdx(self.str(msid))) |c_idx| {
                            if (self.candToFinalIndex(c_idx)) |t_mod_idx| {
                                if (t_mod_idx != final_mod_idx) {
                                    try imports_used.put(self.scratch, t_mod_idx, {});
                                    try out_list.append(self.alloc, .{
                                        .source_decl_id = decl_id,
                                        .zig_ident = bound.zig_ident,
                                        .logical_name = bound.logical_name,
                                        .wire_name = bound.wire_name,
                                        .is_exported = true,
                                        .is_default_export = is_default_export,
                                        .jsdoc = top_jsdoc,
                                        .kind = .{ .namespace_re_export = .{ .target_module_index = t_mod_idx } },
                                    });
                                }
                            }
                        }
                    }
                },
            }

            if (local_fallback_notes.items.len > 0 and out_list.items.len > out_start_idx) {
                var target_idx = out_start_idx;
                for (out_list.items[out_start_idx..], out_start_idx..) |cand_item, idx| {
                    if (!cand_item.is_synthetic_companion) {
                        target_idx = idx;
                        break;
                    }
                }
                const owned_notes = try self.alloc.dupe([]const u8, local_fallback_notes.items);
                out_list.items[target_idx].fallback_notes = owned_notes;
            }
        }

        fn chooseStructSelfIdent(
            self: *Self,
            raw_tps: []const u32,
            merged_ids: []const u32,
            parent_scope: *const naming.ScopeNamer,
            prebound_names: *const std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *const std.AutoHashMapUnmanaged(u32, []naming.BoundName),
        ) error{OutOfMemory}![]const u8 {
            // Preview type-parameter bindings against `parent_scope` so `preview_tp.used` reflects
            // this struct's comptime type parameters while `preview_tp.isTakenInAnyAncestor` checks
            // EVERY enclosing scope (`parent_scope` — which already contains this struct's own outer
            // declaration name AND all sibling declarations — plus all outer namespaces/structs/modules!).
            var preview_tp = naming.ScopeNamer.initParam(self.scratch, parent_scope);
            defer preview_tp.deinit();
            for (raw_tps) |tp_id| {
                const raw_tp = if (tp_id < self.graph.type_params.len) self.str(self.graph.type_params[tp_id].name) else "T";
                const b = try preview_tp.bindWithFallbackSuffix(raw_tp, .pascal, "T");
                b.deinit(self.scratch);
            }

            var merged_used: std.StringHashMapUnmanaged(void) = .empty;
            defer merged_used.deinit(self.scratch);
            for (merged_ids) |mid| {
                if (self.merged_ns_consumed.contains(mid)) {
                    for (self.graph.decls[mid].kind.namespace_decl) |cid| {
                        if (prebound_names.get(cid)) |cb| try merged_used.put(self.scratch, cb.logical_name, {});
                        if (prebound_overloads.get(cid)) |ovs| {
                            for (ovs) |ov| try merged_used.put(self.scratch, ov.logical_name, {});
                        }
                    }
                }
            }

            var suffix_n: usize = 1;
            while (true) : (suffix_n += 1) {
                const cand = if (suffix_n == 1)
                    try self.scratch.dupe(u8, "Self")
                else
                    try std.fmt.allocPrint(self.scratch, "Self_{d}", .{suffix_n});
                defer self.scratch.free(cand);

                if (!preview_tp.used.contains(cand) and
                    !preview_tp.isTakenInAnyAncestor(cand) and
                    !merged_used.contains(cand))
                {
                    return try self.alloc.dupe(u8, cand);
                }
            }
        }

        fn propsShareIdentity(self: *const Self, a_id: u32, b_id: u32) bool {
            if (a_id >= self.graph.properties.len or b_id >= self.graph.properties.len) return false;
            const a = self.graph.properties[a_id];
            const b = self.graph.properties[b_id];
            if (a.modifiers.static_mod != b.modifiers.static_mod) return false;
            if (a.computed_symbol != null or b.computed_symbol != null) {
                if (a.computed_symbol == null or b.computed_symbol == null) return false;
                return std.meta.eql(a.computed_symbol.?, b.computed_symbol.?);
            }
            return std.mem.eql(u8, self.str(a.name), self.str(b.name));
        }

        fn wrapUnsourcedProps(self: *Self, prop_ids: []const u32) error{OutOfMemory}![]SourcedProp {
            const res = try self.scratch.alloc(SourcedProp, prop_ids.len);
            for (prop_ids, 0..) |pid, idx| {
                res[idx] = .{ .pid = pid, .env = null };
            }
            return res;
        }

        const ObjectLiteralMemberSplit = struct {
            props: []SourcedProp,
            methods: []SourcedMethod,
        };

        fn collectMethodSigsFromType(
            self: *const Self,
            ty_id: u32,
            out_sigs: *std.ArrayList(u32),
            depth: usize,
        ) error{OutOfMemory}!void {
            if (depth > 8 or ty_id >= self.graph.types.len) return;
            switch (self.graph.types[ty_id].kind) {
                .function_type => |sid| {
                    for (out_sigs.items) |existing| {
                        if (existing == sid) return;
                    }
                    try out_sigs.append(self.scratch, sid);
                },
                .object_literal => |obj| {
                    if (obj.properties.len == 0 and obj.construct_signatures.len == 0 and obj.index_signatures.len == 0) {
                        for (obj.call_signatures) |sid| {
                            var seen = false;
                            for (out_sigs.items) |existing| {
                                if (existing == sid) {
                                    seen = true;
                                    break;
                                }
                            }
                            if (!seen) try out_sigs.append(self.scratch, sid);
                        }
                    }
                },
                .intersection, .union_type => |parts| {
                    for (parts) |part_id| {
                        try self.collectMethodSigsFromType(part_id, out_sigs, depth + 1);
                    }
                },
                else => {},
            }
        }

        fn splitObjectLiteralPropsAndMethods(self: *Self, prop_ids: []const u32) error{OutOfMemory}!ObjectLiteralMemberSplit {
            return self.splitObjectLiteralPropsAndMethodsWithEnv(prop_ids, null);
        }

        fn splitObjectLiteralPropsAndMethodsWithEnv(
            self: *Self,
            prop_ids: []const u32,
            env: ?*const HeritageEnv,
        ) error{OutOfMemory}!ObjectLiteralMemberSplit {
            var props: std.ArrayList(SourcedProp) = .empty;
            var methods: std.ArrayList(SourcedMethod) = .empty;
            for (prop_ids) |pid| {
                if (pid < self.graph.properties.len) {
                    const p = self.graph.properties[pid];
                    if (p.modifiers.method_mod and !p.has_getter and !p.has_setter) {
                        var sigs: std.ArrayList(u32) = .empty;
                        try self.collectMethodSigsFromType(p.ty, &sigs, 0);
                        if (sigs.items.len > 0) {
                            try methods.append(self.scratch, .{
                                .method = .{
                                    .name = p.name,
                                    .computed_symbol = p.computed_symbol,
                                    .signatures = try sigs.toOwnedSlice(self.scratch),
                                    .modifiers = p.modifiers,
                                    .jsdoc = p.jsdoc,
                                },
                                .env = env,
                            });
                            continue;
                        }
                        sigs.deinit(self.scratch);
                    }
                }
                try props.append(self.scratch, .{ .pid = pid, .env = env });
            }
            return .{
                .props = try props.toOwnedSlice(self.scratch),
                .methods = try methods.toOwnedSlice(self.scratch),
            };
        }

        fn wrapUnsourcedSigs(self: *Self, sig_ids: []const u32) error{OutOfMemory}![]SourcedSig {
            const res = try self.scratch.alloc(SourcedSig, sig_ids.len);
            for (sig_ids, 0..) |sid, idx| {
                res[idx] = .{ .sid = sid, .env = null };
            }
            return res;
        }

        fn wrapUnsourcedIndexSigs(self: *Self, index_sigs: []const IndexSigNodeType) error{OutOfMemory}![]SourcedIndexSig {
            const res = try self.scratch.alloc(SourcedIndexSig, index_sigs.len);
            for (index_sigs, 0..) |isig, idx| {
                res[idx] = .{ .sig = isig, .env = null };
            }
            return res;
        }

        fn wrapUnsourcedBases(self: *Self, part_ty_ids: []const u32) error{OutOfMemory}![]SourcedBaseClause {
            const res = try self.scratch.alloc(SourcedBaseClause, part_ty_ids.len);
            for (part_ty_ids, 0..) |tid, idx| {
                res[idx] = .{ .target_type = tid, .env = null };
            }
            return res;
        }

        fn appendUniqueSourcedSig(
            list: *std.ArrayList(SourcedSig),
            scratch: std.mem.Allocator,
            item: SourcedSig,
        ) error{OutOfMemory}!void {
            for (list.items) |existing| {
                if (existing.sid == item.sid) return;
            }
            try list.append(scratch, item);
        }

        fn upsertPropByWireName(self: *Self, list: *std.ArrayList(SourcedProp), sp: SourcedProp) error{OutOfMemory}!void {
            return self.upsertPropWithMode(list, sp, false);
        }

        fn upsertPropWithMode(
            self: *Self,
            list: *std.ArrayList(SourcedProp),
            sp: SourcedProp,
            prefer_required: bool,
        ) error{OutOfMemory}!void {
            if (sp.pid >= self.graph.properties.len) return;
            const new_prop = self.graph.properties[sp.pid];
            for (list.items, 0..) |existing, idx| {
                if (self.propsShareIdentity(existing.pid, sp.pid)) {
                    if (prefer_required and existing.pid < self.graph.properties.len) {
                        const old_prop = self.graph.properties[existing.pid];
                        if (!old_prop.modifiers.optional_mod and new_prop.modifiers.optional_mod) {
                            if (!sp.from_class_base) list.items[idx].from_class_base = false;
                            return;
                        }
                    }
                    list.items[idx] = sp;
                    return;
                }
            }
            try list.append(self.scratch, sp);
        }

        fn graphTypesEquivalent(
            self: *const Self,
            ty_a: u32,
            env_a: ?*const HeritageEnv,
            ty_b: u32,
            env_b: ?*const HeritageEnv,
            depth: usize,
        ) bool {
            if (depth > 8) return ty_a == ty_b and env_a == env_b;
            const ra = self.resolvePropGraphTypeForLiteralConstraint(ty_a, env_a, 0);
            const rb = self.resolvePropGraphTypeForLiteralConstraint(ty_b, env_b, 0);
            if (ra >= self.graph.types.len or rb >= self.graph.types.len) return ra == rb;
            if (ra == rb and env_a == env_b) return true;

            const ka = self.graph.types[ra].kind;
            const kb = self.graph.types[rb].kind;
            if (std.meta.activeTag(ka) != std.meta.activeTag(kb)) return false;

            return switch (ka) {
                .any_type,
                .unknown_type,
                .never_type,
                .void_type,
                .undefined_type,
                .null_type,
                .boolean_type,
                .number_type,
                .bigint_type,
                .string_type,
                .symbol_type,
                .object_type,
                .this_type,
                => true,
                .literal => |la| switch (la) {
                    .str => |sa| std.mem.eql(u8, self.str(sa), self.str(kb.literal.str)),
                    .num => |na| na == kb.literal.num,
                    .boolean => |ba| ba == kb.literal.boolean,
                    .bigint_literal => |ba| std.mem.eql(u8, self.str(ba), self.str(kb.literal.bigint_literal)),
                },
                .array, .readonly_array => |ea| self.graphTypesEquivalent(
                    ea,
                    env_a,
                    if (kb == .array) kb.array else kb.readonly_array,
                    env_b,
                    depth + 1,
                ),
                .reference => |ref_a| blk: {
                    const ref_b = kb.reference;
                    if (ref_a.target_decl != ref_b.target_decl) break :blk false;
                    if (!std.mem.eql(u8, self.str(ref_a.target_name), self.str(ref_b.target_name))) break :blk false;
                    if (ref_a.type_args.len != ref_b.type_args.len) break :blk false;
                    for (ref_a.type_args, ref_b.type_args) |ta, tb| {
                        if (!self.graphTypesEquivalent(ta, env_a, tb, env_b, depth + 1)) break :blk false;
                    }
                    break :blk true;
                },
                else => ra == rb and env_a == env_b,
            };
        }

        fn signaturesEquivalentInGraph(
            self: *const Self,
            sid_a: u32,
            env_a: ?*const HeritageEnv,
            sid_b: u32,
            env_b: ?*const HeritageEnv,
        ) bool {
            if (sid_a == sid_b and env_a == env_b) return true;
            if (sid_a >= self.graph.signatures.len or sid_b >= self.graph.signatures.len) return false;
            const sa = self.graph.signatures[sid_a];
            const sb = self.graph.signatures[sid_b];
            if (sa.type_params.len != sb.type_params.len) return false;
            if (sa.params.len != sb.params.len) return false;
            if ((sa.type_predicate != null) != (sb.type_predicate != null)) return false;
            for (sa.params, sb.params) |pa, pb| {
                if (pa.optional != pb.optional or pa.rest != pb.rest) return false;
                if (!self.graphTypesEquivalent(pa.ty, env_a, pb.ty, env_b, 0)) return false;
            }
            return self.graphTypesEquivalent(sa.return_type, env_a, sb.return_type, env_b, 0);
        }

        fn methodsShareSlotName(self: *const Self, a: MethodNodeType, b: MethodNodeType) bool {
            if (a.modifiers.static_mod != b.modifiers.static_mod) return false;
            if (a.computed_symbol != null or b.computed_symbol != null) {
                return a.computed_symbol != null and b.computed_symbol != null and
                    std.meta.eql(a.computed_symbol.?, b.computed_symbol.?);
            }
            return std.mem.eql(u8, self.str(a.name), self.str(b.name));
        }

        fn appendMethodDedupOverloads(self: *Self, list: *std.ArrayList(SourcedMethod), sm: SourcedMethod) error{OutOfMemory}!void {
            const m = sm.method;
            if (m.signatures.len == 0) {
                for (list.items) |existing_sm| {
                    if (self.methodsShareSlotName(existing_sm.method, m)) return;
                }
                try list.append(self.scratch, sm);
                return;
            }

            var kept_sigs: std.ArrayList(u32) = .empty;
            for (m.signatures) |sid| {
                var is_dup = false;
                outer: for (list.items) |existing_sm| {
                    if (!self.methodsShareSlotName(existing_sm.method, m)) continue;
                    for (existing_sm.method.signatures) |esid| {
                        if (self.signaturesEquivalentInGraph(esid, existing_sm.env, sid, sm.env)) {
                            is_dup = true;
                            break :outer;
                        }
                    }
                }
                if (!is_dup) {
                    try kept_sigs.append(self.scratch, sid);
                }
            }
            if (kept_sigs.items.len == 0) {
                kept_sigs.deinit(self.scratch);
                return;
            }
            var filtered_method = m;
            filtered_method.signatures = try kept_sigs.toOwnedSlice(self.scratch);
            try list.append(self.scratch, .{
                .method = filtered_method,
                .env = sm.env,
            });
        }

        fn buildHeritageEnv(
            self: *Self,
            parent_env: ?*const HeritageEnv,
            base_tps: []const u32,
            hc_type_args: []const u32,
        ) error{OutOfMemory}!?*const HeritageEnv {
            if (base_tps.len == 0) return null;
            const bindings = try self.scratch.alloc(HeritageBinding, base_tps.len);
            for (base_tps, 0..) |tp_id, i| {
                const tp_name = if (tp_id < self.graph.type_params.len)
                    self.str(self.graph.type_params[tp_id].name)
                else
                    "";
                if (i < hc_type_args.len) {
                    bindings[i] = .{
                        .ts_name = tp_name,
                        .arg_ty_id = hc_type_args[i],
                        .arg_in_self_env = false,
                    };
                } else if (tp_id < self.graph.type_params.len and self.graph.type_params[tp_id].default_type != null) {
                    bindings[i] = .{
                        .ts_name = tp_name,
                        .arg_ty_id = self.graph.type_params[tp_id].default_type,
                        .arg_in_self_env = true,
                    };
                } else if (tp_id < self.graph.type_params.len and self.graph.type_params[tp_id].constraint != null) {
                    bindings[i] = .{
                        .ts_name = tp_name,
                        .arg_ty_id = self.graph.type_params[tp_id].constraint,
                        .arg_in_self_env = true,
                    };
                } else {
                    bindings[i] = .{
                        .ts_name = tp_name,
                        .arg_ty_id = null,
                        .arg_in_self_env = false,
                    };
                }
            }
            const env_ptr = try self.scratch.create(HeritageEnv);
            env_ptr.* = .{
                .bindings = bindings,
                .parent = parent_env,
            };
            return env_ptr;
        }

        fn resolveHeritageActiveTps(
            self: *Self,
            env_opt: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            depth: usize,
        ) error{OutOfMemory}![]const ActiveTypeParam {
            const env = env_opt orelse return owner_active_tps;
            if (cache.get(env)) |cached| return cached;
            if (depth >= 24) return owner_active_tps;

            const parent_active = try self.resolveHeritageActiveTps(
                env.parent,
                owner_active_tps,
                self_ident_opt,
                imports_used,
                needs_runtime,
                cache,
                depth + 1,
            );

            const list = try self.scratch.alloc(ActiveTypeParam, env.bindings.len);
            var built_len: usize = 0;
            for (env.bindings, 0..) |b, idx| {
                const sub_ty: *TypeIr = if (b.arg_ty_id) |aty_id| blk: {
                    var v: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer v.deinit(self.scratch);
                    const eval_tps = if (b.arg_in_self_env) list[0..built_len] else parent_active;
                    break :blk try self.lowerGenericTypeArg(
                        aty_id,
                        eval_tps,
                        self_ident_opt,
                        &v,
                        imports_used,
                        needs_runtime,
                    );
                } else blk: {
                    needs_runtime.* = true;
                    break :blk try self.makeType(.js_any);
                };
                list[idx] = .{
                    .ts_name = b.ts_name,
                    .zig_ident = "",
                    .subst_ty = sub_ty,
                };
                built_len = idx + 1;
            }
            try cache.put(self.scratch, env, list);
            return list;
        }

        fn resolvePropGraphTypeForLiteralConstraint(
            self: *const Self,
            prop_ty_id: u32,
            env_opt: ?*const HeritageEnv,
            depth: usize,
        ) u32 {
            if (depth >= 16 or prop_ty_id >= self.graph.types.len) return prop_ty_id;
            const env = env_opt orelse return prop_ty_id;
            const tn = self.graph.types[prop_ty_id];
            const tp_name: ?[]const u8 = switch (tn.kind) {
                .type_param, .infer_type => |tp_id| if (tp_id < self.graph.type_params.len)
                    self.str(self.graph.type_params[tp_id].name)
                else
                    null,
                .reference => |ref| if (ref.target_decl == null and ref.type_args.len == 0)
                    self.str(ref.target_name)
                else
                    null,
                else => null,
            };
            const name = tp_name orelse return prop_ty_id;
            var i: usize = env.bindings.len;
            while (i > 0) {
                i -= 1;
                const b = env.bindings[i];
                if (std.mem.eql(u8, b.ts_name, name)) {
                    const aty = b.arg_ty_id orelse return prop_ty_id;
                    const next_env = if (b.arg_in_self_env) env else env.parent;
                    return self.resolvePropGraphTypeForLiteralConstraint(aty, next_env, depth + 1);
                }
            }
            return prop_ty_id;
        }

        fn resolveHeritageTargetDecl(self: *const Self, hc: anytype) ?u32 {
            if (hc.target_decl) |td| {
                if (td < self.graph.decls.len) return td;
            }
            if (hc.target_type < self.graph.types.len) {
                const tn = self.graph.types[hc.target_type];
                if (tn.kind == .reference) {
                    if (tn.kind.reference.target_decl) |td| {
                        if (td < self.graph.decls.len) return td;
                    }
                }
            }
            return null;
        }

        const InheritedCtorLookup = union(enum) {
            inherited_sigs: []SourcedSig,
            default_zero_arg,
            unknown_external_base,
        };

        fn collectInheritedClassCtors(
            self: *Self,
            initial_hc: anytype,
        ) error{OutOfMemory}!InheritedCtorLookup {
            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);

            var cur_hc = initial_hc;
            var cur_env: ?*const HeritageEnv = null;
            var depth: usize = 0;
            while (depth < 32) : (depth += 1) {
                const base_did = self.resolveHeritageTargetDecl(cur_hc) orelse return .unknown_external_base;
                if (self.isBundledLibDecl(base_did)) return .unknown_external_base;
                if (visited.contains(base_did)) return .unknown_external_base;
                try visited.put(self.scratch, base_did, {});

                const bd = self.graph.decls[base_did];
                if (bd.kind != .class_decl) return .unknown_external_base;
                const child_env = try self.buildHeritageEnv(cur_env, bd.type_params, cur_hc.type_args);
                const bcls = bd.kind.class_decl;
                if (bcls.constructors.len > 0) {
                    const out = try self.scratch.alloc(SourcedSig, bcls.constructors.len);
                    for (bcls.constructors, 0..) |sid, idx| {
                        out[idx] = .{ .sid = sid, .env = child_env };
                    }
                    return .{ .inherited_sigs = out };
                }
                if (bcls.extends_clause) |next_hc| {
                    cur_hc = next_hc;
                    cur_env = child_env;
                } else {
                    return .default_zero_arg;
                }
            }
            return .unknown_external_base;
        }

        fn collectInheritedHeritageClauses(
            self: *Self,
            parent_env: ?*const HeritageEnv,
            extends_clauses: anytype,
            out_props: *std.ArrayList(SourcedProp),
            out_methods: *std.ArrayList(SourcedMethod),
            out_call_sigs: *std.ArrayList(SourcedSig),
            out_construct_sigs: *std.ArrayList(SourcedSig),
            out_index_sigs: *std.ArrayList(SourcedIndexSig),
            seen_methods: *std.StringHashMapUnmanaged(void),
            derived_methods: *std.StringHashMapUnmanaged(void),
            visited_bases: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            if (extends_clauses.len <= 1) {
                for (extends_clauses) |hc| {
                    try self.collectInheritedHeritageClause(
                        parent_env,
                        hc,
                        out_props,
                        out_methods,
                        out_call_sigs,
                        out_construct_sigs,
                        out_index_sigs,
                        seen_methods,
                        derived_methods,
                        visited_bases,
                    );
                }
                return;
            }

            // Clone `seen_methods` per sibling heritage clause so sibling `extends Left, Right`
            // preserve overloaded methods from both siblings while `appendMethodDedupOverloads`
            // deduplicates identical signatures and `visited_bases` prevents diamond repetition!
            var merged_seen = try seen_methods.clone(self.scratch);
            defer merged_seen.deinit(self.scratch);
            for (extends_clauses) |hc| {
                var branch_seen = try seen_methods.clone(self.scratch);
                defer branch_seen.deinit(self.scratch);
                try self.collectInheritedHeritageClause(
                    parent_env,
                    hc,
                    out_props,
                    out_methods,
                    out_call_sigs,
                    out_construct_sigs,
                    out_index_sigs,
                    &branch_seen,
                    derived_methods,
                    visited_bases,
                );
                var bit = branch_seen.keyIterator();
                while (bit.next()) |k| try merged_seen.put(self.scratch, k.*, {});
            }
            var mit = merged_seen.keyIterator();
            while (mit.next()) |k| try seen_methods.put(self.scratch, k.*, {});
        }

        fn collectObjectIntersectionMembers(
            self: *Self,
            ty_id: u32,
            out_props: *std.ArrayList(SourcedProp),
            out_methods: *std.ArrayList(SourcedMethod),
            out_call_sigs: *std.ArrayList(SourcedSig),
            out_construct_sigs: *std.ArrayList(SourcedSig),
            out_index_sigs: *std.ArrayList(SourcedIndexSig),
        ) error{OutOfMemory}!bool {
            var seen_methods: std.StringHashMapUnmanaged(void) = .empty;
            defer seen_methods.deinit(self.scratch);
            var derived_methods: std.StringHashMapUnmanaged(void) = .empty;
            defer derived_methods.deinit(self.scratch);
            var visited_bases: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited_bases.deinit(self.scratch);
            var newly_seen: std.ArrayList([]const u8) = .empty;
            defer newly_seen.deinit(self.scratch);
            return self.collectStructuralTypeMembers(
                ty_id,
                null,
                out_props,
                out_methods,
                out_call_sigs,
                out_construct_sigs,
                out_index_sigs,
                &seen_methods,
                &derived_methods,
                &visited_bases,
                &newly_seen,
                true,
                0,
            );
        }

        fn collectStructuralTypeMembers(
            self: *Self,
            ty_id: u32,
            env: ?*const HeritageEnv,
            out_props: *std.ArrayList(SourcedProp),
            out_methods: *std.ArrayList(SourcedMethod),
            out_call_sigs: *std.ArrayList(SourcedSig),
            out_construct_sigs: *std.ArrayList(SourcedSig),
            out_index_sigs: *std.ArrayList(SourcedIndexSig),
            seen_methods: *std.StringHashMapUnmanaged(void),
            derived_methods: *std.StringHashMapUnmanaged(void),
            visited_bases: *std.AutoHashMapUnmanaged(u32, void),
            newly_seen_methods: *std.ArrayList([]const u8),
            prefer_required_props: bool,
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (ty_id >= self.graph.types.len or depth > 16) return false;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .function_type => |sid| {
                    try appendUniqueSourcedSig(out_call_sigs, self.scratch, .{ .sid = sid, .env = env });
                    return true;
                },
                .constructor_type => |sid| {
                    try appendUniqueSourcedSig(out_construct_sigs, self.scratch, .{ .sid = sid, .env = env });
                    return true;
                },
                .object_literal => |obj| {
                    const split = try self.splitObjectLiteralPropsAndMethodsWithEnv(obj.properties, env);
                    for (split.methods) |sm| {
                        if (sm.method.modifiers.static_mod or sm.method.modifiers.private_mod or
                            sm.method.modifiers.protected_mod or sm.method.computed_symbol != null)
                        {
                            continue;
                        }
                        const mw = self.str(sm.method.name);
                        if (!seen_methods.contains(mw)) {
                            try self.appendMethodDedupOverloads(out_methods, sm);
                            try newly_seen_methods.append(self.scratch, mw);
                        }
                    }
                    for (split.props) |sp| {
                        if (sp.pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[sp.pid];
                        if (p.modifiers.static_mod or p.modifiers.private_mod or
                            p.modifiers.protected_mod or p.computed_symbol != null)
                        {
                            continue;
                        }
                        const pw = self.str(p.name);
                        if (!derived_methods.contains(pw)) {
                            try self.upsertPropWithMode(out_props, sp, prefer_required_props);
                        }
                        try newly_seen_methods.append(self.scratch, pw);
                    }
                    for (obj.call_signatures) |sid| {
                        try appendUniqueSourcedSig(out_call_sigs, self.scratch, .{ .sid = sid, .env = env });
                    }
                    for (obj.construct_signatures) |sid| {
                        try appendUniqueSourcedSig(out_construct_sigs, self.scratch, .{ .sid = sid, .env = env });
                    }
                    for (obj.index_signatures) |isig| {
                        try out_index_sigs.append(self.scratch, .{ .sig = isig, .env = env });
                    }
                    return true;
                },
                .intersection => |parts| {
                    if (parts.len == 0 or
                        self.detectOpenPrimitiveIntersection(parts) != null or
                        self.detectBrandedPrimitiveIntersection(parts, 0) != null) return false;

                    var tmp_props: std.ArrayList(SourcedProp) = .empty;
                    defer tmp_props.deinit(self.scratch);
                    var tmp_methods: std.ArrayList(SourcedMethod) = .empty;
                    defer tmp_methods.deinit(self.scratch);
                    var tmp_calls: std.ArrayList(SourcedSig) = .empty;
                    defer tmp_calls.deinit(self.scratch);
                    var tmp_ctors: std.ArrayList(SourcedSig) = .empty;
                    defer tmp_ctors.deinit(self.scratch);
                    var tmp_index_sigs: std.ArrayList(SourcedIndexSig) = .empty;
                    defer tmp_index_sigs.deinit(self.scratch);
                    var tmp_bases = try visited_bases.clone(self.scratch);
                    defer tmp_bases.deinit(self.scratch);
                    var tmp_newly_seen: std.ArrayList([]const u8) = .empty;
                    defer tmp_newly_seen.deinit(self.scratch);

                    for (parts) |pid| {
                        var part_seen = try seen_methods.clone(self.scratch);
                        defer part_seen.deinit(self.scratch);
                        if (!try self.collectStructuralTypeMembers(
                            pid,
                            env,
                            &tmp_props,
                            &tmp_methods,
                            &tmp_calls,
                            &tmp_ctors,
                            &tmp_index_sigs,
                            &part_seen,
                            derived_methods,
                            &tmp_bases,
                            &tmp_newly_seen,
                            true,
                            depth + 1,
                        )) {
                            return false;
                        }
                    }

                    for (tmp_methods.items) |sm| try self.appendMethodDedupOverloads(out_methods, sm);
                    for (tmp_props.items) |sp| try self.upsertPropWithMode(out_props, sp, prefer_required_props);
                    for (tmp_calls.items) |ss| try appendUniqueSourcedSig(out_call_sigs, self.scratch, ss);
                    for (tmp_ctors.items) |ss| try appendUniqueSourcedSig(out_construct_sigs, self.scratch, ss);
                    for (tmp_index_sigs.items) |sis| try out_index_sigs.append(self.scratch, sis);
                    for (tmp_newly_seen.items) |mw| try newly_seen_methods.append(self.scratch, mw);
                    var bit = tmp_bases.keyIterator();
                    while (bit.next()) |k| try visited_bases.put(self.scratch, k.*, {});
                    return true;
                },
                .reference => |ref| {
                    const rname = self.str(ref.target_name);
                    if (self.isBuiltinMappedReference(rname, ref.type_args.len, ref.target_decl)) return false;
                    if (self.classifyBuiltinProtocolReference(rname, ref.target_decl) != null) return true;
                    if (std.mem.eql(u8, rname, "Array") or std.mem.eql(u8, rname, "ReadonlyArray") or
                        std.mem.eql(u8, rname, "Promise") or std.mem.eql(u8, rname, "PromiseLike") or
                        std.mem.eql(u8, rname, "Map") or std.mem.eql(u8, rname, "ReadonlyMap") or
                        std.mem.eql(u8, rname, "Set") or std.mem.eql(u8, rname, "ReadonlySet") or
                        std.mem.eql(u8, rname, "Record"))
                    {
                        return false;
                    }
                    if (ref.target_decl) |td| {
                        if (td >= self.graph.decls.len) return false;
                        const bd = self.graph.decls[td];
                        if (self.isBundledLibDecl(td)) {
                            if (bd.kind == .type_alias_decl) {
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id) {
                                        return self.collectStructuralTypeMembers(
                                            rt,
                                            env,
                                            out_props,
                                            out_methods,
                                            out_call_sigs,
                                            out_construct_sigs,
                                            out_index_sigs,
                                            seen_methods,
                                            derived_methods,
                                            visited_bases,
                                            newly_seen_methods,
                                            prefer_required_props,
                                            depth + 1,
                                        );
                                    }
                                }
                            }
                            return false;
                        }
                        switch (bd.kind) {
                            .interface_decl, .class_decl => {
                                var sub_seen = try seen_methods.clone(self.scratch);
                                defer sub_seen.deinit(self.scratch);
                                const before_methods = out_methods.items.len;
                                const before_props = out_props.items.len;
                                try self.collectInheritedDeclMembers(
                                    env,
                                    td,
                                    ref.type_args,
                                    out_props,
                                    out_methods,
                                    out_call_sigs,
                                    out_construct_sigs,
                                    out_index_sigs,
                                    &sub_seen,
                                    derived_methods,
                                    visited_bases,
                                    prefer_required_props,
                                );
                                for (out_methods.items[before_methods..]) |sm| {
                                    try newly_seen_methods.append(self.scratch, self.str(sm.method.name));
                                }
                                for (out_props.items[before_props..]) |sp| {
                                    if (sp.pid < self.graph.properties.len) {
                                        try newly_seen_methods.append(self.scratch, self.str(self.graph.properties[sp.pid].name));
                                    }
                                }
                                return true;
                            },
                            .type_alias_decl => |alias_ty| {
                                if (visited_bases.contains(td)) return true;
                                try visited_bases.put(self.scratch, td, {});
                                const child_env = try self.buildHeritageEnv(env, bd.type_params, ref.type_args);
                                if (try self.collectStructuralTypeMembers(
                                    alias_ty,
                                    child_env,
                                    out_props,
                                    out_methods,
                                    out_call_sigs,
                                    out_construct_sigs,
                                    out_index_sigs,
                                    seen_methods,
                                    derived_methods,
                                    visited_bases,
                                    newly_seen_methods,
                                    prefer_required_props,
                                    depth + 1,
                                )) {
                                    return true;
                                }
                                if (tn.resolved_type) |rt| {
                                    if (rt != ty_id) {
                                        return self.collectStructuralTypeMembers(
                                            rt,
                                            env,
                                            out_props,
                                            out_methods,
                                            out_call_sigs,
                                            out_construct_sigs,
                                            out_index_sigs,
                                            seen_methods,
                                            derived_methods,
                                            visited_bases,
                                            newly_seen_methods,
                                            prefer_required_props,
                                            depth + 1,
                                        );
                                    }
                                }
                                return false;
                            },
                            else => return false,
                        }
                    }
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) {
                            return self.collectStructuralTypeMembers(
                                rt,
                                env,
                                out_props,
                                out_methods,
                                out_call_sigs,
                                out_construct_sigs,
                                out_index_sigs,
                                seen_methods,
                                derived_methods,
                                visited_bases,
                                newly_seen_methods,
                                prefer_required_props,
                                depth + 1,
                            );
                        }
                    }
                    return false;
                },
                else => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) {
                            return self.collectStructuralTypeMembers(
                                rt,
                                env,
                                out_props,
                                out_methods,
                                out_call_sigs,
                                out_construct_sigs,
                                out_index_sigs,
                                seen_methods,
                                derived_methods,
                                visited_bases,
                                newly_seen_methods,
                                prefer_required_props,
                                depth + 1,
                            );
                        }
                    }
                    return false;
                },
            }
        }

        fn collectInheritedHeritageClause(
            self: *Self,
            parent_env: ?*const HeritageEnv,
            hc: anytype,
            out_props: *std.ArrayList(SourcedProp),
            out_methods: *std.ArrayList(SourcedMethod),
            out_call_sigs: *std.ArrayList(SourcedSig),
            out_construct_sigs: *std.ArrayList(SourcedSig),
            out_index_sigs: *std.ArrayList(SourcedIndexSig),
            seen_methods: *std.StringHashMapUnmanaged(void),
            derived_methods: *std.StringHashMapUnmanaged(void),
            visited_bases: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            if (self.resolveHeritageTargetDecl(hc)) |base_did| {
                const bd = self.graph.decls[base_did];
                if (self.isBundledLibDecl(base_did)) {
                    if (bd.kind == .type_alias_decl and hc.target_type < self.graph.types.len) {
                        var newly_seen: std.ArrayList([]const u8) = .empty;
                        defer newly_seen.deinit(self.scratch);
                        _ = try self.collectStructuralTypeMembers(
                            hc.target_type,
                            parent_env,
                            out_props,
                            out_methods,
                            out_call_sigs,
                            out_construct_sigs,
                            out_index_sigs,
                            seen_methods,
                            derived_methods,
                            visited_bases,
                            &newly_seen,
                            false,
                            0,
                        );
                        for (newly_seen.items) |mw| try seen_methods.put(self.scratch, mw, {});
                    }
                    return;
                }
                if (bd.kind == .interface_decl or bd.kind == .class_decl) {
                    try self.collectInheritedDeclMembers(
                        parent_env,
                        base_did,
                        hc.type_args,
                        out_props,
                        out_methods,
                        out_call_sigs,
                        out_construct_sigs,
                        out_index_sigs,
                        seen_methods,
                        derived_methods,
                        visited_bases,
                        false,
                    );
                    return;
                }
                if (bd.kind == .type_alias_decl) {
                    if (visited_bases.contains(base_did)) return;
                    try visited_bases.put(self.scratch, base_did, {});
                    const child_env = try self.buildHeritageEnv(parent_env, bd.type_params, hc.type_args);
                    var newly_seen: std.ArrayList([]const u8) = .empty;
                    defer newly_seen.deinit(self.scratch);
                    const ok = try self.collectStructuralTypeMembers(
                        bd.kind.type_alias_decl,
                        child_env,
                        out_props,
                        out_methods,
                        out_call_sigs,
                        out_construct_sigs,
                        out_index_sigs,
                        seen_methods,
                        derived_methods,
                        visited_bases,
                        &newly_seen,
                        false,
                        0,
                    );
                    if (!ok and hc.target_type < self.graph.types.len) {
                        if (self.graph.types[hc.target_type].resolved_type) |rt| {
                            if (rt != hc.target_type) {
                                _ = try self.collectStructuralTypeMembers(
                                    rt,
                                    parent_env,
                                    out_props,
                                    out_methods,
                                    out_call_sigs,
                                    out_construct_sigs,
                                    out_index_sigs,
                                    seen_methods,
                                    derived_methods,
                                    visited_bases,
                                    &newly_seen,
                                    false,
                                    0,
                                );
                            }
                        }
                    }
                    for (newly_seen.items) |mw| try seen_methods.put(self.scratch, mw, {});
                    return;
                }
                return;
            }

            if (hc.target_type < self.graph.types.len) {
                var newly_seen: std.ArrayList([]const u8) = .empty;
                defer newly_seen.deinit(self.scratch);
                _ = try self.collectStructuralTypeMembers(
                    hc.target_type,
                    parent_env,
                    out_props,
                    out_methods,
                    out_call_sigs,
                    out_construct_sigs,
                    out_index_sigs,
                    seen_methods,
                    derived_methods,
                    visited_bases,
                    &newly_seen,
                    false,
                    0,
                );
                for (newly_seen.items) |mw| try seen_methods.put(self.scratch, mw, {});
            }
        }

        fn collectInheritedDeclMembers(
            self: *Self,
            parent_env: ?*const HeritageEnv,
            base_did: u32,
            type_args: []const u32,
            out_props: *std.ArrayList(SourcedProp),
            out_methods: *std.ArrayList(SourcedMethod),
            out_call_sigs: *std.ArrayList(SourcedSig),
            out_construct_sigs: *std.ArrayList(SourcedSig),
            out_index_sigs: *std.ArrayList(SourcedIndexSig),
            seen_methods: *std.StringHashMapUnmanaged(void),
            derived_methods: *std.StringHashMapUnmanaged(void),
            visited_bases: *std.AutoHashMapUnmanaged(u32, void),
            prefer_required_props: bool,
        ) error{OutOfMemory}!void {
            if (self.isBundledLibDecl(base_did)) return;
            if (visited_bases.contains(base_did)) return;
            const bd = self.graph.decls[base_did];
            const b_wire = if (bd.export_name) |esid| self.str(esid) else self.str(bd.name);
            if (bd.kind != .interface_decl and bd.kind != .class_decl) return;

            const child_env = try self.buildHeritageEnv(parent_env, bd.type_params, type_args);
            const canon_base = self.canonicalMergedStructOwnerId(base_did);
            const base_is_class = (try self.classifyDecl(canon_base)).is_class;

            try visited_bases.put(self.scratch, base_did, {});
            for (bd.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].kind == .interface_decl) {
                    const md = self.graph.decls[mid];
                    const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                    if (merge_decls.sameWireName(b_wire, m_wire)) {
                        try visited_bases.put(self.scratch, mid, {});
                    }
                }
            }

            var bd_props: std.ArrayList(SourcedProp) = .empty;
            defer bd_props.deinit(self.scratch);
            var newly_seen_methods: std.ArrayList([]const u8) = .empty;
            defer newly_seen_methods.deinit(self.scratch);

            switch (bd.kind) {
                .interface_decl => |biface| {
                    for (biface.methods) |bm| {
                        if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                        const mw = self.str(bm.name);
                        if (!seen_methods.contains(mw)) {
                            try self.appendMethodDedupOverloads(out_methods, .{ .method = bm, .env = child_env });
                            try newly_seen_methods.append(self.scratch, mw);
                        }
                    }
                    for (biface.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                        const pw = self.str(p.name);
                        if (!derived_methods.contains(pw)) {
                            try self.upsertPropByWireName(&bd_props, .{ .pid = pid, .env = child_env, .from_class_base = base_is_class });
                        }
                        try newly_seen_methods.append(self.scratch, pw);
                    }
                    for (biface.call_signatures) |sid| try appendUniqueSourcedSig(out_call_sigs, self.scratch, .{ .sid = sid, .env = child_env });
                    for (biface.construct_signatures) |sid| try appendUniqueSourcedSig(out_construct_sigs, self.scratch, .{ .sid = sid, .env = child_env });
                    for (biface.index_signatures) |isig| try out_index_sigs.append(self.scratch, .{ .sig = isig, .env = child_env });
                },
                .class_decl => |bcls| {
                    for (bcls.methods) |bm| {
                        if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                        const mw = self.str(bm.name);
                        if (!seen_methods.contains(mw)) {
                            try self.appendMethodDedupOverloads(out_methods, .{ .method = bm, .env = child_env });
                            try newly_seen_methods.append(self.scratch, mw);
                        }
                    }
                    for (bcls.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                        const pw = self.str(p.name);
                        if (!derived_methods.contains(pw)) {
                            try self.upsertPropByWireName(&bd_props, .{ .pid = pid, .env = child_env, .from_class_base = true });
                        }
                        try newly_seen_methods.append(self.scratch, pw);
                    }
                    for (bcls.index_signatures) |isig| try out_index_sigs.append(self.scratch, .{ .sig = isig, .env = child_env });
                },
                else => unreachable,
            }

            // Also include same-symbol merged `interface_decl` members on `bd` at the same inheritance depth!
            for (bd.merged_with) |mid| {
                if (mid == base_did or mid >= self.graph.decls.len) continue;
                const mdecl = self.graph.decls[mid];
                if (mdecl.kind != .interface_decl) continue;
                const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                if (!merge_decls.sameWireName(b_wire, m_wire)) continue;
                const miface = mdecl.kind.interface_decl;
                for (miface.methods) |bm| {
                    if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                    const mw = self.str(bm.name);
                    if (!seen_methods.contains(mw)) {
                        try self.appendMethodDedupOverloads(out_methods, .{ .method = bm, .env = child_env });
                        try newly_seen_methods.append(self.scratch, mw);
                    }
                }
                for (miface.properties) |pid| {
                    if (pid >= self.graph.properties.len) continue;
                    const p = self.graph.properties[pid];
                    if (p.modifiers.static_mod or p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                    const pw = self.str(p.name);
                    if (!derived_methods.contains(pw)) {
                        try self.upsertPropByWireName(&bd_props, .{ .pid = pid, .env = child_env, .from_class_base = base_is_class });
                    }
                    try newly_seen_methods.append(self.scratch, pw);
                }
                for (miface.call_signatures) |sid| try appendUniqueSourcedSig(out_call_sigs, self.scratch, .{ .sid = sid, .env = child_env });
                if (bd.kind == .interface_decl) {
                    for (miface.construct_signatures) |sid| try appendUniqueSourcedSig(out_construct_sigs, self.scratch, .{ .sid = sid, .env = child_env });
                }
                for (miface.index_signatures) |isig| try out_index_sigs.append(self.scratch, .{ .sig = isig, .env = child_env });
            }

            // Record `bd`'s instance members BEFORE recursing into `GrandBase` so `bd` overrides `GrandBase`.
            var sub_derived_methods = try derived_methods.clone(self.scratch);
            defer sub_derived_methods.deinit(self.scratch);
            for (newly_seen_methods.items) |name| {
                try seen_methods.put(self.scratch, name, {});
            }
            switch (bd.kind) {
                .interface_decl => |biface| {
                    for (biface.methods) |bm| {
                        if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                        try sub_derived_methods.put(self.scratch, self.str(bm.name), {});
                    }
                },
                .class_decl => |bcls| {
                    for (bcls.methods) |bm| {
                        if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                        try sub_derived_methods.put(self.scratch, self.str(bm.name), {});
                    }
                },
                else => unreachable,
            }
            for (bd.merged_with) |mid| {
                if (mid == base_did or mid >= self.graph.decls.len) continue;
                const mdecl = self.graph.decls[mid];
                if (mdecl.kind != .interface_decl) continue;
                const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                if (!merge_decls.sameWireName(b_wire, m_wire)) continue;
                for (mdecl.kind.interface_decl.methods) |bm| {
                    if (bm.modifiers.static_mod or bm.modifiers.private_mod or bm.modifiers.protected_mod or bm.computed_symbol != null) continue;
                    try sub_derived_methods.put(self.scratch, self.str(bm.name), {});
                }
            }

            // Recurse into ancestors FIRST so ancestor properties precede `bd_props`!
            const props_start = out_props.items.len;
            switch (bd.kind) {
                .interface_decl => |biface| {
                    try self.collectInheritedHeritageClauses(
                        child_env,
                        biface.extends_clauses,
                        out_props,
                        out_methods,
                        out_call_sigs,
                        out_construct_sigs,
                        out_index_sigs,
                        seen_methods,
                        &sub_derived_methods,
                        visited_bases,
                    );
                },
                .class_decl => |bcls| {
                    if (bcls.extends_clause) |bhc| {
                        try self.collectInheritedHeritageClause(
                            child_env,
                            bhc,
                            out_props,
                            out_methods,
                            out_call_sigs,
                            out_construct_sigs,
                            out_index_sigs,
                            seen_methods,
                            &sub_derived_methods,
                            visited_bases,
                        );
                    }
                },
                else => unreachable,
            }
            for (bd.merged_with) |mid| {
                if (mid == base_did or mid >= self.graph.decls.len) continue;
                const mdecl = self.graph.decls[mid];
                if (mdecl.kind != .interface_decl) continue;
                const m_wire = if (mdecl.export_name) |esid| self.str(esid) else self.str(mdecl.name);
                if (!merge_decls.sameWireName(b_wire, m_wire)) continue;
                try self.collectInheritedHeritageClauses(
                    child_env,
                    mdecl.kind.interface_decl.extends_clauses,
                    out_props,
                    out_methods,
                    out_call_sigs,
                    out_construct_sigs,
                    out_index_sigs,
                    seen_methods,
                    &sub_derived_methods,
                    visited_bases,
                );
            }

            if (base_is_class) {
                for (out_props.items[props_start..]) |*anc_sp| {
                    anc_sp.from_class_base = true;
                }
            }

            for (bd_props.items) |sp| {
                try self.upsertPropWithMode(out_props, sp, prefer_required_props);
            }
        }

        fn lowerSourcedFields(
            self: *Self,
            sourced_props: []const SourcedProp,
            only_instance: bool,
            field_scope: *naming.ScopeNamer,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
        ) error{OutOfMemory}![]FieldIr {
            var list: std.ArrayList(FieldIr) = .empty;
            errdefer list.deinit(self.alloc);

            for (sourced_props) |sp| {
                const pid = sp.pid;
                if (pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                if (only_instance and p.modifiers.static_mod) continue;
                const wire = self.str(p.name);
                const bound = try field_scope.bind(wire, .snake);
                const zig_ident = try self.alloc.dupe(u8, bound.zig_ident);
                const logical = try self.alloc.dupe(u8, bound.logical_name);
                const wire_copy = try self.alloc.dupe(u8, bound.wire_name);
                bound.deinit(self.scratch);

                const field_active_tps = try self.resolveHeritageActiveTps(
                    sp.env,
                    owner_active_tps,
                    self_ident_opt,
                    imports_used,
                    needs_runtime,
                    env_cache,
                    0,
                );
                visited.clearRetainingCapacity();
                var f_ty = try self.lowerType(p.ty, false, field_active_tps, self_ident_opt, visited, imports_used, needs_runtime);
                var lit_constraint: ?FieldLiteralConstraintIr = null;
                if (p.modifiers.optional_mod) {
                    f_ty = try self.wrapOptional(f_ty);
                } else {
                    const lit_ty_id = self.resolvePropGraphTypeForLiteralConstraint(p.ty, sp.env, 0);
                    lit_constraint = try self.extractCompatibleFieldLiteralConstraint(lit_ty_id, f_ty);
                }

                try list.append(self.alloc, .{
                    .zig_ident = zig_ident,
                    .logical_name = logical,
                    .wire_name = wire_copy,
                    .ty = f_ty,
                    .is_optional = p.modifiers.optional_mod,
                    .is_readonly = p.modifiers.readonly_mod,
                    .nullish_kind = if (f_ty.* == .optional) f_ty.optional.nullish_kind else .none,
                    .literal_constraint = lit_constraint,
                    .jsdoc = try self.lowerJsDoc(p.jsdoc),
                });
            }

            return try list.toOwnedSlice(self.alloc);
        }

        const MergedCallFnSlot = struct {
            source_decl_id: u32,
            sig_id: u32,
            primary_zig_ident: []const u8,
            primary_logical_name: []const u8,
            is_default_export: bool,
            is_global_scope: bool,
            decl_jsdoc: ?JsDocIr,
        };

        fn prebindMergedCallFnSlots(
            self: *Self,
            owner_decl_id: u32,
            owner_wire: []const u8,
            merged_ids: []const u32,
            always_emit: bool,
            target_scope: *naming.ScopeNamer,
            outer_active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}![]MergedCallFnSlot {
            _ = outer_active_tps;
            _ = imports_used;
            _ = needs_runtime;
            var slots: std.ArrayList(MergedCallFnSlot) = .empty;
            var primary_zig_ident: ?[]const u8 = null;
            var primary_logical_name: ?[]const u8 = null;

            for (merged_ids) |mid| {
                if (mid == owner_decl_id or mid >= self.graph.decls.len) continue;
                const md = self.graph.decls[mid];
                if (md.kind != .function_decl) continue;
                if (md.modifiers.private_mod or md.modifiers.protected_mod) continue;
                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                if (!merge_decls.sameWireName(owner_wire, m_wire)) continue;
                if (!always_emit and !self.merged_fn_consumed.contains(mid) and target_scope.isTaken("call")) {
                    continue;
                }
                const decl_jsdoc = try self.lowerJsDoc(md.jsdoc);
                const is_global = self.global_aug_decls.contains(mid);
                for (md.kind.function_decl) |sid| {
                    if (primary_zig_ident == null) {
                        const cb = try target_scope.bind("call", .camel);
                        primary_zig_ident = try self.alloc.dupe(u8, cb.zig_ident);
                        primary_logical_name = try self.alloc.dupe(u8, cb.logical_name);
                        cb.deinit(self.scratch);
                    }
                    try slots.append(self.scratch, .{
                        .source_decl_id = mid,
                        .sig_id = sid,
                        .primary_zig_ident = primary_zig_ident.?,
                        .primary_logical_name = primary_logical_name.?,
                        .is_default_export = md.modifiers.default_export or
                            (std.mem.eql(u8, owner_wire, "default") and self.js_exported_decls.contains(mid)),
                        .is_global_scope = is_global,
                        .decl_jsdoc = decl_jsdoc,
                    });
                }
            }
            return try slots.toOwnedSlice(self.scratch);
        }

        fn finishMergedCallFns(
            self: *Self,
            owner_wire: []const u8,
            slots: []const MergedCallFnSlot,
            target_scope: *naming.ScopeNamer,
            outer_active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
        ) error{OutOfMemory}![]DeclIr {
            if (slots.len == 0) return &.{};
            needs_runtime.* = true;

            const primary_zig = slots[0].primary_zig_ident;
            const primary_logical = slots[0].primary_logical_name;

            var raw_sigs = try self.scratch.alloc(SignatureIr, slots.len);
            defer self.scratch.free(raw_sigs);
            for (slots, 0..) |slot, idx| {
                raw_sigs[idx] = try self.lowerSignature(
                    slot.sig_id,
                    target_scope,
                    false,
                    false,
                    slots.len > 1,
                    outer_active_tps,
                    null,
                    imports_used,
                    needs_runtime,
                );
            }

            const kept = try overloads.deduplicateSubsumedIndices(self.scratch, self.scratch, raw_sigs);
            defer self.scratch.free(kept);

            if (kept.len == 1) {
                const orig_idx = kept[0];
                const slot = slots[orig_idx];
                const raw_one = raw_sigs[orig_idx];
                const split_opt = try self.prepareAwaitedAndPromiseSig(raw_one);
                var sig_ir = if (split_opt) |sp| sp.awaited else raw_one;
                const comps = try self.bindSigCompanions(target_scope, primary_logical, &sig_ir);

                var prom_decl_opt: ?DeclIr = null;
                if (split_opt) |sp| {
                    var prom_sig = sp.promise_companion;
                    const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{primary_logical});
                    defer self.scratch.free(raw_prom);
                    const pb = try target_scope.bind(raw_prom, .camel);
                    const prom_zig = try self.alloc.dupe(u8, pb.zig_ident);
                    const prom_logical = try self.alloc.dupe(u8, pb.logical_name);
                    pb.deinit(self.scratch);
                    const prom_comps = try self.bindSigCompanions(target_scope, prom_logical, &prom_sig);
                    try self.refreshSigParamsAgainstScope(&prom_sig, target_scope);
                    prom_decl_opt = .{
                        .source_decl_id = slot.source_decl_id,
                        .zig_ident = prom_zig,
                        .logical_name = prom_logical,
                        .wire_name = try self.alloc.dupe(u8, owner_wire),
                        .is_exported = true,
                        .is_js_exported = false,
                        .is_default_export = slot.is_default_export,
                        .is_global_scope = slot.is_global_scope,
                        .is_synthetic_companion = true,
                        .alloc_companion_ident = prom_comps.alloc_ident,
                        .slice_companion_ident = prom_comps.slice_ident,
                        .slice_alloc_companion_ident = prom_comps.slice_alloc_ident,
                        .narrow_companion_ident = prom_comps.narrow_ident,
                        .narrow_alloc_companion_ident = prom_comps.narrow_alloc_ident,
                        .default_companion_ident = prom_comps.default_ident,
                        .default_alloc_companion_ident = prom_comps.default_alloc_ident,
                        .infer_companion_ident = prom_comps.infer_ident,
                        .infer_alloc_companion_ident = prom_comps.infer_alloc_ident,
                        .jsdoc = prom_sig.jsdoc orelse slot.decl_jsdoc,
                        .kind = .{ .function_decl = prom_sig },
                    };
                }

                try self.refreshSigParamsAgainstScope(&sig_ir, target_scope);
                var out = try self.alloc.alloc(DeclIr, if (prom_decl_opt != null) 2 else 1);
                out[0] = .{
                    .source_decl_id = slot.source_decl_id,
                    .zig_ident = primary_zig,
                    .logical_name = primary_logical,
                    .wire_name = try self.alloc.dupe(u8, owner_wire),
                    .is_exported = true,
                    .is_js_exported = false,
                    .is_default_export = slot.is_default_export,
                    .is_global_scope = slot.is_global_scope,
                    .alloc_companion_ident = comps.alloc_ident,
                    .slice_companion_ident = comps.slice_ident,
                    .slice_alloc_companion_ident = comps.slice_alloc_ident,
                    .narrow_companion_ident = comps.narrow_ident,
                    .narrow_alloc_companion_ident = comps.narrow_alloc_ident,
                    .default_companion_ident = comps.default_ident,
                    .default_alloc_companion_ident = comps.default_alloc_ident,
                    .infer_companion_ident = comps.infer_ident,
                    .infer_alloc_companion_ident = comps.infer_alloc_ident,
                    .jsdoc = sig_ir.jsdoc orelse slot.decl_jsdoc,
                    .kind = .{ .function_decl = sig_ir },
                };
                if (prom_decl_opt) |pd| out[1] = pd;
                return out;
            }

            var kept_sigs = try self.scratch.alloc(SignatureIr, kept.len);
            defer self.scratch.free(kept_sigs);
            var prom_sigs_list: std.ArrayList(SignatureIr) = .empty;
            defer prom_sigs_list.deinit(self.scratch);
            var prom_slot_indices: std.ArrayList(usize) = .empty;
            defer prom_slot_indices.deinit(self.scratch);

            for (kept, 0..) |orig_idx, ki| {
                if (try self.prepareAwaitedAndPromiseSig(raw_sigs[orig_idx])) |sp| {
                    kept_sigs[ki] = sp.awaited;
                    try prom_sigs_list.append(self.scratch, sp.promise_companion);
                    try prom_slot_indices.append(self.scratch, orig_idx);
                } else {
                    kept_sigs[ki] = raw_sigs[orig_idx];
                }
            }

            const sem_names = try overloads.assignSemanticOverloadNames(
                self.alloc,
                self.scratch,
                target_scope,
                primary_logical,
                kept_sigs,
            );
            var kept_comps = try self.scratch.alloc(BoundSigCompanions, kept.len);
            defer self.scratch.free(kept_comps);
            var any_alloc = false;
            for (0..kept.len) |ki| {
                kept_comps[ki] = try self.bindSigCompanions(target_scope, sem_names[ki].logical_name, &kept_sigs[ki]);
                if (kept_comps[ki].alloc_ident != null) any_alloc = true;
            }

            var disp_alloc_ident: ?[]const u8 = null;
            if (any_alloc) {
                const raw_da = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{primary_logical});
                defer self.scratch.free(raw_da);
                const dab = try target_scope.bind(raw_da, .camel);
                disp_alloc_ident = try self.alloc.dupe(u8, dab.zig_ident);
                dab.deinit(self.scratch);
            }

            var prom_primary_zig: ?[]const u8 = null;
            var prom_primary_logical: ?[]const u8 = null;
            var prom_sem_names: []overloads.BoundOverloadIdent = &.{};
            var prom_comps: []BoundSigCompanions = &.{};
            defer if (prom_comps.len > 0) self.scratch.free(prom_comps);
            var prom_disp_alloc_ident: ?[]const u8 = null;

            if (prom_sigs_list.items.len > 0) {
                const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{primary_logical});
                defer self.scratch.free(raw_prom);
                const pb = try target_scope.bind(raw_prom, .camel);
                prom_primary_zig = try self.alloc.dupe(u8, pb.zig_ident);
                prom_primary_logical = try self.alloc.dupe(u8, pb.logical_name);
                pb.deinit(self.scratch);

                if (prom_sigs_list.items.len == 1) {
                    prom_comps = try self.scratch.alloc(BoundSigCompanions, 1);
                    prom_comps[0] = try self.bindSigCompanions(target_scope, prom_primary_logical.?, &prom_sigs_list.items[0]);
                } else {
                    prom_sem_names = try overloads.assignSemanticOverloadNames(
                        self.alloc,
                        self.scratch,
                        target_scope,
                        prom_primary_logical.?,
                        prom_sigs_list.items,
                    );
                    prom_comps = try self.scratch.alloc(BoundSigCompanions, prom_sigs_list.items.len);
                    var prom_any_alloc = false;
                    for (0..prom_sigs_list.items.len) |pi| {
                        prom_comps[pi] = try self.bindSigCompanions(target_scope, prom_sem_names[pi].logical_name, &prom_sigs_list.items[pi]);
                        if (prom_comps[pi].alloc_ident != null) prom_any_alloc = true;
                    }
                    if (prom_any_alloc) {
                        const raw_pda = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{prom_primary_logical.?});
                        defer self.scratch.free(raw_pda);
                        const pdab = try target_scope.bind(raw_pda, .camel);
                        prom_disp_alloc_ident = try self.alloc.dupe(u8, pdab.zig_ident);
                        pdab.deinit(self.scratch);
                    }
                }
            }

            const disp_alloc_param = try lower_objects.chooseNonShadowingParamIdent(
                target_scope,
                self.scratch,
                self.alloc,
                "allocator",
            );

            var out_list: std.ArrayList(DeclIr) = .empty;
            var cands = try self.alloc.alloc(OverloadCandidateIr, kept.len);
            const wire_duped = try self.alloc.dupe(u8, owner_wire);
            for (0..kept.len) |ki| {
                const slot = slots[kept[ki]];
                try self.refreshSigParamsAgainstScope(&kept_sigs[ki], target_scope);
                cands[ki] = .{
                    .target_ident = sem_names[ki].zig_ident,
                    .alloc_target_ident = kept_comps[ki].alloc_ident,
                    .slice_target_ident = kept_comps[ki].slice_ident,
                    .infer_target_ident = kept_comps[ki].infer_ident,
                    .infer_alloc_target_ident = kept_comps[ki].infer_alloc_ident,
                    .default_target_ident = kept_comps[ki].default_ident,
                    .default_alloc_target_ident = kept_comps[ki].default_alloc_ident,
                    .signature = kept_sigs[ki],
                };
                try out_list.append(self.alloc, .{
                    .source_decl_id = slot.source_decl_id,
                    .zig_ident = sem_names[ki].zig_ident,
                    .logical_name = sem_names[ki].logical_name,
                    .wire_name = wire_duped,
                    .is_exported = true,
                    .is_js_exported = false,
                    .is_default_export = slot.is_default_export and ki == 0,
                    .is_global_scope = slot.is_global_scope,
                    .alloc_companion_ident = kept_comps[ki].alloc_ident,
                    .slice_companion_ident = kept_comps[ki].slice_ident,
                    .slice_alloc_companion_ident = kept_comps[ki].slice_alloc_ident,
                    .narrow_companion_ident = kept_comps[ki].narrow_ident,
                    .narrow_alloc_companion_ident = kept_comps[ki].narrow_alloc_ident,
                    .default_companion_ident = kept_comps[ki].default_ident,
                    .default_alloc_companion_ident = kept_comps[ki].default_alloc_ident,
                    .infer_companion_ident = kept_comps[ki].infer_ident,
                    .infer_alloc_companion_ident = kept_comps[ki].infer_alloc_ident,
                    .jsdoc = kept_sigs[ki].jsdoc orelse slot.decl_jsdoc,
                    .kind = .{ .function_decl = kept_sigs[ki] },
                });
            }
            const first_slot = slots[kept[0]];
            try out_list.append(self.alloc, .{
                .source_decl_id = first_slot.source_decl_id,
                .zig_ident = primary_zig,
                .logical_name = primary_logical,
                .wire_name = wire_duped,
                .is_exported = true,
                .is_js_exported = false,
                .is_default_export = false,
                .is_global_scope = first_slot.is_global_scope,
                .alloc_companion_ident = disp_alloc_ident,
                .jsdoc = first_slot.decl_jsdoc orelse kept_sigs[0].jsdoc,
                .kind = .{
                    .overload_dispatch = .{
                        .zig_ident = primary_zig,
                        .logical_name = primary_logical,
                        .alloc_companion_ident = disp_alloc_ident,
                        .alloc_param_ident = disp_alloc_param,
                        .is_static = true,
                        .is_constructor = false,
                        .mode = overloads.planDispatchMode(kept_sigs),
                        .candidates = cands,
                        .jsdoc = first_slot.decl_jsdoc orelse kept_sigs[0].jsdoc,
                    },
                },
            });

            if (prom_sigs_list.items.len == 1) {
                const pslot = slots[prom_slot_indices.items[0]];
                var psig = prom_sigs_list.items[0];
                try self.refreshSigParamsAgainstScope(&psig, target_scope);
                const pc = prom_comps[0];
                try out_list.append(self.alloc, .{
                    .source_decl_id = pslot.source_decl_id,
                    .zig_ident = prom_primary_zig.?,
                    .logical_name = prom_primary_logical.?,
                    .wire_name = wire_duped,
                    .is_exported = true,
                    .is_js_exported = false,
                    .is_default_export = pslot.is_default_export,
                    .is_global_scope = pslot.is_global_scope,
                    .is_synthetic_companion = true,
                    .alloc_companion_ident = pc.alloc_ident,
                    .slice_companion_ident = pc.slice_ident,
                    .slice_alloc_companion_ident = pc.slice_alloc_ident,
                    .narrow_companion_ident = pc.narrow_ident,
                    .narrow_alloc_companion_ident = pc.narrow_alloc_ident,
                    .default_companion_ident = pc.default_ident,
                    .default_alloc_companion_ident = pc.default_alloc_ident,
                    .infer_companion_ident = pc.infer_ident,
                    .infer_alloc_companion_ident = pc.infer_alloc_ident,
                    .jsdoc = psig.jsdoc orelse pslot.decl_jsdoc,
                    .kind = .{ .function_decl = psig },
                });
            } else if (prom_sigs_list.items.len > 1) {
                var prom_cands = try self.alloc.alloc(OverloadCandidateIr, prom_sigs_list.items.len);
                for (0..prom_sigs_list.items.len) |pi| {
                    const pslot = slots[prom_slot_indices.items[pi]];
                    const psig = &prom_sigs_list.items[pi];
                    try self.refreshSigParamsAgainstScope(psig, target_scope);
                    const pc = prom_comps[pi];
                    prom_cands[pi] = .{
                        .target_ident = prom_sem_names[pi].zig_ident,
                        .alloc_target_ident = pc.alloc_ident,
                        .slice_target_ident = pc.slice_ident,
                        .infer_target_ident = pc.infer_ident,
                        .infer_alloc_target_ident = pc.infer_alloc_ident,
                        .default_target_ident = pc.default_ident,
                        .default_alloc_target_ident = pc.default_alloc_ident,
                        .signature = psig.*,
                    };
                    try out_list.append(self.alloc, .{
                        .source_decl_id = pslot.source_decl_id,
                        .zig_ident = prom_sem_names[pi].zig_ident,
                        .logical_name = prom_sem_names[pi].logical_name,
                        .wire_name = wire_duped,
                        .is_exported = true,
                        .is_js_exported = false,
                        .is_default_export = pslot.is_default_export and pi == 0,
                        .is_global_scope = pslot.is_global_scope,
                        .is_synthetic_companion = true,
                        .alloc_companion_ident = pc.alloc_ident,
                        .slice_companion_ident = pc.slice_ident,
                        .slice_alloc_companion_ident = pc.slice_alloc_ident,
                        .narrow_companion_ident = pc.narrow_ident,
                        .narrow_alloc_companion_ident = pc.narrow_alloc_ident,
                        .default_companion_ident = pc.default_ident,
                        .default_alloc_companion_ident = pc.default_alloc_ident,
                        .infer_companion_ident = pc.infer_ident,
                        .infer_alloc_companion_ident = pc.infer_alloc_ident,
                        .jsdoc = psig.jsdoc orelse pslot.decl_jsdoc,
                        .kind = .{ .function_decl = psig.* },
                    });
                }
                const first_pslot = slots[prom_slot_indices.items[0]];
                try out_list.append(self.alloc, .{
                    .source_decl_id = first_pslot.source_decl_id,
                    .zig_ident = prom_primary_zig.?,
                    .logical_name = prom_primary_logical.?,
                    .wire_name = wire_duped,
                    .is_exported = true,
                    .is_js_exported = false,
                    .is_default_export = false,
                    .is_global_scope = first_pslot.is_global_scope,
                    .is_synthetic_companion = true,
                    .alloc_companion_ident = prom_disp_alloc_ident,
                    .jsdoc = first_pslot.decl_jsdoc orelse prom_sigs_list.items[0].jsdoc,
                    .kind = .{
                        .overload_dispatch = .{
                            .zig_ident = prom_primary_zig.?,
                            .logical_name = prom_primary_logical.?,
                            .alloc_companion_ident = prom_disp_alloc_ident,
                            .alloc_param_ident = disp_alloc_param,
                            .is_static = true,
                            .is_constructor = false,
                            .mode = overloads.planDispatchMode(prom_sigs_list.items),
                            .candidates = prom_cands,
                            .jsdoc = first_pslot.decl_jsdoc orelse prom_sigs_list.items[0].jsdoc,
                        },
                    },
                });
            }
            return try out_list.toOwnedSlice(self.alloc);
        }

        fn expandIndexSigKeyGraphTypes(
            self: *const Self,
            key_ty_id: u32,
            out: *std.ArrayList(u32),
            depth: usize,
        ) error{OutOfMemory}!void {
            if (key_ty_id >= self.graph.types.len or depth > 8) return;
            const tn = self.graph.types[key_ty_id];
            switch (tn.kind) {
                .reference => |ref| {
                    if (ref.type_args.len == 0) {
                        if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                                const alias_ty_id = self.graph.decls[td].kind.type_alias_decl;
                                if (alias_ty_id < self.graph.types.len and self.graph.types[alias_ty_id].kind == .union_type) {
                                    const arms = self.graph.types[alias_ty_id].kind.union_type;
                                    var all_lits = arms.len > 0;
                                    for (arms) |aid| {
                                        if (aid >= self.graph.types.len or self.graph.types[aid].kind != .literal) {
                                            all_lits = false;
                                            break;
                                        }
                                    }
                                    if (!all_lits) {
                                        for (arms) |aid| try self.expandIndexSigKeyGraphTypes(aid, out, depth + 1);
                                        return;
                                    }
                                }
                            }
                        }
                    }
                    try out.append(self.scratch, key_ty_id);
                },
                .union_type => |arms| {
                    var all_lits = arms.len > 0;
                    for (arms) |aid| {
                        if (aid >= self.graph.types.len or self.graph.types[aid].kind != .literal) {
                            all_lits = false;
                            break;
                        }
                    }
                    if (all_lits) {
                        try out.append(self.scratch, key_ty_id);
                    } else {
                        for (arms) |aid| try self.expandIndexSigKeyGraphTypes(aid, out, depth + 1);
                    }
                },
                else => try out.append(self.scratch, key_ty_id),
            }
        }

        fn classifyGraphIndexKeyCategory(
            self: *const Self,
            key_ty_id: u32,
            depth: usize,
        ) lower_heritage.IndexKeyCategory {
            if (key_ty_id >= self.graph.types.len or depth > 8) return .other_key;
            return switch (self.graph.types[key_ty_id].kind) {
                .string_type => .string_key,
                .number_type => .number_key,
                .symbol_type, .unique_symbol => .symbol_key,
                .template_literal => .template_key,
                .intersection => |parts| blk: {
                    if (self.detectOpenPrimitiveIntersection(parts)) |base_kind| {
                        break :blk switch (base_kind) {
                            .str => .string_key,
                            .num => .number_key,
                            else => .other_key,
                        };
                    }
                    if (self.detectBrandedPrimitiveIntersection(parts, 0)) |bpk| {
                        break :blk switch (bpk) {
                            .str => .string_key,
                            .num => .number_key,
                            .symbol => .symbol_key,
                            else => .other_key,
                        };
                    }
                    break :blk .other_key;
                },
                .reference => |ref| blk: {
                    if (ref.type_args.len == 0) {
                        if (ref.target_decl) |td| {
                            if (td < self.graph.decls.len and self.graph.decls[td].kind == .type_alias_decl) {
                                break :blk self.classifyGraphIndexKeyCategory(
                                    self.graph.decls[td].kind.type_alias_decl,
                                    depth + 1,
                                );
                            }
                        }
                    }
                    break :blk .other_key;
                },
                else => .other_key,
            };
        }

        fn normalizeIndexKeyTypeAndCategory(
            self: *Self,
            graph_key_ty_id: u32,
            lowered_key_ty: *const TypeIr,
        ) error{OutOfMemory}!struct { ty: *const TypeIr, category: lower_heritage.IndexKeyCategory } {
            const graph_cat = self.classifyGraphIndexKeyCategory(graph_key_ty_id, 0);
            switch (lowered_key_ty.*) {
                .string_type, .js_string => return .{ .ty = lowered_key_ty, .category = .string_key },
                .f64_type, .i64_type => return .{ .ty = lowered_key_ty, .category = .number_key },
                .js_symbol => return .{ .ty = lowered_key_ty, .category = .symbol_key },
                .template_pattern => return .{ .ty = lowered_key_ty, .category = .template_key },
                .inline_enum => |en| {
                    var all_str = en.members.len > 0;
                    for (en.members) |m| {
                        if (m.alias_of_zig_ident != null) continue;
                        if (m.value != .str) all_str = false;
                    }
                    if (all_str or en.backing != .none) {
                        const cat: lower_heritage.IndexKeyCategory = if (graph_cat == .template_key) .template_key else .other_key;
                        return .{ .ty = lowered_key_ty, .category = cat };
                    }
                    return .{ .ty = try self.makeType(.js_any), .category = .other_key };
                },
                .open_literal_union => |olu| return switch (olu.base_kind) {
                    .str => .{ .ty = try self.makeType(.string_type), .category = .string_key },
                    .num => .{ .ty = try self.makeType(.f64_type), .category = .number_key },
                    else => .{ .ty = try self.makeType(.js_any), .category = .other_key },
                },
                .js_any, .js_unknown, .js_value => return .{ .ty = lowered_key_ty, .category = graph_cat },
                .decl_ref => |dr| {
                    if (graph_cat == .template_key) {
                        return .{ .ty = lowered_key_ty, .category = .template_key };
                    }
                    if (dr.target_decl_id < self.graph.decls.len) {
                        const td = self.graph.decls[dr.target_decl_id];
                        switch (td.kind) {
                            .enum_decl => |ed| {
                                var has_unknown = false;
                                var all_str = ed.members.len > 0;
                                var all_num = ed.members.len > 0;
                                for (ed.members) |em| {
                                    if (em.value) |ev| {
                                        switch (ev) {
                                            .str => all_num = false,
                                            .num => |n| {
                                                all_str = false;
                                                if (!std.math.isFinite(n)) has_unknown = true;
                                            },
                                            else => {
                                                all_str = false;
                                                all_num = false;
                                                has_unknown = true;
                                            },
                                        }
                                    } else {
                                        all_str = false;
                                        all_num = false;
                                        has_unknown = true;
                                    }
                                }
                                if (!has_unknown and (all_str or all_num)) {
                                    return .{ .ty = lowered_key_ty, .category = .other_key };
                                }
                            },
                            .type_alias_decl => |ta_ty_id| {
                                if (ta_ty_id < self.graph.types.len) {
                                    const atk = self.graph.types[ta_ty_id].kind;
                                    if (atk == .string_type or atk == .number_type or atk == .symbol_type or
                                        atk == .unique_symbol or atk == .template_literal)
                                    {
                                        return .{ .ty = lowered_key_ty, .category = graph_cat };
                                    }
                                    if (atk == .union_type) {
                                        const arms = atk.union_type;
                                        var all_str = arms.len > 0;
                                        var all_num = arms.len > 0;
                                        for (arms) |aid| {
                                            if (aid >= self.graph.types.len or self.graph.types[aid].kind != .literal) {
                                                all_str = false;
                                                all_num = false;
                                                break;
                                            }
                                            switch (self.graph.types[aid].kind.literal) {
                                                .str => all_num = false,
                                                .num => all_str = false,
                                                else => {
                                                    all_str = false;
                                                    all_num = false;
                                                },
                                            }
                                        }
                                        if (all_str or all_num) {
                                            return .{ .ty = lowered_key_ty, .category = .other_key };
                                        }
                                    }
                                }
                            },
                            else => {},
                        }
                    }
                    if (graph_cat == .string_key) return .{ .ty = try self.makeType(.string_type), .category = .string_key };
                    if (graph_cat == .number_key) return .{ .ty = try self.makeType(.f64_type), .category = .number_key };
                    return .{ .ty = try self.makeType(.js_any), .category = .other_key };
                },
                else => {
                    if (graph_cat == .string_key) return .{ .ty = try self.makeType(.string_type), .category = .string_key };
                    if (graph_cat == .number_key) return .{ .ty = try self.makeType(.f64_type), .category = .number_key };
                    return .{ .ty = try self.makeType(.js_any), .category = .other_key };
                },
            }
        }

        fn canonicalMergedStructOwnerId(self: *const Self, did: u32) u32 {
            if (did >= self.graph.decls.len) return did;
            if (!self.merged_iface_consumed.contains(did)) return did;
            const d = self.graph.decls[did];
            const dw = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
            for (d.merged_with) |mid| {
                if (mid < self.graph.decls.len and !self.merged_iface_consumed.contains(mid)) {
                    const md = self.graph.decls[mid];
                    const mw = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                    if ((md.kind == .class_decl or md.kind == .interface_decl) and merge_decls.sameWireName(dw, mw)) {
                        return mid;
                    }
                }
            }
            return did;
        }

        fn isDeclEmittedAsStructWithRepr(
            self: *Self,
            did: u32,
            repr: classify_decls.ObjectDeclKind,
        ) error{OutOfMemory}!bool {
            if (did >= self.graph.decls.len) return false;
            if (self.isBundledLibDecl(did)) return false;
            if (!self.decl_locations.contains(did)) return false;
            const d = self.graph.decls[did];
            switch (d.kind) {
                .class_decl => return repr == .handle_wrapper,
                .interface_decl => return (try self.classifyDecl(did)).kind == repr,
                .type_alias_decl => |ta_ty_id| {
                    if (ta_ty_id >= self.graph.types.len) return false;
                    const tn = self.graph.types[ta_ty_id];
                    switch (tn.kind) {
                        .object_literal => return (try self.classifyDecl(did)).kind == repr,
                        .intersection => |parts| {
                            if (parts.len == 0 or
                                self.detectOpenPrimitiveIntersection(parts) != null or
                                self.detectBrandedPrimitiveIntersection(parts, 0) != null) return false;
                            if ((try self.classifyDecl(did)).kind != repr) return false;
                            var p: std.ArrayList(SourcedProp) = .empty;
                            defer p.deinit(self.scratch);
                            var m: std.ArrayList(SourcedMethod) = .empty;
                            defer m.deinit(self.scratch);
                            var cs: std.ArrayList(SourcedSig) = .empty;
                            defer cs.deinit(self.scratch);
                            var ks: std.ArrayList(SourcedSig) = .empty;
                            defer ks.deinit(self.scratch);
                            var is: std.ArrayList(SourcedIndexSig) = .empty;
                            defer is.deinit(self.scratch);
                            return try self.collectObjectIntersectionMembers(ta_ty_id, &p, &m, &cs, &ks, &is);
                        },
                        else => return false,
                    }
                },
                else => return false,
            }
        }

        fn appendDirectBaseFromGraphType(
            self: *Self,
            owner_decl_id: u32,
            repr: classify_decls.ObjectDeclKind,
            ty_id: u32,
            env: ?*const HeritageEnv,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited_ty: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
            out: *std.ArrayList(*const TypeIr),
            depth: usize,
        ) error{OutOfMemory}!void {
            if (ty_id >= self.graph.types.len or depth > 12) return;
            const tn = self.graph.types[ty_id];
            switch (tn.kind) {
                .intersection => |parts| {
                    if (self.detectOpenPrimitiveIntersection(parts) != null or
                        self.detectBrandedPrimitiveIntersection(parts, 0) != null) return;
                    for (parts) |pid| {
                        try self.appendDirectBaseFromGraphType(
                            owner_decl_id,
                            repr,
                            pid,
                            env,
                            owner_active_tps,
                            self_ident_opt,
                            visited_ty,
                            imports_used,
                            needs_runtime,
                            env_cache,
                            out,
                            depth + 1,
                        );
                    }
                },
                .reference => |ref| {
                    if (repr == .handle_wrapper) {
                        if (self.classifyBuiltinProtocolReference(self.str(ref.target_name), ref.target_decl)) |pk| {
                            const proto_base_opt: ?TypeIr = switch (pk) {
                                .disposable => .js_disposable,
                                .async_disposable => .js_async_disposable,
                                else => null,
                            };
                            if (proto_base_opt) |pb_tag| {
                                needs_runtime.* = true;
                                const pb_ty = try self.makeType(pb_tag);
                                for (out.items) |existing| {
                                    if (typeIrEql(existing, pb_ty, 0)) return;
                                }
                                try out.append(self.alloc, pb_ty);
                            }
                            return;
                        }
                    }
                    const raw_td = ref.target_decl orelse {
                        if (tn.resolved_type) |rt| {
                            if (rt != ty_id) {
                                try self.appendDirectBaseFromGraphType(
                                    owner_decl_id,
                                    repr,
                                    rt,
                                    env,
                                    owner_active_tps,
                                    self_ident_opt,
                                    visited_ty,
                                    imports_used,
                                    needs_runtime,
                                    env_cache,
                                    out,
                                    depth + 1,
                                );
                            }
                        }
                        return;
                    };
                    const td = self.canonicalMergedStructOwnerId(raw_td);
                    if (td == owner_decl_id or td >= self.graph.decls.len) return;
                    if (self.isBundledLibDecl(td)) return;

                    if (try self.isDeclEmittedAsStructWithRepr(td, repr)) {
                        const active_tps = try self.resolveHeritageActiveTps(
                            env,
                            owner_active_tps,
                            self_ident_opt,
                            imports_used,
                            needs_runtime,
                            env_cache,
                            0,
                        );
                        visited_ty.clearRetainingCapacity();
                        const b_ty = try self.lowerType(
                            ty_id,
                            false,
                            active_tps,
                            self_ident_opt,
                            visited_ty,
                            imports_used,
                            needs_runtime,
                        );
                        if (b_ty.* == .decl_ref) {
                            var clean_dr = b_ty.decl_ref;
                            clean_dr.indirect = false;
                            const clean_ty = try self.makeType(.{ .decl_ref = clean_dr });
                            for (out.items) |existing| {
                                if (typeIrEql(existing, clean_ty, 0)) return;
                            }
                            try out.append(self.alloc, clean_ty);
                        }
                        return;
                    }

                    // Transparent non-struct `type_alias_decl` (`type Alias<U> = Base<U>` or conditional
                    // web-global `_Headers` / `_Response` / `_WebSocket` aliases): unwrap syntax first,
                    // then fall back to `tn.resolved_type` when the alias body is a conditional/mapped op.
                    const d = self.graph.decls[td];
                    if (d.kind == .type_alias_decl) {
                        const prev_len = out.items.len;
                        const child_env = try self.buildHeritageEnv(env, d.type_params, ref.type_args);
                        try self.appendDirectBaseFromGraphType(
                            owner_decl_id,
                            repr,
                            d.kind.type_alias_decl,
                            child_env,
                            owner_active_tps,
                            self_ident_opt,
                            visited_ty,
                            imports_used,
                            needs_runtime,
                            env_cache,
                            out,
                            depth + 1,
                        );
                        if (out.items.len == prev_len) {
                            if (tn.resolved_type) |rt| {
                                if (rt != ty_id) {
                                    try self.appendDirectBaseFromGraphType(
                                        owner_decl_id,
                                        repr,
                                        rt,
                                        env,
                                        owner_active_tps,
                                        self_ident_opt,
                                        visited_ty,
                                        imports_used,
                                        needs_runtime,
                                        env_cache,
                                        out,
                                        depth + 1,
                                    );
                                }
                            }
                        }
                    }
                },
                else => {
                    if (tn.resolved_type) |rt| {
                        if (rt != ty_id) {
                            try self.appendDirectBaseFromGraphType(
                                owner_decl_id,
                                repr,
                                rt,
                                env,
                                owner_active_tps,
                                self_ident_opt,
                                visited_ty,
                                imports_used,
                                needs_runtime,
                                env_cache,
                                out,
                                depth + 1,
                            );
                        }
                    }
                },
            }
        }

        fn resolveDirectStructBases(
            self: *Self,
            owner_decl_id: u32,
            repr: classify_decls.ObjectDeclKind,
            sourced_bases: []const SourcedBaseClause,
            owner_active_tps: []const ActiveTypeParam,
            self_ident_opt: ?[]const u8,
            visited_ty: *std.AutoHashMapUnmanaged(u32, void),
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            env_cache: *std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam),
        ) error{OutOfMemory}![]const *const TypeIr {
            if (sourced_bases.len == 0) return &.{};
            var out: std.ArrayList(*const TypeIr) = .empty;
            for (sourced_bases) |sb| {
                try self.appendDirectBaseFromGraphType(
                    owner_decl_id,
                    repr,
                    sb.target_type,
                    sb.env,
                    owner_active_tps,
                    self_ident_opt,
                    visited_ty,
                    imports_used,
                    needs_runtime,
                    env_cache,
                    &out,
                    0,
                );
            }
            return try out.toOwnedSlice(self.alloc);
        }

        fn lowerStructDecl(
            self: *Self,
            final_mod_idx: u32,
            owner_decl_id: u32,
            explicit_cls: classify_decls.DeclClassification,
            is_abstract: bool,
            allow_default_ctor: bool,
            raw_tps: []const u32,
            raw_ctors: []const u32,
            inherited_ctors: []const SourcedSig,
            raw_props: []const SourcedProp,
            companion_static_props: []const u32,
            raw_methods: []const SourcedMethod,
            call_sigs: []const SourcedSig,
            construct_sigs: []const SourcedSig,
            raw_index_sigs: []const SourcedIndexSig,
            sourced_bases: []const SourcedBaseClause,
            merged_ids: []const u32,
            parent_scope: *const naming.ScopeNamer,
            prebound_names: *const std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *const std.AutoHashMapUnmanaged(u32, []naming.BoundName),
            outer_active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            active_decls: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!StructDeclIr {
            const repr = explicit_cls.kind;
            const is_class = explicit_cls.is_class;
            const is_callable_handle = explicit_cls.is_callable_handle;
            const owner_is_class_decl = owner_decl_id < self.graph.decls.len and
                self.graph.decls[owner_decl_id].kind == .class_decl;
            const owner_is_iface_decl = owner_decl_id < self.graph.decls.len and
                self.graph.decls[owner_decl_id].kind == .interface_decl;
            const owner_wire: []const u8 = if (owner_decl_id < self.graph.decls.len) blk: {
                const od = self.graph.decls[owner_decl_id];
                break :blk if (od.export_name) |esid| self.str(esid) else self.str(od.name);
            } else "";

            const saved_in_handle = self.in_handle_struct;
            self.in_handle_struct = (repr == .handle_wrapper);
            defer self.in_handle_struct = saved_in_handle;

            if (repr == .handle_wrapper or is_class) {
                needs_runtime.* = true;
            }

            const self_ident = try self.chooseStructSelfIdent(
                raw_tps,
                merged_ids,
                parent_scope,
                prebound_names,
                prebound_overloads,
            );

            var tp_scope = naming.ScopeNamer.initParam(self.scratch, parent_scope);
            defer tp_scope.deinit();

            const tp_res = try self.lowerTypeParams(
                raw_tps,
                &tp_scope,
                outer_active_tps,
                self_ident,
                imports_used,
                needs_runtime,
            );

            var struct_scope = naming.ScopeNamer.initContainer(self.scratch, &tp_scope);
            defer struct_scope.deinit();
            try struct_scope.reserve("zigar_js");
            try struct_scope.reserve(self_ident);

            // Reserve merged namespace child decl names (and overloads) in `struct_scope` first.
            for (merged_ids) |mid| {
                if (self.merged_ns_consumed.contains(mid)) {
                    for (self.graph.decls[mid].kind.namespace_decl) |cid| {
                        if (prebound_names.get(cid)) |cb| try struct_scope.reserve(cb.logical_name);
                        if (prebound_overloads.get(cid)) |ovs| {
                            for (ovs) |ov| try struct_scope.reserve(ov.logical_name);
                        }
                    }
                }
            }

            var has_non_public_members = false;
            for (raw_props) |sp| {
                if (sp.pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[sp.pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) {
                    has_non_public_members = true;
                    break;
                }
            }
            for (raw_methods) |sm| {
                const m = sm.method;
                if (m.modifiers.private_mod or m.modifiers.protected_mod) {
                    has_non_public_members = true;
                    break;
                }
            }

            var visited: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer visited.deinit(self.scratch);
            var env_cache: std.AutoHashMapUnmanaged(*const HeritageEnv, []const ActiveTypeParam) = .empty;
            defer env_cache.deinit(self.scratch);

            const direct_bases = try self.resolveDirectStructBases(
                owner_decl_id,
                repr,
                sourced_bases,
                tp_res.active,
                self_ident,
                &visited,
                imports_used,
                needs_runtime,
                &env_cache,
            );

            if (repr == .value_struct) {
                const fields = try self.lowerSourcedFields(
                    raw_props,
                    true,
                    &struct_scope,
                    tp_res.active,
                    self_ident,
                    &visited,
                    imports_used,
                    needs_runtime,
                    &env_cache,
                );

                const merged_call_slots = if (owner_is_iface_decl and raw_tps.len == 0)
                    try self.prebindMergedCallFnSlots(
                        owner_decl_id,
                        owner_wire,
                        merged_ids,
                        false,
                        &struct_scope,
                        outer_active_tps,
                        imports_used,
                        needs_runtime,
                    )
                else
                    &[_]MergedCallFnSlot{};

                var nested_decls: std.ArrayList(DeclIr) = .empty;
                try self.lowerMergedStructNestedDecls(
                    final_mod_idx,
                    owner_decl_id,
                    merged_ids,
                    &struct_scope,
                    prebound_names,
                    prebound_overloads,
                    tp_res.active,
                    imports_used,
                    needs_runtime,
                    &nested_decls,
                    active_decls,
                );

                const to_js_ref_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "toJsRef");
                const from_js_ref_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "fromJsRef");
                const from_js_ref_alloc_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "fromJsRefAlloc");
                const as_ident = if (direct_bases.len > 0)
                    try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "as")
                else
                    null;
                if (to_js_ref_ident != null or from_js_ref_ident != null or from_js_ref_alloc_ident != null or as_ident != null) {
                    needs_runtime.* = true;
                }
                const merged_call_fns = try self.finishMergedCallFns(
                    owner_wire,
                    merged_call_slots,
                    &struct_scope,
                    outer_active_tps,
                    imports_used,
                    needs_runtime,
                );
                const self_param_ident = try lower_objects.chooseNonShadowingParamIdent(&struct_scope, self.scratch, self.alloc, "self");
                const raw_param_ident = try lower_objects.chooseNonShadowingParamIdent(&struct_scope, self.scratch, self.alloc, "raw");
                const alloc_param_ident = try lower_objects.chooseNonShadowingParamIdent(&struct_scope, self.scratch, self.alloc, "allocator");
                const base_tp_ident = try lower_objects.chooseNonShadowingParamIdent(&struct_scope, self.scratch, self.alloc, "Base");

                return .{
                    .repr = .value_struct,
                    .is_class = false,
                    .is_abstract = false,
                    .is_callable_handle = false,
                    .has_private_constructor = false,
                    .has_non_public_members = has_non_public_members,
                    .self_ident = self_ident,
                    .self_param_ident = self_param_ident,
                    .raw_param_ident = raw_param_ident,
                    .alloc_param_ident = alloc_param_ident,
                    .base_type_param_ident = base_tp_ident,
                    .to_js_ref_ident = to_js_ref_ident,
                    .from_js_ref_ident = from_js_ref_ident,
                    .from_js_ref_alloc_ident = from_js_ref_alloc_ident,
                    .as_ident = as_ident,
                    .bases = direct_bases,
                    .type_params = tp_res.ir,
                    .fields = fields,
                    .static_props = &.{},
                    .constructors = &.{},
                    .methods = &.{},
                    .merged_call_fns = merged_call_fns,
                    .nested_decls = try nested_decls.toOwnedSlice(self.alloc),
                };
            }

            // `.handle_wrapper`: pre-bind ALL struct-level declarations in `struct_scope` BEFORE
            // calling `lowerSignature` so Zig 0.17 function parameters NEVER shadow struct members!

            // 1. Static properties (`raw_props` with `static_mod` + `companion_static_props`).
            var static_prop_ids: std.ArrayList(u32) = .empty;
            defer static_prop_ids.deinit(self.scratch);
            for (raw_props) |sp| {
                const pid = sp.pid;
                if (pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) {
                    has_non_public_members = true;
                    continue;
                }
                if (!p.modifiers.static_mod) continue;
                if (p.computed_symbol != null) continue;
                try static_prop_ids.append(self.scratch, pid);
            }
            for (companion_static_props) |pid| {
                if (pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                if (p.computed_symbol != null) continue;
                const pwire = self.str(p.name);
                if (std.mem.eql(u8, pwire, "prototype")) continue;
                var dup = false;
                for (static_prop_ids.items) |epid| {
                    if (std.mem.eql(u8, self.str(self.graph.properties[epid].name), pwire)) {
                        dup = true;
                        break;
                    }
                }
                if (!dup) try static_prop_ids.append(self.scratch, pid);
            }

            var static_props: std.ArrayList(StaticPropIr) = .empty;
            for (static_prop_ids.items) |pid| {
                const p = self.graph.properties[pid];
                const wire = self.str(p.name);
                const access = lower_objects.analyzePropAccess(p);
                if (!access.is_readable and !access.is_writable) continue;

                const style: naming.NameStyle = if (isAllUpperOrUnderscore(wire)) .preserve else .snake;
                const sb = try struct_scope.bind(wire, style);
                defer sb.deinit(self.scratch);

                visited.clearRetainingCapacity();
                const primary_ty_id = if (!access.is_readable and access.is_writable) access.write_ty_id else access.read_ty_id;
                var sty = try self.lowerType(primary_ty_id, false, tp_res.active, self_ident, &visited, imports_used, needs_runtime);
                if (p.modifiers.optional_mod) {
                    sty = try self.wrapOptional(sty);
                }

                var setter_ty_ir: ?*const TypeIr = null;
                const access_kind: lower_objects.StaticPropAccessKind = if (!access.is_readable and access.is_writable)
                    .write_only
                else if (access.is_readable and !access.is_writable)
                    .read_only
                else if (access.has_divergent_setter) blk: {
                    visited.clearRetainingCapacity();
                    var wty = try self.lowerType(access.write_ty_id, false, tp_res.active, self_ident, &visited, imports_used, needs_runtime);
                    if (p.modifiers.optional_mod) wty = try self.wrapOptional(wty);
                    setter_ty_ir = wty;
                    break :blk .divergent_read_write;
                } else .read_write;

                var lit_opt: ?LiteralValueIr = null;
                if (access.is_literal_const_candidate and !p.modifiers.optional_mod and
                    p.ty < self.graph.types.len and self.graph.types[p.ty].kind == .literal)
                {
                    lit_opt = switch (self.graph.types[p.ty].kind.literal) {
                        .str => |sid| .{ .str = try self.alloc.dupe(u8, self.str(sid)) },
                        .num => |n| .{ .num = n },
                        .bigint_literal => |sid| .{ .bigint_val = try self.alloc.dupe(u8, self.str(sid)) },
                        .boolean => |b| .{ .boolean = b },
                    };
                } else {
                    needs_runtime.* = true;
                }

                try static_props.append(self.alloc, .{
                    .zig_ident = try self.alloc.dupe(u8, sb.zig_ident),
                    .logical_name = try self.alloc.dupe(u8, sb.logical_name),
                    .wire_name = try self.alloc.dupe(u8, sb.wire_name),
                    .ty = sty,
                    .setter_ty = setter_ty_ir,
                    .access_kind = access_kind,
                    .literal = lit_opt,
                    .jsdoc = try self.lowerJsDoc(p.jsdoc),
                });
            }

            // 2. Class / companion-var constructors (`init`, `init_2`, ...).
            //    `abstract class` declarations cannot be constructed directly via `new` (`TS2511`),
            //    even when they declare a `constructor(...)` signature for `super(...)` calls.
            var cand_ctor_sigs: std.ArrayList(SourcedSig) = .empty;
            defer cand_ctor_sigs.deinit(self.scratch);
            if (is_class and !is_abstract) {
                if (raw_ctors.len > 0) {
                    for (raw_ctors) |sid| try cand_ctor_sigs.append(self.scratch, .{ .sid = sid, .env = null });
                } else if (inherited_ctors.len > 0) {
                    for (inherited_ctors) |ss| try cand_ctor_sigs.append(self.scratch, ss);
                } else {
                    for (construct_sigs) |ss| try cand_ctor_sigs.append(self.scratch, ss);
                }
            }
            var public_ctor_sigs: std.ArrayList(SourcedSig) = .empty;
            defer public_ctor_sigs.deinit(self.scratch);
            var saw_non_public_ctor = false;
            for (cand_ctor_sigs.items) |ss| {
                if (ss.sid < self.graph.signatures.len) {
                    const csig = self.graph.signatures[ss.sid];
                    if (csig.modifiers.private_mod or csig.modifiers.protected_mod) {
                        saw_non_public_ctor = true;
                        continue;
                    }
                }
                try public_ctor_sigs.append(self.scratch, ss);
            }
            const has_private_constructor = saw_non_public_ctor and (public_ctor_sigs.items.len == 0);
            const synthesize_default_ctor = owner_is_class_decl and
                !is_abstract and
                !has_private_constructor and
                cand_ctor_sigs.items.len == 0 and
                allow_default_ctor;

            const has_ctors = synthesize_default_ctor or public_ctor_sigs.items.len > 0;
            const ctor_count = if (synthesize_default_ctor) @as(usize, 1) else public_ctor_sigs.items.len;
            var ctor_primary_ident: []const u8 = "";
            var ctor_primary_logical: []const u8 = "";
            if (has_ctors) {
                const cb = try struct_scope.bind("init", .camel);
                ctor_primary_ident = try self.alloc.dupe(u8, cb.zig_ident);
                ctor_primary_logical = try self.alloc.dupe(u8, cb.logical_name);
                cb.deinit(self.scratch);
            }

            // 3. Explicit methods, call signatures, and standalone construct signatures (grouped by wire identity).
            const RawMethodEntry = struct {
                sig_id: u32,
                env: ?*const HeritageEnv,
                prop_jsdoc: ?JsDocIr,
            };
            const MethodGroupPlan = struct {
                primary_zig_ident: []const u8,
                primary_logical_name: []const u8,
                wire_name: []const u8,
                is_static: bool,
                call_kind: lower_objects.MethodCallKind,
                entries: std.ArrayList(RawMethodEntry) = .empty,
            };
            var method_groups: std.ArrayList(MethodGroupPlan) = .empty;
            defer {
                for (method_groups.items) |*mg| mg.entries.deinit(self.scratch);
                method_groups.deinit(self.scratch);
            }

            const appendMethodGroupSig = struct {
                fn add(
                    ctx: *Self,
                    sscope: *naming.ScopeNamer,
                    groups: *std.ArrayList(MethodGroupPlan),
                    wire_name: []const u8,
                    is_static: bool,
                    call_kind: lower_objects.MethodCallKind,
                    sig_id: u32,
                    env: ?*const HeritageEnv,
                    prop_jsdoc: ?JsDocIr,
                ) error{OutOfMemory}!void {
                    for (groups.items) |*g| {
                        if (g.is_static == is_static and g.call_kind == call_kind and std.mem.eql(u8, g.wire_name, wire_name)) {
                            try g.entries.append(ctx.scratch, .{ .sig_id = sig_id, .env = env, .prop_jsdoc = prop_jsdoc });
                            return;
                        }
                    }
                    const mb = try sscope.bind(wire_name, .camel);
                    const p_zig = try ctx.alloc.dupe(u8, mb.zig_ident);
                    const p_log = try ctx.alloc.dupe(u8, mb.logical_name);
                    const w_dup = try ctx.alloc.dupe(u8, mb.wire_name);
                    mb.deinit(ctx.scratch);
                    var grp = MethodGroupPlan{
                        .primary_zig_ident = p_zig,
                        .primary_logical_name = p_log,
                        .wire_name = w_dup,
                        .is_static = is_static,
                        .call_kind = call_kind,
                    };
                    try grp.entries.append(ctx.scratch, .{ .sig_id = sig_id, .env = env, .prop_jsdoc = prop_jsdoc });
                    try groups.append(ctx.scratch, grp);
                }
            }.add;

            var required_methods: std.ArrayList([]const u8) = .empty;
            var required_props: std.ArrayList([]const u8) = .empty;
            var declared_required_methods: usize = 0;
            var declared_optional_methods: usize = 0;
            var declared_required_props: usize = 0;

            for (raw_methods) |sm| {
                const m = sm.method;
                if (m.modifiers.private_mod or m.modifiers.protected_mod) {
                    has_non_public_members = true;
                    continue;
                }
                if (m.computed_symbol != null) continue;
                const m_wire = self.str(m.name);
                if (!is_class and !m.modifiers.static_mod) {
                    if (m.modifiers.optional_mod) {
                        declared_optional_methods += 1;
                    } else {
                        declared_required_methods += 1;
                        if (!self.methodIsExperimentalOrDeprecated(m) and
                            required_methods.items.len < lower_objects.max_required_handle_checks)
                        {
                            var seen_rm = false;
                            for (required_methods.items) |existing_rm| {
                                if (std.mem.eql(u8, existing_rm, m_wire)) {
                                    seen_rm = true;
                                    break;
                                }
                            }
                            if (!seen_rm) {
                                try required_methods.append(self.alloc, try self.alloc.dupe(u8, m_wire));
                            }
                        }
                    }
                }
                const m_jsdoc = try self.lowerJsDoc(m.jsdoc);
                for (m.signatures) |sid| {
                    try appendMethodGroupSig(
                        self,
                        &struct_scope,
                        &method_groups,
                        m_wire,
                        m.modifiers.static_mod,
                        .method,
                        sid,
                        sm.env,
                        m_jsdoc,
                    );
                }
            }
            for (call_sigs) |ss| {
                try appendMethodGroupSig(
                    self,
                    &struct_scope,
                    &method_groups,
                    "call",
                    false,
                    .call_sig,
                    ss.sid,
                    ss.env,
                    null,
                );
            }
            if (!is_class) {
                for (construct_sigs) |ss| {
                    try appendMethodGroupSig(
                        self,
                        &struct_scope,
                        &method_groups,
                        "construct",
                        false,
                        .construct_sig,
                        ss.sid,
                        ss.env,
                        null,
                    );
                }
            }

            // Promote non-optional `readonly` callable properties on handle classes/interfaces
            // (e.g. `undici-types` `BodyMixin`'s `readonly text: () => Promise<string>`,
            // `readonly json: () => Promise<unknown>`, `readonly bytes: () => Promise<Uint8Array>`)
            // into bound instance methods (`invokeMethod`) so JS prototype methods that require
            // `this = self` never throw `TypeError: Illegal invocation` and gain auto-awaited
            // `*Alloc` / `*Promise` forms.
            var promoted_prop_methods: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer promoted_prop_methods.deinit(self.scratch);
            for (raw_props) |sp| {
                const pid = sp.pid;
                if (pid >= self.graph.properties.len) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod or
                    p.modifiers.static_mod or p.modifiers.optional_mod or
                    p.computed_symbol != null)
                {
                    continue;
                }
                if (!p.modifiers.readonly_mod or p.has_getter or p.has_setter) continue;
                if (p.ty >= self.graph.types.len) continue;
                var fn_sigs: std.ArrayList(u32) = .empty;
                defer fn_sigs.deinit(self.scratch);
                switch (self.graph.types[p.ty].kind) {
                    .function_type => |sid| try fn_sigs.append(self.scratch, sid),
                    .object_literal => |obj| {
                        if (obj.properties.len == 0 and obj.construct_signatures.len == 0 and
                            obj.index_signatures.len == 0 and obj.call_signatures.len > 0)
                        {
                            try fn_sigs.appendSlice(self.scratch, obj.call_signatures);
                        }
                    },
                    else => {},
                }
                if (fn_sigs.items.len == 0) continue;
                try promoted_prop_methods.put(self.scratch, pid, {});
                const p_wire = self.str(p.name);
                if (!is_class) {
                    declared_required_methods += 1;
                    if (!self.jsdocIsExperimentalOrDeprecated(p.jsdoc) and
                        required_methods.items.len < lower_objects.max_required_handle_checks)
                    {
                        var seen_rm = false;
                        for (required_methods.items) |existing_rm| {
                            if (std.mem.eql(u8, existing_rm, p_wire)) {
                                seen_rm = true;
                                break;
                            }
                        }
                        if (!seen_rm) {
                            try required_methods.append(self.alloc, try self.alloc.dupe(u8, p_wire));
                        }
                    }
                }
                const p_jsdoc = try self.lowerJsDoc(p.jsdoc);
                for (fn_sigs.items) |sid| {
                    try appendMethodGroupSig(
                        self,
                        &struct_scope,
                        &method_groups,
                        p_wire,
                        false,
                        .method,
                        sid,
                        sp.env,
                        p_jsdoc,
                    );
                }
            }

            // 4. Instance property getters / `*Alloc` getters / setters.
            var instance_props: std.ArrayList(InstancePropIr) = .empty;
            for (raw_props) |sp| {
                const pid = sp.pid;
                if (pid >= self.graph.properties.len) continue;
                if (promoted_prop_methods.contains(pid)) continue;
                const p = self.graph.properties[pid];
                if (p.modifiers.private_mod or p.modifiers.protected_mod) continue;
                if (p.modifiers.static_mod) continue;
                if (p.computed_symbol != null) continue;

                const wire = self.str(p.name);
                const access = lower_objects.analyzePropAccess(p);
                if (!access.is_readable and !access.is_writable) continue;

                const prop_active_tps = try self.resolveHeritageActiveTps(
                    sp.env,
                    tp_res.active,
                    self_ident,
                    imports_used,
                    needs_runtime,
                    &env_cache,
                    0,
                );

                var getter_ident: ?[]const u8 = null;
                var getter_alloc_ident: ?[]const u8 = null;
                var getter_ty: ?*const TypeIr = null;
                if (access.is_readable) {
                    const gb = try struct_scope.bind(wire, .camel);
                    getter_ident = try self.alloc.dupe(u8, gb.zig_ident);
                    const getter_logical = try self.scratch.dupe(u8, gb.logical_name);
                    defer self.scratch.free(getter_logical);
                    gb.deinit(self.scratch);

                    visited.clearRetainingCapacity();
                    var gty = try self.lowerType(access.read_ty_id, false, prop_active_tps, self_ident, &visited, imports_used, needs_runtime);
                    if (p.modifiers.optional_mod) gty = try self.wrapOptional(gty);
                    getter_ty = gty;

                    if (try self.typeMayAllocateOnDecode(gty)) {
                        const raw_ga = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{getter_logical});
                        defer self.scratch.free(raw_ga);
                        const gab = try struct_scope.bind(raw_ga, .camel);
                        getter_alloc_ident = try self.alloc.dupe(u8, gab.zig_ident);
                        gab.deinit(self.scratch);
                    }

                    if (!is_class and !p.modifiers.optional_mod) {
                        const allows_undef = switch (gty.*) {
                            .optional => |opt| opt.nullish_kind != .null_only,
                            .js_any, .js_unknown, .js_value, .void_type => true,
                            else => false,
                        };
                        if (!allows_undef) {
                            declared_required_props += 1;
                            if (!sp.from_class_base and
                                !self.jsdocIsExperimentalOrDeprecated(p.jsdoc) and
                                required_props.items.len < lower_objects.max_required_handle_checks)
                            {
                                var seen_rp = false;
                                for (required_props.items) |existing_rp| {
                                    if (std.mem.eql(u8, existing_rp, wire)) {
                                        seen_rp = true;
                                        break;
                                    }
                                }
                                if (!seen_rp) {
                                    try required_props.append(self.alloc, try self.alloc.dupe(u8, wire));
                                }
                            }
                        }
                    }
                }

                var setter_ident: ?[]const u8 = null;
                var setter_ty: ?*const TypeIr = null;
                if (access.is_writable) {
                    const raw_setter = try lower_objects.buildSetterRawName(self.scratch, wire);
                    defer self.scratch.free(raw_setter);
                    const sb = try struct_scope.bind(raw_setter, .camel);
                    setter_ident = try self.alloc.dupe(u8, sb.zig_ident);
                    sb.deinit(self.scratch);

                    if (access.has_divergent_setter) {
                        visited.clearRetainingCapacity();
                        var wty = try self.lowerType(access.write_ty_id, false, prop_active_tps, self_ident, &visited, imports_used, needs_runtime);
                        if (p.modifiers.optional_mod) wty = try self.wrapOptional(wty);
                        setter_ty = wty;
                    } else if (getter_ty) |gty| {
                        setter_ty = gty;
                    } else {
                        visited.clearRetainingCapacity();
                        var wty = try self.lowerType(access.write_ty_id, false, prop_active_tps, self_ident, &visited, imports_used, needs_runtime);
                        if (p.modifiers.optional_mod) wty = try self.wrapOptional(wty);
                        setter_ty = wty;
                    }
                }

                try instance_props.append(self.alloc, .{
                    .wire_name = try self.alloc.dupe(u8, wire),
                    .is_optional = p.modifiers.optional_mod,
                    .getter_ident = getter_ident,
                    .getter_alloc_ident = getter_alloc_ident,
                    .getter_ty = getter_ty,
                    .setter_ident = setter_ident,
                    .setter_ty = setter_ty,
                    .setter_is_optional = p.modifiers.optional_mod,
                    .jsdoc = try self.lowerJsDoc(p.jsdoc),
                });
            }

            // 4a.2. Synthesize callback setters (`setGetWorkerUrl`, `setGetWorker`, etc.) for
            // non-static optional methods on non-class handle interfaces (`interface Environment { getWorkerUrl?(...): string }`).
            if (!is_class) {
                for (raw_methods) |sm| {
                    const m = sm.method;
                    if (m.modifiers.private_mod or m.modifiers.protected_mod or m.modifiers.static_mod) continue;
                    if (!m.modifiers.optional_mod or m.computed_symbol != null) continue;
                    if (m.signatures.len != 1) continue;
                    const sid = m.signatures[0];
                    if (sid >= self.graph.signatures.len) continue;
                    if (self.graph.signatures[sid].type_params.len != 0) continue;

                    const m_wire = self.str(m.name);
                    var has_prop_same_wire = false;
                    for (instance_props.items) |ip_existing| {
                        if (std.mem.eql(u8, ip_existing.wire_name, m_wire)) {
                            has_prop_same_wire = true;
                            break;
                        }
                    }
                    if (has_prop_same_wire) continue;

                    const raw_setter = try lower_objects.buildSetterRawName(self.scratch, m_wire);
                    defer self.scratch.free(raw_setter);
                    const setter_ident = (try lower_objects.tryBindOptionalHelperIdent(
                        &struct_scope,
                        self.scratch,
                        self.alloc,
                        raw_setter,
                    )) orelse continue;

                    const m_active_tps = try self.resolveHeritageActiveTps(
                        sm.env,
                        tp_res.active,
                        self_ident,
                        imports_used,
                        needs_runtime,
                        &env_cache,
                        0,
                    );
                    visited.clearRetainingCapacity();
                    const fp = try self.lowerGraphSigToFnPtrIr(
                        sid,
                        m_active_tps,
                        self_ident,
                        &visited,
                        imports_used,
                        needs_runtime,
                    );
                    const fp_ty = try self.makeType(.{ .fn_ptr = fp });
                    const opt_fp_ty = try self.wrapOptional(fp_ty);
                    needs_runtime.* = true;

                    try instance_props.append(self.alloc, .{
                        .wire_name = try self.alloc.dupe(u8, m_wire),
                        .is_optional = true,
                        .getter_ident = null,
                        .getter_alloc_ident = null,
                        .getter_ty = null,
                        .setter_ident = setter_ident,
                        .setter_ty = opt_fp_ty,
                        .setter_is_optional = true,
                        .jsdoc = try self.lowerJsDoc(m.jsdoc),
                    });
                }
            }

            // 4b. Dynamic index signatures (`[key: string]: V`, `[index: number]: V`, ``[attr: `data-${string}`]: V``).
            const UniqueIndexCand = struct {
                key_ty: *const TypeIr,
                category: lower_heritage.IndexKeyCategory,
                getter_ty: *const TypeIr,
                strict_undefined_missing: bool,
                setter_ty: *const TypeIr,
                is_readonly: bool,
            };
            var unique_index_cands: std.ArrayList(UniqueIndexCand) = .empty;
            defer unique_index_cands.deinit(self.scratch);

            for (raw_index_sigs) |sis| {
                const isig_active_tps = try self.resolveHeritageActiveTps(
                    sis.env,
                    tp_res.active,
                    self_ident,
                    imports_used,
                    needs_runtime,
                    &env_cache,
                    0,
                );
                visited.clearRetainingCapacity();
                const raw_val_ty = try self.lowerType(
                    sis.sig.value_type,
                    false,
                    isig_active_tps,
                    self_ident,
                    &visited,
                    imports_used,
                    needs_runtime,
                );
                var getter_ty: *const TypeIr = raw_val_ty;
                var strict_undefined_missing = true;
                switch (raw_val_ty.*) {
                    .optional => |opt| {
                        getter_ty = raw_val_ty;
                        strict_undefined_missing = (opt.nullish_kind == .undefined_only);
                    },
                    .js_any, .js_unknown, .js_value, .void_type => {
                        getter_ty = raw_val_ty;
                        strict_undefined_missing = false;
                    },
                    else => {
                        getter_ty = try self.wrapOptional(raw_val_ty);
                        strict_undefined_missing = true;
                    },
                }

                var expanded_keys: std.ArrayList(u32) = .empty;
                defer expanded_keys.deinit(self.scratch);
                try self.expandIndexSigKeyGraphTypes(sis.sig.key_type, &expanded_keys, 0);

                for (expanded_keys.items) |k_graph_ty_id| {
                    visited.clearRetainingCapacity();
                    const raw_key_ty = try self.lowerType(
                        k_graph_ty_id,
                        false,
                        isig_active_tps,
                        self_ident,
                        &visited,
                        imports_used,
                        needs_runtime,
                    );
                    const norm_key = try self.normalizeIndexKeyTypeAndCategory(k_graph_ty_id, raw_key_ty);
                    var dup_key = false;
                    for (unique_index_cands.items) |existing| {
                        if (typeIrEql(existing.key_ty, norm_key.ty, 0)) {
                            dup_key = true;
                            break;
                        }
                    }
                    if (!dup_key) {
                        try unique_index_cands.append(self.scratch, .{
                            .key_ty = norm_key.ty,
                            .category = norm_key.category,
                            .getter_ty = getter_ty,
                            .strict_undefined_missing = strict_undefined_missing,
                            .setter_ty = raw_val_ty,
                            .is_readonly = sis.sig.is_readonly,
                        });
                    }
                }
            }

            var has_string_indexer = false;
            for (unique_index_cands.items) |uic| {
                if (uic.category == .string_key) {
                    has_string_indexer = true;
                    break;
                }
            }

            var index_accessors: std.ArrayList(IndexAccessorIr) = .empty;
            for (unique_index_cands.items, 0..) |uic, idx| {
                const allow_short_primary = (uic.category == .string_key) or (!has_string_indexer and idx == 0);
                const bound_idx = try lower_heritage.bindIndexAccessorNames(
                    &struct_scope,
                    self.scratch,
                    self.alloc,
                    uic.category,
                    uic.is_readonly,
                    allow_short_primary,
                );
                var getter_alloc_ident: ?[]const u8 = null;
                if (try self.typeMayAllocateOnDecode(uic.getter_ty)) {
                    getter_alloc_ident = try lower_heritage.bindIndexGetterAllocName(
                        &struct_scope,
                        self.scratch,
                        self.alloc,
                        bound_idx.getter_logical,
                    );
                }
                try index_accessors.append(self.alloc, .{
                    .getter_ident = bound_idx.getter_ident,
                    .getter_alloc_ident = getter_alloc_ident,
                    .key_ty = uic.key_ty,
                    .getter_ty = uic.getter_ty,
                    .strict_undefined_missing = uic.strict_undefined_missing,
                    .setter_ident = bound_idx.setter_ident,
                    .setter_ty = uic.setter_ty,
                });
            }

            const struct_protocols = try self.extractStructProtocols(
                raw_props,
                raw_methods,
                sourced_bases,
                tp_res.active,
                self_ident,
                imports_used,
                needs_runtime,
                &env_cache,
            );

            // 4c. Empty `init()` factory when `{}` is valid (pure dictionary or optional-methods handle interface).
            const empty_init_ident = if (!struct_protocols.hasAny() and lower_heritage.shouldSynthesizeEmptyHandleInit(
                is_class,
                explicit_cls.has_class_base,
                has_non_public_members,
                is_callable_handle,
                ctor_count,
                index_accessors.items.len,
                declared_optional_methods,
                declared_required_methods,
                declared_required_props,
            ))
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "init")
            else
                null;

            // 5. Backing `ref` field (`ref` or `__zigar_ref` when `.ref()` exists) + lifecycle, cast & protocol helpers!
            const ref_field_ident = try lower_objects.bindBackingRefFieldIdent(&struct_scope, self.scratch, self.alloc);
            const deinit_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "deinit");
            const to_js_ref_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "toJsRef");
            const from_js_ref_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "fromJsRef");
            const clone_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "clone");
            const as_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "as");
            const try_as_ident = try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "tryAs");
            const iterator_ident = if (struct_protocols.iterator_elem_ty != null)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "iterator")
            else
                null;
            const async_iterator_ident = if (struct_protocols.async_iterator_elem_ty != null)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "asyncIterator")
            else
                null;
            const dispose_ident = if (struct_protocols.has_sync_dispose)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "dispose")
            else
                null;
            const try_dispose_ident = if (struct_protocols.has_sync_dispose)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "tryDispose")
            else
                null;
            const release_handle_only_ident = if (struct_protocols.has_sync_dispose)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "releaseHandleOnly")
            else
                null;
            const async_dispose_ident = if (struct_protocols.has_async_dispose)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "asyncDispose")
            else
                null;
            const try_async_dispose_ident = if (struct_protocols.has_async_dispose)
                try lower_objects.tryBindOptionalHelperIdent(&struct_scope, self.scratch, self.alloc, "tryAsyncDispose")
            else
                null;

            // 7. Nested declarations (`merged_ns_consumed` & `merged_generic_ns_peer`) + merged static `call`
            // functions (`interface $` + `function $`) so ALL explicit struct-level declarations are registered in
            // `struct_scope` BEFORE step 8!
            const merged_call_slots = if (owner_is_iface_decl and raw_tps.len == 0)
                try self.prebindMergedCallFnSlots(
                    owner_decl_id,
                    owner_wire,
                    merged_ids,
                    false,
                    &struct_scope,
                    outer_active_tps,
                    imports_used,
                    needs_runtime,
                )
            else
                &[_]MergedCallFnSlot{};

            var nested_decls: std.ArrayList(DeclIr) = .empty;
            try self.lowerMergedStructNestedDecls(
                final_mod_idx,
                owner_decl_id,
                merged_ids,
                &struct_scope,
                prebound_names,
                prebound_overloads,
                tp_res.active,
                imports_used,
                needs_runtime,
                &nested_decls,
                active_decls,
            );

            // 8. Lower constructors, grouped methods, and merged call functions once, deduplicate subsumed
            // overloads, bind semantic overload & companion names (`*Alloc`, `*Slice`, `as*`) into `struct_scope`,
            // then finalize non-shadowing parameter names across the complete `struct_scope`!
            var ctors_list: std.ArrayList(ConstructorIr) = .empty;
            var ctor_dispatch: ?OverloadDispatchIr = null;
            if (synthesize_default_ctor) {
                try ctors_list.append(self.alloc, .{
                    .zig_ident = ctor_primary_ident,
                    .signature = .{
                        .self_param_ident = null,
                        .alloc_param_ident = "allocator",
                        .type_params = &.{},
                        .params = &.{},
                        .return_type = try self.makeType(.{ .self_type = self_ident }),
                        .has_type_predicate = false,
                        .type_predicate_asserts = false,
                        .jsdoc = null,
                    },
                    .jsdoc = null,
                });
            } else if (public_ctor_sigs.items.len > 0) {
                var raw_ctor_sigs = try self.scratch.alloc(SignatureIr, public_ctor_sigs.items.len);
                defer self.scratch.free(raw_ctor_sigs);
                for (public_ctor_sigs.items, 0..) |ss, idx| {
                    var ctor_active_tps = try self.resolveHeritageActiveTps(
                        ss.env,
                        tp_res.active,
                        self_ident,
                        imports_used,
                        needs_runtime,
                        &env_cache,
                        0,
                    );
                    var skip_ctor_tps: std.ArrayList(u32) = .empty;
                    defer skip_ctor_tps.deinit(self.scratch);
                    var extra_active_tps: std.ArrayList(ActiveTypeParam) = .empty;
                    defer extra_active_tps.deinit(self.scratch);
                    var preserve_concrete_owner_ret = false;

                    if (tp_res.active.len > 0 and ss.sid < self.graph.signatures.len) {
                        const csig = self.graph.signatures[ss.sid];
                        if (csig.return_type < self.graph.types.len and self.graph.types[csig.return_type].kind == .reference) {
                            const r = self.graph.types[csig.return_type].kind.reference;
                            const ret_matches_owner = (r.target_decl != null and r.target_decl.? == owner_decl_id) or
                                std.mem.eql(u8, lower_types.stripGlobalQualifier(self.str(r.target_name)), owner_wire);
                            if (ret_matches_owner and r.type_args.len == tp_res.active.len) {
                                if (csig.type_params.len > 0) {
                                    try extra_active_tps.appendSlice(self.scratch, ctor_active_tps);
                                    for (csig.type_params) |ctp_id| {
                                        for (r.type_args, 0..) |ta_id, ta_idx| {
                                            if (type_ops.typeNodeMatchesTypeParam(self.graph, ta_id, ctp_id)) {
                                                try skip_ctor_tps.append(self.scratch, ctp_id);
                                                if (ctp_id < self.graph.type_params.len) {
                                                    const ctp_name = self.str(self.graph.type_params[ctp_id].name);
                                                    try extra_active_tps.append(self.scratch, .{
                                                        .ts_name = ctp_name,
                                                        .zig_ident = tp_res.active[ta_idx].zig_ident,
                                                    });
                                                }
                                                break;
                                            }
                                        }
                                    }
                                    if (skip_ctor_tps.items.len > 0) {
                                        ctor_active_tps = extra_active_tps.items;
                                    }
                                } else {
                                    preserve_concrete_owner_ret = true;
                                }
                            }
                        }
                    }

                    var c_sig = try self.lowerSignatureWithSkip(
                        ss.sid,
                        skip_ctor_tps.items,
                        &struct_scope,
                        false,
                        true,
                        raw_ctor_sigs.len > 1,
                        ctor_active_tps,
                        self_ident,
                        imports_used,
                        needs_runtime,
                    );
                    if (!(preserve_concrete_owner_ret and c_sig.return_type.* == .decl_ref)) {
                        c_sig.return_type = try self.makeType(.{ .self_type = self_ident });
                    }
                    raw_ctor_sigs[idx] = c_sig;
                }
                const kept_ctors = try overloads.deduplicateSubsumedIndices(self.scratch, self.scratch, raw_ctor_sigs);
                defer self.scratch.free(kept_ctors);

                if (kept_ctors.len == 1) {
                    const c_sig = raw_ctor_sigs[kept_ctors[0]];
                    var slice_ident: ?[]const u8 = null;
                    if (c_sig.params.len > 0 and c_sig.params[c_sig.params.len - 1].is_rest) {
                        const vs = try lower_functions.bindVariadicSliceCompanions(
                            self.alloc,
                            self.scratch,
                            &struct_scope,
                            ctor_primary_logical,
                            false,
                        );
                        slice_ident = vs.slice_ident;
                    }
                    try ctors_list.append(self.alloc, .{
                        .zig_ident = ctor_primary_ident,
                        .slice_companion_ident = slice_ident,
                        .signature = c_sig,
                        .jsdoc = c_sig.jsdoc,
                    });
                } else {
                    var kept_ctor_sigs = try self.scratch.alloc(SignatureIr, kept_ctors.len);
                    defer self.scratch.free(kept_ctor_sigs);
                    for (kept_ctors, 0..) |orig_idx, ki| kept_ctor_sigs[ki] = raw_ctor_sigs[orig_idx];

                    const sem_names = try overloads.assignSemanticOverloadNames(
                        self.alloc,
                        self.scratch,
                        &struct_scope,
                        ctor_primary_logical,
                        kept_ctor_sigs,
                    );
                    var cands = try self.alloc.alloc(OverloadCandidateIr, kept_ctors.len);
                    for (0..kept_ctors.len) |ki| {
                        const c_sig = kept_ctor_sigs[ki];
                        var slice_ident: ?[]const u8 = null;
                        if (c_sig.params.len > 0 and c_sig.params[c_sig.params.len - 1].is_rest) {
                            const vs = try lower_functions.bindVariadicSliceCompanions(
                                self.alloc,
                                self.scratch,
                                &struct_scope,
                                sem_names[ki].logical_name,
                                false,
                            );
                            slice_ident = vs.slice_ident;
                        }
                        try ctors_list.append(self.alloc, .{
                            .zig_ident = sem_names[ki].zig_ident,
                            .slice_companion_ident = slice_ident,
                            .signature = c_sig,
                            .jsdoc = c_sig.jsdoc,
                        });
                        cands[ki] = .{
                            .target_ident = sem_names[ki].zig_ident,
                            .alloc_target_ident = null,
                            .slice_target_ident = slice_ident,
                            .signature = c_sig,
                        };
                    }
                    ctor_dispatch = .{
                        .zig_ident = ctor_primary_ident,
                        .logical_name = ctor_primary_logical,
                        .alloc_companion_ident = null,
                        .is_static = true,
                        .is_constructor = true,
                        .mode = overloads.planDispatchMode(kept_ctor_sigs),
                        .candidates = cands,
                        .jsdoc = kept_ctor_sigs[0].jsdoc,
                    };
                }
            }

            var methods_list: std.ArrayList(MethodIr) = .empty;
            var method_dispatches_list: std.ArrayList(OverloadDispatchIr) = .empty;
            const PendingMethodDispatch = struct {
                disp_idx: usize,
                cand_start: usize,
                cand_len: usize,
            };
            var pending_dispatches: std.ArrayList(PendingMethodDispatch) = .empty;
            defer pending_dispatches.deinit(self.scratch);

            for (method_groups.items) |grp| {
                const receiver_binds_this = grp.call_kind != .call_sig;
                var raw_msigs = try self.scratch.alloc(SignatureIr, grp.entries.items.len);
                defer self.scratch.free(raw_msigs);
                for (grp.entries.items, 0..) |ent, idx| {
                    const slot_active_tps = try self.resolveHeritageActiveTps(
                        ent.env,
                        tp_res.active,
                        self_ident,
                        imports_used,
                        needs_runtime,
                        &env_cache,
                        0,
                    );
                    raw_msigs[idx] = try self.lowerSignature(
                        ent.sig_id,
                        &struct_scope,
                        !grp.is_static,
                        receiver_binds_this,
                        raw_msigs.len > 1,
                        slot_active_tps,
                        self_ident,
                        imports_used,
                        needs_runtime,
                    );
                }

                const kept_m = try overloads.deduplicateSubsumedIndices(self.scratch, self.scratch, raw_msigs);
                defer self.scratch.free(kept_m);

                if (kept_m.len == 1) {
                    const orig_idx = kept_m[0];
                    const ent = grp.entries.items[orig_idx];
                    const raw_one = raw_msigs[orig_idx];
                    const split_opt = try self.prepareAwaitedAndPromiseSig(raw_one);
                    const m_sig = if (split_opt) |sp| sp.awaited else raw_one;
                    const comps = try self.bindSigCompanions(&struct_scope, grp.primary_logical_name, &m_sig);
                    try methods_list.append(self.alloc, .{
                        .zig_ident = grp.primary_zig_ident,
                        .logical_name = grp.primary_logical_name,
                        .wire_name = grp.wire_name,
                        .alloc_companion_ident = comps.alloc_ident,
                        .slice_companion_ident = comps.slice_ident,
                        .slice_alloc_companion_ident = comps.slice_alloc_ident,
                        .narrow_companion_ident = comps.narrow_ident,
                        .narrow_alloc_companion_ident = comps.narrow_alloc_ident,
                        .default_companion_ident = comps.default_ident,
                        .default_alloc_companion_ident = comps.default_alloc_ident,
                        .infer_companion_ident = comps.infer_ident,
                        .infer_alloc_companion_ident = comps.infer_alloc_ident,
                        .is_static = grp.is_static,
                        .call_kind = grp.call_kind,
                        .signature = m_sig,
                        .jsdoc = m_sig.jsdoc orelse ent.prop_jsdoc,
                    });
                    if (split_opt) |sp| {
                        const prom_sig = sp.promise_companion;
                        const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{grp.primary_logical_name});
                        defer self.scratch.free(raw_prom);
                        const pb = try struct_scope.bind(raw_prom, .camel);
                        const prom_zig = try self.alloc.dupe(u8, pb.zig_ident);
                        const prom_logical = try self.alloc.dupe(u8, pb.logical_name);
                        pb.deinit(self.scratch);
                        const prom_comps = try self.bindSigCompanions(&struct_scope, prom_logical, &prom_sig);
                        try methods_list.append(self.alloc, .{
                            .zig_ident = prom_zig,
                            .logical_name = prom_logical,
                            .wire_name = grp.wire_name,
                            .alloc_companion_ident = prom_comps.alloc_ident,
                            .slice_companion_ident = prom_comps.slice_ident,
                            .slice_alloc_companion_ident = prom_comps.slice_alloc_ident,
                            .narrow_companion_ident = prom_comps.narrow_ident,
                            .narrow_alloc_companion_ident = prom_comps.narrow_alloc_ident,
                            .default_companion_ident = prom_comps.default_ident,
                            .default_alloc_companion_ident = prom_comps.default_alloc_ident,
                            .infer_companion_ident = prom_comps.infer_ident,
                            .infer_alloc_companion_ident = prom_comps.infer_alloc_ident,
                            .is_static = grp.is_static,
                            .is_synthetic_companion = true,
                            .call_kind = grp.call_kind,
                            .signature = prom_sig,
                            .jsdoc = prom_sig.jsdoc orelse ent.prop_jsdoc,
                        });
                    }
                } else {
                    var kept_msigs = try self.scratch.alloc(SignatureIr, kept_m.len);
                    defer self.scratch.free(kept_msigs);
                    var prom_msigs_list: std.ArrayList(SignatureIr) = .empty;
                    defer prom_msigs_list.deinit(self.scratch);
                    var prom_ent_indices: std.ArrayList(usize) = .empty;
                    defer prom_ent_indices.deinit(self.scratch);

                    for (kept_m, 0..) |orig_idx, ki| {
                        if (try self.prepareAwaitedAndPromiseSig(raw_msigs[orig_idx])) |sp| {
                            kept_msigs[ki] = sp.awaited;
                            try prom_msigs_list.append(self.scratch, sp.promise_companion);
                            try prom_ent_indices.append(self.scratch, orig_idx);
                        } else {
                            kept_msigs[ki] = raw_msigs[orig_idx];
                        }
                    }

                    const sem_names = try overloads.assignSemanticOverloadNames(
                        self.alloc,
                        self.scratch,
                        &struct_scope,
                        grp.primary_logical_name,
                        kept_msigs,
                    );
                    var kept_comps = try self.scratch.alloc(BoundSigCompanions, kept_m.len);
                    defer self.scratch.free(kept_comps);
                    var any_alloc = false;
                    for (0..kept_m.len) |ki| {
                        kept_comps[ki] = try self.bindSigCompanions(&struct_scope, sem_names[ki].logical_name, &kept_msigs[ki]);
                        if (kept_comps[ki].alloc_ident != null) any_alloc = true;
                    }
                    var disp_alloc_ident: ?[]const u8 = null;
                    if (any_alloc) {
                        const raw_da = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{grp.primary_logical_name});
                        defer self.scratch.free(raw_da);
                        const dab = try struct_scope.bind(raw_da, .camel);
                        disp_alloc_ident = try self.alloc.dupe(u8, dab.zig_ident);
                        dab.deinit(self.scratch);
                    }

                    const cand_start = methods_list.items.len;
                    const cands = try self.alloc.alloc(OverloadCandidateIr, kept_m.len);
                    for (0..kept_m.len) |ki| {
                        const ent = grp.entries.items[kept_m[ki]];
                        const m_sig = kept_msigs[ki];
                        try methods_list.append(self.alloc, .{
                            .zig_ident = sem_names[ki].zig_ident,
                            .logical_name = sem_names[ki].logical_name,
                            .wire_name = grp.wire_name,
                            .alloc_companion_ident = kept_comps[ki].alloc_ident,
                            .slice_companion_ident = kept_comps[ki].slice_ident,
                            .slice_alloc_companion_ident = kept_comps[ki].slice_alloc_ident,
                            .narrow_companion_ident = kept_comps[ki].narrow_ident,
                            .narrow_alloc_companion_ident = kept_comps[ki].narrow_alloc_ident,
                            .default_companion_ident = kept_comps[ki].default_ident,
                            .default_alloc_companion_ident = kept_comps[ki].default_alloc_ident,
                            .infer_companion_ident = kept_comps[ki].infer_ident,
                            .infer_alloc_companion_ident = kept_comps[ki].infer_alloc_ident,
                            .is_static = grp.is_static,
                            .call_kind = grp.call_kind,
                            .signature = m_sig,
                            .jsdoc = m_sig.jsdoc orelse ent.prop_jsdoc,
                        });
                    }
                    const first_ent = grp.entries.items[kept_m[0]];
                    const disp_idx = method_dispatches_list.items.len;
                    try method_dispatches_list.append(self.alloc, .{
                        .zig_ident = grp.primary_zig_ident,
                        .logical_name = grp.primary_logical_name,
                        .alloc_companion_ident = disp_alloc_ident,
                        .is_static = grp.is_static,
                        .is_constructor = false,
                        .mode = overloads.planDispatchMode(kept_msigs),
                        .candidates = cands,
                        .jsdoc = kept_msigs[0].jsdoc orelse first_ent.prop_jsdoc,
                    });
                    try pending_dispatches.append(self.scratch, .{
                        .disp_idx = disp_idx,
                        .cand_start = cand_start,
                        .cand_len = kept_m.len,
                    });

                    if (prom_msigs_list.items.len > 0) {
                        const raw_prom = try std.fmt.allocPrint(self.scratch, "{s}Promise", .{grp.primary_logical_name});
                        defer self.scratch.free(raw_prom);
                        const pb = try struct_scope.bind(raw_prom, .camel);
                        const prom_primary_zig = try self.alloc.dupe(u8, pb.zig_ident);
                        const prom_primary_logical = try self.alloc.dupe(u8, pb.logical_name);
                        pb.deinit(self.scratch);

                        if (prom_msigs_list.items.len == 1) {
                            const pent = grp.entries.items[prom_ent_indices.items[0]];
                            const psig = prom_msigs_list.items[0];
                            const pc = try self.bindSigCompanions(&struct_scope, prom_primary_logical, &psig);
                            try methods_list.append(self.alloc, .{
                                .zig_ident = prom_primary_zig,
                                .logical_name = prom_primary_logical,
                                .wire_name = grp.wire_name,
                                .alloc_companion_ident = pc.alloc_ident,
                                .slice_companion_ident = pc.slice_ident,
                                .slice_alloc_companion_ident = pc.slice_alloc_ident,
                                .narrow_companion_ident = pc.narrow_ident,
                                .narrow_alloc_companion_ident = pc.narrow_alloc_ident,
                                .default_companion_ident = pc.default_ident,
                                .default_alloc_companion_ident = pc.default_alloc_ident,
                                .infer_companion_ident = pc.infer_ident,
                                .infer_alloc_companion_ident = pc.infer_alloc_ident,
                                .is_static = grp.is_static,
                                .is_synthetic_companion = true,
                                .call_kind = grp.call_kind,
                                .signature = psig,
                                .jsdoc = psig.jsdoc orelse pent.prop_jsdoc,
                            });
                        } else {
                            const prom_sem_names = try overloads.assignSemanticOverloadNames(
                                self.alloc,
                                self.scratch,
                                &struct_scope,
                                prom_primary_logical,
                                prom_msigs_list.items,
                            );
                            var prom_comps = try self.scratch.alloc(BoundSigCompanions, prom_msigs_list.items.len);
                            defer self.scratch.free(prom_comps);
                            var prom_any_alloc = false;
                            for (0..prom_msigs_list.items.len) |pi| {
                                prom_comps[pi] = try self.bindSigCompanions(&struct_scope, prom_sem_names[pi].logical_name, &prom_msigs_list.items[pi]);
                                if (prom_comps[pi].alloc_ident != null) prom_any_alloc = true;
                            }
                            var prom_disp_alloc_ident: ?[]const u8 = null;
                            if (prom_any_alloc) {
                                const raw_pda = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{prom_primary_logical});
                                defer self.scratch.free(raw_pda);
                                const pdab = try struct_scope.bind(raw_pda, .camel);
                                prom_disp_alloc_ident = try self.alloc.dupe(u8, pdab.zig_ident);
                                pdab.deinit(self.scratch);
                            }

                            const prom_cand_start = methods_list.items.len;
                            const prom_cands = try self.alloc.alloc(OverloadCandidateIr, prom_msigs_list.items.len);
                            for (0..prom_msigs_list.items.len) |pi| {
                                const pent = grp.entries.items[prom_ent_indices.items[pi]];
                                const psig = prom_msigs_list.items[pi];
                                try methods_list.append(self.alloc, .{
                                    .zig_ident = prom_sem_names[pi].zig_ident,
                                    .logical_name = prom_sem_names[pi].logical_name,
                                    .wire_name = grp.wire_name,
                                    .alloc_companion_ident = prom_comps[pi].alloc_ident,
                                    .slice_companion_ident = prom_comps[pi].slice_ident,
                                    .slice_alloc_companion_ident = prom_comps[pi].slice_alloc_ident,
                                    .narrow_companion_ident = prom_comps[pi].narrow_ident,
                                    .narrow_alloc_companion_ident = prom_comps[pi].narrow_alloc_ident,
                                    .default_companion_ident = prom_comps[pi].default_ident,
                                    .default_alloc_companion_ident = prom_comps[pi].default_alloc_ident,
                                    .infer_companion_ident = prom_comps[pi].infer_ident,
                                    .infer_alloc_companion_ident = prom_comps[pi].infer_alloc_ident,
                                    .is_static = grp.is_static,
                                    .is_synthetic_companion = true,
                                    .call_kind = grp.call_kind,
                                    .signature = psig,
                                    .jsdoc = psig.jsdoc orelse pent.prop_jsdoc,
                                });
                            }
                            const first_pent = grp.entries.items[prom_ent_indices.items[0]];
                            const prom_disp_idx = method_dispatches_list.items.len;
                            try method_dispatches_list.append(self.alloc, .{
                                .zig_ident = prom_primary_zig,
                                .logical_name = prom_primary_logical,
                                .alloc_companion_ident = prom_disp_alloc_ident,
                                .is_static = grp.is_static,
                                .is_constructor = false,
                                .mode = overloads.planDispatchMode(prom_msigs_list.items),
                                .candidates = prom_cands,
                                .jsdoc = prom_msigs_list.items[0].jsdoc orelse first_pent.prop_jsdoc,
                            });
                            try pending_dispatches.append(self.scratch, .{
                                .disp_idx = prom_disp_idx,
                                .cand_start = prom_cand_start,
                                .cand_len = prom_msigs_list.items.len,
                            });
                        }
                    }
                }
            }

            const merged_call_fns = try self.finishMergedCallFns(
                owner_wire,
                merged_call_slots,
                &struct_scope,
                outer_active_tps,
                imports_used,
                needs_runtime,
            );

            // Refresh all signature & helper parameter names now that `struct_scope` is 100% populated!
            for (ctors_list.items) |*ctor| {
                try self.refreshSigParamsAgainstScope(&ctor.signature, &struct_scope);
            }
            if (ctor_dispatch) |*cd| {
                const cands_mut = try self.alloc.alloc(OverloadCandidateIr, ctors_list.items.len);
                for (ctors_list.items, 0..) |ctor, ci| {
                    cands_mut[ci] = .{
                        .target_ident = ctor.zig_ident,
                        .alloc_target_ident = null,
                        .slice_target_ident = ctor.slice_companion_ident,
                        .signature = ctor.signature,
                    };
                }
                cd.candidates = cands_mut;
            }
            for (methods_list.items) |*m_item| {
                try self.refreshSigParamsAgainstScope(&m_item.signature, &struct_scope);
            }
            for (merged_call_fns) |*mcf| {
                if (mcf.kind == .function_decl) {
                    try self.refreshSigParamsAgainstScope(&mcf.kind.function_decl, &struct_scope);
                } else if (mcf.kind == .overload_dispatch) {
                    mcf.kind.overload_dispatch.alloc_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                        &struct_scope,
                        self.scratch,
                        self.alloc,
                        "allocator",
                    );
                }
            }

            const self_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                &struct_scope,
                self.scratch,
                self.alloc,
                "self",
            );
            const raw_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                &struct_scope,
                self.scratch,
                self.alloc,
                "raw",
            );
            const base_tp_ident = try lower_objects.chooseNonShadowingParamIdent(
                &struct_scope,
                self.scratch,
                self.alloc,
                "Base",
            );
            const sub_tp_ident = try lower_objects.chooseNonShadowingParamIdent(
                &struct_scope,
                self.scratch,
                self.alloc,
                "Sub",
            );

            for (pending_dispatches.items) |pd| {
                var disp = &method_dispatches_list.items[pd.disp_idx];
                disp.self_param_ident = self_param_ident;
                var disp_param_scope = naming.ScopeNamer.initParam(self.scratch, &struct_scope);
                defer disp_param_scope.deinit();
                if (!disp.is_static) try disp_param_scope.reserve(self_param_ident);
                disp.alloc_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                    &disp_param_scope,
                    self.scratch,
                    self.alloc,
                    "allocator",
                );
                const cands_mut = try self.alloc.alloc(OverloadCandidateIr, pd.cand_len);
                for (0..pd.cand_len) |ci| {
                    const m_item = methods_list.items[pd.cand_start + ci];
                    cands_mut[ci] = .{
                        .target_ident = m_item.zig_ident,
                        .alloc_target_ident = m_item.alloc_companion_ident,
                        .slice_target_ident = m_item.slice_companion_ident,
                        .infer_target_ident = m_item.infer_companion_ident,
                        .infer_alloc_target_ident = m_item.infer_alloc_companion_ident,
                        .default_target_ident = m_item.default_companion_ident,
                        .default_alloc_target_ident = m_item.default_alloc_companion_ident,
                        .signature = m_item.signature,
                    };
                }
                disp.candidates = cands_mut;
            }

            for (instance_props.items) |*ip| {
                if (ip.getter_alloc_ident != null) {
                    ip.getter_alloc_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                        &struct_scope,
                        self.scratch,
                        self.alloc,
                        "allocator",
                    );
                }
                if (ip.setter_ident != null) {
                    ip.setter_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                        &struct_scope,
                        self.scratch,
                        self.alloc,
                        "value",
                    );
                }
            }
            for (index_accessors.items, unique_index_cands.items) |*ia, uic| {
                const raw_key_name = uic.category.defaultKeyParamRawName();
                ia.key_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                    &struct_scope,
                    self.scratch,
                    self.alloc,
                    raw_key_name,
                );
                if (ia.getter_alloc_ident != null) {
                    var alloc_scope = naming.ScopeNamer.initParam(self.scratch, &struct_scope);
                    defer alloc_scope.deinit();
                    try alloc_scope.reserve(self_param_ident);
                    try alloc_scope.reserve(ia.key_param_ident);
                    ia.getter_alloc_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                        &alloc_scope,
                        self.scratch,
                        self.alloc,
                        "allocator",
                    );
                }
                if (ia.setter_ident != null) {
                    ia.setter_key_param_ident = ia.key_param_ident;
                    var set_scope = naming.ScopeNamer.initParam(self.scratch, &struct_scope);
                    defer set_scope.deinit();
                    try set_scope.reserve(self_param_ident);
                    try set_scope.reserve(ia.setter_key_param_ident);
                    ia.setter_val_param_ident = try lower_objects.chooseNonShadowingParamIdent(
                        &set_scope,
                        self.scratch,
                        self.alloc,
                        "value",
                    );
                }
            }

            return .{
                .repr = .handle_wrapper,
                .is_class = is_class,
                .is_abstract = is_abstract,
                .is_callable_handle = is_callable_handle,
                .has_private_constructor = has_private_constructor,
                .has_non_public_members = has_non_public_members,
                .self_ident = self_ident,
                .ref_field_ident = ref_field_ident,
                .self_param_ident = self_param_ident,
                .raw_param_ident = raw_param_ident,
                .base_type_param_ident = base_tp_ident,
                .sub_type_param_ident = sub_tp_ident,
                .to_js_ref_ident = to_js_ref_ident,
                .from_js_ref_ident = from_js_ref_ident,
                .deinit_ident = deinit_ident,
                .as_ident = as_ident,
                .try_as_ident = try_as_ident,
                .clone_ident = clone_ident,
                .empty_init_ident = empty_init_ident,
                .iterator_ident = iterator_ident,
                .iterator_elem_ty = struct_protocols.iterator_elem_ty,
                .async_iterator_ident = async_iterator_ident,
                .async_iterator_elem_ty = struct_protocols.async_iterator_elem_ty,
                .has_sync_dispose = struct_protocols.has_sync_dispose,
                .dispose_ident = dispose_ident,
                .try_dispose_ident = try_dispose_ident,
                .release_handle_only_ident = release_handle_only_ident,
                .has_async_dispose = struct_protocols.has_async_dispose,
                .async_dispose_ident = async_dispose_ident,
                .try_async_dispose_ident = try_async_dispose_ident,
                .required_methods = try required_methods.toOwnedSlice(self.alloc),
                .required_props = try required_props.toOwnedSlice(self.alloc),
                .bases = direct_bases,
                .type_params = tp_res.ir,
                .fields = &.{},
                .instance_props = try instance_props.toOwnedSlice(self.alloc),
                .index_accessors = try index_accessors.toOwnedSlice(self.alloc),
                .static_props = try static_props.toOwnedSlice(self.alloc),
                .constructors = try ctors_list.toOwnedSlice(self.alloc),
                .ctor_dispatch = ctor_dispatch,
                .methods = try methods_list.toOwnedSlice(self.alloc),
                .method_dispatches = try method_dispatches_list.toOwnedSlice(self.alloc),
                .merged_call_fns = merged_call_fns,
                .nested_decls = try nested_decls.toOwnedSlice(self.alloc),
            };
        }

        fn collectConsumedMergedNamespaceChildren(
            self: *Self,
            owner_decl_id: u32,
            owner_wire: []const u8,
            merged_ids: []const u32,
            initial_children: []const u32,
        ) error{OutOfMemory}![]u32 {
            var ns_owners: std.ArrayList(u32) = .empty;
            defer ns_owners.deinit(self.scratch);
            var ns_slices: std.ArrayList([]const u32) = .empty;
            defer ns_slices.deinit(self.scratch);

            try ns_owners.append(self.scratch, owner_decl_id);
            if (initial_children.len > 0) {
                try ns_slices.append(self.scratch, initial_children);
            }
            for (merged_ids) |mid| {
                if (mid == owner_decl_id or mid >= self.graph.decls.len) continue;
                if (!self.merged_ns_consumed.contains(mid)) continue;
                const md = self.graph.decls[mid];
                if (md.kind != .namespace_decl) continue;
                const m_wire = if (md.export_name) |esid| self.str(esid) else self.str(md.name);
                if (!merge_decls.sameWireName(owner_wire, m_wire)) continue;
                try ns_owners.append(self.scratch, mid);
                try ns_slices.append(self.scratch, md.kind.namespace_decl);
            }
            return try merge_decls.mergeNamespaceChildIds(
                self.scratch,
                ns_owners.items,
                ns_slices.items,
            );
        }

        fn lowerMergedStructNestedDecls(
            self: *Self,
            final_mod_idx: u32,
            owner_decl_id: u32,
            merged_ids: []const u32,
            struct_scope: *naming.ScopeNamer,
            prebound_names: *const std.AutoHashMapUnmanaged(u32, naming.BoundName),
            prebound_overloads: *const std.AutoHashMapUnmanaged(u32, []naming.BoundName),
            active_tps: []const ActiveTypeParam,
            imports_used: *std.AutoHashMapUnmanaged(u32, void),
            needs_runtime: *bool,
            nested_decls: *std.ArrayList(DeclIr),
            active_decls: *std.AutoHashMapUnmanaged(u32, void),
        ) error{OutOfMemory}!void {
            if (owner_decl_id >= self.graph.decls.len) return;
            const owner_d = self.graph.decls[owner_decl_id];
            const owner_wire = if (owner_d.export_name) |esid| self.str(esid) else self.str(owner_d.name);
            const merged_ns_children = try self.collectConsumedMergedNamespaceChildren(
                owner_decl_id,
                owner_wire,
                merged_ids,
                &.{},
            );
            for (merged_ns_children) |cid| {
                try self.lowerDeclIntoListInner(
                    final_mod_idx,
                    cid,
                    false,
                    struct_scope,
                    prebound_names,
                    prebound_overloads,
                    active_tps,
                    imports_used,
                    needs_runtime,
                    nested_decls,
                    active_decls,
                );
            }

            if (self.merged_generic_ns_peer.get(owner_decl_id)) |ns_peer_id| {
                if (ns_peer_id < self.graph.decls.len and self.graph.decls[ns_peer_id].kind == .namespace_decl) {
                    for (self.graph.decls[ns_peer_id].kind.namespace_decl) |cid| {
                        if (cid >= self.graph.decls.len) continue;
                        const cd = self.graph.decls[cid];
                        if (!cd.modifiers.export_decl) continue;
                        const cloc = (try self.resolveEffectiveReExportTarget(cid, 0)) orelse continue;
                        if (cloc.zig_path.len == 0) continue;
                        const cwire = if (cd.export_name) |esid| self.str(esid) else self.str(cd.name);
                        const cstyle = self.declNameStyle(cd);
                        const desired = switch (cstyle) {
                            .preserve => try self.scratch.dupe(u8, cwire),
                            .camel => try naming.toCamelCase(self.scratch, cwire),
                            .pascal => try naming.toPascalCase(self.scratch, cwire),
                            .snake => try naming.toSnakeCase(self.scratch, cwire),
                        };
                        defer self.scratch.free(desired);
                        if (desired.len == 0 or struct_scope.isTaken(desired)) continue;
                        const ab = try struct_scope.bind(cwire, cstyle);
                        if (cloc.module_index != final_mod_idx) {
                            try imports_used.put(self.scratch, cloc.module_index, {});
                        }
                        try nested_decls.append(self.alloc, .{
                            .source_decl_id = cid,
                            .zig_ident = try self.alloc.dupe(u8, ab.zig_ident),
                            .logical_name = try self.alloc.dupe(u8, ab.logical_name),
                            .wire_name = try self.alloc.dupe(u8, ab.wire_name),
                            .is_exported = true,
                            .is_js_exported = true,
                            .is_default_export = false,
                            .jsdoc = null,
                            .kind = .{
                                .re_export_decl = .{
                                    .target_module_index = cloc.module_index,
                                    .target_zig_path = cloc.zig_path,
                                },
                            },
                        });
                        ab.deinit(self.scratch);
                    }
                }
            }
        }

        fn resolveFinalModFromSourceMod(self: *const Self, source_mod_id: u32) ?u32 {
            const cand_idx = self.source_mod_to_cand.get(source_mod_id) orelse return null;
            return self.candToFinalIndex(cand_idx);
        }

        fn candToFinalIndex(self: *const Self, cand_idx: u32) ?u32 {
            if (self.cand_to_final_map) |m| {
                if (cand_idx < m.len) return m[cand_idx];
            }
            return null;
        }

        fn resolveNamespaceReExportTargetMod(self: *Self, re: anytype) error{OutOfMemory}!?u32 {
            if (re.target_module) |tmid| {
                return self.resolveFinalModFromSourceMod(tmid);
            }
            const mspec = self.str(re.module_specifier);
            if (try self.resolveSpecToCandidateIdx(mspec)) |amb_cand| {
                return self.candToFinalIndex(amb_cand);
            }
            return null;
        }

        fn resolveNamedReExportTargetLoc(
            self: *Self,
            d: anytype,
            re: anytype,
            depth: usize,
        ) error{OutOfMemory}!?DeclLocation {
            if (depth > 64) return null;
            if (re.target_decl) |tdid| {
                return try self.resolveEffectiveReExportTarget(tdid, depth + 1);
            }
            const target_cand_opt: ?u32 = if (re.target_module) |tmid|
                self.source_mod_to_cand.get(tmid)
            else
                try self.resolveSpecToCandidateIdx(self.str(re.module_specifier));

            const target_cand_idx = target_cand_opt orelse return null;
            const orig_name = self.str(d.name);
            if (orig_name.len == 0) return null;

            const tcand = &self.candidates.items[target_cand_idx];
            for (tcand.exported_decl_ids.items) |edid| {
                if (edid >= self.graph.decls.len) continue;
                const ed = self.graph.decls[edid];
                const ew = if (ed.export_name) |esid| self.str(esid) else self.str(ed.name);
                if (std.mem.eql(u8, ew, orig_name)) {
                    return try self.resolveEffectiveReExportTarget(edid, depth + 1);
                }
            }
            for (tcand.foreign_exports.items) |fe| {
                if (fe.is_default_export or fe.decl_id >= self.graph.decls.len) continue;
                const fd = self.graph.decls[fe.decl_id];
                const fw = fe.wire_name_override orelse (if (fd.export_name) |esid| self.str(esid) else self.str(fd.name));
                if (std.mem.eql(u8, fw, orig_name)) {
                    return try self.resolveEffectiveReExportTarget(fe.decl_id, depth + 1);
                }
            }
            return null;
        }

        fn isAliasedNamespaceChildReExport(self: *const Self, did: u32) ?u32 {
            if (did >= self.graph.decls.len) return null;
            if (!self.ns_child_ids.contains(did)) return null;
            const d = self.graph.decls[did];
            if (d.kind != .re_export_decl) return null;
            const re = d.kind.re_export_decl;
            if (re.is_namespace or re.is_type_only) return null;
            const eff_wire = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
            const root_td = self.resolveTransitiveReExportTarget(did) orelse return null;
            if (root_td >= self.graph.decls.len) return null;
            const rd = self.graph.decls[root_td];
            if (rd.kind != .namespace_decl) return null;
            for (rd.merged_with) |mid| {
                if (mid < self.graph.decls.len and self.graph.decls[mid].module == rd.module and self.graph.decls[mid].kind != .namespace_decl) {
                    return null;
                }
            }
            if (std.mem.eql(u8, eff_wire, self.str(rd.name))) return null;
            return root_td;
        }

        fn resolveEffectiveReExportTarget(self: *Self, did: u32, depth: usize) error{OutOfMemory}!?DeclLocation {
            if (depth > 64 or did >= self.graph.decls.len) return null;
            const d = self.graph.decls[did];
            switch (d.kind) {
                .re_export_decl => |re| {
                    const eff_name = if (d.export_name) |esid| self.str(esid) else self.str(d.name);
                    if (re.is_namespace and std.mem.eql(u8, eff_name, "*")) return null;
                    if (re.is_namespace) {
                        const owner_loc = self.decl_locations.get(did) orelse return null;
                        if (try self.resolveNamespaceReExportTargetMod(re)) |t_mod_idx| {
                            if (t_mod_idx != owner_loc.module_index) return owner_loc;
                        }
                        return null;
                    }
                    if (self.isAliasedNamespaceChildReExport(did) != null) {
                        if (self.decl_locations.get(did)) |aliased_loc| {
                            return aliased_loc;
                        }
                    }
                    return try self.resolveNamedReExportTargetLoc(d, re, depth + 1);
                },
                .import_equals_decl => |ie| {
                    if (!d.modifiers.export_decl) return null;
                    if (ie.target_decl) |tdid| {
                        return try self.resolveEffectiveReExportTarget(tdid, depth + 1);
                    }
                    if (ie.module_specifier) |msid| {
                        const owner_loc = self.decl_locations.get(did) orelse return null;
                        if (try self.resolveSpecToCandidateIdx(self.str(msid))) |c_idx| {
                            if (self.candToFinalIndex(c_idx)) |t_mod_idx| {
                                if (t_mod_idx != owner_loc.module_index) return owner_loc;
                            }
                        }
                    }
                    return null;
                },
                else => return self.decl_locations.get(did),
            }
        }

        const StarCanonLoc = struct {
            module_index: u32,
            canonical_decl_id: u32,
            zig_path: []const []const u8,

            fn samePath(pa: []const []const u8, pb: []const []const u8) bool {
                if (pa.len != pb.len) return false;
                for (pa, pb) |sa, sb_seg| {
                    if (!std.mem.eql(u8, sa, sb_seg)) return false;
                }
                return true;
            }

            fn areMergedPeers(decls: anytype, da: u32, db: u32) bool {
                if (da == db) return true;
                if (da < decls.len) {
                    for (decls[da].merged_with) |m| {
                        if (m == db) return true;
                    }
                }
                if (db < decls.len) {
                    for (decls[db].merged_with) |m| {
                        if (m == da) return true;
                    }
                }
                return false;
            }

            fn resolveCanonDeclId(decls: anytype, start_did: u32) u32 {
                var cur = start_did;
                var hops: usize = 0;
                while (hops < 16 and cur < decls.len) : (hops += 1) {
                    switch (decls[cur].kind) {
                        .re_export_decl => |re| cur = re.target_decl orelse break,
                        .import_equals_decl => |ie| cur = ie.target_decl orelse break,
                        else => break,
                    }
                }
                return cur;
            }

            fn sameSymbol(decls: anytype, a: @This(), b: @This()) bool {
                if (a.module_index != b.module_index) return false;
                return samePath(a.zig_path, b.zig_path) or
                    areMergedPeers(decls, a.canonical_decl_id, b.canonical_decl_id);
            }
        };

        const ResolvedStarItem = struct {
            item: StarExportItem,
            export_wire: []const u8,
            canon: StarCanonLoc,
        };

        const ModuleStarSummary = struct {
            exported_items: []const ResolvedStarItem = &.{},
            nested_star_items: []const ResolvedStarItem = &.{},
            poisoned_wires: []const []const u8 = &.{},
        };

        fn starItemExportWire(self: *const Self, item: StarExportItem) []const u8 {
            if (item.wire_name_override) |ov| return ov;
            if (item.decl_id >= self.graph.decls.len) return "";
            const sd = self.graph.decls[item.decl_id];
            return if (sd.export_name) |esid| self.str(esid) else self.str(sd.name);
        }

        fn buildModuleStarSummary(
            self: *Self,
            direct_items: []const StarExportItem,
            has_final_mod: bool,
            child_summaries: []const ModuleStarSummary,
        ) error{OutOfMemory}!ModuleStarSummary {
            var direct_wires: std.StringHashMapUnmanaged(void) = .empty;
            defer direct_wires.deinit(self.scratch);
            var resolved_direct: std.ArrayList(ResolvedStarItem) = .empty;

            for (direct_items) |di| {
                if (di.decl_id >= self.graph.decls.len) continue;
                const d = self.graph.decls[di.decl_id];
                if (d.modifiers.default_export) continue;
                const ew = self.starItemExportWire(di);
                if (ew.len == 0 or std.mem.eql(u8, ew, "default")) continue;
                try direct_wires.put(self.scratch, ew, {});
                if (has_final_mod and !self.merged_ns_consumed.contains(di.decl_id)) {
                    if (try self.resolveEffectiveReExportTarget(di.decl_id, 0)) |loc| {
                        if (loc.zig_path.len > 0) {
                            try resolved_direct.append(self.scratch, .{
                                .item = di,
                                .export_wire = ew,
                                .canon = .{
                                    .module_index = loc.module_index,
                                    .canonical_decl_id = StarCanonLoc.resolveCanonDeclId(self.graph.decls, di.decl_id),
                                    .zig_path = loc.zig_path,
                                },
                            });
                        }
                    }
                }
            }

            // ECMA-262 `ResolveExport` step 10.d: both propagated `AMBIGUOUS` wires from child
            // `export *` branches and multi-branch symbol collisions poison the wire at this
            // module unless shadowed by `direct_wires`.
            var branch_canon: std.StringHashMapUnmanaged(StarCanonLoc) = .empty;
            defer branch_canon.deinit(self.scratch);
            var branch_ambig: std.StringHashMapUnmanaged(void) = .empty;
            defer branch_ambig.deinit(self.scratch);
            var poisoned_list: std.ArrayList([]const u8) = .empty;

            for (child_summaries) |cs| {
                for (cs.poisoned_wires) |pw| {
                    if (direct_wires.contains(pw)) continue;
                    const gop = try branch_ambig.getOrPut(self.scratch, pw);
                    if (!gop.found_existing) {
                        try poisoned_list.append(self.scratch, pw);
                    }
                }
                for (cs.exported_items) |ri| {
                    if (direct_wires.contains(ri.export_wire)) continue;
                    if (branch_canon.get(ri.export_wire)) |prev_canon| {
                        if (!StarCanonLoc.sameSymbol(self.graph.decls, prev_canon, ri.canon)) {
                            const gop = try branch_ambig.getOrPut(self.scratch, ri.export_wire);
                            if (!gop.found_existing) {
                                try poisoned_list.append(self.scratch, ri.export_wire);
                            }
                        }
                    } else {
                        try branch_canon.put(self.scratch, ri.export_wire, ri.canon);
                    }
                }
            }

            var nested_list: std.ArrayList(ResolvedStarItem) = .empty;
            var seen_branch_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer seen_branch_decls.deinit(self.scratch);
            const OverrideKey = struct { decl_id: u32, wire: []const u8 };
            var seen_override_items: std.ArrayList(OverrideKey) = .empty;
            defer seen_override_items.deinit(self.scratch);

            for (child_summaries) |cs| {
                for (cs.exported_items) |ri| {
                    if (direct_wires.contains(ri.export_wire) or branch_ambig.contains(ri.export_wire)) continue;
                    if (ri.item.wire_name_override == null) {
                        const gop = try seen_branch_decls.getOrPut(self.scratch, ri.item.decl_id);
                        if (gop.found_existing) continue;
                    } else {
                        var dup_ov = false;
                        for (seen_override_items.items) |ok| {
                            if (ok.decl_id == ri.item.decl_id and std.mem.eql(u8, ok.wire, ri.export_wire)) {
                                dup_ov = true;
                                break;
                            }
                        }
                        if (dup_ov) continue;
                        try seen_override_items.append(self.scratch, .{ .decl_id = ri.item.decl_id, .wire = ri.export_wire });
                    }
                    try nested_list.append(self.scratch, ri);
                }
            }

            const nested_slice = try nested_list.toOwnedSlice(self.scratch);
            var exported_list: std.ArrayList(ResolvedStarItem) = .empty;
            try exported_list.ensureTotalCapacity(self.scratch, resolved_direct.items.len + nested_slice.len);
            exported_list.appendSliceAssumeCapacity(resolved_direct.items);
            exported_list.appendSliceAssumeCapacity(nested_slice);
            resolved_direct.deinit(self.scratch);

            return .{
                .exported_items = try exported_list.toOwnedSlice(self.scratch),
                .nested_star_items = nested_slice,
                .poisoned_wires = try poisoned_list.toOwnedSlice(self.scratch),
            };
        }

        fn getSourceModStarSummary(
            self: *Self,
            source_mod_id: u32,
            visiting_source_mods: *std.AutoHashMapUnmanaged(u32, void),
            visiting_cands: *std.AutoHashMapUnmanaged(u32, void),
            hit_cycle: *bool,
        ) error{OutOfMemory}!ModuleStarSummary {
            if (self.source_mod_to_cand.get(source_mod_id)) |sc_idx| {
                return self.getCandStarSummary(
                    sc_idx,
                    visiting_source_mods,
                    visiting_cands,
                    hit_cycle,
                );
            }
            if (self.star_summary_smods.get(source_mod_id)) |cached| return cached;
            if (visiting_source_mods.contains(source_mod_id)) {
                hit_cycle.* = true;
                return .{};
            }

            const is_root_call = (visiting_source_mods.count() == 0 and visiting_cands.count() == 0);
            try visiting_source_mods.put(self.scratch, source_mod_id, {});
            defer _ = visiting_source_mods.remove(source_mod_id);

            const sm_idx = self.findGraphModuleIndexById(source_mod_id) orelse return .{};
            const sm = self.graph.modules[sm_idx];

            var direct_items: std.ArrayList(StarExportItem) = .empty;
            defer direct_items.deinit(self.scratch);
            for (sm.exports) |did| {
                if (sm.default_export != null and sm.default_export.? == did) continue;
                try direct_items.append(self.scratch, .{ .decl_id = did });
            }

            var seen_child_cands: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer seen_child_cands.deinit(self.scratch);
            var seen_child_smods: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer seen_child_smods.deinit(self.scratch);
            var child_summaries: std.ArrayList(ModuleStarSummary) = .empty;
            defer child_summaries.deinit(self.scratch);

            var sub_hit_cycle = false;
            for (sm.star_re_exports) |next_sm| {
                if (self.source_mod_to_cand.get(next_sm)) |dep_cand| {
                    if ((try seen_child_cands.getOrPut(self.scratch, dep_cand)).found_existing) continue;
                    try child_summaries.append(self.scratch, try self.getCandStarSummary(
                        dep_cand,
                        visiting_source_mods,
                        visiting_cands,
                        &sub_hit_cycle,
                    ));
                } else {
                    if ((try seen_child_smods.getOrPut(self.scratch, next_sm)).found_existing) continue;
                    try child_summaries.append(self.scratch, try self.getSourceModStarSummary(
                        next_sm,
                        visiting_source_mods,
                        visiting_cands,
                        &sub_hit_cycle,
                    ));
                }
            }

            if (sub_hit_cycle) hit_cycle.* = true;
            const has_final_mod = (self.resolveFinalModFromSourceMod(source_mod_id) != null);
            const summary = try self.buildModuleStarSummary(
                direct_items.items,
                has_final_mod,
                child_summaries.items,
            );
            if (!sub_hit_cycle or is_root_call) {
                try self.star_summary_smods.put(self.scratch, source_mod_id, summary);
            }
            return summary;
        }

        fn getCandStarSummary(
            self: *Self,
            cand_idx: u32,
            visiting_source_mods: *std.AutoHashMapUnmanaged(u32, void),
            visiting_cands: *std.AutoHashMapUnmanaged(u32, void),
            hit_cycle: *bool,
        ) error{OutOfMemory}!ModuleStarSummary {
            if (cand_idx >= self.candidates.items.len) return .{};
            if (self.star_summary_cands.get(cand_idx)) |cached| return cached;
            if (visiting_cands.contains(cand_idx)) {
                hit_cycle.* = true;
                return .{};
            }
            const cand = &self.candidates.items[cand_idx];
            for (cand.source_mod_ids.items) |self_smid| {
                if (visiting_source_mods.contains(self_smid)) {
                    hit_cycle.* = true;
                    return .{};
                }
            }

            const is_root_call = (visiting_source_mods.count() == 0 and visiting_cands.count() == 0);
            try visiting_cands.put(self.scratch, cand_idx, {});
            defer _ = visiting_cands.remove(cand_idx);
            for (cand.source_mod_ids.items) |self_smid| {
                try visiting_source_mods.put(self.scratch, self_smid, {});
            }
            defer {
                for (cand.source_mod_ids.items) |self_smid| {
                    _ = visiting_source_mods.remove(self_smid);
                }
            }

            var direct_items: std.ArrayList(StarExportItem) = .empty;
            defer direct_items.deinit(self.scratch);
            for (cand.exported_decl_ids.items) |did| {
                if (cand.default_export_decl_id != null and cand.default_export_decl_id.? == did) continue;
                try direct_items.append(self.scratch, .{ .decl_id = did });
            }
            for (cand.foreign_exports.items) |fe| {
                if (!fe.is_default_export) {
                    try direct_items.append(self.scratch, .{
                        .decl_id = fe.decl_id,
                        .wire_name_override = fe.wire_name_override,
                    });
                }
            }

            var seen_child_cands: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer seen_child_cands.deinit(self.scratch);
            var seen_child_smods: std.AutoHashMapUnmanaged(u32, void) = .empty;
            defer seen_child_smods.deinit(self.scratch);
            var child_summaries: std.ArrayList(ModuleStarSummary) = .empty;
            defer child_summaries.deinit(self.scratch);

            var sub_hit_cycle = false;
            for (cand.star_re_export_source_mods.items) |smid| {
                if (self.source_mod_to_cand.get(smid)) |dep_cand| {
                    if ((try seen_child_cands.getOrPut(self.scratch, dep_cand)).found_existing) continue;
                    try child_summaries.append(self.scratch, try self.getCandStarSummary(
                        dep_cand,
                        visiting_source_mods,
                        visiting_cands,
                        &sub_hit_cycle,
                    ));
                } else {
                    if ((try seen_child_smods.getOrPut(self.scratch, smid)).found_existing) continue;
                    try child_summaries.append(self.scratch, try self.getSourceModStarSummary(
                        smid,
                        visiting_source_mods,
                        visiting_cands,
                        &sub_hit_cycle,
                    ));
                }
            }
            for (cand.star_re_export_specs.items) |mspec| {
                if (try self.resolveSpecToCandidateIdx(mspec)) |dep_cand| {
                    if ((try seen_child_cands.getOrPut(self.scratch, dep_cand)).found_existing) continue;
                    try child_summaries.append(self.scratch, try self.getCandStarSummary(
                        dep_cand,
                        visiting_source_mods,
                        visiting_cands,
                        &sub_hit_cycle,
                    ));
                }
            }

            if (sub_hit_cycle) hit_cycle.* = true;
            const has_final_mod = (self.candToFinalIndex(cand_idx) != null);
            const summary = try self.buildModuleStarSummary(
                direct_items.items,
                has_final_mod,
                child_summaries.items,
            );
            if (!sub_hit_cycle or is_root_call) {
                try self.star_summary_cands.put(self.scratch, cand_idx, summary);
            }
            return summary;
        }

        /// Detects expansive / non-regular generic recursion (`Box<Box<T>>`, `Foo<Bar<Foo<T>>>`,
        /// `Nest<T[]>`) and unguarded non-container recursive type aliases (`type Loop<T> = Loop<T>[]`)
        /// that would cause unbounded Zig comptime monomorphization, rewriting the cycle-closing
        /// `TypeIr` edge in-place to `.js_object` and recording an explicit `.expansive_generic_cycle`
        /// fallback entry and doc-comment note.
        fn breakExpansiveGenericCycles(self: *Self, modules: []ModuleIr) !void {
            var decl_ptr_map: std.StringHashMapUnmanaged(*DeclIr) = .empty;
            defer {
                var it = decl_ptr_map.keyIterator();
                while (it.next()) |k| self.scratch.free(k.*);
                decl_ptr_map.deinit(self.scratch);
            }

            for (modules) |*m| {
                try indexDeclPointersByPath(self.scratch, m.index, &.{}, @constCast(m.decls), &decl_ptr_map);
            }

            for (modules) |*m| {
                try self.scanModuleDeclsForExpansiveCycles(modules, m.index, &.{}, @constCast(m.decls), &decl_ptr_map);
            }
        }

        const GenSymVal = union(enum) {
            closed,
            bare_param: struct {
                depth: u6,
                idx: u16,
            },
            compound: u64,

            fn mask(self: GenSymVal) u64 {
                return switch (self) {
                    .closed => 0,
                    .bare_param => |bp| (@as(u64, 1) << bp.depth),
                    .compound => |m| m,
                };
            }
        };

        const GenParamBinding = struct {
            ident: []const u8,
            val: GenSymVal,
        };

        const GenActiveFrame = struct {
            key: []const u8,
            decl: *DeclIr,
            mod_idx: u32,
            saw_nominal_container: bool,
            under_eager_typeinfo: bool = false,
        };

        fn evalGenSymType(
            self: *const Self,
            ty: *const TypeIr,
            bindings: []const GenParamBinding,
            decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
            depth: usize,
        ) error{OutOfMemory}!GenSymVal {
            if (depth >= 24) return .closed;
            switch (ty.*) {
                .type_param_ref => |ident| {
                    for (bindings) |b| {
                        if (std.mem.eql(u8, b.ident, ident)) return b.val;
                    }
                    return .closed;
                },
                .decl_ref => |dref| {
                    if (dref.type_args.len > 0) {
                        const target_key = try formatDeclCycleKey(self.scratch, dref.module_index, dref.decl_zig_path, null);
                        defer self.scratch.free(target_key);
                        if (decl_map.get(target_key)) |t_decl| {
                            if (t_decl.kind == .type_alias and t_decl.kind.type_alias.target.* == .type_param_ref) {
                                const ref_tp = t_decl.kind.type_alias.target.type_param_ref;
                                for (t_decl.kind.type_alias.type_params, 0..) |tp, p_idx| {
                                    if (std.mem.eql(u8, tp.zig_ident, ref_tp) and p_idx < dref.type_args.len) {
                                        return self.evalGenSymType(dref.type_args[p_idx], bindings, decl_map, depth + 1);
                                    }
                                }
                            }
                        }
                    }
                    var m: u64 = 0;
                    for (dref.type_args) |arg| {
                        m |= (try self.evalGenSymType(arg, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .slice, .pointer_const, .promise, .js_iterator, .js_async_iterator => |inner| {
                    const m = (try self.evalGenSymType(inner, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .optional => |opt| {
                    const m = (try self.evalGenSymType(opt.child, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .js_map => |mp| {
                    const m = (try self.evalGenSymType(mp.key, bindings, decl_map, depth + 1)).mask() |
                        (try self.evalGenSymType(mp.value, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .js_record => |rec| {
                    const m = (try self.evalGenSymType(rec.key, bindings, decl_map, depth + 1)).mask() |
                        (try self.evalGenSymType(rec.value, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .mapped_values_op => |mv| {
                    const m = (try self.evalGenSymType(mv.target, bindings, decl_map, depth + 1)).mask() |
                        (try self.evalGenSymType(mv.value, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .unary_type_op => |uo| {
                    const m = (try self.evalGenSymType(uo.operand, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .key_filter_op => |kfo| {
                    var m = (try self.evalGenSymType(kfo.target, bindings, decl_map, depth + 1)).mask();
                    if (kfo.keys == .ty) {
                        m |= (try self.evalGenSymType(kfo.keys.ty, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .index_access_op => |iao| {
                    var m = (try self.evalGenSymType(iao.object_ty, bindings, decl_map, depth + 1)).mask();
                    if (iao.index_spec == .ty) {
                        m |= (try self.evalGenSymType(iao.index_spec.ty, bindings, decl_map, depth + 1)).mask();
                    }
                    if (iao.fallback_ty) |ft| {
                        m |= (try self.evalGenSymType(ft, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .empty_object_extends_op => |eoe| {
                    var m = (try self.evalGenSymType(eoe.target_ty, bindings, decl_map, depth + 1)).mask();
                    m |= (try self.evalGenSymType(eoe.true_ty, bindings, decl_map, depth + 1)).mask();
                    m |= (try self.evalGenSymType(eoe.false_ty, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .intersect_op => |arms| {
                    var m: u64 = 0;
                    for (arms) |arm| {
                        m |= (try self.evalGenSymType(arm, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .tuple => |elems| {
                    var m: u64 = 0;
                    for (elems) |el| {
                        m |= (try self.evalGenSymType(el.ty, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .anon_struct => |fields| {
                    var m: u64 = 0;
                    for (fields) |f| {
                        m |= (try self.evalGenSymType(f.ty, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .tagged_union => |tu| {
                    var m: u64 = 0;
                    for (tu.variants) |v| {
                        m |= (try self.evalGenSymType(v.payload, bindings, decl_map, depth + 1)).mask();
                    }
                    return if (m == 0) .closed else .{ .compound = m };
                },
                .fn_ptr => |fp| {
                    var m: u64 = 0;
                    if (fp.this_param) |thp| {
                        m |= (try self.evalGenSymType(thp, bindings, decl_map, depth + 1)).mask();
                    }
                    for (fp.params) |pt| {
                        m |= (try self.evalGenSymType(pt, bindings, decl_map, depth + 1)).mask();
                    }
                    m |= (try self.evalGenSymType(fp.return_type, bindings, decl_map, depth + 1)).mask();
                    return if (m == 0) .closed else .{ .compound = m };
                },
                else => return .closed,
            }
        }

        fn appendFallbackNoteToDecl(
            self: *Self,
            modules: []ModuleIr,
            owner_mod_idx: u32,
            owner_decl: *DeclIr,
            kind: FallbackKind,
            detail: []const u8,
        ) error{OutOfMemory}!void {
            const mod_spec = if (owner_mod_idx < modules.len) modules[owner_mod_idx].specifier else "";
            var extra_notes: std.ArrayList([]const u8) = .empty;
            defer extra_notes.deinit(self.scratch);
            for (owner_decl.fallback_notes) |existing| {
                try extra_notes.append(self.scratch, existing);
            }
            const before_len = extra_notes.items.len;
            try self.recordFallbackAt(mod_spec, owner_decl.logical_name, &extra_notes, kind, detail);
            if (extra_notes.items.len > before_len) {
                owner_decl.fallback_notes = try self.alloc.dupe([]const u8, extra_notes.items);
            }
            if (owner_mod_idx < modules.len) {
                modules[owner_mod_idx].needs_root_runtime = true;
            }
        }

        fn scanModuleDeclsForExpansiveCycles(
            self: *Self,
            modules: []ModuleIr,
            mod_idx: u32,
            prefix: []const []const u8,
            decls: []DeclIr,
            decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
        ) error{OutOfMemory}!void {
            if (prefix.len >= 32) return;
            for (decls) |*d| {
                const tps_opt: ?[]const TypeParamIr = switch (d.kind) {
                    .struct_decl => |st| if (st.repr == .value_struct and st.type_params.len > 0) st.type_params else null,
                    .union_decl => |un| if (un.type_params.len > 0) un.type_params else null,
                    .type_alias => |ta| ta.type_params,
                    else => null,
                };
                if (tps_opt) |tps| {
                    var frames: std.ArrayList(GenActiveFrame) = .empty;
                    defer frames.deinit(self.scratch);
                    const root_bindings = try self.scratch.alloc(GenParamBinding, tps.len);
                    defer self.scratch.free(root_bindings);
                    for (tps, 0..) |tp, idx| {
                        root_bindings[idx] = .{
                            .ident = tp.zig_ident,
                            .val = .{ .bare_param = .{ .depth = 0, .idx = @intCast(idx) } },
                        };
                    }
                    var visits: usize = 0;
                    try self.dfsExpansiveGenericDecl(
                        modules,
                        mod_idx,
                        prefix,
                        d,
                        root_bindings,
                        decl_map,
                        &frames,
                        &visits,
                    );
                }

                switch (d.kind) {
                    .namespace_decl => |*ns| {
                        const sub = try self.scratch.alloc([]const u8, prefix.len + 1);
                        defer self.scratch.free(sub);
                        @memcpy(sub[0..prefix.len], prefix);
                        sub[prefix.len] = d.zig_ident;
                        try self.scanModuleDeclsForExpansiveCycles(modules, mod_idx, sub, @constCast(ns.children), decl_map);
                    },
                    .struct_decl => |*st| {
                        if (st.nested_decls.len > 0) {
                            const sub = try self.scratch.alloc([]const u8, prefix.len + 1);
                            defer self.scratch.free(sub);
                            @memcpy(sub[0..prefix.len], prefix);
                            sub[prefix.len] = d.zig_ident;
                            try self.scanModuleDeclsForExpansiveCycles(modules, mod_idx, sub, @constCast(st.nested_decls), decl_map);
                        }
                    },
                    .enum_decl => |*en| {
                        if (en.nested_decls.len > 0) {
                            const sub = try self.scratch.alloc([]const u8, prefix.len + 1);
                            defer self.scratch.free(sub);
                            @memcpy(sub[0..prefix.len], prefix);
                            sub[prefix.len] = d.zig_ident;
                            try self.scanModuleDeclsForExpansiveCycles(modules, mod_idx, sub, @constCast(en.nested_decls), decl_map);
                        }
                    },
                    else => {},
                }
            }
        }

        fn dfsExpansiveGenericDecl(
            self: *Self,
            modules: []ModuleIr,
            mod_idx: u32,
            prefix: []const []const u8,
            d: *DeclIr,
            bindings: []const GenParamBinding,
            decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
            frames: *std.ArrayList(GenActiveFrame),
            visits: *usize,
        ) error{OutOfMemory}!void {
            if (frames.items.len >= 24 or visits.* >= 1024) return;
            visits.* += 1;

            const self_key = try formatDeclCycleKey(self.scratch, mod_idx, prefix, d.zig_ident);
            defer self.scratch.free(self_key);

            const is_nominal_decl = (d.kind == .struct_decl and d.kind.struct_decl.repr == .value_struct) or
                (d.kind == .union_decl);
            var saved_container_flags: [24]bool = undefined;
            const n_parent_frames = frames.items.len;
            if (is_nominal_decl) {
                for (frames.items[0..n_parent_frames], 0..) |*fr, idx| {
                    saved_container_flags[idx] = fr.saw_nominal_container;
                    if (!fr.under_eager_typeinfo) {
                        fr.saw_nominal_container = true;
                    }
                }
            }
            defer if (is_nominal_decl) {
                for (frames.items[0..n_parent_frames], 0..) |*fr, idx| {
                    fr.saw_nominal_container = saved_container_flags[idx];
                }
            };

            try frames.append(self.scratch, .{
                .key = self_key,
                .decl = d,
                .mod_idx = mod_idx,
                .saw_nominal_container = is_nominal_decl,
                .under_eager_typeinfo = false,
            });
            defer _ = frames.pop();

            switch (d.kind) {
                .struct_decl => |*st| {
                    if (st.repr == .value_struct) {
                        for (st.fields) |f| {
                            try self.dfsExpansiveGenericType(modules, mod_idx, d, @constCast(f.ty), bindings, decl_map, frames, visits);
                        }
                    }
                },
                .union_decl => |*un| {
                    for (un.variants) |v| {
                        try self.dfsExpansiveGenericType(modules, mod_idx, d, @constCast(v.payload), bindings, decl_map, frames, visits);
                    }
                },
                .type_alias => |*ta| {
                    try self.dfsExpansiveGenericType(modules, mod_idx, d, @constCast(ta.target), bindings, decl_map, frames, visits);
                },
                else => {},
            }
        }

        fn dfsExpansiveGenericTypeEager(
            self: *Self,
            modules: []ModuleIr,
            owner_mod_idx: u32,
            owner_decl: *DeclIr,
            ty: *TypeIr,
            bindings: []const GenParamBinding,
            decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
            frames: *std.ArrayList(GenActiveFrame),
            visits: *usize,
        ) error{OutOfMemory}!void {
            var saved_eager: [24]bool = undefined;
            const n_frames = frames.items.len;
            for (frames.items[0..n_frames], 0..) |*fr, idx| {
                saved_eager[idx] = fr.under_eager_typeinfo;
                if (fr.decl.kind == .type_alias and !fr.saw_nominal_container) {
                    fr.under_eager_typeinfo = true;
                }
            }
            defer {
                for (frames.items[0..n_frames], 0..) |*fr, idx| {
                    fr.under_eager_typeinfo = saved_eager[idx];
                }
            }
            try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, ty, bindings, decl_map, frames, visits);
        }

        fn dfsExpansiveGenericType(
            self: *Self,
            modules: []ModuleIr,
            owner_mod_idx: u32,
            owner_decl: *DeclIr,
            ty: *TypeIr,
            bindings: []const GenParamBinding,
            decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
            frames: *std.ArrayList(GenActiveFrame),
            visits: *usize,
        ) error{OutOfMemory}!void {
            if (visits.* >= 1024) return;

            const enters_container = switch (ty.*) {
                .tuple, .anon_struct, .tagged_union => true,
                else => false,
            };
            var saved_container_flags: [24]bool = undefined;
            const n_frames = frames.items.len;
            if (enters_container) {
                for (frames.items[0..n_frames], 0..) |*fr, idx| {
                    saved_container_flags[idx] = fr.saw_nominal_container;
                    if (!fr.under_eager_typeinfo) {
                        fr.saw_nominal_container = true;
                    }
                }
            }
            defer if (enters_container) {
                for (frames.items[0..n_frames], 0..) |*fr, idx| {
                    fr.saw_nominal_container = saved_container_flags[idx];
                }
            };

            switch (ty.*) {
                .slice, .pointer_const, .promise, .js_iterator, .js_async_iterator => |inner| {
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(inner), bindings, decl_map, frames, visits);
                },
                .optional => |opt| {
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(opt.child), bindings, decl_map, frames, visits);
                },
                .js_map => |mp| {
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(mp.key), bindings, decl_map, frames, visits);
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(mp.value), bindings, decl_map, frames, visits);
                },
                .js_record => |rec| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(rec.key), bindings, decl_map, frames, visits);
                    if (rec.key.* != .string_type) {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(rec.value), bindings, decl_map, frames, visits);
                    } else {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(rec.value), bindings, decl_map, frames, visits);
                    }
                },
                .mapped_values_op => |mv| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(mv.target), bindings, decl_map, frames, visits);
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(mv.value), bindings, decl_map, frames, visits);
                },
                .unary_type_op => |uo| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(uo.operand), bindings, decl_map, frames, visits);
                },
                .key_filter_op => |kfo| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(kfo.target), bindings, decl_map, frames, visits);
                    if (kfo.keys == .ty) {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(kfo.keys.ty), bindings, decl_map, frames, visits);
                    }
                },
                .index_access_op => |iao| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(iao.object_ty), bindings, decl_map, frames, visits);
                    if (iao.index_spec == .ty) {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(iao.index_spec.ty), bindings, decl_map, frames, visits);
                    }
                    if (iao.fallback_ty) |ft| {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(ft), bindings, decl_map, frames, visits);
                    }
                },
                .empty_object_extends_op => |eoe| {
                    try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(eoe.target_ty), bindings, decl_map, frames, visits);
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(eoe.true_ty), bindings, decl_map, frames, visits);
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(eoe.false_ty), bindings, decl_map, frames, visits);
                },
                .intersect_op => |arms| {
                    for (arms) |arm| {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(arm), bindings, decl_map, frames, visits);
                    }
                },
                .tuple => |elems| {
                    for (elems) |el| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(el.ty), bindings, decl_map, frames, visits);
                    }
                },
                .anon_struct => |fields| {
                    for (fields) |f| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(f.ty), bindings, decl_map, frames, visits);
                    }
                },
                .tagged_union => |tu| {
                    for (tu.variants) |v| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(v.payload), bindings, decl_map, frames, visits);
                    }
                },
                .fn_ptr => |fp| {
                    if (fp.this_param == null and fp.rest_sequence_ty != null) {
                        try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(fp.rest_sequence_ty.?), bindings, decl_map, frames, visits);
                    } else if (fp.rest_sequence_ty) |rst| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(rst), bindings, decl_map, frames, visits);
                    }
                    if (fp.this_param) |thp| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(thp), bindings, decl_map, frames, visits);
                    }
                    for (fp.params) |pt| {
                        try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(pt), bindings, decl_map, frames, visits);
                    }
                    try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(fp.return_type), bindings, decl_map, frames, visits);
                },
                .decl_ref => |dref| {
                    // Resolve re-export hops first so we can check whether `target_decl` eagerly
                    // inspects `@typeInfo` on any of its generic type parameters.
                    var cur_mod = dref.module_index;
                    var cur_path = dref.decl_zig_path;
                    var target_decl_opt: ?*DeclIr = null;
                    var hops: usize = 0;
                    while (hops < 8) : (hops += 1) {
                        const k = try formatDeclCycleKey(self.scratch, cur_mod, cur_path, null);
                        defer self.scratch.free(k);
                        const found = decl_map.get(k) orelse break;
                        if (found.kind == .re_export_decl) {
                            cur_mod = found.kind.re_export_decl.target_module_index;
                            cur_path = found.kind.re_export_decl.target_zig_path;
                            continue;
                        }
                        target_decl_opt = found;
                        break;
                    }

                    const call_tps: []const TypeParamIr = if (target_decl_opt) |td| switch (td.kind) {
                        .struct_decl => |st| if (st.repr == .value_struct) st.type_params else &.{},
                        .union_decl => |un| un.type_params,
                        .type_alias => |ta| ta.type_params,
                        else => &.{},
                    } else &.{};

                    for (dref.type_args, 0..) |arg_ty, idx| {
                        const inspects_info = if (target_decl_opt != null and idx < call_tps.len)
                            declInspectsTypeParamInfo(self.scratch, target_decl_opt.?, call_tps[idx].zig_ident, decl_map, 0)
                        else
                            false;
                        if (inspects_info) {
                            try self.dfsExpansiveGenericTypeEager(modules, owner_mod_idx, owner_decl, @constCast(arg_ty), bindings, decl_map, frames, visits);
                        } else {
                            try self.dfsExpansiveGenericType(modules, owner_mod_idx, owner_decl, @constCast(arg_ty), bindings, decl_map, frames, visits);
                        }
                    }

                    const target_decl = target_decl_opt orelse return;
                    const target_tps: []const TypeParamIr = switch (target_decl.kind) {
                        .struct_decl => |st| if (st.repr == .value_struct) st.type_params else return,
                        .union_decl => |un| un.type_params,
                        .type_alias => |ta| ta.type_params,
                        else => return,
                    };

                    const target_key = try formatDeclCycleKey(self.scratch, cur_mod, cur_path, null);
                    defer self.scratch.free(target_key);

                    var arg_syms = try self.scratch.alloc(GenSymVal, dref.type_args.len);
                    defer self.scratch.free(arg_syms);
                    var combined_mask: u64 = 0;
                    for (dref.type_args, 0..) |arg_ty, i| {
                        arg_syms[i] = try self.evalGenSymType(arg_ty, bindings, decl_map, 0);
                        combined_mask |= arg_syms[i].mask();
                    }

                    for (frames.items, 0..) |fr, d_idx| {
                        if (!std.mem.eql(u8, fr.key, target_key)) continue;
                        const bit = @as(u64, 1) << @intCast(d_idx);
                        var is_expansive = false;
                        for (arg_syms) |sym| {
                            if (sym == .compound and (sym.compound & bit) != 0) {
                                is_expansive = true;
                                break;
                            }
                        }
                        const is_unguarded_alias = (fr.decl.kind == .type_alias and !fr.saw_nominal_container);
                        if (is_expansive or is_unguarded_alias) {
                            const reason = try std.fmt.allocPrint(
                                self.scratch,
                                "non-regular recursive instantiation of '{s}' -> zigar_js.Object",
                                .{fr.decl.logical_name},
                            );
                            defer self.scratch.free(reason);
                            ty.* = .js_object;
                            try self.appendFallbackNoteToDecl(
                                modules,
                                owner_mod_idx,
                                owner_decl,
                                .expansive_generic_cycle,
                                reason,
                            );
                        }
                        return;
                    }

                    // Prune non-generic / closed calls unless we still have an active unguarded type_alias frame!
                    var any_unguarded_alias_frame = false;
                    for (frames.items) |fr| {
                        if (fr.decl.kind == .type_alias and !fr.saw_nominal_container) {
                            any_unguarded_alias_frame = true;
                            break;
                        }
                    }
                    if (combined_mask == 0 and !any_unguarded_alias_frame) return;
                    if (frames.items.len >= 24) return;

                    const next_depth: u6 = @intCast(frames.items.len);
                    const next_bindings = try self.scratch.alloc(GenParamBinding, target_tps.len);
                    defer self.scratch.free(next_bindings);
                    for (target_tps, 0..) |tp, idx| {
                        const passed = if (idx < arg_syms.len) arg_syms[idx] else .closed;
                        // Also tag with `next_depth` if we need to detect cycles rooted at `target_decl`,
                        // though `scanModuleDeclsForExpansiveCycles` also visits `target_decl` as its own root!
                        _ = next_depth;
                        next_bindings[idx] = .{
                            .ident = tp.zig_ident,
                            .val = passed,
                        };
                    }

                    const parent_prefix = if (cur_path.len > 1)
                        cur_path[0 .. cur_path.len - 1]
                    else
                        &[_][]const u8{};
                    try self.dfsExpansiveGenericDecl(
                        modules,
                        cur_mod,
                        parent_prefix,
                        target_decl,
                        next_bindings,
                        decl_map,
                        frames,
                        visits,
                    );
                },
                else => {},
            }
        }

        /// Breaks any by-value struct/union/tuple/alias cycles across the entire `PackageIr` by setting
        /// `decl_ref.indirect = true` (`*const Target` / `?*const Target`) on back-edges!
        fn breakValueTypeCycles(self: *Self, modules: []ModuleIr) !void {
            var decl_ptr_map: std.StringHashMapUnmanaged(*DeclIr) = .empty;
            defer {
                var it = decl_ptr_map.keyIterator();
                while (it.next()) |k| self.scratch.free(k.*);
                decl_ptr_map.deinit(self.scratch);
            }

            for (modules) |*m| {
                try indexDeclPointersByPath(self.scratch, m.index, &.{}, @constCast(m.decls), &decl_ptr_map);
            }

            // Visit state keyed by `"mod_idx:seg0.seg1"`: 1 = visiting (active stack), 2 = finished.
            var state: std.StringHashMapUnmanaged(u8) = .empty;
            defer {
                var it = state.keyIterator();
                while (it.next()) |k| self.scratch.free(k.*);
                state.deinit(self.scratch);
            }

            for (modules) |*m| {
                for (@constCast(m.decls)) |*d| {
                    try dfsValueCycleDeclByPath(self.scratch, self.alloc, m.index, &.{}, d, &decl_ptr_map, &state);
                }
            }
        }

        const DisjointTypeDomain = enum {
            str,
            num,
            bigint,
            boolean,
            symbol,
            null_dom,
            undef_dom,
            non_prim_obj,
        };

        const IntersectionDomainState = struct {
            domain: ?DisjointTypeDomain = null,
            str_lit: ?[]const u8 = null,
            num_lit: ?f64 = null,
            bigint_lit: ?[]const u8 = null,
            bool_lit: ?bool = null,
        };

        fn foldArmIntoDomainState(
            self: *const Self,
            types_slice: anytype,
            ty_id: u32,
            st: *IntersectionDomainState,
            obj_arms: *std.ArrayList(u32),
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (ty_id >= types_slice.len or depth > 8) return true;
            const tn = types_slice[ty_id];
            switch (tn.kind) {
                .never_type => return false,
                .string_type, .template_literal => {
                    if (st.domain != null and st.domain.? != .str) return false;
                    st.domain = .str;
                    if (tn.kind == .template_literal and tn.kind.template_literal.spans.len == 0) {
                        const lit_s = self.str(tn.kind.template_literal.head);
                        if (st.str_lit) |prev| {
                            if (!std.mem.eql(u8, prev, lit_s)) return false;
                        } else {
                            st.str_lit = lit_s;
                        }
                    }
                    return true;
                },
                .number_type => {
                    if (st.domain != null and st.domain.? != .num) return false;
                    st.domain = .num;
                    return true;
                },
                .bigint_type => {
                    if (st.domain != null and st.domain.? != .bigint) return false;
                    st.domain = .bigint;
                    return true;
                },
                .boolean_type => {
                    if (st.domain != null and st.domain.? != .boolean) return false;
                    st.domain = .boolean;
                    return true;
                },
                .symbol_type, .unique_symbol => {
                    if (st.domain != null and st.domain.? != .symbol) return false;
                    st.domain = .symbol;
                    return true;
                },
                .null_type => {
                    if (st.domain != null and st.domain.? != .null_dom) return false;
                    st.domain = .null_dom;
                    return true;
                },
                .undefined_type, .void_type => {
                    if (st.domain != null and st.domain.? != .undef_dom) return false;
                    st.domain = .undef_dom;
                    return true;
                },
                .object_type, .array, .readonly_array, .tuple, .readonly_tuple, .function_type, .constructor_type => {
                    if (st.domain != null and st.domain.? != .non_prim_obj) return false;
                    st.domain = .non_prim_obj;
                    return true;
                },
                .literal => |lit| {
                    switch (lit) {
                        .str => |sid| {
                            if (st.domain != null and st.domain.? != .str) return false;
                            st.domain = .str;
                            const s = self.str(sid);
                            if (st.str_lit) |prev| {
                                if (!std.mem.eql(u8, prev, s)) return false;
                            } else {
                                st.str_lit = s;
                            }
                        },
                        .num => |n| {
                            if (st.domain != null and st.domain.? != .num) return false;
                            st.domain = .num;
                            if (st.num_lit) |prev| {
                                if (prev != n) return false;
                            } else {
                                st.num_lit = n;
                            }
                        },
                        .bigint_literal => |sid| {
                            if (st.domain != null and st.domain.? != .bigint) return false;
                            st.domain = .bigint;
                            const norm = try lower_types.normalizeBigIntLiteral(self.scratch, self.str(sid));
                            if (st.bigint_lit) |prev| {
                                if (!std.mem.eql(u8, prev, norm)) return false;
                            } else {
                                st.bigint_lit = norm;
                            }
                        },
                        .boolean => |b| {
                            if (st.domain != null and st.domain.? != .boolean) return false;
                            st.domain = .boolean;
                            if (st.bool_lit) |prev| {
                                if (prev != b) return false;
                            } else {
                                st.bool_lit = b;
                            }
                        },
                    }
                    return true;
                },
                .intersection => |sub_parts| {
                    if (sub_parts.len == 0) return true;
                    for (sub_parts) |spid| {
                        if (!try self.foldArmIntoDomainState(types_slice, spid, st, obj_arms, depth + 1)) return false;
                    }
                    return true;
                },
                .object_literal => {
                    try obj_arms.append(self.scratch, ty_id);
                    return true;
                },
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len) {
                            const d = self.graph.decls[td];
                            switch (d.kind) {
                                .type_alias_decl => |alias_ty| {
                                    if (d.type_params.len == 0 and ref.type_args.len == 0) {
                                        return self.foldArmIntoDomainState(types_slice, alias_ty, st, obj_arms, depth + 1);
                                    }
                                },
                                .class_decl => {
                                    if (st.domain != null and st.domain.? != .non_prim_obj) return false;
                                    st.domain = .non_prim_obj;
                                },
                                .interface_decl => {
                                    if (d.type_params.len == 0 and ref.type_args.len == 0) {
                                        try obj_arms.append(self.scratch, ty_id);
                                    }
                                },
                                else => {},
                            }
                        }
                    }
                    return true;
                },
                else => return true,
            }
        }

        const ConflictCheckProp = struct {
            wire: []const u8,
            ty: u32,
        };

        fn collectRequiredPlainPropsForConflictCheck(
            self: *const Self,
            types_slice: anytype,
            arm_ty_id: u32,
            out: *std.ArrayList(ConflictCheckProp),
        ) error{OutOfMemory}!void {
            if (arm_ty_id >= types_slice.len) return;
            switch (types_slice[arm_ty_id].kind) {
                .object_literal => |obj| {
                    for (obj.properties) |pid| {
                        if (pid >= self.graph.properties.len) continue;
                        const p = self.graph.properties[pid];
                        if (p.modifiers.optional_mod or p.modifiers.method_mod or p.modifiers.static_mod or
                            p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                        try out.append(self.scratch, .{ .wire = self.str(p.name), .ty = p.ty });
                    }
                },
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and ref.type_args.len == 0) {
                            const d = self.graph.decls[td];
                            if (d.kind == .interface_decl and d.type_params.len == 0 and d.kind.interface_decl.extends_clauses.len == 0) {
                                for (d.kind.interface_decl.properties) |pid| {
                                    if (pid >= self.graph.properties.len) continue;
                                    const p = self.graph.properties[pid];
                                    if (p.modifiers.optional_mod or p.modifiers.method_mod or p.modifiers.static_mod or
                                        p.modifiers.private_mod or p.modifiers.protected_mod or p.computed_symbol != null) continue;
                                    try out.append(self.scratch, .{ .wire = self.str(p.name), .ty = p.ty });
                                }
                            }
                        }
                    }
                },
                else => {},
            }
        }

        fn isUninhabitedIntersectionInTypes(
            self: *const Self,
            types_slice: anytype,
            parts: []const u32,
            depth: usize,
        ) error{OutOfMemory}!bool {
            if (parts.len == 0 or depth > 6) return false;
            var st: IntersectionDomainState = .{};
            var obj_arms: std.ArrayList(u32) = .empty;
            defer obj_arms.deinit(self.scratch);

            if (!try self.foldArmIntoDomainState(types_slice, parts[0], &st, &obj_arms, 0)) return true;
            for (parts[1..]) |pid| {
                if (!try self.foldArmIntoDomainState(types_slice, pid, &st, &obj_arms, 0)) return true;
            }

            // Detect conflicting required scalar/literal object properties (`{ kind: "a" } & { kind: "b" }`).
            if (st.domain == null and obj_arms.items.len >= 2) {
                var req_props: std.ArrayList(ConflictCheckProp) = .empty;
                defer req_props.deinit(self.scratch);
                for (obj_arms.items) |oaid| {
                    try self.collectRequiredPlainPropsForConflictCheck(types_slice, oaid, &req_props);
                }
                for (req_props.items, 0..) |pa, i| {
                    for (req_props.items[i + 1 ..]) |pb| {
                        if (!std.mem.eql(u8, pa.wire, pb.wire)) continue;
                        var prop_st: IntersectionDomainState = .{};
                        var dummy_objs: std.ArrayList(u32) = .empty;
                        defer dummy_objs.deinit(self.scratch);
                        if (!try self.foldArmIntoDomainState(types_slice, pa.ty, &prop_st, &dummy_objs, depth + 1)) return true;
                        if (prop_st.domain == null) continue;
                        var prop_st_b: IntersectionDomainState = .{};
                        if (!try self.foldArmIntoDomainState(types_slice, pb.ty, &prop_st_b, &dummy_objs, depth + 1)) return true;
                        if (prop_st_b.domain == null) continue;
                        const pair = [_]u32{ pa.ty, pb.ty };
                        var merged_prop_st: IntersectionDomainState = .{};
                        if (!try self.foldArmIntoDomainState(types_slice, pair[0], &merged_prop_st, &dummy_objs, depth + 1) or
                            !try self.foldArmIntoDomainState(types_slice, pair[1], &merged_prop_st, &dummy_objs, depth + 1))
                        {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /// Simplifies intersections whose arms are purely compatible scalar primitives/literals
        /// (for example `"b" & string` -> `"b"` or `"b" & "b"` -> `"b"`) without touching
        /// object/brand intersections such as `string & {}` or `string & Brand`.
        fn simplifyPureScalarIntersectionInTypes(
            self: *const Self,
            types_slice: anytype,
            parts: []const u32,
            depth: usize,
        ) ?u32 {
            if (parts.len == 0 or depth > 6) return null;
            var prim_id: ?u32 = null;
            var lit_id: ?u32 = null;
            for (parts) |pid| {
                if (!self.collectPureScalarIntersectionArm(types_slice, pid, &prim_id, &lit_id, depth)) return null;
            }
            return lit_id orelse prim_id;
        }

        fn collectPureScalarIntersectionArm(
            self: *const Self,
            types_slice: anytype,
            arm_id: u32,
            prim_id: *?u32,
            lit_id: *?u32,
            depth: usize,
        ) bool {
            if (arm_id >= types_slice.len or depth > 6) return false;
            const tn = types_slice[arm_id];
            switch (tn.kind) {
                .string_type, .number_type, .bigint_type, .boolean_type, .symbol_type, .unique_symbol => {
                    if (prim_id.* == null) prim_id.* = arm_id;
                    return true;
                },
                .literal => {
                    if (lit_id.* == null) lit_id.* = arm_id;
                    return true;
                },
                .intersection => |sub| {
                    if (sub.len == 0) return false;
                    for (sub) |spid| {
                        if (!self.collectPureScalarIntersectionArm(types_slice, spid, prim_id, lit_id, depth + 1)) return false;
                    }
                    return true;
                },
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and ref.type_args.len == 0) {
                            const d = self.graph.decls[td];
                            if (d.kind == .type_alias_decl and d.type_params.len == 0) {
                                return self.collectPureScalarIntersectionArm(types_slice, d.kind.type_alias_decl, prim_id, lit_id, depth + 1);
                            }
                        }
                    }
                    return false;
                },
                else => return false,
            }
        }

        fn getDistributableUnionArmsInTypes(
            self: *const Self,
            types_slice: anytype,
            arm_id: u32,
        ) ?[]const u32 {
            if (arm_id >= types_slice.len) return null;
            const tn = types_slice[arm_id];
            switch (tn.kind) {
                .union_type => |u_arms| {
                    if (u_arms.len >= 2 and u_arms.len <= 16) return u_arms;
                    return null;
                },
                .reference => |ref| {
                    if (ref.target_decl) |td| {
                        if (td < self.graph.decls.len and ref.type_args.len == 0) {
                            const d = self.graph.decls[td];
                            if (d.kind == .type_alias_decl and d.type_params.len == 0) {
                                const target_id = d.kind.type_alias_decl;
                                if (target_id < types_slice.len and types_slice[target_id].kind == .union_type) {
                                    const u_arms = types_slice[target_id].kind.union_type;
                                    if (u_arms.len >= 2 and u_arms.len <= 16) return u_arms;
                                }
                            }
                        }
                    }
                    return null;
                },
                else => return null,
            }
        }

        fn normalizeIntersectionGraphTypes(self: *Self) error{OutOfMemory}!void {
            if (self.graph.types.len == 0) return;
            var any_intersection = false;
            for (self.graph.types) |tn| {
                if (tn.kind == .intersection) {
                    any_intersection = true;
                    break;
                }
            }
            if (!any_intersection) return;

            const TypeNodeElem = @TypeOf(self.graph.types[0]);
            var types: std.ArrayList(TypeNodeElem) = .empty;
            try types.appendSlice(self.alloc, self.graph.types);

            var pass: usize = 0;
            while (pass < 3) : (pass += 1) {
                var changed = false;
                const pass_len = types.items.len;
                var tid: usize = 0;
                while (tid < pass_len) : (tid += 1) {
                    if (types.items[tid].kind != .intersection) continue;
                    const parts = types.items[tid].kind.intersection;

                    // 1. Reduce uninhabited intersections (`string & number`, `{ kind: "a" } & { kind: "b" }`) -> `never`.
                    if (try self.isUninhabitedIntersectionInTypes(types.items, parts, 0)) {
                        types.items[tid].kind = .never_type;
                        types.items[tid].resolved_type = null;
                        changed = true;
                        continue;
                    }

                    // 2. Simplify pure scalar intersections (`"b" & string` -> `"b"`, `"b" & "b"` -> `"b"`).
                    if (self.simplifyPureScalarIntersectionInTypes(types.items, parts, 0)) |scalar_id| {
                        types.items[tid].kind = types.items[scalar_id].kind;
                        types.items[tid].resolved_type = types.items[scalar_id].resolved_type;
                        changed = true;
                        continue;
                    }

                    // 3. Distribute intersections over unions: `(A | B) & C` -> `(A & C) | (B & C)` (bounded <= 16 combinations).
                    var has_union_arm = false;
                    var total_combos: usize = 1;
                    var overflow = false;
                    for (parts) |pid| {
                        if (self.getDistributableUnionArmsInTypes(types.items, pid)) |u_arms| {
                            has_union_arm = true;
                            if (total_combos > 16 / u_arms.len) {
                                overflow = true;
                                break;
                            }
                            total_combos *= u_arms.len;
                        }
                    }
                    if (!has_union_arm or overflow or total_combos < 2 or total_combos > 16) continue;

                    var arm_choices = try self.scratch.alloc([]const u32, parts.len);
                    defer self.scratch.free(arm_choices);
                    var single_buf = try self.scratch.alloc([1]u32, parts.len);
                    defer self.scratch.free(single_buf);
                    for (parts, 0..) |pid, pi| {
                        if (self.getDistributableUnionArmsInTypes(types.items, pid)) |u_arms| {
                            arm_choices[pi] = u_arms;
                        } else {
                            single_buf[pi] = .{pid};
                            arm_choices[pi] = &single_buf[pi];
                        }
                    }

                    var combo_buf = try self.scratch.alloc(u32, parts.len);
                    defer self.scratch.free(combo_buf);
                    var distributed_arms: std.ArrayList(u32) = .empty;
                    defer distributed_arms.deinit(self.scratch);

                    for (0..total_combos) |ci| {
                        var rem = ci;
                        var pi: usize = parts.len;
                        while (pi > 0) {
                            pi -= 1;
                            const opts = arm_choices[pi];
                            combo_buf[pi] = opts[rem % opts.len];
                            rem /= opts.len;
                        }
                        if (try self.isUninhabitedIntersectionInTypes(types.items, combo_buf, 0)) continue;
                        if (self.simplifyPureScalarIntersectionInTypes(types.items, combo_buf, 0)) |scalar_id| {
                            try distributed_arms.append(self.scratch, scalar_id);
                        } else {
                            const owned_combo = try self.alloc.dupe(u32, combo_buf);
                            const new_id: u32 = @intCast(types.items.len);
                            try types.append(self.alloc, .{
                                .id = new_id,
                                .kind = .{ .intersection = owned_combo },
                                .resolved_type = null,
                            });
                            try distributed_arms.append(self.scratch, new_id);
                        }
                    }

                    if (distributed_arms.items.len == 0) {
                        types.items[tid].kind = .never_type;
                        types.items[tid].resolved_type = null;
                    } else if (distributed_arms.items.len == 1) {
                        const only_id = distributed_arms.items[0];
                        types.items[tid].kind = types.items[only_id].kind;
                        types.items[tid].resolved_type = types.items[only_id].resolved_type;
                    } else {
                        types.items[tid].kind = .{ .union_type = try self.alloc.dupe(u32, distributed_arms.items) };
                        types.items[tid].resolved_type = null;
                    }
                    changed = true;
                }
                if (!changed) break;
            }

            self.graph.types = types.items;
        }

        fn build(self: *Self) LowerError![]ModuleIr {
            for (self.options.source_files) |sf| {
                try self.vfs_sources.put(self.scratch, sf.vfs_path, sf.contents);
                if (sf.vfs_path.len > 0 and sf.vfs_path[0] == '/') {
                    try self.vfs_sources.put(self.scratch, sf.vfs_path[1..], sf.contents);
                }
            }
            try self.normalizeIntersectionGraphTypes();
            try self.computeTypeRefCounts();
            try self.discoverCandidates();
            const selected_cands = try self.filterAndCloseDependencies();

            var map_slice = try self.alloc.alloc(?u32, self.candidates.items.len);
            @memset(map_slice, null);
            for (selected_cands, 0..) |cand_idx, final_i| {
                map_slice[cand_idx] = @intCast(final_i);
            }
            self.cand_to_final_map = map_slice;

            // Pass 1: Pre-bind canonical module-level scopes & declaration locations across all
            // selected modules first so cross-module and cyclic references resolve deterministically!
            var mod_scopes = try self.scratch.alloc(naming.ScopeNamer, selected_cands.len);
            for (mod_scopes) |*ms| ms.* = naming.ScopeNamer.initContainer(self.scratch, null);
            defer {
                for (mod_scopes) |*ms| ms.deinit();
                self.scratch.free(mod_scopes);
            }

            var prebound_names: std.AutoHashMapUnmanaged(u32, naming.BoundName) = .empty;
            defer prebound_names.deinit(self.scratch);

            var prebound_overloads: std.AutoHashMapUnmanaged(u32, []naming.BoundName) = .empty;
            defer prebound_overloads.deinit(self.scratch);

            for (selected_cands, 0..) |cand_idx, final_i| {
                var ms = &mod_scopes[final_i];
                try ms.reserve("__root");
                try ms.reserve("__zigar_mod");
                try ms.reserve("__zigar_js");
                try ms.reserve("__zigar_args");
                try ms.reserve("__zigar_argc");
                try ms.reserve("zigar_js");
                for (0..selected_cands.len) |dep_i| {
                    const mod_alias = try std.fmt.allocPrint(self.scratch, "__mod_{d}", .{dep_i});
                    defer self.scratch.free(mod_alias);
                    try ms.reserve(mod_alias);
                }

                try self.prebindScopeDecls(
                    @intCast(final_i),
                    self.candidates.items[cand_idx].decl_ids.items,
                    ms,
                    &.{},
                    &prebound_names,
                    &prebound_overloads,
                );
            }

            // Pass 2: Pre-bind foreign exports (`export *` expanded into `mod.exports`, cross-module
            // `default_export` / `export_equals`) and `star_re_export_source_mods` into `mod_scopes`
            // BEFORE lowering any module's functions so no parameter can shadow a re-exported symbol!
            var planned_re_exports = try self.scratch.alloc(std.ArrayList(PlannedReExport), selected_cands.len);
            for (planned_re_exports) |*pl| pl.* = .empty;
            defer {
                for (planned_re_exports) |*pl| pl.deinit(self.scratch);
                self.scratch.free(planned_re_exports);
            }

            for (selected_cands, 0..) |cand_idx, final_i| {
                const cand = &self.candidates.items[cand_idx];
                const final_mod_idx: u32 = @intCast(final_i);
                var ms = &mod_scopes[final_i];

                var seen_non_default_decls: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer seen_non_default_decls.deinit(self.scratch);

                var explicit_own_wires: std.StringHashMapUnmanaged(u32) = .empty;
                defer explicit_own_wires.deinit(self.scratch);
                var reexported_wire_canon: std.StringHashMapUnmanaged(StarCanonLoc) = .empty;
                defer reexported_wire_canon.deinit(self.scratch);
                for (cand.exported_decl_ids.items) |edid| {
                    if (edid >= self.graph.decls.len) continue;
                    // Do not pre-seed `same_mod_export_equals_children` in `explicit_own_wires` before
                    // binding them below as top-level `planned_re_exports`!
                    var is_same_mod_eq_child = false;
                    for (cand.same_mod_export_equals_children.items) |eq_cid| {
                        if (eq_cid == edid) {
                            is_same_mod_eq_child = true;
                            break;
                        }
                    }
                    if (is_same_mod_eq_child) continue;
                    const ed = self.graph.decls[edid];
                    if (ed.modifiers.default_export) continue;
                    const ew = if (ed.export_name) |esid| self.str(esid) else self.str(ed.name);
                    if (ew.len > 0 and !explicit_own_wires.contains(ew)) {
                        try explicit_own_wires.put(self.scratch, ew, edid);
                    }
                }

                // Expose exported members of a same-module `export = <namespace>` at module top-level (`H4`)!
                for (cand.same_mod_export_equals_children.items) |eq_cid| {
                    if (eq_cid >= self.graph.decls.len) continue;
                    const sd = self.graph.decls[eq_cid];
                    const loc = (try self.resolveEffectiveReExportTarget(eq_cid, 0)) orelse continue;
                    if (loc.zig_path.len == 0) continue;
                    const export_wire = if (sd.export_name) |esid| self.str(esid) else self.str(sd.name);
                    if (seen_non_default_decls.contains(eq_cid) or explicit_own_wires.contains(export_wire)) continue;
                    const style = self.declNameStyle(sd);
                    const desired_styled = switch (style) {
                        .preserve => try self.scratch.dupe(u8, export_wire),
                        .camel => try naming.toCamelCase(self.scratch, export_wire),
                        .pascal => try naming.toPascalCase(self.scratch, export_wire),
                        .snake => try naming.toSnakeCase(self.scratch, export_wire),
                    };
                    defer self.scratch.free(desired_styled);
                    const base_check = if (desired_styled.len == 0) "_empty" else desired_styled;
                    if (ms.isTaken(base_check)) continue;
                    try seen_non_default_decls.put(self.scratch, eq_cid, {});
                    if (export_wire.len > 0 and !explicit_own_wires.contains(export_wire)) {
                        try explicit_own_wires.put(self.scratch, export_wire, eq_cid);
                    }

                    const sb = try ms.bind(export_wire, style);
                    try planned_re_exports[final_i].append(self.scratch, .{
                        .source_decl_id = eq_cid,
                        .zig_ident = try self.alloc.dupe(u8, sb.zig_ident),
                        .logical_name = try self.alloc.dupe(u8, sb.logical_name),
                        .wire_name = try self.alloc.dupe(u8, sb.wire_name),
                        .is_default_export = false,
                        .target_module_index = loc.module_index,
                        .target_zig_path = loc.zig_path,
                    });
                    sb.deinit(self.scratch);
                }

                // Process `cand.foreign_exports` BEFORE `star_items`: the Go extractor already filters
                // ambiguous `export *` bindings per module while keeping explicit re-exports
                // (`import { X } from './a'; export { X }`) and non-ambiguous intermediate overrides
                // (`mid` overriding `b`'s `X`). Recording bound wires in `reexported_wire_canon`
                // ensures explicit/resolved bindings take precedence over `star_items`.
                for (cand.foreign_exports.items) |fe| {
                    if (self.merged_ns_consumed.contains(fe.decl_id)) continue;
                    if (fe.decl_id >= self.graph.decls.len) continue;
                    const sd = self.graph.decls[fe.decl_id];
                    const loc = (try self.resolveEffectiveReExportTarget(fe.decl_id, 0)) orelse continue;
                    if (loc.zig_path.len == 0 or loc.module_index == final_mod_idx) continue;

                    const export_wire = fe.wire_name_override orelse
                        (if (sd.export_name) |esid| self.str(esid) else self.str(sd.name));
                    const style: naming.NameStyle = if (fe.wire_name_override != null)
                        .preserve
                    else if (self.merged_ctor_var_consumed.contains(fe.decl_id) or self.merged_fn_consumed.contains(fe.decl_id))
                        .pascal
                    else
                        self.declNameStyle(sd);

                    if (!fe.is_default_export) {
                        if (seen_non_default_decls.contains(fe.decl_id)) continue;
                        const cur_canon: StarCanonLoc = .{
                            .module_index = loc.module_index,
                            .canonical_decl_id = StarCanonLoc.resolveCanonDeclId(self.graph.decls, fe.decl_id),
                            .zig_path = loc.zig_path,
                        };
                        if (explicit_own_wires.get(export_wire)) |own_edid| {
                            const own_canon_id = StarCanonLoc.resolveCanonDeclId(self.graph.decls, own_edid);
                            if (!StarCanonLoc.areMergedPeers(self.graph.decls, own_canon_id, cur_canon.canonical_decl_id)) continue;
                        }
                        if (reexported_wire_canon.get(export_wire)) |prev_canon| {
                            if (!StarCanonLoc.sameSymbol(self.graph.decls, prev_canon, cur_canon)) continue;
                        }
                        const desired_styled = switch (style) {
                            .preserve => try self.scratch.dupe(u8, export_wire),
                            .camel => try naming.toCamelCase(self.scratch, export_wire),
                            .pascal => try naming.toPascalCase(self.scratch, export_wire),
                            .snake => try naming.toSnakeCase(self.scratch, export_wire),
                        };
                        defer self.scratch.free(desired_styled);
                        const base_check = if (desired_styled.len == 0) "_empty" else desired_styled;
                        if (ms.isTaken(base_check)) continue;
                        try seen_non_default_decls.put(self.scratch, fe.decl_id, {});
                        if (export_wire.len > 0 and !reexported_wire_canon.contains(export_wire)) {
                            try reexported_wire_canon.put(self.scratch, export_wire, cur_canon);
                        }
                    }

                    const sb = try ms.bind(export_wire, style);
                    try planned_re_exports[final_i].append(self.scratch, .{
                        .source_decl_id = fe.decl_id,
                        .zig_ident = try self.alloc.dupe(u8, sb.zig_ident),
                        .logical_name = try self.alloc.dupe(u8, sb.logical_name),
                        .wire_name = try self.alloc.dupe(u8, sb.wire_name),
                        .is_default_export = fe.is_default_export,
                        .target_module_index = loc.module_index,
                        .target_zig_path = loc.zig_path,
                    });
                    sb.deinit(self.scratch);
                }

                var visiting_star_smods: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer visiting_star_smods.deinit(self.scratch);
                var visiting_star_cands: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer visiting_star_cands.deinit(self.scratch);
                var root_hit_cycle = false;
                const star_summary = try self.getCandStarSummary(
                    cand_idx,
                    &visiting_star_smods,
                    &visiting_star_cands,
                    &root_hit_cycle,
                );

                for (star_summary.nested_star_items) |ri| {
                    const item = ri.item;
                    if (ri.canon.module_index == final_mod_idx) continue;
                    const sd = self.graph.decls[item.decl_id];
                    const export_wire = ri.export_wire;
                    if (explicit_own_wires.contains(export_wire)) continue;
                    if (item.wire_name_override == null and seen_non_default_decls.contains(item.decl_id)) continue;
                    const cur_canon = ri.canon;
                    if (reexported_wire_canon.get(export_wire)) |prev_canon| {
                        if (!StarCanonLoc.sameSymbol(self.graph.decls, prev_canon, cur_canon)) continue;
                    }

                    const style: naming.NameStyle = if (item.wire_name_override != null)
                        .preserve
                    else if (self.merged_ctor_var_consumed.contains(item.decl_id) or self.merged_fn_consumed.contains(item.decl_id))
                        .pascal
                    else
                        self.declNameStyle(sd);
                    const desired_styled = switch (style) {
                        .preserve => try self.scratch.dupe(u8, export_wire),
                        .camel => try naming.toCamelCase(self.scratch, export_wire),
                        .pascal => try naming.toPascalCase(self.scratch, export_wire),
                        .snake => try naming.toSnakeCase(self.scratch, export_wire),
                    };
                    defer self.scratch.free(desired_styled);
                    const base_check = if (desired_styled.len == 0) "_empty" else desired_styled;

                    // `export *` in TypeScript does NOT override a direct export of the same name.
                    if (ms.isTaken(base_check)) continue;
                    if (item.wire_name_override == null) {
                        try seen_non_default_decls.put(self.scratch, item.decl_id, {});
                    }
                    if (export_wire.len > 0 and !reexported_wire_canon.contains(export_wire)) {
                        try reexported_wire_canon.put(self.scratch, export_wire, cur_canon);
                    }

                    const sb = try ms.bind(export_wire, style);
                    try planned_re_exports[final_i].append(self.scratch, .{
                        .source_decl_id = item.decl_id,
                        .zig_ident = try self.alloc.dupe(u8, sb.zig_ident),
                        .logical_name = try self.alloc.dupe(u8, sb.logical_name),
                        .wire_name = try self.alloc.dupe(u8, sb.wire_name),
                        .is_default_export = false,
                        .target_module_index = ri.canon.module_index,
                        .target_zig_path = ri.canon.zig_path,
                    });
                    sb.deinit(self.scratch);
                }
            }

            // Assign unique `root.zig` export identifiers for all emitted modules, binding
            // `is_primary` modules first so non-primary transitive modules never shadow them!
            var root_scope = naming.ScopeNamer.initContainer(self.scratch, null);
            defer root_scope.deinit();
            try root_scope.reserve("zigar_js");

            var root_export_idents = try self.scratch.alloc([]const u8, selected_cands.len);
            defer self.scratch.free(root_export_idents);
            var root_export_logicals = try self.scratch.alloc([]const u8, selected_cands.len);
            defer self.scratch.free(root_export_logicals);

            for ([_]bool{ true, false }) |primary_pass| {
                for (selected_cands, 0..) |cand_idx, final_i| {
                    const cand = &self.candidates.items[cand_idx];
                    if (cand.is_primary != primary_pass) continue;
                    const rb = try root_scope.bind(cand.substituted_specifier, .snake);
                    root_export_idents[final_i] = try self.alloc.dupe(u8, rb.zig_ident);
                    root_export_logicals[final_i] = try self.alloc.dupe(u8, rb.logical_name);
                    rb.deinit(self.scratch);
                }
            }

            var modules = try self.alloc.alloc(ModuleIr, selected_cands.len);

            // Pass 3: Lower declarations and append planned cross-module re-export aliases!
            for (selected_cands, 0..) |cand_idx, final_i| {
                const cand = &self.candidates.items[cand_idx];
                const final_mod_idx: u32 = @intCast(final_i);
                const ms = &mod_scopes[final_i];

                const root_export_ident = root_export_idents[final_i];
                const root_export_logical = root_export_logicals[final_i];

                var imports_used: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer imports_used.deinit(self.scratch);
                var needs_runtime = false;

                var decl_irs: std.ArrayList(DeclIr) = .empty;
                self.cur_mod_idx = final_mod_idx;
                self.cur_cand_idx = cand_idx;
                self.cur_mod_specifier = cand.substituted_specifier;
                self.cur_mod_hoisted_locs.clearRetainingCapacity();
                self.cur_mod_closed_types.clearRetainingCapacity();
                self.cur_mod_enum_member_types.clearRetainingCapacity();
                self.cur_mod_unit_literal_types.clearRetainingCapacity();
                self.cur_mod_property_key_loc = null;
                self.cur_mod_array_buffer_view_loc = null;
                self.cur_mod_decls_out = &decl_irs;
                self.cur_mod_root_scope = ms;
                self.cur_mod_anon_counter = 0;
                self.inline_anon_depth = 0;
                defer {
                    self.cur_cand_idx = null;
                    self.cur_mod_decls_out = null;
                    self.cur_mod_root_scope = null;
                }

                for (cand.decl_ids.items) |did| {
                    try self.lowerDeclIntoList(
                        final_mod_idx,
                        did,
                        true,
                        ms,
                        &prebound_names,
                        &prebound_overloads,
                        &.{},
                        &imports_used,
                        &needs_runtime,
                        &decl_irs,
                    );
                }

                for (planned_re_exports[final_i].items) |pre| {
                    if (pre.target_module_index != final_mod_idx) {
                        try imports_used.put(self.scratch, pre.target_module_index, {});
                    }
                    const is_pure_eq_ns = self.pure_export_equals_ns.contains(pre.source_decl_id);
                    const is_type_only_re = pre.source_decl_id < self.graph.decls.len and
                        ((self.graph.decls[pre.source_decl_id].kind == .re_export_decl and
                            self.graph.decls[pre.source_decl_id].kind.re_export_decl.is_type_only) or
                            (self.graph.decls[pre.source_decl_id].kind == .import_equals_decl and
                                self.graph.decls[pre.source_decl_id].kind.import_equals_decl.is_type_only));
                    try decl_irs.append(self.alloc, .{
                        .source_decl_id = pre.source_decl_id,
                        .zig_ident = pre.zig_ident,
                        .logical_name = pre.logical_name,
                        .wire_name = pre.wire_name,
                        .is_exported = true,
                        .is_js_exported = !is_pure_eq_ns,
                        .is_default_export = pre.is_default_export,
                        .jsdoc = null,
                        .kind = .{
                            .re_export_decl = .{
                                .target_module_index = pre.target_module_index,
                                .target_zig_path = pre.target_zig_path,
                                .is_type_only = is_type_only_re,
                            },
                        },
                    });
                }

                try deduplicateDeclIrsInPlace(self.scratch, &decl_irs);

                // Materialize aliased namespace child re-exports (`namespace path { export { path as posix, path as win32 } }`)
                // as concrete sub-namespaces so runtime wire calls emit `.ns_path = &.{"posix"}` / `.ns_path = &.{"win32"}`
                // while aliasing pure nominal types back to the parent namespace!
                for (decl_irs.items) |*di| {
                    if (di.kind != .namespace_decl) continue;
                    var mutated_children: ?[]DeclIr = null;
                    for (di.kind.namespace_decl.children, 0..) |cd, c_idx_inner| {
                        if (cd.kind != .re_export_decl) continue;
                        const re = cd.kind.re_export_decl;
                        if (re.is_type_only or re.target_module_index != final_mod_idx or re.target_zig_path.len != 1) continue;
                        var target_ns_opt: ?DeclIr = null;
                        for (decl_irs.items) |cand_ns| {
                            if (cand_ns.kind == .namespace_decl and
                                (std.mem.eql(u8, cand_ns.zig_ident, re.target_zig_path[0]) or
                                    std.mem.eql(u8, cand_ns.logical_name, re.target_zig_path[0])))
                            {
                                target_ns_opt = cand_ns;
                                break;
                            }
                        }
                        const target_ns_decl = target_ns_opt orelse continue;
                        if (std.mem.eql(u8, cd.wire_name, target_ns_decl.wire_name)) continue;

                        const orig_ns = target_ns_decl.kind.namespace_decl;
                        const sub_children = try self.alloc.alloc(DeclIr, orig_ns.children.len);
                        for (orig_ns.children, 0..) |orig_child, oc_i| {
                            switch (orig_child.kind) {
                                .function_decl, .overload_dispatch, .global_var => {
                                    sub_children[oc_i] = orig_child;
                                },
                                else => {
                                    const alias_path = try self.alloc.alloc([]const u8, 2);
                                    alias_path[0] = target_ns_decl.zig_ident;
                                    alias_path[1] = orig_child.zig_ident;
                                    sub_children[oc_i] = .{
                                        .source_decl_id = orig_child.source_decl_id,
                                        .zig_ident = orig_child.zig_ident,
                                        .logical_name = orig_child.logical_name,
                                        .wire_name = orig_child.wire_name,
                                        .is_exported = orig_child.is_exported,
                                        .is_js_exported = orig_child.is_js_exported,
                                        .is_default_export = false,
                                        .jsdoc = orig_child.jsdoc,
                                        .kind = .{
                                            .re_export_decl = .{
                                                .target_module_index = final_mod_idx,
                                                .target_zig_path = alias_path,
                                                .is_type_only = false,
                                            },
                                        },
                                    };
                                },
                            }
                        }

                        if (mutated_children == null) {
                            const copy = try self.alloc.alloc(DeclIr, di.kind.namespace_decl.children.len);
                            @memcpy(copy, di.kind.namespace_decl.children);
                            mutated_children = copy;
                        }
                        mutated_children.?[c_idx_inner] = .{
                            .source_decl_id = cd.source_decl_id,
                            .zig_ident = cd.zig_ident,
                            .logical_name = cd.logical_name,
                            .wire_name = cd.wire_name,
                            .is_exported = cd.is_exported,
                            .is_js_exported = cd.is_js_exported,
                            .is_default_export = cd.is_default_export,
                            .jsdoc = cd.jsdoc,
                            .kind = .{
                                .namespace_decl = .{
                                    .merged_call_fns = orig_ns.merged_call_fns,
                                    .children = sub_children,
                                },
                            },
                        };
                    }
                    if (mutated_children) |mc| {
                        di.kind = .{
                            .namespace_decl = .{
                                .merged_call_fns = di.kind.namespace_decl.merged_call_fns,
                                .children = mc,
                            },
                        };
                    }
                }

                // Route cross-module `export = Ns.subNs` (`declare module "node:path/win32" { export = path.win32 }`)
                // re-exports through the materialized sub-namespace (`Path.win32.*`) instead of the root `Path.*`!
                if (cand.export_equals_subns_decl_id) |subns_did| {
                    if (self.decl_locations.get(subns_did)) |subns_loc| {
                        if (subns_loc.module_index != final_mod_idx and subns_loc.zig_path.len == 2) {
                            const parent_ns_id = self.child_to_parent_ns.get(subns_did);
                            for (decl_irs.items) |*di| {
                                if (di.kind != .re_export_decl) continue;
                                const re = &di.kind.re_export_decl;
                                if (re.target_module_index != subns_loc.module_index) continue;
                                if (re.target_zig_path.len == 1 and std.mem.eql(u8, re.target_zig_path[0], subns_loc.zig_path[0])) {
                                    var matched_sibling_loc: ?DeclLocation = null;
                                    if (parent_ns_id) |pns_id| {
                                        var p_peers: [8]u32 = undefined;
                                        var p_count: usize = 0;
                                        p_peers[p_count] = pns_id;
                                        p_count += 1;
                                        if (pns_id < self.graph.decls.len) {
                                            for (self.graph.decls[pns_id].merged_with) |mpid| {
                                                if (p_count < p_peers.len and mpid < self.graph.decls.len and self.graph.decls[mpid].kind == .namespace_decl) {
                                                    p_peers[p_count] = mpid;
                                                    p_count += 1;
                                                }
                                            }
                                        }
                                        outer_sib: for (p_peers[0..p_count]) |ppid| {
                                            for (self.graph.decls[ppid].kind.namespace_decl) |scid| {
                                                if (self.isAliasedNamespaceChildReExport(scid) == null) continue;
                                                const scd = self.graph.decls[scid];
                                                const swire = if (scd.export_name) |esid| self.str(esid) else self.str(scd.name);
                                                if (std.mem.eql(u8, swire, di.wire_name)) {
                                                    matched_sibling_loc = self.decl_locations.get(scid);
                                                    break :outer_sib;
                                                }
                                            }
                                        }
                                    }
                                    if (matched_sibling_loc) |sib_loc| {
                                        re.target_zig_path = sib_loc.zig_path;
                                    } else {
                                        re.target_zig_path = subns_loc.zig_path;
                                    }
                                } else if (re.target_zig_path.len == 2 and
                                    std.mem.eql(u8, re.target_zig_path[0], subns_loc.zig_path[0]) and
                                    (di.source_decl_id == null or self.isAliasedNamespaceChildReExport(di.source_decl_id.?) == null))
                                {
                                    const sub_path = try self.alloc.alloc([]const u8, 3);
                                    sub_path[0] = subns_loc.zig_path[0];
                                    sub_path[1] = subns_loc.zig_path[1];
                                    sub_path[2] = re.target_zig_path[1];
                                    re.target_zig_path = sub_path;
                                }
                            }
                        }
                    }
                }

                var export_equals_ident: ?[]const u8 = null;
                var export_equals_wire_name: ?[]const u8 = null;
                if (cand.export_equals_decl_id) |eq_did| {
                    for (decl_irs.items) |di| {
                        if (di.source_decl_id == eq_did) {
                            export_equals_ident = di.logical_name;
                            export_equals_wire_name = di.wire_name;
                            break;
                        }
                    }
                    if (export_equals_ident == null and eq_did < self.graph.decls.len) {
                        const eq_d = self.graph.decls[eq_did];
                        const eq_wire = if (eq_d.export_name) |esid| self.str(esid) else self.str(eq_d.name);
                        for (eq_d.merged_with) |mid| {
                            for (decl_irs.items) |di| {
                                if (di.source_decl_id == mid and merge_decls.sameWireName(eq_wire, di.wire_name)) {
                                    export_equals_ident = di.logical_name;
                                    export_equals_wire_name = di.wire_name;
                                    break;
                                }
                            }
                            if (export_equals_ident != null) break;
                        }
                    }
                }

                // Deterministic sorted module imports (excluding self-imports).
                var dep_indices: std.ArrayList(u32) = .empty;
                defer dep_indices.deinit(self.scratch);
                var imp_it = imports_used.keyIterator();
                while (imp_it.next()) |dep_ptr| {
                    if (dep_ptr.* != final_mod_idx) {
                        try dep_indices.append(self.scratch, dep_ptr.*);
                    }
                }
                std.mem.sort(u32, dep_indices.items, {}, std.sort.asc(u32));

                var mod_imports = try self.alloc.alloc(ModuleImportIr, dep_indices.items.len);
                for (dep_indices.items, 0..) |dep_idx, i_pos| {
                    const target_cand = &self.candidates.items[selected_cands[dep_idx]];
                    const alias_raw = try std.fmt.allocPrint(self.alloc, "__mod_{d}", .{dep_idx});
                    const rel_imp = try naming.relativeImportPath(
                        self.alloc,
                        cand.rel_zig_path,
                        target_cand.rel_zig_path,
                    );
                    mod_imports[i_pos] = .{
                        .target_module_index = dep_idx,
                        .local_alias = alias_raw,
                        .rel_import_path = rel_imp,
                    };
                }

                modules[final_i] = .{
                    .index = final_mod_idx,
                    .specifier = cand.substituted_specifier,
                    .wire_specifier = cand.wire_specifier,
                    .rel_zig_path = cand.rel_zig_path,
                    .root_export_ident = root_export_ident,
                    .root_export_logical_name = root_export_logical,
                    .export_equals_ident = export_equals_ident,
                    .export_equals_wire_name = export_equals_wire_name,
                    .is_primary = cand.is_primary,
                    .is_encapsulated_internal = !cand.is_public_export_mod,
                    .needs_root_runtime = needs_runtime,
                    .imports = mod_imports,
                    .decls = try decl_irs.toOwnedSlice(self.alloc),
                };
            }

            try self.resolveRuntimeWireTargetsAndPruneUnreachable(modules, mod_scopes);
            try self.synthesizeReExportAllocCompanions(modules, mod_scopes);
            try self.breakExpansiveGenericCycles(modules);
            try self.breakValueTypeCycles(modules);
            return modules;
        }

        fn resolveRuntimeWireTargetsAndPruneUnreachable(
            self: *Self,
            modules: []ModuleIr,
            mod_scopes: []naming.ScopeNamer,
        ) error{OutOfMemory}!void {
            const ModDeclKey = struct {
                mod_idx: u32,
                sid: u32,
            };
            const ClaimInfo = struct {
                wire_module: []const u8,
                wire_path_prefix: []const []const u8,
                wire_name: []const u8,
                is_default: bool,
            };
            const CloneEntry = struct {
                wire_module: []const u8,
                wire_name: []const u8,
                is_default: bool,
                primary_zig_ident: []const u8,
            };

            var natively_reachable: std.AutoHashMapUnmanaged(ModDeclKey, void) = .empty;
            defer natively_reachable.deinit(self.scratch);
            var claimed_targets: std.AutoHashMapUnmanaged(ModDeclKey, ClaimInfo) = .empty;
            defer claimed_targets.deinit(self.scratch);
            var cloned_aliases: std.AutoHashMapUnmanaged(ModDeclKey, std.ArrayList(CloneEntry)) = .empty;
            defer {
                var cit = cloned_aliases.valueIterator();
                while (cit.next()) |lst| lst.deinit(self.scratch);
                cloned_aliases.deinit(self.scratch);
            }

            // 1. Mark declarations that are directly reachable from a public runtime module
            // (or global scope).
            for (modules, 0..) |m, mi| {
                const m_idx: u32 = @intCast(mi);
                for (m.decls) |d| {
                    if (d.kind == .re_export_decl or d.kind == .namespace_re_export) continue;
                    const sid = d.source_decl_id orelse continue;
                    if (d.is_global_scope) {
                        try natively_reachable.put(self.scratch, .{ .mod_idx = m_idx, .sid = sid }, {});
                        continue;
                    }
                    if (m.is_encapsulated_internal) continue;
                    const is_eq = m.export_equals_ident != null and std.mem.eql(u8, d.logical_name, m.export_equals_ident.?);
                    if (d.is_js_exported or is_eq or self.pure_export_equals_ns.contains(sid)) {
                        try natively_reachable.put(self.scratch, .{ .mod_idx = m_idx, .sid = sid }, {});
                        if (is_eq and sid < self.graph.decls.len) {
                            for (self.graph.decls[sid].merged_with) |peer_sid| {
                                try natively_reachable.put(self.scratch, .{ .mod_idx = m_idx, .sid = peer_sid }, {});
                            }
                        }
                    }
                }
            }

            var mod_mut_decls = try self.scratch.alloc([]DeclIr, modules.len);
            defer self.scratch.free(mod_mut_decls);
            for (modules, 0..) |*m, mi| {
                const md = try self.alloc.dupe(DeclIr, m.decls);
                mod_mut_decls[mi] = md;
                m.decls = md;
            }

            const claimDeclAndMergedPeers = struct {
                fn run(
                    s: *Self,
                    claimed: *std.AutoHashMapUnmanaged(ModDeclKey, ClaimInfo),
                    natively: *const std.AutoHashMapUnmanaged(ModDeclKey, void),
                    mut_decls: []DeclIr,
                    t_idx: u32,
                    sid: u32,
                    wire_mod: []const u8,
                    wire_pfx: []const []const u8,
                    wire_name_val: []const u8,
                    wire_name_opt: ?[]const u8,
                    is_def: bool,
                ) error{OutOfMemory}!void {
                    try claimed.put(s.scratch, .{ .mod_idx = t_idx, .sid = sid }, .{
                        .wire_module = wire_mod,
                        .wire_path_prefix = wire_pfx,
                        .wire_name = wire_name_val,
                        .is_default = is_def,
                    });
                    for (mut_decls) |*item| {
                        if (item.source_decl_id != sid) continue;
                        if (item.kind == .re_export_decl or item.kind == .namespace_re_export) continue;
                        item.wire_module_override = wire_mod;
                        item.wire_path_prefix = wire_pfx;
                        if (wire_name_opt) |wn| {
                            item.wire_name = wn;
                        }
                        if (is_def and !item.is_synthetic_companion) {
                            item.is_default_export = true;
                        }
                    }
                    if (sid < s.graph.decls.len) {
                        for (s.graph.decls[sid].merged_with) |peer_sid| {
                            const pkey: ModDeclKey = .{ .mod_idx = t_idx, .sid = peer_sid };
                            if (natively.contains(pkey) or claimed.contains(pkey)) continue;
                            try claimed.put(s.scratch, pkey, .{
                                .wire_module = wire_mod,
                                .wire_path_prefix = wire_pfx,
                                .wire_name = wire_name_val,
                                .is_default = is_def,
                            });
                            for (mut_decls) |*item| {
                                if (item.source_decl_id != peer_sid) continue;
                                if (item.kind == .re_export_decl or item.kind == .namespace_re_export) continue;
                                item.wire_module_override = wire_mod;
                                item.wire_path_prefix = wire_pfx;
                                if (wire_name_opt) |wn| {
                                    item.wire_name = wn;
                                }
                            }
                        }
                    }
                }
            }.run;

            // 2a. Public `export * as ns from "./internal"` (`namespace_re_export`) claims
            // exported declarations on encapsulated internal target modules recursively across
            // direct exports, ES-filtered `.re_export_decl`s (`export * from './deep'`), and
            // nested `namespace_re_export`s under `.ns_path = &.{ ns, ... }`.
            const NsClaimWork = struct {
                target_mod_idx: u32,
                pfx: []const []const u8,
                depth: usize,
            };
            for (modules) |pub_mod| {
                if (pub_mod.is_encapsulated_internal) continue;
                for (pub_mod.decls) |d| {
                    if (!d.is_exported or !d.is_js_exported) continue;
                    if (d.kind != .namespace_re_export) continue;
                    const nre = d.kind.namespace_re_export;
                    if (nre.is_type_only or nre.target_module_index >= modules.len) continue;
                    const root_pfx = try self.alloc.dupe([]const u8, &.{d.wire_name});

                    var ns_queue: std.ArrayList(NsClaimWork) = .empty;
                    defer ns_queue.deinit(self.scratch);
                    var visited_ns_mods: std.AutoHashMapUnmanaged(u32, void) = .empty;
                    defer visited_ns_mods.deinit(self.scratch);
                    try ns_queue.append(self.scratch, .{
                        .target_mod_idx = nre.target_module_index,
                        .pfx = root_pfx,
                        .depth = 0,
                    });

                    var nq_i: usize = 0;
                    while (nq_i < ns_queue.items.len) : (nq_i += 1) {
                        const work = ns_queue.items[nq_i];
                        if (work.depth > 16 or work.target_mod_idx >= modules.len) continue;
                        if (visited_ns_mods.contains(work.target_mod_idx)) continue;
                        try visited_ns_mods.put(self.scratch, work.target_mod_idx, {});

                        const t_idx = work.target_mod_idx;
                        for (modules[t_idx].decls) |td| {
                            if (!td.is_exported or !td.is_js_exported) continue;
                            switch (td.kind) {
                                .namespace_re_export => |sub_nre| {
                                    if (sub_nre.is_type_only or sub_nre.target_module_index >= modules.len) continue;
                                    var next_pfx = try self.alloc.alloc([]const u8, work.pfx.len + 1);
                                    @memcpy(next_pfx[0..work.pfx.len], work.pfx);
                                    next_pfx[work.pfx.len] = td.wire_name;
                                    try ns_queue.append(self.scratch, .{
                                        .target_mod_idx = sub_nre.target_module_index,
                                        .pfx = next_pfx,
                                        .depth = work.depth + 1,
                                    });
                                },
                                .re_export_decl => |sub_re0| {
                                    if (sub_re0.is_type_only or td.is_default_export) continue;
                                    var cur_m = sub_re0.target_module_index;
                                    var cur_p = sub_re0.target_zig_path;
                                    var chain_to = false;
                                    var hops: usize = 0;
                                    while (hops < 16) : (hops += 1) {
                                        if (cur_m >= modules.len or cur_p.len != 1) break;
                                        const found = findNestedDeclByZigPath(modules[cur_m].decls, cur_p) orelse break;
                                        if (found.kind != .re_export_decl) break;
                                        if (found.kind.re_export_decl.is_type_only) {
                                            chain_to = true;
                                            break;
                                        }
                                        cur_m = found.kind.re_export_decl.target_module_index;
                                        cur_p = found.kind.re_export_decl.target_zig_path;
                                    }
                                    if (chain_to or cur_m >= modules.len or cur_p.len != 1) continue;
                                    const orig_td = findNestedDeclByZigPath(modules[cur_m].decls, cur_p) orelse continue;
                                    if (orig_td.kind == .re_export_decl or orig_td.kind == .namespace_re_export) continue;
                                    const orig_sid = orig_td.source_decl_id orelse continue;
                                    const okey: ModDeclKey = .{ .mod_idx = cur_m, .sid = orig_sid };
                                    if (natively_reachable.contains(okey) or claimed_targets.contains(okey)) continue;
                                    try claimDeclAndMergedPeers(
                                        self,
                                        &claimed_targets,
                                        &natively_reachable,
                                        mod_mut_decls[cur_m],
                                        cur_m,
                                        orig_sid,
                                        pub_mod.wire_specifier,
                                        work.pfx,
                                        td.wire_name,
                                        td.wire_name,
                                        false,
                                    );
                                },
                                else => {
                                    if (td.is_default_export) continue;
                                    if (!modules[t_idx].is_encapsulated_internal) continue;
                                    const tsid = td.source_decl_id orelse continue;
                                    const key: ModDeclKey = .{ .mod_idx = t_idx, .sid = tsid };
                                    if (natively_reachable.contains(key) or claimed_targets.contains(key)) continue;
                                    try claimDeclAndMergedPeers(
                                        self,
                                        &claimed_targets,
                                        &natively_reachable,
                                        mod_mut_decls[t_idx],
                                        t_idx,
                                        tsid,
                                        pub_mod.wire_specifier,
                                        work.pfx,
                                        td.wire_name,
                                        null,
                                        false,
                                    );
                                },
                            }
                        }
                    }
                }
            }

            // 2b. Public `.re_export_decl` (`export { foo as bar } from "./internal"` or same-file
            // `declare function fnA(); export { fnA as alias1, fnA as alias2 }`) claims or clones
            // otherwise-unreachable canonical declarations with the public module's wire specifier
            // and exported wire name.
            var next_synth_sid: u32 = @intCast(self.graph.decls.len + 1_000_000);
            for (modules, 0..) |*pub_mod, pub_mi| {
                if (pub_mod.is_encapsulated_internal) continue;
                const pub_mod_idx: u32 = @intCast(pub_mi);
                const orig_pub_len = mod_mut_decls[pub_mi].len;
                var di: usize = 0;
                while (di < orig_pub_len) : (di += 1) {
                    const d_val = mod_mut_decls[pub_mi][di];
                    if (!d_val.is_exported or !d_val.is_js_exported or d_val.kind != .re_export_decl) continue;
                    const re0 = d_val.kind.re_export_decl;
                    if (re0.is_type_only) continue;

                    // Follow `.re_export_decl` chains to canonical `(orig_mod_idx, orig_zig_path)`.
                    var cur_mod_idx = re0.target_module_index;
                    var cur_path = re0.target_zig_path;
                    var chain_type_only = false;
                    var hops: usize = 0;
                    while (hops < 16) : (hops += 1) {
                        if (cur_mod_idx >= modules.len or cur_path.len != 1) break;
                        const found = findNestedDeclByZigPath(modules[cur_mod_idx].decls, cur_path) orelse break;
                        if (found.kind != .re_export_decl) break;
                        if (found.kind.re_export_decl.is_type_only) {
                            chain_type_only = true;
                            break;
                        }
                        cur_mod_idx = found.kind.re_export_decl.target_module_index;
                        cur_path = found.kind.re_export_decl.target_zig_path;
                    }
                    if (chain_type_only or cur_mod_idx >= modules.len or cur_path.len == 0) continue;
                    if (cur_path.len > 1) {
                        if (findNestedDeclByZigPath(modules[cur_mod_idx].decls, cur_path[0..1])) |root_d| {
                            if (root_d.source_decl_id) |rsid| {
                                const rkey: ModDeclKey = .{ .mod_idx = cur_mod_idx, .sid = rsid };
                                if (!natively_reachable.contains(rkey) and !claimed_targets.contains(rkey)) {
                                    try claimDeclAndMergedPeers(
                                        self,
                                        &claimed_targets,
                                        &natively_reachable,
                                        mod_mut_decls[cur_mod_idx],
                                        cur_mod_idx,
                                        rsid,
                                        pub_mod.wire_specifier,
                                        &.{},
                                        root_d.wire_name,
                                        null,
                                        false,
                                    );
                                }
                            }
                        }
                        continue;
                    }
                    const orig_d_val = findNestedDeclByZigPath(modules[cur_mod_idx].decls, cur_path) orelse continue;
                    if (orig_d_val.kind == .re_export_decl or orig_d_val.kind == .namespace_re_export) continue;
                    const orig_sid = orig_d_val.source_decl_id orelse continue;
                    const key: ModDeclKey = .{ .mod_idx = cur_mod_idx, .sid = orig_sid };
                    if (natively_reachable.contains(key)) continue;

                    if (claimed_targets.get(key)) |prev_claim| {
                        const same_target = std.mem.eql(u8, prev_claim.wire_module, pub_mod.wire_specifier) and
                            prev_claim.wire_path_prefix.len == 0 and
                            std.mem.eql(u8, prev_claim.wire_name, d_val.wire_name) and
                            prev_claim.is_default == d_val.is_default_export;
                        if (same_target) continue;

                        // Check if we already synthesized a clone for `(pub_mod.wire_specifier, d_val.wire_name, d_val.is_default_export)`.
                        if (cloned_aliases.get(key)) |existing_list| {
                            var reused = false;
                            for (existing_list.items) |ce| {
                                if (std.mem.eql(u8, ce.wire_module, pub_mod.wire_specifier) and
                                    std.mem.eql(u8, ce.wire_name, d_val.wire_name) and
                                    ce.is_default == d_val.is_default_export)
                                {
                                    mod_mut_decls[pub_mi][di].kind = .{
                                        .re_export_decl = .{
                                            .target_module_index = cur_mod_idx,
                                            .target_zig_path = try self.alloc.dupe([]const u8, &.{ce.primary_zig_ident}),
                                            .is_type_only = false,
                                        },
                                    };
                                    reused = true;
                                    break;
                                }
                            }
                            if (reused) continue;
                        }

                        if (orig_d_val.kind == .function_decl or
                            orig_d_val.kind == .overload_dispatch or
                            orig_d_val.kind == .global_var)
                        {
                            const clone_sid = next_synth_sid;
                            next_synth_sid += 1;
                            const target_scope = &mod_scopes[cur_mod_idx];
                            const old_primary_logical = orig_d_val.logical_name;
                            const old_primary_zig = orig_d_val.zig_ident;
                            const export_cloned = (cur_mod_idx != pub_mod_idx);

                            var orig_group: std.ArrayList(DeclIr) = .empty;
                            defer orig_group.deinit(self.scratch);
                            for (modules[cur_mod_idx].decls) |item| {
                                if (item.source_decl_id == orig_sid and
                                    item.kind != .re_export_decl and
                                    item.kind != .namespace_re_export)
                                {
                                    try orig_group.append(self.scratch, item);
                                }
                            }

                            var ident_remap: std.StringHashMapUnmanaged([]const u8) = .empty;
                            defer ident_remap.deinit(self.scratch);
                            var cloned_items: std.ArrayList(DeclIr) = .empty;
                            defer cloned_items.deinit(self.scratch);
                            var new_primary_zig: ?[]const u8 = null;

                            // First pass: clone non-dispatch items so arm `zig_ident`s + companions exist in `ident_remap`.
                            const CloneCompMap = struct {
                                zig_ident: []const u8,
                                comps: BoundSigCompanions,
                            };
                            var comp_remap: std.StringHashMapUnmanaged(CloneCompMap) = .empty;
                            defer comp_remap.deinit(self.scratch);

                            for (orig_group.items) |item| {
                                if (item.kind == .overload_dispatch) continue;
                                const suffix = if (std.mem.startsWith(u8, item.logical_name, old_primary_logical))
                                    item.logical_name[old_primary_logical.len..]
                                else
                                    "";
                                const raw_name = try std.fmt.allocPrint(self.scratch, "{s}{s}", .{ d_val.logical_name, suffix });
                                defer self.scratch.free(raw_name);
                                const b = try target_scope.bind(raw_name, .preserve);
                                const czig = try self.alloc.dupe(u8, b.zig_ident);
                                const clog = try self.alloc.dupe(u8, b.logical_name);
                                b.deinit(self.scratch);

                                var cloned = item;
                                cloned.source_decl_id = clone_sid;
                                cloned.zig_ident = czig;
                                cloned.logical_name = clog;
                                cloned.wire_name = d_val.wire_name;
                                cloned.wire_module_override = pub_mod.wire_specifier;
                                cloned.wire_path_prefix = &.{};
                                cloned.is_exported = export_cloned;
                                cloned.is_default_export = d_val.is_default_export and !item.is_synthetic_companion;

                                if (cloned.kind == .function_decl) {
                                    const comps = try self.bindSigCompanions(target_scope, clog, &cloned.kind.function_decl);
                                    cloned.alloc_companion_ident = comps.alloc_ident;
                                    cloned.slice_companion_ident = comps.slice_ident;
                                    cloned.slice_alloc_companion_ident = comps.slice_alloc_ident;
                                    cloned.narrow_companion_ident = comps.narrow_ident;
                                    cloned.narrow_alloc_companion_ident = comps.narrow_alloc_ident;
                                    cloned.default_companion_ident = comps.default_ident;
                                    cloned.default_alloc_companion_ident = comps.default_alloc_ident;
                                    cloned.infer_companion_ident = comps.infer_ident;
                                    cloned.infer_alloc_companion_ident = comps.infer_alloc_ident;
                                    try comp_remap.put(self.scratch, item.zig_ident, .{ .zig_ident = czig, .comps = comps });
                                }
                                try ident_remap.put(self.scratch, item.zig_ident, czig);
                                if (std.mem.eql(u8, item.zig_ident, old_primary_zig)) {
                                    new_primary_zig = czig;
                                }
                                try cloned_items.append(self.scratch, cloned);
                            }

                            // Second pass: clone `overload_dispatch` items with remapped candidate target idents.
                            for (orig_group.items) |item| {
                                if (item.kind != .overload_dispatch) continue;
                                const suffix = if (std.mem.startsWith(u8, item.logical_name, old_primary_logical))
                                    item.logical_name[old_primary_logical.len..]
                                else
                                    "";
                                const raw_name = try std.fmt.allocPrint(self.scratch, "{s}{s}", .{ d_val.logical_name, suffix });
                                defer self.scratch.free(raw_name);
                                const b = try target_scope.bind(raw_name, .preserve);
                                const czig = try self.alloc.dupe(u8, b.zig_ident);
                                const clog = try self.alloc.dupe(u8, b.logical_name);
                                b.deinit(self.scratch);

                                var disp_alloc: ?[]const u8 = null;
                                if (item.alloc_companion_ident != null) {
                                    const raw_da = try std.fmt.allocPrint(self.scratch, "{s}Alloc", .{clog});
                                    defer self.scratch.free(raw_da);
                                    const dab = try target_scope.bind(raw_da, .preserve);
                                    disp_alloc = try self.alloc.dupe(u8, dab.zig_ident);
                                    dab.deinit(self.scratch);
                                }

                                const old_od = item.kind.overload_dispatch;
                                var new_cands = try self.alloc.alloc(OverloadCandidateIr, old_od.candidates.len);
                                for (old_od.candidates, 0..) |oc, ci| {
                                    new_cands[ci] = oc;
                                    if (comp_remap.get(oc.target_ident)) |cm| {
                                        new_cands[ci].target_ident = cm.zig_ident;
                                        new_cands[ci].alloc_target_ident = cm.comps.alloc_ident;
                                        new_cands[ci].slice_target_ident = cm.comps.slice_ident;
                                        new_cands[ci].infer_target_ident = cm.comps.infer_ident;
                                        new_cands[ci].infer_alloc_target_ident = cm.comps.infer_alloc_ident;
                                        new_cands[ci].default_target_ident = cm.comps.default_ident;
                                        new_cands[ci].default_alloc_target_ident = cm.comps.default_alloc_ident;
                                    }
                                }

                                var cloned = item;
                                cloned.source_decl_id = clone_sid;
                                cloned.zig_ident = czig;
                                cloned.logical_name = clog;
                                cloned.wire_name = d_val.wire_name;
                                cloned.wire_module_override = pub_mod.wire_specifier;
                                cloned.wire_path_prefix = &.{};
                                cloned.is_exported = export_cloned;
                                cloned.alloc_companion_ident = disp_alloc;
                                var new_od = old_od;
                                new_od.zig_ident = czig;
                                new_od.logical_name = clog;
                                new_od.alloc_companion_ident = disp_alloc;
                                new_od.candidates = new_cands;
                                cloned.kind = .{ .overload_dispatch = new_od };

                                if (std.mem.eql(u8, item.zig_ident, old_primary_zig)) {
                                    new_primary_zig = czig;
                                }
                                try cloned_items.append(self.scratch, cloned);
                            }

                            if (new_primary_zig) |npz| {
                                const old_slice = mod_mut_decls[cur_mod_idx];
                                var merged_decls = try self.alloc.alloc(DeclIr, old_slice.len + cloned_items.items.len);
                                @memcpy(merged_decls[0..old_slice.len], old_slice);
                                @memcpy(merged_decls[old_slice.len..], cloned_items.items);
                                mod_mut_decls[cur_mod_idx] = merged_decls;
                                modules[cur_mod_idx].decls = merged_decls;

                                try claimed_targets.put(self.scratch, .{ .mod_idx = cur_mod_idx, .sid = clone_sid }, .{
                                    .wire_module = pub_mod.wire_specifier,
                                    .wire_path_prefix = &.{},
                                    .wire_name = d_val.wire_name,
                                    .is_default = d_val.is_default_export,
                                });

                                const gop = try cloned_aliases.getOrPut(self.scratch, key);
                                if (!gop.found_existing) gop.value_ptr.* = .empty;
                                try gop.value_ptr.append(self.scratch, .{
                                    .wire_module = pub_mod.wire_specifier,
                                    .wire_name = d_val.wire_name,
                                    .is_default = d_val.is_default_export,
                                    .primary_zig_ident = npz,
                                });

                                mod_mut_decls[pub_mi][di].kind = .{
                                    .re_export_decl = .{
                                        .target_module_index = cur_mod_idx,
                                        .target_zig_path = try self.alloc.dupe([]const u8, &.{npz}),
                                        .is_type_only = false,
                                    },
                                };
                                if (cur_mod_idx != pub_mod_idx) {
                                    try self.ensureModuleImport(pub_mod, pub_mod_idx, cur_mod_idx, modules[cur_mod_idx].rel_zig_path);
                                }
                            }
                        }
                    } else {
                        try claimDeclAndMergedPeers(
                            self,
                            &claimed_targets,
                            &natively_reachable,
                            mod_mut_decls[cur_mod_idx],
                            cur_mod_idx,
                            orig_sid,
                            pub_mod.wire_specifier,
                            &.{},
                            d_val.wire_name,
                            d_val.wire_name,
                            d_val.is_default_export,
                        );
                    }
                }
            }

            // 2b-ns. Transitively claim `.re_export_decl` targets nested inside reachable
            // `namespace_decl`s (e.g. Rollup-bundled `monaco.d.ts`: `export { editor_main as m }`,
            // `declare namespace editor_main { export { register$3 as css, editor_main_editor as editor } }`,
            // `declare namespace register$3 { export { register$3_cssDefaults as cssDefaults } }`),
            // propagating the accumulated runtime namespace path (`&.{"m", "css"}`).
            {
                const NsDeclWork = struct {
                    mod_idx: u32,
                    ns_sid: u32,
                    wire_mod: []const u8,
                    ns_pfx: []const []const u8,
                    depth: usize,
                };
                var ns_decl_queue: std.ArrayList(NsDeclWork) = .empty;
                defer ns_decl_queue.deinit(self.scratch);
                var visited_ns_decls: std.AutoHashMapUnmanaged(ModDeclKey, void) = .empty;
                defer visited_ns_decls.deinit(self.scratch);

                for (modules, 0..) |m_seed, mi_seed| {
                    const m_idx: u32 = @intCast(mi_seed);
                    for (mod_mut_decls[mi_seed]) |d_seed| {
                        if (d_seed.kind != .namespace_decl or d_seed.is_global_scope) continue;
                        const sid = d_seed.source_decl_id orelse continue;
                        const skey: ModDeclKey = .{ .mod_idx = m_idx, .sid = sid };
                        if (natively_reachable.contains(skey)) {
                            const wmod = d_seed.wire_module_override orelse m_seed.wire_specifier;
                            var next_pfx = try self.alloc.alloc([]const u8, d_seed.wire_path_prefix.len + 1);
                            @memcpy(next_pfx[0..d_seed.wire_path_prefix.len], d_seed.wire_path_prefix);
                            next_pfx[d_seed.wire_path_prefix.len] = d_seed.wire_name;
                            try visited_ns_decls.put(self.scratch, skey, {});
                            try ns_decl_queue.append(self.scratch, .{
                                .mod_idx = m_idx,
                                .ns_sid = sid,
                                .wire_mod = wmod,
                                .ns_pfx = next_pfx,
                                .depth = 0,
                            });
                        } else if (claimed_targets.get(skey)) |cinfo| {
                            var next_pfx = try self.alloc.alloc([]const u8, cinfo.wire_path_prefix.len + 1);
                            @memcpy(next_pfx[0..cinfo.wire_path_prefix.len], cinfo.wire_path_prefix);
                            next_pfx[cinfo.wire_path_prefix.len] = cinfo.wire_name;
                            try visited_ns_decls.put(self.scratch, skey, {});
                            try ns_decl_queue.append(self.scratch, .{
                                .mod_idx = m_idx,
                                .ns_sid = sid,
                                .wire_mod = cinfo.wire_module,
                                .ns_pfx = next_pfx,
                                .depth = 0,
                            });
                        }
                    }
                }

                const processNsChildren = struct {
                    fn run(
                        s: *Self,
                        mods: []ModuleIr,
                        mut_decls_all: [][]DeclIr,
                        claimed: *std.AutoHashMapUnmanaged(ModDeclKey, ClaimInfo),
                        natively: *const std.AutoHashMapUnmanaged(ModDeclKey, void),
                        visited_ns: *std.AutoHashMapUnmanaged(ModDeclKey, void),
                        queue: *std.ArrayList(NsDeclWork),
                        wire_mod: []const u8,
                        cur_pfx: []const []const u8,
                        depth: usize,
                        children: []const DeclIr,
                    ) error{OutOfMemory}!void {
                        if (depth > 16) return;
                        for (children) |cd| {
                            if (!cd.is_exported) continue;
                            switch (cd.kind) {
                                .namespace_decl => |sub_ns| {
                                    var next_pfx = try s.alloc.alloc([]const u8, cur_pfx.len + 1);
                                    @memcpy(next_pfx[0..cur_pfx.len], cur_pfx);
                                    next_pfx[cur_pfx.len] = cd.wire_name;
                                    try run(
                                        s,
                                        mods,
                                        mut_decls_all,
                                        claimed,
                                        natively,
                                        visited_ns,
                                        queue,
                                        wire_mod,
                                        next_pfx,
                                        depth + 1,
                                        sub_ns.children,
                                    );
                                },
                                .re_export_decl => |re0| {
                                    if (re0.is_type_only) continue;
                                    var cur_m = re0.target_module_index;
                                    var cur_p = re0.target_zig_path;
                                    var chain_to = false;
                                    var hops: usize = 0;
                                    while (hops < 16) : (hops += 1) {
                                        if (cur_m >= mods.len or cur_p.len != 1) break;
                                        const found = findNestedDeclByZigPath(mods[cur_m].decls, cur_p) orelse break;
                                        if (found.kind != .re_export_decl) break;
                                        if (found.kind.re_export_decl.is_type_only) {
                                            chain_to = true;
                                            break;
                                        }
                                        cur_m = found.kind.re_export_decl.target_module_index;
                                        cur_p = found.kind.re_export_decl.target_zig_path;
                                    }
                                    if (chain_to or cur_m >= mods.len or cur_p.len == 0) continue;
                                    if (cur_p.len > 1) {
                                        if (findNestedDeclByZigPath(mods[cur_m].decls, cur_p[0..1])) |root_d| {
                                            if (root_d.source_decl_id) |rsid| {
                                                const rkey: ModDeclKey = .{ .mod_idx = cur_m, .sid = rsid };
                                                if (!natively.contains(rkey) and !claimed.contains(rkey)) {
                                                    try claimDeclAndMergedPeers(
                                                        s,
                                                        claimed,
                                                        natively,
                                                        mut_decls_all[cur_m],
                                                        cur_m,
                                                        rsid,
                                                        wire_mod,
                                                        cur_pfx,
                                                        root_d.wire_name,
                                                        null,
                                                        false,
                                                    );
                                                }
                                            }
                                        }
                                        continue;
                                    }
                                    const orig_d = findNestedDeclByZigPath(mods[cur_m].decls, cur_p) orelse continue;
                                    if (orig_d.kind == .re_export_decl or orig_d.kind == .namespace_re_export) continue;
                                    const orig_sid = orig_d.source_decl_id orelse continue;
                                    const okey: ModDeclKey = .{ .mod_idx = cur_m, .sid = orig_sid };
                                    if (!natively.contains(okey) and !claimed.contains(okey)) {
                                        try claimDeclAndMergedPeers(
                                            s,
                                            claimed,
                                            natively,
                                            mut_decls_all[cur_m],
                                            cur_m,
                                            orig_sid,
                                            wire_mod,
                                            cur_pfx,
                                            cd.wire_name,
                                            cd.wire_name,
                                            false,
                                        );
                                    }
                                    if (orig_d.kind == .namespace_decl and !visited_ns.contains(okey)) {
                                        var next_pfx = try s.alloc.alloc([]const u8, cur_pfx.len + 1);
                                        @memcpy(next_pfx[0..cur_pfx.len], cur_pfx);
                                        next_pfx[cur_pfx.len] = cd.wire_name;
                                        try visited_ns.put(s.scratch, okey, {});
                                        try queue.append(s.scratch, .{
                                            .mod_idx = cur_m,
                                            .ns_sid = orig_sid,
                                            .wire_mod = wire_mod,
                                            .ns_pfx = next_pfx,
                                            .depth = depth + 1,
                                        });
                                    }
                                },
                                else => {},
                            }
                        }
                    }
                }.run;

                var nq_i: usize = 0;
                while (nq_i < ns_decl_queue.items.len) : (nq_i += 1) {
                    const work = ns_decl_queue.items[nq_i];
                    if (work.depth > 16 or work.mod_idx >= modules.len) continue;
                    for (mod_mut_decls[work.mod_idx]) |cand| {
                        if (cand.source_decl_id == work.ns_sid and cand.kind == .namespace_decl) {
                            try processNsChildren(
                                self,
                                modules,
                                mod_mut_decls,
                                &claimed_targets,
                                &natively_reachable,
                                &visited_ns_decls,
                                &ns_decl_queue,
                                work.wire_mod,
                                work.ns_pfx,
                                work.depth,
                                cand.kind.namespace_decl.children,
                            );
                        }
                    }
                }
            }

            // 2c. When a global-scope runtime handle class (`globals.AbortSignal`, `globals.AbortController`,
            // `globals.Event`, `globals.EventTarget`, `globals.Headers`, `globals.Response`, `globals.Request`,
            // `globals.FormData`, `globals.WebSocket`, etc.) extends a same-named handle interface/class inside
            // an encapsulated types-only helper module (`web-globals/*`, `undici-types/*`, etc.), redirect the
            // helper declaration to a `.re_export_decl` of the canonical `globals` declaration (splicing the
            // helper's own bases into `globals.<Name>.bases` to prevent self-inheritance cycles) so methods
            // like `AbortController.signal()` and `Response.headers()` return `globals.AbortSignal` and
            // `globals.Headers` directly. If the helper cannot be aliased (e.g. has nested namespace decls),
            // fall back to promoting its runtime constructor target to global scope (`globalThis.<Name>`).
            for (modules, 0..) |*pub_mod, pub_mi| {
                const pub_mod_idx: u32 = @intCast(pub_mi);
                for (mod_mut_decls[pub_mi]) |*d| {
                    if (!d.is_global_scope or d.kind != .struct_decl) continue;
                    const st = &d.kind.struct_decl;
                    if (!st.is_class or !st.has_runtime_ctor_target) continue;

                    var next_bases: std.ArrayList(*const TypeIr) = .empty;
                    defer next_bases.deinit(self.scratch);
                    var spliced_any_base = false;

                    for (st.bases) |base_ty| {
                        var cur_ty: *const TypeIr = base_ty;
                        var resolved_mod: ?u32 = null;
                        var resolved_ident: ?[]const u8 = null;
                        var hops: usize = 0;
                        while (hops < 8) : (hops += 1) {
                            if (cur_ty.* != .decl_ref) break;
                            var cur_m = cur_ty.decl_ref.module_index;
                            var cur_p = cur_ty.decl_ref.decl_zig_path;
                            var re_hops: usize = 0;
                            while (re_hops < 8) : (re_hops += 1) {
                                if (cur_m >= modules.len or cur_p.len != 1) break;
                                const re_cand = findNestedDeclByZigPath(modules[cur_m].decls, cur_p) orelse break;
                                if (re_cand.kind != .re_export_decl) break;
                                cur_m = re_cand.kind.re_export_decl.target_module_index;
                                cur_p = re_cand.kind.re_export_decl.target_zig_path;
                            }
                            if (cur_m >= modules.len or cur_p.len != 1) break;
                            const found = findNestedDeclByZigPath(modules[cur_m].decls, cur_p) orelse break;
                            if (found.kind == .type_alias and found.kind.type_alias.type_params.len == 0) {
                                cur_ty = found.kind.type_alias.target;
                                continue;
                            }
                            resolved_mod = cur_m;
                            resolved_ident = cur_p[0];
                            break;
                        }
                        const b_mod = resolved_mod orelse {
                            try next_bases.append(self.scratch, base_ty);
                            continue;
                        };
                        const b_ident = resolved_ident.?;
                        if (b_mod >= modules.len) {
                            try next_bases.append(self.scratch, base_ty);
                            continue;
                        }

                        var redirected_base = false;
                        for (mod_mut_decls[b_mod]) |*bd| {
                            if (!std.mem.eql(u8, bd.zig_ident, b_ident)) continue;
                            if (bd.kind != .struct_decl) continue;
                            if (!std.mem.eql(u8, bd.wire_name, d.wire_name)) continue;
                            if (!modules[b_mod].is_encapsulated_internal and bd.is_js_exported) continue;

                            const bst = bd.kind.struct_decl;
                            if (b_mod != pub_mod_idx and
                                st.repr == .handle_wrapper and bst.repr == .handle_wrapper and
                                st.type_params.len == 0 and bst.type_params.len == 0 and
                                bst.nested_decls.len == 0)
                            {
                                for (bst.bases) |inh_base| {
                                    if (inh_base.* == .decl_ref and
                                        inh_base.decl_ref.module_index == pub_mod_idx and
                                        inh_base.decl_ref.decl_zig_path.len == 1 and
                                        std.mem.eql(u8, inh_base.decl_ref.decl_zig_path[0], d.zig_ident))
                                    {
                                        continue;
                                    }
                                    try self.ensureTypeImports(pub_mod, pub_mod_idx, modules, inh_base);
                                    try next_bases.append(self.scratch, inh_base);
                                }
                                const target_path = try self.alloc.alloc([]const u8, 1);
                                target_path[0] = d.zig_ident;
                                bd.is_exported = true;
                                bd.kind = .{
                                    .re_export_decl = .{
                                        .target_module_index = pub_mod_idx,
                                        .target_zig_path = target_path,
                                        .is_type_only = false,
                                    },
                                };
                                try self.ensureModuleImport(&modules[b_mod], b_mod, pub_mod_idx, pub_mod.rel_zig_path);
                                redirected_base = true;
                                spliced_any_base = true;
                                break;
                            }

                            if (!modules[b_mod].is_encapsulated_internal or !bst.is_class) continue;
                            const b_sid = bd.source_decl_id orelse continue;
                            const bkey: ModDeclKey = .{ .mod_idx = b_mod, .sid = b_sid };
                            if (natively_reachable.contains(bkey) or claimed_targets.contains(bkey)) continue;
                            bd.is_global_scope = true;
                            try natively_reachable.put(self.scratch, bkey, {});
                            if (b_sid < self.graph.decls.len) {
                                for (self.graph.decls[b_sid].merged_with) |peer_sid| {
                                    try natively_reachable.put(self.scratch, .{ .mod_idx = b_mod, .sid = peer_sid }, {});
                                    for (mod_mut_decls[b_mod]) |*pitem| {
                                        if (pitem.source_decl_id == peer_sid and std.mem.eql(u8, pitem.wire_name, d.wire_name)) {
                                            pitem.is_global_scope = true;
                                        }
                                    }
                                }
                            }
                        }

                        if (!redirected_base) {
                            try next_bases.append(self.scratch, base_ty);
                        }
                    }

                    if (spliced_any_base) {
                        st.bases = try self.alloc.dupe(*const TypeIr, next_bases.items);
                    }
                }
            }

            // 3. Prune runtime-unreachable module-level call targets (`function_decl`,
            // `overload_dispatch`, `global_var`, class `constructors`/`static_props`/static `methods`/
            // `ctor_target`, and runtime-computed `enum_decl` members) while keeping all types and
            // instance handle methods/properties intact.
            for (modules, 0..) |*m, mi| {
                const m_idx: u32 = @intCast(mi);
                var kept_top: std.ArrayList(DeclIr) = .empty;
                defer kept_top.deinit(self.scratch);

                for (m.decls) |d| {
                    const is_reach = if (d.kind == .re_export_decl or d.kind == .namespace_re_export)
                        true
                    else if (d.is_global_scope)
                        true
                    else if (d.source_decl_id) |sid| blk: {
                        const key: ModDeclKey = .{ .mod_idx = m_idx, .sid = sid };
                        break :blk natively_reachable.contains(key) or claimed_targets.contains(key);
                    } else !m.is_encapsulated_internal;

                    if (try self.pruneDeclRuntimeTargets(d, is_reach)) |kept_d| {
                        try kept_top.append(self.scratch, kept_d);
                    }
                }
                m.decls = try self.alloc.dupe(DeclIr, kept_top.items);

                if (m.export_equals_ident) |eq_id| {
                    var still_has_eq = false;
                    for (m.decls) |kd| {
                        if (std.mem.eql(u8, kd.logical_name, eq_id)) {
                            still_has_eq = true;
                            break;
                        }
                    }
                    if (!still_has_eq) {
                        m.export_equals_ident = null;
                        m.export_equals_wire_name = null;
                    }
                }
            }

            // 4. Drop any `.re_export_decl` whose target was pruned in step 3 (fixpoint, including nested namespaces).
            const filterDanglingReExports = struct {
                fn run(
                    s: *Self,
                    mods: []const ModuleIr,
                    decls_in: []const DeclIr,
                    removed_any: *bool,
                ) error{OutOfMemory}![]const DeclIr {
                    var next_decls: std.ArrayList(DeclIr) = .empty;
                    defer next_decls.deinit(s.scratch);
                    var mutated = false;
                    for (decls_in) |d_in| {
                        var d = d_in;
                        switch (d.kind) {
                            .re_export_decl => |re| {
                                if (re.target_module_index >= mods.len or
                                    !zigPathTargetExists(mods[re.target_module_index].decls, re.target_zig_path))
                                {
                                    removed_any.* = true;
                                    mutated = true;
                                    continue;
                                }
                            },
                            .namespace_decl => |ns| {
                                const cleaned = try run(s, mods, ns.children, removed_any);
                                if (cleaned.ptr != ns.children.ptr or cleaned.len != ns.children.len) {
                                    var next_ns = ns;
                                    next_ns.children = cleaned;
                                    d.kind = .{ .namespace_decl = next_ns };
                                    mutated = true;
                                }
                            },
                            else => {},
                        }
                        try next_decls.append(s.scratch, d);
                    }
                    if (!mutated) return decls_in;
                    return try s.alloc.dupe(DeclIr, next_decls.items);
                }
            }.run;

            var clean_pass: usize = 0;
            while (clean_pass < 8) : (clean_pass += 1) {
                var removed_any = false;
                for (modules) |*m| {
                    m.decls = try filterDanglingReExports(self, modules, m.decls, &removed_any);
                }
                if (!removed_any) break;
            }
        }

        fn ensureModuleImport(
            self: *Self,
            mod: *ModuleIr,
            self_mod_idx: u32,
            target_mod_idx: u32,
            target_rel_zig_path: []const u8,
        ) error{OutOfMemory}!void {
            if (self_mod_idx == target_mod_idx) return;
            for (mod.imports) |imp| {
                if (imp.target_module_index == target_mod_idx) return;
            }
            const alias_raw = try std.fmt.allocPrint(self.alloc, "__mod_{d}", .{target_mod_idx});
            const rel_imp = try naming.relativeImportPath(
                self.alloc,
                mod.rel_zig_path,
                target_rel_zig_path,
            );
            var next_imps = try self.alloc.alloc(ModuleImportIr, mod.imports.len + 1);
            @memcpy(next_imps[0..mod.imports.len], mod.imports);
            next_imps[mod.imports.len] = .{
                .target_module_index = target_mod_idx,
                .local_alias = alias_raw,
                .rel_import_path = rel_imp,
            };
            mod.imports = next_imps;
        }

        fn ensureTypeImports(
            self: *Self,
            mod: *ModuleIr,
            self_mod_idx: u32,
            modules: []const ModuleIr,
            ty: *const TypeIr,
        ) error{OutOfMemory}!void {
            switch (ty.*) {
                .decl_ref => |dr| {
                    if (dr.module_index < modules.len) {
                        try self.ensureModuleImport(mod, self_mod_idx, dr.module_index, modules[dr.module_index].rel_zig_path);
                    }
                    for (dr.type_args) |ta| {
                        try self.ensureTypeImports(mod, self_mod_idx, modules, ta);
                    }
                },
                .optional => |opt| try self.ensureTypeImports(mod, self_mod_idx, modules, opt.child),
                .pointer_const, .slice, .promise, .js_iterator, .js_async_iterator => |ch| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, ch);
                },
                .js_map => |kv| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, kv.key);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, kv.value);
                },
                .js_record => |kv| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, kv.key);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, kv.value);
                },
                .mapped_values_op => |mv| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, mv.target);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, mv.value);
                },
                .unary_type_op => |uo| try self.ensureTypeImports(mod, self_mod_idx, modules, uo.operand),
                .key_filter_op => |kf| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, kf.target);
                    if (kf.keys == .ty) try self.ensureTypeImports(mod, self_mod_idx, modules, kf.keys.ty);
                },
                .index_access_op => |ia| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, ia.object_ty);
                    if (ia.index_spec == .ty) try self.ensureTypeImports(mod, self_mod_idx, modules, ia.index_spec.ty);
                    if (ia.fallback_ty) |fb| try self.ensureTypeImports(mod, self_mod_idx, modules, fb);
                },
                .empty_object_extends_op => |eoe| {
                    try self.ensureTypeImports(mod, self_mod_idx, modules, eoe.target_ty);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, eoe.true_ty);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, eoe.false_ty);
                },
                .intersect_op => |members| {
                    for (members) |mt| try self.ensureTypeImports(mod, self_mod_idx, modules, mt);
                },
                .tuple => |elems| {
                    for (elems) |el| try self.ensureTypeImports(mod, self_mod_idx, modules, el.ty);
                },
                .fn_ptr => |fp| {
                    if (fp.this_param) |tp| try self.ensureTypeImports(mod, self_mod_idx, modules, tp);
                    for (fp.params) |pt| try self.ensureTypeImports(mod, self_mod_idx, modules, pt);
                    try self.ensureTypeImports(mod, self_mod_idx, modules, fp.return_type);
                    if (fp.rest_sequence_ty) |rt| try self.ensureTypeImports(mod, self_mod_idx, modules, rt);
                },
                .anon_struct => |fields| {
                    for (fields) |fld| try self.ensureTypeImports(mod, self_mod_idx, modules, fld.ty);
                },
                .tagged_union => |tu| {
                    for (tu.variants) |vr| try self.ensureTypeImports(mod, self_mod_idx, modules, vr.payload);
                },
                else => {},
            }
        }

        fn pruneDeclRuntimeTargets(
            self: *Self,
            d_in: DeclIr,
            is_reach: bool,
        ) error{OutOfMemory}!?DeclIr {
            var d = d_in;
            switch (d.kind) {
                .function_decl, .overload_dispatch, .global_var => {
                    if (!is_reach) return null;
                    return d;
                },
                .struct_decl => |*st| {
                    if (!is_reach) {
                        st.has_runtime_ctor_target = false;
                        st.constructors = &.{};
                        st.ctor_dispatch = null;
                        st.static_props = &.{};
                        st.merged_call_fns = &.{};
                        if (st.methods.len > 0) {
                            var inst_methods: std.ArrayList(MethodIr) = .empty;
                            defer inst_methods.deinit(self.scratch);
                            for (st.methods) |mth| {
                                if (!mth.is_static) try inst_methods.append(self.scratch, mth);
                            }
                            st.methods = try self.alloc.dupe(MethodIr, inst_methods.items);
                        }
                        if (st.method_dispatches.len > 0) {
                            var inst_disps: std.ArrayList(OverloadDispatchIr) = .empty;
                            defer inst_disps.deinit(self.scratch);
                            for (st.method_dispatches) |md| {
                                if (!md.is_static) try inst_disps.append(self.scratch, md);
                            }
                            st.method_dispatches = try self.alloc.dupe(OverloadDispatchIr, inst_disps.items);
                        }
                    }
                    if (st.nested_decls.len > 0) {
                        var kept_nested: std.ArrayList(DeclIr) = .empty;
                        defer kept_nested.deinit(self.scratch);
                        for (st.nested_decls) |nd| {
                            const nd_reach = is_reach and nd.is_exported;
                            if (try self.pruneDeclRuntimeTargets(nd, nd_reach)) |knd| {
                                try kept_nested.append(self.scratch, knd);
                            }
                        }
                        st.nested_decls = try self.alloc.dupe(DeclIr, kept_nested.items);
                    }
                    return d;
                },
                .namespace_decl => |*ns| {
                    if (!is_reach) {
                        ns.merged_call_fns = &.{};
                    }
                    if (ns.children.len > 0) {
                        var kept_children: std.ArrayList(DeclIr) = .empty;
                        defer kept_children.deinit(self.scratch);
                        for (ns.children) |ch| {
                            const ch_reach = is_reach and ch.is_exported;
                            if (try self.pruneDeclRuntimeTargets(ch, ch_reach)) |kch| {
                                try kept_children.append(self.scratch, kch);
                            }
                        }
                        ns.children = try self.alloc.dupe(DeclIr, kept_children.items);
                    }
                    return d;
                },
                .enum_decl => |*ed| {
                    if (!is_reach and ed.has_unknown_values) {
                        ed.members = &.{};
                    }
                    if (ed.nested_decls.len > 0) {
                        var kept_nested: std.ArrayList(DeclIr) = .empty;
                        defer kept_nested.deinit(self.scratch);
                        for (ed.nested_decls) |nd| {
                            const nd_reach = is_reach and nd.is_exported;
                            if (try self.pruneDeclRuntimeTargets(nd, nd_reach)) |knd| {
                                try kept_nested.append(self.scratch, knd);
                            }
                        }
                        ed.nested_decls = try self.alloc.dupe(DeclIr, kept_nested.items);
                    }
                    return d;
                },
                else => return d,
            }
        }

        fn synthesizeReExportAllocCompanions(
            self: *Self,
            modules: []ModuleIr,
            mod_scopes: []naming.ScopeNamer,
        ) error{OutOfMemory}!void {
            const CompFieldTag = enum {
                alloc,
                slice,
                slice_alloc,
                narrow,
                narrow_alloc,
                default,
                default_alloc,
                with,
                infer,
                infer_alloc,
            };
            const CompUpdate = struct {
                decl_idx: usize,
                tag: CompFieldTag,
                ident: []const u8,
            };

            var pass: usize = 0;
            while (pass < 4) : (pass += 1) {
                var added_any = false;
                for (modules, 0..) |*m, m_idx| {
                    var extras: std.ArrayList(DeclIr) = .empty;
                    defer extras.deinit(self.scratch);
                    var comp_updates: std.ArrayList(CompUpdate) = .empty;
                    defer comp_updates.deinit(self.scratch);

                    for (m.decls, 0..) |d, di| {
                        if (d.kind != .re_export_decl) continue;
                        const re = d.kind.re_export_decl;
                        if (re.target_module_index >= modules.len or re.target_zig_path.len == 0) continue;
                        const target_mod = modules[re.target_module_index];
                        const target_di = findNestedDeclByZigPath(target_mod.decls, re.target_zig_path) orelse continue;

                        const field_specs = [_]struct {
                            tag: CompFieldTag,
                            suffix: []const u8,
                            cur: ?[]const u8,
                            target: ?[]const u8,
                        }{
                            .{ .tag = .alloc, .suffix = "Alloc", .cur = d.alloc_companion_ident, .target = target_di.alloc_companion_ident },
                            .{ .tag = .slice, .suffix = "Slice", .cur = d.slice_companion_ident, .target = target_di.slice_companion_ident },
                            .{ .tag = .slice_alloc, .suffix = "SliceAlloc", .cur = d.slice_alloc_companion_ident, .target = target_di.slice_alloc_companion_ident },
                            .{ .tag = .narrow, .suffix = "Narrow", .cur = d.narrow_companion_ident, .target = target_di.narrow_companion_ident },
                            .{ .tag = .narrow_alloc, .suffix = "NarrowAlloc", .cur = d.narrow_alloc_companion_ident, .target = target_di.narrow_alloc_companion_ident },
                            .{ .tag = .default, .suffix = "Default", .cur = d.default_companion_ident, .target = target_di.default_companion_ident },
                            .{ .tag = .default_alloc, .suffix = "DefaultAlloc", .cur = d.default_alloc_companion_ident, .target = target_di.default_alloc_companion_ident },
                            .{ .tag = .with, .suffix = "With", .cur = d.with_companion_ident, .target = target_di.with_companion_ident },
                            .{ .tag = .infer, .suffix = "Infer", .cur = d.infer_companion_ident, .target = target_di.infer_companion_ident },
                            .{ .tag = .infer_alloc, .suffix = "InferAlloc", .cur = d.infer_alloc_companion_ident, .target = target_di.infer_alloc_companion_ident },
                        };

                        for (field_specs) |fs| {
                            if (fs.cur != null) continue;
                            const target_comp_ident = fs.target orelse continue;
                            const desired = try std.fmt.allocPrint(self.scratch, "{s}{s}", .{ d.logical_name, fs.suffix });
                            defer self.scratch.free(desired);
                            if (mod_scopes[m_idx].isTaken(desired)) continue;

                            const sb = try mod_scopes[m_idx].bind(desired, .preserve);
                            defer sb.deinit(self.scratch);

                            const new_zig_ident = try self.alloc.dupe(u8, sb.zig_ident);
                            const new_logical = try self.alloc.dupe(u8, sb.logical_name);
                            const comp_path = try self.alloc.alloc([]const u8, re.target_zig_path.len);
                            for (re.target_zig_path[0 .. re.target_zig_path.len - 1], 0..) |seg, si| {
                                comp_path[si] = seg;
                            }
                            comp_path[re.target_zig_path.len - 1] = target_comp_ident;

                            try comp_updates.append(self.scratch, .{
                                .decl_idx = di,
                                .tag = fs.tag,
                                .ident = new_zig_ident,
                            });
                            try extras.append(self.scratch, .{
                                .source_decl_id = d.source_decl_id,
                                .zig_ident = new_zig_ident,
                                .logical_name = new_logical,
                                .wire_name = d.wire_name,
                                .is_exported = true,
                                .is_js_exported = false,
                                .is_default_export = false,
                                .jsdoc = null,
                                .kind = .{
                                    .re_export_decl = .{
                                        .target_module_index = re.target_module_index,
                                        .target_zig_path = comp_path,
                                    },
                                },
                            });
                            added_any = true;
                        }

                        // Also synthesize re-exports for sibling synthetic companion DeclIrs
                        // (such as `*Promise` and overloaded `*Promise<Suffix>` companions).
                        if (!d.is_synthetic_companion) {
                            if (findSiblingDeclsByZigPath(target_mod.decls, re.target_zig_path)) |siblings| {
                                for (siblings) |sib| {
                                    if (!sib.is_synthetic_companion) continue;
                                    if (sib.source_decl_id != target_di.source_decl_id) continue;
                                    if (sib.logical_name.len <= target_di.logical_name.len) continue;
                                    if (!std.mem.startsWith(u8, sib.logical_name, target_di.logical_name)) continue;

                                    const suffix = sib.logical_name[target_di.logical_name.len..];
                                    const desired_sib = try std.fmt.allocPrint(self.scratch, "{s}{s}", .{ d.logical_name, suffix });
                                    defer self.scratch.free(desired_sib);
                                    if (mod_scopes[m_idx].isTaken(desired_sib)) continue;

                                    const sib_sb = try mod_scopes[m_idx].bind(desired_sib, .preserve);
                                    defer sib_sb.deinit(self.scratch);

                                    const new_zig_ident = try self.alloc.dupe(u8, sib_sb.zig_ident);
                                    const new_logical = try self.alloc.dupe(u8, sib_sb.logical_name);
                                    const sib_path = try self.alloc.alloc([]const u8, re.target_zig_path.len);
                                    for (re.target_zig_path[0 .. re.target_zig_path.len - 1], 0..) |seg, si| {
                                        sib_path[si] = seg;
                                    }
                                    sib_path[re.target_zig_path.len - 1] = sib.zig_ident;

                                    try extras.append(self.scratch, .{
                                        .source_decl_id = sib.source_decl_id,
                                        .zig_ident = new_zig_ident,
                                        .logical_name = new_logical,
                                        .wire_name = sib.wire_name,
                                        .is_exported = true,
                                        .is_js_exported = false,
                                        .is_synthetic_companion = true,
                                        .is_default_export = false,
                                        .jsdoc = null,
                                        .kind = .{
                                            .re_export_decl = .{
                                                .target_module_index = re.target_module_index,
                                                .target_zig_path = sib_path,
                                            },
                                        },
                                    });
                                    added_any = true;
                                }
                            }
                        }
                    }

                    if (extras.items.len > 0) {
                        const merged = try self.alloc.alloc(DeclIr, m.decls.len + extras.items.len);
                        @memcpy(merged[0..m.decls.len], m.decls);
                        for (comp_updates.items) |cu| {
                            switch (cu.tag) {
                                .alloc => merged[cu.decl_idx].alloc_companion_ident = cu.ident,
                                .slice => merged[cu.decl_idx].slice_companion_ident = cu.ident,
                                .slice_alloc => merged[cu.decl_idx].slice_alloc_companion_ident = cu.ident,
                                .narrow => merged[cu.decl_idx].narrow_companion_ident = cu.ident,
                                .narrow_alloc => merged[cu.decl_idx].narrow_alloc_companion_ident = cu.ident,
                                .default => merged[cu.decl_idx].default_companion_ident = cu.ident,
                                .default_alloc => merged[cu.decl_idx].default_alloc_companion_ident = cu.ident,
                                .with => merged[cu.decl_idx].with_companion_ident = cu.ident,
                                .infer => merged[cu.decl_idx].infer_companion_ident = cu.ident,
                                .infer_alloc => merged[cu.decl_idx].infer_alloc_companion_ident = cu.ident,
                            }
                        }
                        @memcpy(merged[m.decls.len..], extras.items);
                        m.decls = merged;
                    }
                }
                if (!added_any) break;
            }
        }
    };
}

fn findSiblingDeclsByZigPath(decls: []const DeclIr, path: []const []const u8) ?[]const DeclIr {
    if (path.len == 0) return null;
    if (path.len == 1) return decls;
    const head = path[0];
    for (decls) |d| {
        if (std.mem.eql(u8, d.zig_ident, head) or std.mem.eql(u8, d.logical_name, head)) {
            return switch (d.kind) {
                .namespace_decl => |ns| findSiblingDeclsByZigPath(ns.children, path[1..]) orelse
                    findSiblingDeclsByZigPath(ns.merged_call_fns, path[1..]),
                .struct_decl => |st| findSiblingDeclsByZigPath(st.nested_decls, path[1..]) orelse
                    findSiblingDeclsByZigPath(st.merged_call_fns, path[1..]),
                .enum_decl => |en| findSiblingDeclsByZigPath(en.nested_decls, path[1..]),
                else => null,
            };
        }
    }
    return null;
}

fn zigPathTargetExists(decls: []const DeclIr, path: []const []const u8) bool {
    if (path.len == 0) return false;
    if (findNestedDeclByZigPath(decls, path) != null) return true;
    const head = path[0];
    for (decls) |d| {
        if (std.mem.eql(u8, d.zig_ident, head) or std.mem.eql(u8, d.logical_name, head)) {
            if (path.len == 1) return true;
            const sub = path[1..];
            switch (d.kind) {
                .namespace_decl => |ns| return zigPathTargetExists(ns.children, sub) or
                    zigPathTargetExists(ns.merged_call_fns, sub),
                .struct_decl => |st| {
                    if (sub.len == 1) {
                        const leaf = sub[0];
                        for (st.methods) |m| {
                            if (m.is_static and (std.mem.eql(u8, m.zig_ident, leaf) or std.mem.eql(u8, m.logical_name, leaf))) return true;
                        }
                        for (st.method_dispatches) |md| {
                            if (md.is_static and (std.mem.eql(u8, md.zig_ident, leaf) or std.mem.eql(u8, md.logical_name, leaf))) return true;
                        }
                        for (st.static_props) |sp| {
                            if (std.mem.eql(u8, sp.zig_ident, leaf) or std.mem.eql(u8, sp.logical_name, leaf)) return true;
                        }
                    }
                    return zigPathTargetExists(st.nested_decls, sub) or
                        zigPathTargetExists(st.merged_call_fns, sub);
                },
                .enum_decl => |en| {
                    if (sub.len == 1) {
                        const leaf = sub[0];
                        for (en.members) |m| {
                            if (std.mem.eql(u8, m.zig_ident, leaf) or std.mem.eql(u8, m.logical_name, leaf)) return true;
                        }
                    }
                    return zigPathTargetExists(en.nested_decls, sub);
                },
                else => return false,
            }
        }
    }
    return false;
}

fn findNestedDeclByZigPath(decls: []const DeclIr, path: []const []const u8) ?DeclIr {
    if (path.len == 0) return null;
    const head = path[0];
    for (decls) |d| {
        if (std.mem.eql(u8, d.zig_ident, head) or std.mem.eql(u8, d.logical_name, head)) {
            if (path.len == 1) return d;
            return switch (d.kind) {
                .namespace_decl => |ns| findNestedDeclByZigPath(ns.children, path[1..]) orelse
                    findNestedDeclByZigPath(ns.merged_call_fns, path[1..]),
                .struct_decl => |st| findNestedDeclByZigPath(st.nested_decls, path[1..]) orelse
                    findNestedDeclByZigPath(st.merged_call_fns, path[1..]),
                .enum_decl => |en| findNestedDeclByZigPath(en.nested_decls, path[1..]),
                else => null,
            };
        }
    }
    return null;
}

fn deduplicateDeclIrsInPlace(scratch: std.mem.Allocator, list: *std.ArrayList(DeclIr)) error{OutOfMemory}!void {
    var seen: std.StringHashMapUnmanaged(void) = .empty;
    defer seen.deinit(scratch);
    var write_idx: usize = 0;
    for (list.items) |item| {
        const gop = try seen.getOrPut(scratch, item.zig_ident);
        if (!gop.found_existing) {
            list.items[write_idx] = item;
            write_idx += 1;
        }
    }
    list.items.len = write_idx;
}

fn appendUniqueU32(list: *std.ArrayList(u32), allocator: std.mem.Allocator, val: u32) !void {
    for (list.items) |existing| {
        if (existing == val) return;
    }
    try list.append(allocator, val);
}

fn isPureDollarOrUnderscoreIdent(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s) |ch| {
        if (ch != '$' and ch != '_') return false;
    }
    return true;
}

fn isAllUpperOrUnderscore(s: []const u8) bool {
    if (s.len == 0) return false;
    var has_upper = false;
    for (s) |ch| {
        if (std.ascii.isUpper(ch)) {
            has_upper = true;
        } else if (!std.ascii.isDigit(ch) and ch != '_') {
            return false;
        }
    }
    return has_upper;
}

fn formatDeclCycleKey(
    allocator: std.mem.Allocator,
    mod_idx: u32,
    prefix: []const []const u8,
    leaf: ?[]const u8,
) ![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.print(allocator, "{d}:", .{mod_idx});
    for (prefix, 0..) |seg, i| {
        if (i > 0) try out.append(allocator, '.');
        try out.appendSlice(allocator, seg);
    }
    if (leaf) |lf| {
        if (prefix.len > 0) try out.append(allocator, '.');
        try out.appendSlice(allocator, lf);
    }
    return try out.toOwnedSlice(allocator);
}

fn indexDeclPointersByPath(
    allocator: std.mem.Allocator,
    mod_idx: u32,
    prefix: []const []const u8,
    decls: []DeclIr,
    map: *std.StringHashMapUnmanaged(*DeclIr),
) error{OutOfMemory}!void {
    if (prefix.len >= 64) return;
    for (decls) |*d| {
        const key = try formatDeclCycleKey(allocator, mod_idx, prefix, d.zig_ident);
        const gop = try map.getOrPut(allocator, key);
        if (gop.found_existing) {
            allocator.free(key);
            continue;
        } else {
            gop.value_ptr.* = d;
        }

        switch (d.kind) {
            .namespace_decl => |*ns| {
                const sub_prefix = try allocator.alloc([]const u8, prefix.len + 1);
                defer allocator.free(sub_prefix);
                @memcpy(sub_prefix[0..prefix.len], prefix);
                sub_prefix[prefix.len] = d.zig_ident;
                try indexDeclPointersByPath(allocator, mod_idx, sub_prefix, @constCast(ns.children), map);
            },
            .struct_decl => |*st| {
                if (st.nested_decls.len > 0) {
                    const sub_prefix = try allocator.alloc([]const u8, prefix.len + 1);
                    defer allocator.free(sub_prefix);
                    @memcpy(sub_prefix[0..prefix.len], prefix);
                    sub_prefix[prefix.len] = d.zig_ident;
                    try indexDeclPointersByPath(allocator, mod_idx, sub_prefix, @constCast(st.nested_decls), map);
                }
            },
            .enum_decl => |*en| {
                if (en.nested_decls.len > 0) {
                    const sub_prefix = try allocator.alloc([]const u8, prefix.len + 1);
                    defer allocator.free(sub_prefix);
                    @memcpy(sub_prefix[0..prefix.len], prefix);
                    sub_prefix[prefix.len] = d.zig_ident;
                    try indexDeclPointersByPath(allocator, mod_idx, sub_prefix, @constCast(en.nested_decls), map);
                }
            },
            else => {},
        }
    }
}

fn dfsValueCycleDeclByPath(
    state_alloc: std.mem.Allocator,
    ir_alloc: std.mem.Allocator,
    mod_idx: u32,
    prefix: []const []const u8,
    d: *DeclIr,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    state: *std.StringHashMapUnmanaged(u8),
) error{OutOfMemory}!void {
    const self_key = try formatDeclCycleKey(state_alloc, mod_idx, prefix, d.zig_ident);
    if (state.get(self_key)) |st| {
        state_alloc.free(self_key);
        if (st == 2 or st == 1) return;
    }
    try state.put(state_alloc, self_key, 1);

    switch (d.kind) {
        .struct_decl => |*st| {
            if (st.repr == .value_struct) {
                for (st.fields) |f| {
                    try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(f.ty), decl_map, state);
                }
            }
            if (st.nested_decls.len > 0) {
                const sub_prefix = try state_alloc.alloc([]const u8, prefix.len + 1);
                defer state_alloc.free(sub_prefix);
                @memcpy(sub_prefix[0..prefix.len], prefix);
                sub_prefix[prefix.len] = d.zig_ident;
                for (@constCast(st.nested_decls)) |*nd| {
                    try dfsValueCycleDeclByPath(state_alloc, ir_alloc, mod_idx, sub_prefix, nd, decl_map, state);
                }
            }
        },
        .enum_decl => |*en| {
            if (en.nested_decls.len > 0) {
                const sub_prefix = try state_alloc.alloc([]const u8, prefix.len + 1);
                defer state_alloc.free(sub_prefix);
                @memcpy(sub_prefix[0..prefix.len], prefix);
                sub_prefix[prefix.len] = d.zig_ident;
                for (@constCast(en.nested_decls)) |*nd| {
                    try dfsValueCycleDeclByPath(state_alloc, ir_alloc, mod_idx, sub_prefix, nd, decl_map, state);
                }
            }
        },
        .union_decl => |*un| {
            for (un.variants) |v| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(v.payload), decl_map, state);
            }
        },
        .type_alias => |*ta| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(ta.target), decl_map, state);
        },
        .re_export_decl => |re| {
            const target_key = try formatDeclCycleKey(state_alloc, re.target_module_index, re.target_zig_path, null);
            defer state_alloc.free(target_key);
            if (decl_map.get(target_key)) |target_decl| {
                const parent_prefix = if (re.target_zig_path.len > 1)
                    re.target_zig_path[0 .. re.target_zig_path.len - 1]
                else
                    &[_][]const u8{};
                try dfsValueCycleDeclByPath(state_alloc, ir_alloc, re.target_module_index, parent_prefix, target_decl, decl_map, state);
            }
        },
        .namespace_decl => |*ns| {
            const sub_prefix = try state_alloc.alloc([]const u8, prefix.len + 1);
            defer state_alloc.free(sub_prefix);
            @memcpy(sub_prefix[0..prefix.len], prefix);
            sub_prefix[prefix.len] = d.zig_ident;
            for (@constCast(ns.children)) |*cd| {
                try dfsValueCycleDeclByPath(state_alloc, ir_alloc, mod_idx, sub_prefix, cd, decl_map, state);
            }
        },
        else => {},
    }

    if (state.getPtr(self_key)) |st_ptr| {
        st_ptr.* = 2;
    }
}

fn dfsValueCycleTypeByPath(
    state_alloc: std.mem.Allocator,
    ir_alloc: std.mem.Allocator,
    ty: *TypeIr,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    state: *std.StringHashMapUnmanaged(u8),
) error{OutOfMemory}!void {
    switch (ty.*) {
        // Indirection boundaries (pointer/slice/fn/runtime handle) cannot cause a value-size dependency loop!
        .slice, .pointer_const, .fn_ptr, .promise, .js_iterator, .js_async_iterator, .js_map => return,
        .js_record => |r| {
            if (r.key.* != .string_type) {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(r.value), decl_map, state);
            }
        },
        .mapped_values_op => |mv| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(mv.value), decl_map, state);
        },
        .unary_type_op => |uo| {
            if (uo.op != .keyof and uo.op != .constructor_of) {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(uo.operand), decl_map, state);
            }
        },
        .key_filter_op => |kfo| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(kfo.target), decl_map, state);
        },
        .index_access_op => |iao| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(iao.object_ty), decl_map, state);
            if (iao.fallback_ty) |ft| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(ft), decl_map, state);
            }
        },
        .empty_object_extends_op => |eoe| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(eoe.true_ty), decl_map, state);
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(eoe.false_ty), decl_map, state);
        },
        .intersect_op => |arms| {
            for (arms) |arm| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(arm), decl_map, state);
            }
        },
        .self_type => |sid| {
            const inner = try ir_alloc.create(TypeIr);
            inner.* = .{ .self_type = sid };
            ty.* = .{ .pointer_const = inner };
        },
        .optional => |opt| {
            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(opt.child), decl_map, state);
        },
        .tuple => |elems| {
            for (elems) |el| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(el.ty), decl_map, state);
            }
        },
        .anon_struct => |fields| {
            for (fields) |f| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(f.ty), decl_map, state);
            }
        },
        .tagged_union => |tu| {
            for (tu.variants) |v| {
                try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(v.payload), decl_map, state);
            }
        },
        .decl_ref => {
            if (ty.decl_ref.indirect) return;
            const target_key = try formatDeclCycleKey(state_alloc, ty.decl_ref.module_index, ty.decl_ref.decl_zig_path, null);
            defer state_alloc.free(target_key);
            const cur_state = state.get(target_key);
            if (cur_state) |st| {
                if (st == 1) {
                    // Cycle back-edge detected! Mutate `ty.decl_ref` directly in place (`*const Target`).
                    ty.decl_ref.indirect = true;
                    return;
                }
            }
            if (decl_map.get(target_key)) |target_decl| {
                if (ty.decl_ref.type_args.len > 0) {
                    const tps = switch (target_decl.kind) {
                        .type_alias => |ta| ta.type_params,
                        .struct_decl => |st_decl| st_decl.type_params,
                        .union_decl => |un_decl| un_decl.type_params,
                        else => &[_]TypeParamIr{},
                    };
                    for (ty.decl_ref.type_args, 0..) |arg_ty, idx| {
                        const by_val = if (idx < tps.len)
                            declUsesTypeParamByValue(state_alloc, target_decl, tps[idx].zig_ident, decl_map, 0)
                        else
                            false;
                        if (by_val) {
                            try dfsValueCycleTypeByPath(state_alloc, ir_alloc, @constCast(arg_ty), decl_map, state);
                        }
                    }
                }
                if (cur_state == null) {
                    const parent_prefix = if (ty.decl_ref.decl_zig_path.len > 1)
                        ty.decl_ref.decl_zig_path[0 .. ty.decl_ref.decl_zig_path.len - 1]
                    else
                        &[_][]const u8{};
                    try dfsValueCycleDeclByPath(
                        state_alloc,
                        ir_alloc,
                        ty.decl_ref.module_index,
                        parent_prefix,
                        target_decl,
                        decl_map,
                        state,
                    );
                }
            }
        },
        else => {},
    }
}

fn declUsesTypeParamByValue(
    state_alloc: std.mem.Allocator,
    d: *const DeclIr,
    tp_ident: []const u8,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    depth: usize,
) bool {
    if (depth >= 16) return true;
    return switch (d.kind) {
        .type_alias => |ta| typeUsesParamByValue(state_alloc, ta.target, tp_ident, decl_map, depth + 1),
        .struct_decl => |st| blk: {
            for (st.fields) |f| {
                if (typeUsesParamByValue(state_alloc, f.ty, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .union_decl => |un| blk: {
            for (un.variants) |v| {
                if (typeUsesParamByValue(state_alloc, v.payload, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

fn typeUsesParamByValue(
    state_alloc: std.mem.Allocator,
    ty: *const TypeIr,
    tp_ident: []const u8,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    depth: usize,
) bool {
    if (depth >= 16) return true;
    return switch (ty.*) {
        .slice, .pointer_const, .fn_ptr, .promise, .js_iterator, .js_async_iterator, .js_map => false,
        .js_record => |r| r.key.* != .string_type and
            (typeUsesParamByValue(state_alloc, r.key, tp_ident, decl_map, depth + 1) or
                typeUsesParamByValue(state_alloc, r.value, tp_ident, decl_map, depth + 1)),
        .mapped_values_op => |mv| typeUsesParamByValue(state_alloc, mv.value, tp_ident, decl_map, depth + 1),
        .unary_type_op => |uo| uo.op != .keyof and uo.op != .constructor_of and typeUsesParamByValue(state_alloc, uo.operand, tp_ident, decl_map, depth + 1),
        .key_filter_op => |kfo| typeUsesParamByValue(state_alloc, kfo.target, tp_ident, decl_map, depth + 1),
        .index_access_op => |iao| typeUsesParamByValue(state_alloc, iao.object_ty, tp_ident, decl_map, depth + 1) or
            (if (iao.fallback_ty) |ft| typeUsesParamByValue(state_alloc, ft, tp_ident, decl_map, depth + 1) else false),
        .empty_object_extends_op => |eoe| typeUsesParamByValue(state_alloc, eoe.true_ty, tp_ident, decl_map, depth + 1) or
            typeUsesParamByValue(state_alloc, eoe.false_ty, tp_ident, decl_map, depth + 1),
        .intersect_op => |arms| blk: {
            for (arms) |arm| {
                if (typeUsesParamByValue(state_alloc, arm, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .type_param_ref => |id| std.mem.eql(u8, id, tp_ident),
        .optional => |opt| typeUsesParamByValue(state_alloc, opt.child, tp_ident, decl_map, depth + 1),
        .tuple => |elems| blk: {
            for (elems) |el| {
                if (!el.is_variadic and typeUsesParamByValue(state_alloc, el.ty, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .anon_struct => |fields| blk: {
            for (fields) |f| {
                if (typeUsesParamByValue(state_alloc, f.ty, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .tagged_union => |tu| blk: {
            for (tu.variants) |v| {
                if (typeUsesParamByValue(state_alloc, v.payload, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .decl_ref => |dr| blk: {
            if (dr.indirect or dr.type_args.len == 0) break :blk false;
            const target_key = formatDeclCycleKey(state_alloc, dr.module_index, dr.decl_zig_path, null) catch break :blk true;
            defer state_alloc.free(target_key);
            if (decl_map.get(target_key)) |td| {
                const tps = switch (td.kind) {
                    .type_alias => |ta| ta.type_params,
                    .struct_decl => |st_decl| st_decl.type_params,
                    .union_decl => |un_decl| un_decl.type_params,
                    else => &[_]TypeParamIr{},
                };
                for (dr.type_args, 0..) |arg_ty, idx| {
                    if (idx < tps.len and
                        declUsesTypeParamByValue(state_alloc, td, tps[idx].zig_ident, decl_map, depth + 1) and
                        typeUsesParamByValue(state_alloc, arg_ty, tp_ident, decl_map, depth + 1))
                    {
                        break :blk true;
                    }
                }
                break :blk false;
            }
            for (dr.type_args) |arg_ty| {
                if (typeUsesParamByValue(state_alloc, arg_ty, tp_ident, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

fn declInspectsTypeParamInfo(
    state_alloc: std.mem.Allocator,
    d: *const DeclIr,
    tp_ident: []const u8,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    depth: usize,
) bool {
    if (depth >= 16) return false;
    return switch (d.kind) {
        .type_alias => |ta| typeInspectsParamInfo(state_alloc, ta.target, tp_ident, false, decl_map, depth + 1),
        else => false,
    };
}

fn typeInspectsParamInfo(
    state_alloc: std.mem.Allocator,
    ty: *const TypeIr,
    tp_ident: []const u8,
    under_eager: bool,
    decl_map: *const std.StringHashMapUnmanaged(*DeclIr),
    depth: usize,
) bool {
    if (depth >= 16) return false;
    return switch (ty.*) {
        .type_param_ref => |id| under_eager and std.mem.eql(u8, id, tp_ident),
        .slice, .pointer_const, .promise, .js_iterator, .js_async_iterator => |inner| under_eager and
            typeInspectsParamInfo(state_alloc, inner, tp_ident, true, decl_map, depth + 1),
        .optional => |opt| typeInspectsParamInfo(state_alloc, opt.child, tp_ident, under_eager, decl_map, depth + 1),
        .js_map => |mp| under_eager and
            (typeInspectsParamInfo(state_alloc, mp.key, tp_ident, true, decl_map, depth + 1) or
                typeInspectsParamInfo(state_alloc, mp.value, tp_ident, true, decl_map, depth + 1)),
        .js_record => |r| typeInspectsParamInfo(state_alloc, r.key, tp_ident, true, decl_map, depth + 1) or
            ((r.key.* != .string_type or under_eager) and
                typeInspectsParamInfo(state_alloc, r.value, tp_ident, true, decl_map, depth + 1)),
        .mapped_values_op => |mv| typeInspectsParamInfo(state_alloc, mv.target, tp_ident, true, decl_map, depth + 1) or
            typeInspectsParamInfo(state_alloc, mv.value, tp_ident, true, decl_map, depth + 1),
        .unary_type_op => |uo| typeInspectsParamInfo(state_alloc, uo.operand, tp_ident, true, decl_map, depth + 1),
        .key_filter_op => |kfo| typeInspectsParamInfo(state_alloc, kfo.target, tp_ident, true, decl_map, depth + 1) or
            (if (kfo.keys == .ty) typeInspectsParamInfo(state_alloc, kfo.keys.ty, tp_ident, true, decl_map, depth + 1) else false),
        .index_access_op => |iao| typeInspectsParamInfo(state_alloc, iao.object_ty, tp_ident, true, decl_map, depth + 1) or
            (if (iao.index_spec == .ty) typeInspectsParamInfo(state_alloc, iao.index_spec.ty, tp_ident, true, decl_map, depth + 1) else false) or
            (if (iao.fallback_ty) |ft| typeInspectsParamInfo(state_alloc, ft, tp_ident, true, decl_map, depth + 1) else false),
        .empty_object_extends_op => |eoe| typeInspectsParamInfo(state_alloc, eoe.target_ty, tp_ident, true, decl_map, depth + 1) or
            typeInspectsParamInfo(state_alloc, eoe.true_ty, tp_ident, under_eager, decl_map, depth + 1) or
            typeInspectsParamInfo(state_alloc, eoe.false_ty, tp_ident, under_eager, decl_map, depth + 1),
        .intersect_op => |arms| blk: {
            for (arms) |arm| {
                if (typeInspectsParamInfo(state_alloc, arm, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .tuple => |elems| blk: {
            if (!under_eager) break :blk false;
            for (elems) |el| {
                if (typeInspectsParamInfo(state_alloc, el.ty, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .anon_struct => |fields| blk: {
            if (!under_eager) break :blk false;
            for (fields) |f| {
                if (typeInspectsParamInfo(state_alloc, f.ty, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .tagged_union => |tu| blk: {
            if (!under_eager) break :blk false;
            for (tu.variants) |v| {
                if (typeInspectsParamInfo(state_alloc, v.payload, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            break :blk false;
        },
        .fn_ptr => |fp| blk: {
            if (fp.this_param == null and fp.rest_sequence_ty != null) {
                if (typeInspectsParamInfo(state_alloc, fp.rest_sequence_ty.?, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            if (!under_eager) break :blk false;
            if (fp.rest_sequence_ty) |rst| {
                if (typeInspectsParamInfo(state_alloc, rst, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            if (fp.this_param) |thp| {
                if (typeInspectsParamInfo(state_alloc, thp, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            for (fp.params) |pt| {
                if (typeInspectsParamInfo(state_alloc, pt, tp_ident, true, decl_map, depth + 1)) break :blk true;
            }
            break :blk typeInspectsParamInfo(state_alloc, fp.return_type, tp_ident, true, decl_map, depth + 1);
        },
        .decl_ref => |dr| blk: {
            var cur_mod = dr.module_index;
            var cur_path = dr.decl_zig_path;
            var td_opt: ?*DeclIr = null;
            var hops: usize = 0;
            while (hops < 8) : (hops += 1) {
                const k = formatDeclCycleKey(state_alloc, cur_mod, cur_path, null) catch break :blk false;
                defer state_alloc.free(k);
                const found = decl_map.get(k) orelse break;
                if (found.kind == .re_export_decl) {
                    cur_mod = found.kind.re_export_decl.target_module_index;
                    cur_path = found.kind.re_export_decl.target_zig_path;
                    continue;
                }
                td_opt = found;
                break;
            }
            const tps: []const TypeParamIr = if (td_opt) |td| switch (td.kind) {
                .type_alias => |ta| ta.type_params,
                .struct_decl => |st_decl| if (st_decl.repr == .value_struct) st_decl.type_params else &.{},
                .union_decl => |un_decl| un_decl.type_params,
                else => &.{},
            } else &.{};
            for (dr.type_args, 0..) |arg_ty, idx| {
                const callee_eager = under_eager or (td_opt != null and idx < tps.len and
                    declInspectsTypeParamInfo(state_alloc, td_opt.?, tps[idx].zig_ident, decl_map, depth + 1));
                if (typeInspectsParamInfo(state_alloc, arg_ty, tp_ident, callee_eager, decl_map, depth + 1)) {
                    break :blk true;
                }
            }
            break :blk false;
        },
        else => false,
    };
}

test "applySubstitutions and moduleMatchesPattern handle prefixes and node: normalization" {
    const alloc = std.testing.allocator;

    const rules = [_]cli.Substitution{
        .{ .from = "node:fs", .to = "fs" },
        .{ .from = "foo/internal", .to = "foo" },
    };

    {
        const s = try applySubstitutions(alloc, "node:fs/promises", &rules);
        defer alloc.free(s);
        try std.testing.expectEqualStrings("fs/promises", s);
    }
    {
        const s = try applySubstitutions(alloc, "foo/internal/bar", &rules);
        defer alloc.free(s);
        try std.testing.expectEqualStrings("foo/bar", s);
    }
    {
        const s = try applySubstitutions(alloc, "foo/internal_other", &rules);
        defer alloc.free(s);
        try std.testing.expectEqualStrings("foo/internal_other", s);
    }

    try std.testing.expect(moduleMatchesPattern("node:http", "node:http", "http"));
    try std.testing.expect(moduleMatchesPattern("http", "http", "node:http"));
    try std.testing.expect(moduleMatchesPattern("dns/promises", "dns/promises", "dns/promises"));
    try std.testing.expect(moduleMatchesPattern("monaco.editor", "monaco/editor", "monaco.editor"));
    try std.testing.expect(!moduleMatchesPattern("http2", "http2", "http"));
}
